import type { Request, Response } from 'express';
import { getDefaultLocale, t } from '@infrastructure/i18n';
import { ConfirmPasswordResetBody } from '@api/schemas.zod';
import { userService } from '@modules/users';
import { accountService } from '../services';
import { destroyRefreshCookie, destroyLoggedCookie } from '../session/cookies';
import { successResponse, rejectResponse } from '@infrastructure/http/response';
import type { PasswordResetConfirmRequest } from '@types';
import { enqueueEmail } from '@infrastructure/adapters/mailer';
import { resetConfirmEmail } from '../emails';
import { parseBody, refused } from '@infrastructure/http/controller';
import { callerContextOf } from '@infrastructure/http/request';

/**
 * POST /account/reset-confirm
 * Validate a one-time reset token and set the new password.
 */
export const postResetConfirm = (
    // This token is provided in the url within the email that has been sent to the user
    request: Request<{ token?: string }, unknown, PasswordResetConfirmRequest>,
    response: Response
) => {
    const body = parseBody(ConfirmPasswordResetBody, request.body, response);
    if (!body) return;

    const { token, password, passwordConfirm } = body;

    /**
     * Search user by token
     */
    return userService
        .findByPasswordResetToken(token)
        .then((user) => {
            // Wrong token
            if (!user) {
                rejectResponse(response, 422, [t('account.reset.token-not-found')]);
                return;
            }

            const tokenEntry = user.tokens.find(
                (tk) => tk.token === token && tk.type === 'password'
            );
            if (!tokenEntry || (tokenEntry.expiration && tokenEntry.expiration < new Date())) {
                rejectResponse(response, 422, [t('account.reset.token-not-found')]);
                return;
            }

            /*
             * Validate BEFORE spending the token, then let spending it decide the race.
             *
             * The lookup above is a read, so two simultaneous confirms of one reset link both
             * find the token and both pass this point — a one-time token used twice. Only the
             * atomic `$pull` inside `consumeToken` can separate them: it reports whether THIS
             * request was the one that removed the entry, and the loser is turned away with the
             * same "token not found" it would get for an invented token, because from its point
             * of view that is exactly what happened.
             *
             * Validation comes first so a mistyped confirmation cannot burn the link. Password
             * writing comes last, so the request that loses the race never changes anything.
             */
            const errors = accountService.validatePasswordChange(password, passwordConfirm);
            if (errors.length > 0) {
                rejectResponse(response, 422, errors);
                return;
            }

            return userService.consumeToken(user, token).then((spentByThisRequest) => {
                if (!spentByThisRequest) {
                    rejectResponse(response, 422, [t('account.reset.token-not-found')]);
                    return;
                }

                /**
                 * Change password
                 */
                return accountService
                    .passwordResetChange(user, password, passwordConfirm, callerContextOf(request))
                    .then((result) => {
                        if (refused(response, result)) return;
                        // send confirmation email (no need to wait)
                        /*
                         * The recipient's OWN language, not the language of the request that triggered
                         * this. These links are clicked from an email client, possibly on a shared or
                         * borrowed device, so the browser's `Accept-Language` says very little about
                         * who the message is for. Passing it explicitly is what makes that choice
                         * visible — and what leaves the job fully translated.
                         */
                        const mail = resetConfirmEmail(
                            user.locale ?? request.locale ?? getDefaultLocale(),
                            user.username
                        );
                        void enqueueEmail(
                            { to: user.email, subject: mail.subject },
                            mail.template,
                            mail.data
                        );

                        destroyRefreshCookie(response);
                        destroyLoggedCookie(response);
                        successResponse(response, undefined, 200, t('account.reset.success'));
                    });
            });
        })
        .catch(() => {
            rejectResponse(response, 500, []);
        });
};

import type { Request, Response } from 'express';
import { getDefaultLocale, t } from '@infrastructure/i18n';
import { RequestPasswordResetBody } from '@api/schemas.zod';
import { userService } from '@modules/users';
import { accountService } from '../services';
import { successResponse } from '@infrastructure/http/response';
import type { PasswordResetRequest } from '@types';
import { enqueueEmail } from '@infrastructure/adapters/mailer';
import { emitAuditEvent, buildAuditEvent } from '@infrastructure/observability/audit';
import { accountAuditActions } from '../audit';
import { resetRequestEmail } from '../emails';
import { authPasswordResetTotal } from '../metrics';
import { parseBody } from '@infrastructure/http/controller';
import { callerContextOf } from '@infrastructure/http/request';

/*
 * The audit emit below stays at the controller, not moved into `tokenAdd`/a wrapper: it fires
 * UNCONDITIONALLY, whether or not the email belongs to a real account, which is what keeps the
 * response identical either way and prevents user enumeration. A service function reachable only
 * once a user is found (the shape every other wrapper in this batch takes) cannot reproduce that
 * — moving it would make the audit trail leak account existence that the response deliberately
 * does not.
 */

/**
 * POST /account/reset-request
 * Indistinguishable response for valid and invalid emails — prevents user enumeration.
 */

/**
 * Resolve reset token data only when both email and user exist.
 * Returns undefined silently to keep the public response identical.
 * @param email - address from request body
 * @returns token payload or undefined
 */
const lookupResetData = (email?: string) => {
    if (!email) return Promise.resolve();
    return userService.findByEmail(email).then((user) => {
        if (!user) return;
        return accountService.tokenAdd(user, 'password', 3_600_000).then((token) => ({
            username: user.username,
            // The account's own language, so the email matches the rest of what this user
            // receives from us rather than the browser that happened to submit the form.
            locale: user.locale,
            token
        }));
    });
};

/**
 * Request handler — always resolves with 200 regardless of email validity.
 * Fires password-reset email only when a valid user + token pair was found.
 * @param request - Express request with PasswordResetRequest body
 * @param response - Express response
 */
export const postResetRequest = (
    request: Request<unknown, unknown, PasswordResetRequest>,
    response: Response
) => {
    // Shape validation only — existence of the account is never revealed (see below).
    const body = parseBody(RequestPasswordResetBody, request.body, response);
    if (!body) return;

    const { email } = body;

    return (
        lookupResetData(email)
            // Fail closed and keep the public response identical to protect account privacy.
            .catch(() => {
                /* error discarded intentionally — response stays 200 to prevent user enumeration */
            })
            .then((data) => {
                authPasswordResetTotal.inc({ status: data?.token ? 'success' : 'failure' });

                if (data?.token) {
                    // The recipient's own language, stated as an argument: the copy is finished
                    // before the job is published, so the worker needs no locale at all.
                    const mail = resetRequestEmail(
                        data.locale ?? request.locale ?? getDefaultLocale(),
                        data.username,
                        data.token
                    );
                    void enqueueEmail(
                        { to: email, subject: mail.subject },
                        mail.template,
                        mail.data
                    );
                }

                emitAuditEvent(
                    buildAuditEvent(callerContextOf(request), {
                        action: accountAuditActions.AUTH_PASSWORD_RESET_REQUESTED,
                        actor_user_id: 'anonymous',
                        actor_role: 'anonymous',
                        outcome: 'success'
                    })
                );

                successResponse(response, undefined, 200, t('account.reset.email-sent'));
            })
    );
};

