import type { Request, Response } from 'express';
import type { CastError } from 'mongoose';
import { t } from '@infrastructure/i18n';
import { successResponse, rejectResponse } from '@infrastructure/http/response';
import { rejectDatabaseError } from '@infrastructure/http/errors';
import { resolveImageUrl } from '@infrastructure/http/uploads';
import { imageStore } from '@infrastructure/adapters/image-store';
import type { UpdateAccountRequest, UpdateAccountRequestMultipart } from '@types';
import { accountService } from '../services';
import { sendVerificationEmail } from '../services';
import { authContextOf, callerContextOf } from '@infrastructure/http/request';

/**
 * PUT /account
 * The authenticated user updates their OWN profile — email, username, locale, image.
 *
 * This endpoint is why a normal user can edit their profile at all: the `/users` writes sit
 * behind `isAdmin`, and self-service going through them answered every non-admin a 403.
 */
export const putAccount = (
    request: Request<unknown, unknown, UpdateAccountRequest | UpdateAccountRequestMultipart>,
    response: Response
) => {
    /* Auth context is guaranteed by isAuth middleware */
    const { id, email: currentEmail } = authContextOf(request);

    /**
     * Uploaded file takes priority over body imageUrl — the same merge signup does.
     */
    const imageUrlFile = resolveImageUrl(request as Request);
    const imageUrl = imageUrlFile ?? (request.body as { imageUrl?: string }).imageUrl;
    // On failure remove the image THIS request uploaded — `imageUrlFile`, never the merged
    // value: a body-supplied url names an image this request did not create.
    const deleteUpload = () => imageStore.remove(imageUrlFile);

    /*
     * Read through the request type rather than parsed against `UpdateAccountBody`, for the reason
     * `post-signup` gives: `accountService.updateProfile` validates these fields with translated
     * messages, and the generated schema would answer first in English.
     */
    const { email, username, locale } = request.body as UpdateAccountRequest;

    return accountService
        .updateProfile(id, { email, username, locale, imageUrl }, callerContextOf(request))
        .then((result) => {
            if (!result.success)
                return deleteUpload().then(() => {
                    rejectResponse(response, result.status, result.errors);
                });

            /*
             * A changed address restarts verification: `updateProfile` has already unset
             * `verified`, and the fresh link goes to the NEW address — proving the mailbox that
             * now backs the account, not the one that used to. Fire-and-forget like every other
             * account email; the response does not wait on the queue.
             */
            if (email !== undefined && email !== currentEmail && result.data)
                void sendVerificationEmail(result.data, request.locale);

            successResponse(response, result.data, 200, t('account.update.success'));
        })
        .catch((error: CastError | Error) => {
            rejectDatabaseError(response, 'putAccount', error);
            return deleteUpload();
        });
};

src/modules/account/controllers/write-ad.source:
/**
 * Adding an entry to the address book, and editing one — the two shipping addresses a caller
 * writes.
 *
 * One file for both, on the same grounds as `products/controllers/write-products.ts`: they are not
 * merely similar in length, they run the same three steps in the same order — parse a body against
 * its generated schema and answer 422 on a miss, call the one service function, then branch on
 * `result.success` and answer with the whole book either way. Split apart, an edit to that shape
 * has two places to land and no reason to reach both.
 *
 * The read lives in `./get-addresses.ts` and the removal in `./delete-address.ts`, because neither
 * parses a body and so neither shares the shape this file is named for.
 */
import type { Request, Response } from 'express';
import { AddAddressBody, UpdateAddressBody } from '@api/schemas.zod';
import { successResponse } from '@infrastructure/http/response';
import type { AddressInput, UpdateAddressRequest } from '@types';
import { accountService } from '../services';
import { catchAs, refused, rejectValidation } from '@infrastructure/http/controller';
import { authContextOf } from '@infrastructure/http/request';

/**
 * POST /account/addresses — add an entry.
 *
 * The first entry becomes the default whether or not it asked; a later one claims the slot only by
 * saying so, and demotes the holder in the same write. Both invariants live in the service.
 */
export const postAddress = (
    request: Request<unknown, unknown, AddressInput>,
    response: Response
) => {
    /* Auth context is guaranteed by isAuth middleware */
    const { id } = authContextOf(request);

    const parseResult = AddAddressBody.safeParse(request.body);
    if (!parseResult.success) return rejectValidation(response, parseResult.error);

    return accountService
        .addressAdd(id, parseResult.data)
        .then((result) => {
            if (refused(response, result)) return;
            successResponse(response, result.data, 200, result.message);
        })
        .catch(catchAs(response, 'postAddress'));
};

/**
 * PUT /account/addresses/:addressId — edit an entry.
 *
 * An entry the caller does not hold answers the same 404 as one that never existed: ownership is
 * checked in the service, and a distinguishable answer would confirm the id belongs to somebody.
 */
export const putAddress = (
    request: Request<{ addressId: string }, unknown, UpdateAddressRequest>,
    response: Response
) => {
    /* Auth context is guaranteed by isAuth middleware */
    const { id } = authContextOf(request);
    const { addressId } = request.params;

    const parseResult = UpdateAddressBody.safeParse(request.body);
    if (!parseResult.success) return rejectValidation(response, parseResult.error);

    return accountService
        .addressUpdate(id, addressId, parseResult.data)
        .then((result) => {
            if (refused(response, result)) return;
            successResponse(response, result.data, 200, result.message);
        })
        .catch(catchAs(response, 'putAddress'));
};

