import { addressBookModel, applyAddressBookTransform } from './model';
import type { AddressBookDocument } from './model';
import type { AddressInput, UpdateAddressRequest } from '@types';
import {
    createBaseRepository,
    toObjectId,
    type BaseRepository
} from '@infrastructure/persistence/base-repository';

/**
 * Address book Repository
 *
 * Every write loads the book, edits it in memory and saves — a READ-MODIFY-WRITE, which the cart
 * deliberately avoids, and the difference is the point: "exactly one default" is an invariant
 * across the WHOLE array, and no single `$set`/`$pull` can demote the old default, promote the
 * new one and prune the removed entry as one server-side expression. Concurrency worry is also
 * of a different order — nobody edits their address book from two devices in the same second the
 * way two tabs race a cart — so mongoose's optimistic versioning on `save()` is protection
 * enough: the loser retries by hand, it does not oversell anything.
 *
 * The type is written out because Mongoose's generics are too large for TypeScript to serialize
 * an inferred one at an export boundary (TS7056) — the same reason `BaseRepository` exists.
 */
export const addressBookRepository: BaseRepository<AddressBookDocument> & {
    findByUserId: (userId: string) => Promise<AddressBookDocument | null>;
    addEntry: (userId: string, entry: AddressInput) => Promise<AddressBookDocument>;
    updateEntry: (
        userId: string,
        addressId: string,
        changes: UpdateAddressRequest
    ) => Promise<AddressBookDocument | null>;
    removeEntry: (userId: string, addressId: string) => Promise<AddressBookDocument | null>;
    deleteByUserId: (userId: string) => Promise<void>;
} = {
    ...createBaseRepository<AddressBookDocument>(addressBookModel, {
        transform: applyAddressBookTransform
    }),

    /**
     * Fetch a user's book. `null` means they never saved an address — the same state as an
     * empty book.
     */
    findByUserId: (userId: string) =>
        addressBookModel.findOne({ userId: toObjectId(userId) }).exec(),

    /**
     * Append one entry, creating the book if the user has none.
     *
     * The default invariant is decided here: the first entry is default regardless of what it
     * asked, a later entry claiming `default: true` demotes the current holder, and a later
     * entry that claims nothing changes nothing.
     */
    addEntry: async (userId: string, entry: AddressInput) => {
        const book =
            (await addressBookModel.findOne({ userId: toObjectId(userId) }).exec()) ??
            new addressBookModel({ userId: toObjectId(userId), items: [] });

        const wantsDefault = (entry.default ?? false) || book.items.length === 0;
        if (wantsDefault) for (const item of book.items) item.default = false;

        book.items.push({ ...entry, default: wantsDefault });
        return book.save();
    },

    /**
     * Edit one entry of the caller's own book.
     *
     * Resolves `null` when the book or the entry is absent — someone else's address id matches
     * nothing here, which is what lets the controller answer the same 404 an invented id gets.
     * `default: true` claims the slot; `false`/absent leave the assignment alone (see the
     * contract note — demoting without a successor would leave the book with none).
     */
    updateEntry: async (userId: string, addressId: string, changes: UpdateAddressRequest) => {
        const book = await addressBookModel.findOne({ userId: toObjectId(userId) }).exec();
        const entry = book?.items.find((item) => String(item._id) === addressId);
        if (!book || !entry) return null;

        if (changes.label !== undefined) entry.label = changes.label;
        if (changes.fullName !== undefined) entry.fullName = changes.fullName;
        if (changes.street !== undefined) entry.street = changes.street;
        if (changes.city !== undefined) entry.city = changes.city;
        if (changes.zip !== undefined) entry.zip = changes.zip;
        if (changes.country !== undefined) entry.country = changes.country;
        if (changes.phone !== undefined) entry.phone = changes.phone;
        if (changes.default === true) {
            for (const item of book.items) item.default = false;
            entry.default = true;
        }

        return book.save();
    },

    /**
     * Remove one entry of the caller's own book. Removing the default promotes the oldest
     * remaining entry — a non-empty book always has exactly one default.
     */
    removeEntry: async (userId: string, addressId: string) => {
        const book = await addressBookModel.findOne({ userId: toObjectId(userId) }).exec();
        const entry = book?.items.find((item) => String(item._id) === addressId);
        if (!book || !entry) return null;

        book.items = book.items.filter((item) => String(item._id) !== addressId);
        if (entry.default && book.items.length > 0) book.items[0].default = true;

        return book.save();
    },

    /**
     * Delete a user's book outright — what a hard account deletion owes it.
     */
    deleteByUserId: (userId: string) =>
        addressBookModel
            .deleteOne({ userId: toObjectId(userId) })
            .exec()
            .then(() => {
                // explicit void return
            })
};

src/modules/account/services/addresses.t.source:
import { t } from '@infrastructure/i18n';
import {
    generateSuccess,
    generateReject,
    type ResponseSuccess,
    type ResponseReject
} from '@infrastructure/http/response';
import type { Address, AddressInput, UpdateAddressRequest } from '@types';
import { addressBookRepository } from '../repository';
import type { AddressBookDocument, AddressItem } from '../model';

/**
 * The address book — the one collection this module owns outright.
 *
 * Every endpoint answers the whole book (`{ addresses }`), never one entry: the invariant worth
 * seeing after any write is "exactly one default", and that is a property of the list. A client
 * that wrote one entry and re-rendered only that entry would happily display two defaults.
 *
 * One slice of `./index`'s service rather than a service of its own. It was `addresses-service.ts`
 * beside `service.ts` at the module root, which made the account's two aggregates look like two
 * layers; they are one layer over two collections, and the namespace in `./index` is where both
 * arrive.
 */

/** The book as `openapi.yaml` declares it: `AddressesResponse`, built rather than serialized. */
export interface AddressesView {
    addresses: Address[];
}

const toAddress = (item: AddressItem): Address => ({
    id: String(item._id),
    ...(item.label === undefined ? {} : { label: item.label }),
    fullName: item.fullName,
    street: item.street,
    city: item.city,
    zip: item.zip,
    country: item.country,
    ...(item.phone === undefined ? {} : { phone: item.phone }),
    default: item.default
});

const toView = (book: AddressBookDocument | null): AddressesView => ({
    addresses: (book?.items ?? []).map((item) => toAddress(item))
});

/** Get the user's book. Absence and emptiness are the same state — an empty view, never 404. */
export const addressesGet = (userId: string): Promise<AddressesView> =>
    addressBookRepository.findByUserId(userId).then((book) => toView(book));

/** Add an entry. The repository decides the default slot — see `addEntry`. */
export const addressAdd = (
    userId: string,
    entry: AddressInput
): Promise<ResponseSuccess<AddressesView> | ResponseReject> =>
    addressBookRepository
        .addEntry(userId, { ...entry, default: entry.default ?? false })
        .then((book) => generateSuccess(toView(book), 200, t('account.addresses.added')));

/** Update one entry of the caller's own book; someone else's id is the same 404 as a bogus one. */
export const addressUpdate = (
    userId: string,
    addressId: string,
    changes: UpdateAddressRequest
): Promise<ResponseSuccess<AddressesView> | ResponseReject> =>
    addressBookRepository.updateEntry(userId, addressId, changes).then((book) => {
        if (!book) return generateReject(404, [t('account.addresses.not-found')]);
        return generateSuccess(toView(book), 200, t('account.addresses.updated'));
    });

/** Remove one entry; the repository keeps the one-default invariant. */
export const addressRemove = (
    userId: string,
    addressId: string
): Promise<ResponseSuccess<AddressesView> | ResponseReject> =>
    addressBookRepository.removeEntry(userId, addressId).then((book) => {
        if (!book) return generateReject(404, [t('account.addresses.not-found')]);
        return generateSuccess(toView(book), 200, t('account.addresses.removed'));
    });

/**
 * The address a checkout should ship to — a named entry, the default, or nothing.
 *
 * Exposed through the barrel for the cart's checkout. `undefined` for "the caller keeps no
 * addresses and named none" (an address is not required to buy), `null` for "the caller NAMED
 * an entry that is not theirs or does not exist" — which the checkout must refuse rather than
 * ship nowhere. The split is the whole return type: collapsing the two would let a stale
 * address id silently downgrade to "no address".
 */
export const addressForCheckout = (
    userId: string,
    addressId?: string
): Promise<AddressItem | null | undefined> =>
    addressBookRepository.findByUserId(userId).then((book) => {
        if (addressId !== undefined)
            return book?.items.find((item) => String(item._id) === addressId) ?? null;
        return book?.items.find((item) => item.default) ?? undefined;
    });

/** What a hard account deletion owes the book — see `module.ts`'s subscription. */
export const addressesDeleteByUserId = (userId: string): Promise<void> =>
    addressBookRepository.deleteByUserId(userId);

/*
 * No namespace object here. These six are members of `accountService` in `./index`, which is the
 * module's one service handle — see the note there on why `authService`/`addressesService` became
 * a single name.
 */

