/**
 * Cleanup entry points — what OTHER modules call when something they own disappears.
 *
 * Neither is reachable from a cart route. They exist because a cart holds references to two things
 * it does not own, a user and a product, and nothing else tidies up after either. `../module.ts`
 * wires both to the domain events that fire on deletion.
 */

import type { CastError } from 'mongoose';
import {
    generateSuccess,
    type ResponseSuccess,
    type ResponseReject
} from '@infrastructure/http/response';
import { rejectDatabaseEnvelope } from '@infrastructure/http/errors';
import { cartRepository } from '../repository';

/**
 * Delete a user's cart outright, for a hard account deletion.
 *
 * Distinct from `cartRemove`, which empties a cart the user still has. Mirrors what
 * {@link productRemoveFromCartsById} does for a deleted product: the cart no longer lives inside
 * the user document, so nothing cleans up after it unless this is called.
 */
export const cartDeleteByUserId = (userId: string): Promise<void> =>
    cartRepository.deleteByUserId(userId);

/**
 * Remove a product from all users' carts by product ID.
 */
export const productRemoveFromCartsById = (
    id: string
): Promise<ResponseSuccess<undefined> | ResponseReject> =>
    cartRepository
        .removeProductFromAll(id)
        .then((result) =>
            generateSuccess(
                undefined,
                200,
                `Product ${id} removed from ${result.modifiedCount} cart(s)`
            )
        )
        .catch((error: CastError | Error) => rejectDatabaseEnvelope('cart', error));

src/modules/cart/services/items.ts.source:
/**
 * Reading a cart, and changing what is in it.
 *
 * Every operation here is one write plus the join that prices the answer. The three that name a
 * PRODUCT carry a response envelope, because each of them can be asked about one the cart may not
 * hold; {@link cartRemove} names none and cannot fail, so it does not carry one — clearing an
 * already-empty cart is the state the caller asked for.
 */

import { t } from '@infrastructure/i18n';
import {
    generateSuccess,
    generateReject,
    type ResponseSuccess,
    type ResponseReject
} from '@infrastructure/http/response';
import { productRepository } from '@modules/products';
import type { CallerContext } from '@infrastructure/http/request';
import { emitAnalyticsEvent, buildAnalyticsBase } from '@infrastructure/observability/analytics';
import { emitAuditEvent, buildAuditEvent } from '@infrastructure/observability/audit';
import { cartAnalyticsEvents } from '../analytics';
import { cartAuditActions } from '../audit';
import { cartRepository } from '../repository';
import { readCartLines, toCartView, type CartLine, type CartView } from './view';

/**
 * Get user cart, each line joined with its product.
 */
export const cartGet = (userId: string): Promise<CartLine[]> =>
    cartRepository.findByUserId(userId).then((cart) => readCartLines(cart));

/**
 * Get user cart with computed summary (item count, total quantity, total price).
 *
 * Split by caller intent, not by data: a person opening their basket and a badge polling a count
 * run the identical read, but only one of them is a `cart_viewed` moment.
 */
const cartViewOf = (userId: string): Promise<CartView> =>
    cartRepository.findByUserId(userId).then((cart) => toCartView(cart));

/** GET /cart/summary — the header badge polling a count. Never counts as viewing the cart. */
export const cartGetForBadge = cartViewOf;

/** GET /cart — a person looking at their basket. The one of the two that is a `cart_viewed` moment. */
export const cartGetForView = (userId: string, context: CallerContext): Promise<CartView> =>
    cartViewOf(userId).then((view) => {
        emitAnalyticsEvent({
            ...buildAnalyticsBase(context),
            event: cartAnalyticsEvents.CART_VIEWED
        });
        return view;
    });

/**
 * Shared logic for adding/setting a cart item quantity.
 *
 * **The catalogue gate lives here, not in a controller.** A cart line may only name a product the
 * storefront would show, and this is where that is decided, so every caller that adds ONE product
 * inherits it — `POST /cart`, `PUT /cart/{productId}`, and the wishlist's move-to-cart, which
 * reaches this function through the module barrel and never sees the catalogue itself.
 *
 * `./reorder` is the one caller that applies the rule itself, because it needs a different answer
 * to it: a discontinued line is SKIPPED there, not refused, so it resolves the whole order's
 * products in one pass and writes the survivors through the repository. Same predicate,
 * `findPublicById`, named in both places rather than derived twice.
 *
 * A route is the wrong place for it. Each one would have to ask the question for itself, in its
 * own words, and a route that forgets produces a stored line for a product no page will serve —
 * silently, because the view drops a reference that resolves to nothing, so the line is invisible
 * in the response that created it and shows up as a priced item at checkout. A rule every caller
 * must obey belongs under all of them rather than beside one, which is what a service layer is
 * for — see `docs/theory/layers.md`.
 *
 * `findPublicById` rather than a scope assembled here: `active`, not soft-deleted, and no variance
 * by role — the catalogue's own definition of "on sale", named once in the products module so this
 * cannot drift from what the product page will actually serve.
 *
 * Stock is deliberately NOT part of it. The shelf is checked when the cart becomes an order
 * (`./checkout`), because units are held at that moment and not before: refusing to hold a
 * sold-out product in a basket would throw away the customer's intent over a number that changes
 * by the minute.
 *
 * Then one write: the repository's update pipeline creates the cart, appends the line or rewrites
 * its quantity server-side and hands back the result, so the only remaining query is the join that
 * prices the answer.
 */
const upsertCartItem = (
    userId: string,
    id: string,
    quantity: number,
    mode: 'set' | 'add'
): Promise<ResponseSuccess<CartView> | ResponseReject> =>
    productRepository.findPublicById(id).then((product) => {
        if (!product) return generateReject(404, [t('products.not-found')]);

        return cartRepository
            .upsertLine(userId, id, quantity, mode)
            .then((cart) => toCartView(cart))
            .then((view) => generateSuccess(view));
    });

/**
 * Set quantity of target product in cart (by ID).
 *
 * The envelope carries no message: what to call a successful write is the caller's to say, and
 * `POST /cart` and `PUT /cart/{productId}` say different things about the same operation.
 */
export const cartItemSetById = (
    userId: string,
    id: string,
    quantity = 1
): Promise<ResponseSuccess<CartView> | ResponseReject> =>
    upsertCartItem(userId, id, quantity, 'set');

/**
 * `POST /cart` — add a product to the cart, or replace the quantity of a line already there.
 *
 * Named apart from `PUT /cart/{productId}`'s wrapper below for the same reason each already
 * carried its own analytics event at the controller: the two routes say different things about
 * the identical write (`cartItemSetById`, unchanged — this does not switch the route to
 * increment). Wrapping rather than folding the emit into `cartItemSetById` itself keeps every
 * other caller — the dozens of unit tests that use it as a plain setup step, `PUT`'s own wrapper
 * below — free of a `CallerContext` neither one needs.
 */
export const cartItemAdd = (
    userId: string,
    id: string,
    quantity: number,
    context: CallerContext
): Promise<ResponseSuccess<CartView> | ResponseReject> =>
    cartItemSetById(userId, id, quantity).then((result) => {
        if (result.success)
            emitAnalyticsEvent({
                ...buildAnalyticsBase(context),
                event: cartAnalyticsEvents.CART_ITEM_ADDED,
                properties: { product_id: id, quantity }
            });
        return result;
    });

/**
 * `PUT /cart/{productId}` — set the quantity of a specific cart item. See {@link cartItemAdd}.
 */
export const cartItemUpdateQuantity = (
    userId: string,
    id: string,
    quantity: number,
    context: CallerContext
): Promise<ResponseSuccess<CartView> | ResponseReject> =>
    cartItemSetById(userId, id, quantity).then((result) => {
        if (result.success)
            emitAnalyticsEvent({
                ...buildAnalyticsBase(context),
                event: cartAnalyticsEvents.CART_ITEM_UPDATED,
                properties: { product_id: id, quantity }
            });
        return result;
    });

/**
 * Add quantity of target product to existing quantity in cart (by ID).
 */
export const cartItemAddById = (
    userId: string,
    id: string,
    quantity = 1
): Promise<ResponseSuccess<CartView> | ResponseReject> =>
    upsertCartItem(userId, id, quantity, 'add');

/**
 * Remove target product from cart (by ID).
 *
 * 404 rather than a silent success: a client deleting a line it cannot see needs to know its view
 * is stale. The repository's filter asks for the cart AND the line, so a `null` result covers both
 * "no cart" and "no such line" without a second query.
 */
export const cartItemRemoveById = (
    userId: string,
    id: string,
    context: CallerContext
): Promise<ResponseSuccess<CartView> | ResponseReject> =>
    cartRepository.removeLine(userId, id).then((cart) => {
        if (!cart) return generateReject(404, []);
        emitAuditEvent(
            buildAuditEvent(context, {
                action: cartAuditActions.USER_CART_ITEM_REMOVED,
                actor_role: 'user',
                outcome: 'success',
                target_type: 'product',
                target_id: id
            })
        );
        emitAnalyticsEvent({
            ...buildAnalyticsBase(context),
            event: cartAnalyticsEvents.CART_ITEM_REMOVED,
            properties: { product_id: id }
        });
        return toCartView(cart).then((view) => generateSuccess(view, 200));
    });

/**
 * Remove all products from cart.
 *
 * Idempotent: a user with no cart document is already in the state this asks for, and the empty
 * view says so.
 */
export const cartRemove = (userId: string, context: CallerContext): Promise<CartView> =>
    cartRepository.clearLines(userId).then((cart) =>
        toCartView(cart).then((view) => {
            emitAnalyticsEvent({
                ...buildAnalyticsBase(context),
                event: cartAnalyticsEvents.CART_CLEARED,
                properties: {}
            });
            return view;
        })
    );

src/modules/cart/services/reorder.ts.source:
/**
 * Reorder — an old order refilling the cart.
 *
 * Lives in cart, not orders, because of what it WRITES: the order is only read, the cart is what
 * changes, and `cart → orders` is the direction the manifests already declare. An
 * `/orders/{id}/reorder` route would have needed the orders module to reach into the cart —
 * the exact cycle the checkout arrow exists to avoid.
 */

import type { CastError } from 'mongoose';
import { t } from '@infrastructure/i18n';
import {
    generateSuccess,
    generateReject,
    type ResponseSuccess,
    type ResponseReject
} from '@infrastructure/http/response';
import { rejectDatabaseEnvelope } from '@infrastructure/http/errors';
import { orderRepository } from '@modules/orders';
import { productRepository } from '@modules/products';
import type { ProductDocument } from '@modules/products';
import type { CallerContext } from '@infrastructure/http/request';
import { emitAnalyticsEvent, buildAnalyticsBase } from '@infrastructure/observability/analytics';
import { emitAuditEvent, buildAuditEvent } from '@infrastructure/observability/audit';
import { cartAnalyticsEvents } from '../analytics';
import { cartAuditActions } from '../audit';
import { cartRepository } from '../repository';
import { toCartView, type CartView } from './view';

/** A line the order asks for, resolved against today's catalogue. */
interface ReorderLine {
    productId: string;
    quantity: number;
    /** `null` when the product is gone, inactive or soft-deleted — not addable. */
    product: ProductDocument | null;
}

/**
 * Copy an order's lines back into the caller's cart.
 *
 * Scoped to the caller's OWN orders — `visibleScope`, admin or not — because the cart being
 * filled is the caller's: reordering someone else's purchases into your basket is not a
 * privilege, it is a leak of what they bought.
 *
 * The order carries product SNAPSHOTS, so each line is re-resolved against the catalogue as it
 * is today, through `findPublicById`: a product that has since been deleted, deactivated or
 * hidden is skipped rather than re-added, exactly as it could not be added from the product page.
 * The quantities come from the order; an item already in the cart is INCREMENTED, matching what
 * "add to cart" does everywhere else.
 *
 * This is the one path that answers the catalogue question for itself instead of letting
 * `./items`' `upsertCartItem` answer it, and SKIPPING is the reason: that function refuses, which
 * is the right answer for a caller naming one product and the wrong one for a basket being
 * refilled from a year-old order. Resolving the batch in a single parallel pass is also what
 * keeps a ten-line reorder at one round of reads rather than ten. The predicate is the same call
 * in both places, so the two cannot disagree about what "on sale" means.
 *
 * Skipping everything is a refusal, not a success: an order whose every product has vanished
 * answers 409 with `REORDER_UNAVAILABLE`, because "your cart now holds none of what you asked
 * for" is not an outcome to dress as 200. A partial skip is reported by the answer itself — the
 * cart view carries what actually landed.
 *
 * Writes are sequential on purpose. Parallel upserts against one cart document all fight the
 * unique `userId` index and resolve by retry; a reduce chain issues them one at a time and needs
 * none.
 */
export const reorderIntoCart = (
    userId: string,
    orderId: string,
    context: CallerContext
): Promise<ResponseSuccess<CartView> | ResponseReject> =>
    orderRepository
        .findByIdScoped(orderId, orderRepository.visibleScope(userId))
        .then<ResponseSuccess<CartView> | ResponseReject>((order) => {
            if (!order) return generateReject(404, [t('cart.reorder.order-not-found')]);

            /*
             * Scoped reads come back as NORMALIZED aggregate output — the embedded snapshot's
             * `_id` is already `id` — but the static type is still the document's. Read both
             * spellings rather than cast to one: this is the exact two-shapes trap
             * `orderService.getById` is known for, and a reader of either shape stays correct.
             */
            const requested = order.items.map((item) => {
                const snapshot = item.product as { id?: unknown; _id?: unknown };
                return {
                    productId: String(snapshot.id ?? snapshot._id),
                    quantity: item.quantity
                };
            });

            return Promise.all(
                requested.map(
                    (line): Promise<ReorderLine> =>
                        productRepository
                            .findPublicById(line.productId)
                            .then((product) => ({ ...line, product }))
                )
            ).then(async (lines) => {
                const addable = lines.filter((line) => line.product !== null);

                if (addable.length === 0)
                    return generateReject(409, [
                        {
                            code: 'REORDER_UNAVAILABLE',
                            message: t('cart.reorder.unavailable')
                        }
                    ]);

                /*
                 * One at a time, in the original order: each `upsertLine` reads and rewrites the
                 * same cart document, so a parallel add would lose lines to a last-write-wins race.
                 */
                for (const line of addable)
                    await cartRepository.upsertLine(userId, line.productId, line.quantity, 'add');

                return cartRepository
                    .findByUserId(userId)
                    .then((cart) => toCartView(cart))
                    .then((view) => generateSuccess(view, 200, t('cart.reorder.success')));
            });
        })
        .catch((error: CastError | Error) => rejectDatabaseEnvelope('cart', error))
        .then((result) => {
            if (result.success) {
                emitAuditEvent(
                    buildAuditEvent(context, {
                        action: cartAuditActions.USER_CART_REORDERED,
                        outcome: 'success',
                        metadata: { order_id: orderId }
                    })
                );
                emitAnalyticsEvent({
                    ...buildAnalyticsBase(context),
                    event: cartAnalyticsEvents.CART_REORDERED,
                    properties: { order_id: orderId }
                });
            }
            return result;
        });

src/modules/cart/services/view.ts.source:
/**
 * The cart projection — how a stored cart becomes something a caller can read.
 *
 * Internal to `services/`; the other three files share these helpers and none of them owns it.
 *
 * A cart is its own document keyed by `userId` (`../model`), so every operation is one addressed
 * write or read. Absence and emptiness are the same state: no cart document answers as an empty
 * cart, never a 404.
 */

import { sumLineItems } from '@modules/orders';
import type { ProductDocument } from '@modules/products';
import type { CartItem } from '@types';
import type { CartDocument } from '../model';

/**
 * A cart line joined with the product it references.
 *
 * `productId` and `product` are separate fields on purpose. `populate()` overwrites the stored
 * reference in place, and it writes `null` there when the product no longer exists — so reading
 * the id off that field afterwards loses it exactly when a caller most needs to know which
 * product a broken line pointed at. {@link readCartLines} captures the id first.
 */
export interface CartLine extends CartItem {
    /** The joined product, or `null` for a reference that resolves to nothing. */
    product: ProductDocument | null;
}

/** A cart line whose reference resolved — what an order may be built from. */
export type JoinedCartLine = CartLine & { product: ProductDocument };

/**
 * The cart as `openapi.yaml` declares it: `CartResponse`, built rather than serialized.
 *
 * Every cart endpoint answers with this — the reads directly, the mutations as their payload —
 * which is why no controller has to re-read the cart after changing it.
 */
export interface CartView {
    items: CartItem[];
    summary: { itemsCount: number; totalQuantity: number; total: number };
}

/**
 * A cart after `populate('items.productId')`.
 *
 * Names what Mongoose swaps into the reference field, so the populated read is typed rather than
 * cast. Spelled as the whole `items` key because `populate<T>` merges `T` over the document's
 * top-level properties — a dotted path is not a key it can merge on.
 */
interface PopulatedCart {
    items: { productId: ProductDocument | null; quantity: number }[];
}

/** Narrow a line to one whose product actually exists. */
export const isJoined = (line: CartLine): line is JoinedCartLine => line.product !== null;

/**
 * Join a cart's lines to their products, in one query.
 *
 * The ids are read before `populate()` runs, because populate replaces the reference field with
 * the fetched document — or with `null` for a product that has since been deleted.
 */
export const readCartLines = (cart: CartDocument | null): Promise<CartLine[]> => {
    if (!cart) return Promise.resolve([]);

    const productIds = cart.items.map(({ productId }) => productId.toString());

    // No `items = []` fallback: the schema defaults the array, so a hydrated cart always has one.
    return cart.populate<PopulatedCart>('items.productId').then(({ items }) =>
        items.map(({ productId, quantity }, index) => ({
            productId: productIds[index],
            quantity,
            product: productId
        }))
    );
};

/**
 * Turn a cart document into the response the contract declares.
 *
 * The joined `product` prices the cart and is then dropped: `CartItem` in `openapi.yaml` is
 * `additionalProperties: false` over `{ productId, quantity }`, so shipping the whole product per
 * line is over-serialization the contract suite fails on. No client reads it — the frontend renders
 * the cart from `productId`/`quantity` and looks products up in its own store. Use `cartGet`
 * where the joined product is actually needed.
 */
export const toCartView = (cart: CartDocument | null): Promise<CartView> =>
    readCartLines(cart).then((lines) => {
        const { count, quantity, price } = sumLineItems(lines);
        return {
            items: lines.map(({ productId, quantity: lineQuantity }) => ({
                productId,
                quantity: lineQuantity
            })),
            summary: {
                itemsCount: count,
                totalQuantity: quantity,
                total: price
            }
        };
    });

