import type { Request, Response } from 'express';
import { isKnownTenant } from '../tenants';
import { readInput } from '@infrastructure/http/request';
import { paginationSchema } from '@infrastructure/http/schemas';
import { rejectResponse, successResponse } from '@infrastructure/http/response';
import { localeService } from '../services';
import { catchAs, rejectValidation } from '@infrastructure/http/controller';

/**
 * GET /locales/:locale/entries (admin)
 * The rows behind one language's dictionary — what a translation screen lists.
 *
 * Flat and paginated, because a row is what gets edited. The nested tree a client consumes is
 * `GET /locales/:locale/messages`; one endpoint trying to be both is how this feature usually goes
 * wrong, so the two are named for what they are.
 *
 * Deliberately NOT cached. Every other locale read is, because they answer the same bytes to
 * everyone for an hour — this one is the screen a translator is typing into, where a stale page
 * means editing a value that has already changed. The saving would be a single indexed query
 * against a collection only admins can reach.
 */
export const getLocaleEntries = (
    request: Request<{ locale: string }, unknown, unknown, Record<string, string>>,
    response: Response
) => {
    // Query only — the `list` surface. The editing screen reaches this over a GET and there is
    // no `POST /locales/:locale/entries/search` to carry a body, so declaring one would claim a
    // source no client can send. See docs/theory/request-input.md.
    const { page, pageSize, text, tenant } = readInput(request, { surface: 'list' }) as Record<
        string,
        string | undefined
    >;

    /*
     * An unrecognised `tenant` is dropped rather than refused, which is the same answer `text=` and
     * every other optional filter gives: a listing narrowed by a value nothing matches would show
     * an empty screen and blame the data. Dropping it shows every tenant, which is what the
     * parameter defaults to anyway.
     */
    const tenantFilter = tenant && isKnownTenant(tenant) ? tenant : undefined;

    // The shared schema is what makes `?pageSize=500` answer 422 here as it does everywhere else,
    // rather than being silently clamped.
    const parseResult = paginationSchema.safeParse({ page, pageSize });
    if (!parseResult.success) return Promise.resolve(rejectValidation(response, parseResult.error));

    return localeService
        .searchEntries(request.params.locale, { ...parseResult.data, text, tenant: tenantFilter })
        .then((result) =>
            result.success
                ? successResponse(response, result.data)
                : rejectResponse(response, result.status, result.errors)
        )
        .catch(catchAs(response, 'getLocaleEntries'));
};

import type { Request, Response } from 'express';
import { successResponse } from '@infrastructure/http/response';
import { listTenants } from '../tenants';

/**
 * GET /locales/tenants
 * Every tenant this deployment holds words for — the keyspaces an entry can belong to.
 *
 * Configuration read back, not a query: the list comes from the environment (see `../tenants`),
 * so an admin screen can offer exactly the tenants this API will accept without hardcoding them,
 * and a client can find which id is the backend's own.
 *
 * Public and cacheable, like every other locale read: no user data, identical for every caller.
 */
export const getLocaleTenants = (_request: Request, response: Response) =>
    successResponse(response, { tenants: listTenants() });

import type { Request, Response } from 'express';
import { successResponse, rejectResponse } from '@infrastructure/http/response';
import { listSupportedLocales, readLocaleDictionary, t } from '@infrastructure/i18n';
import { localeService } from '../services';
import { catchAs } from '@infrastructure/http/controller';

/**
 * GET /locales
 * Every language this deployment offers, from both tiers, each stating what it can actually do.
 *
 * Which locales exist is a RUNTIME fact — it depends on which dictionary files are deployed and
 * which languages have been registered — so it cannot live in `openapi.yaml` as an enum. A client
 * that wants to offer a language picker matching what the API actually supports has to ask.
 *
 * `scopes` is what stops the two tiers from being read as one capability. A language with `api`
 * can be sent as `Accept-Language`; a language with `app` has a dictionary to download; a language
 * with both does both. Merging them into a flat list of tags would tell a client that `es` is
 * available and let it discover the hard way which kind of available was meant.
 *
 * The dynamic half is best-effort — see `localeService.readDynamicTier`. A database outage costs
 * the languages that are downloadable, never the ones the API can answer in, because a client
 * asking this question has usually just failed to reach something else.
 */
export const getLocales = (request: Request, response: Response) =>
    localeService
        // Which rows this caller may read — `getAuth` on the route is what makes the role
        // readable here, exactly as the products list does it.
        .listCapabilities(localeService.callerScope(request.authContext))
        .then((capabilities) => successResponse(response, capabilities))
        .catch(catchAs(response, 'getLocales'));

/**
 * GET /locales/:locale
 * This API's OWN dictionary for one language — its ~60 message keys, nothing else.
 *
 * Deliberately not "the translations a client needs": the two repositories are independent, and
 * serving a client's UI copy from the API repository would put view text in the API's keyspace.
 * What this serves is the API's own strings, which the API already owns and already ships. A
 * client merges them under a namespace it reserves for exactly that (`api.*` in the Vue
 * boilerplate) and never at the root, where two independently-authored keyspaces would collide.
 *
 * In normal operation a client needs none of this: the API resolves its own keys and puts
 * finished text on the wire. It earns its place when no response arrives at all — a network
 * failure, a bare 502 — and the client has to produce the copy itself.
 *
 * The client's OWN copy is `GET /locales/:locale/messages`, which reads the database. This one
 * reads the filesystem and always will: putting the fallback copy behind a store would make it
 * unavailable in precisely the outage it exists for.
 *
 * Public and cacheable: static copy, identical for every caller, no user data.
 */
export const getLocaleDictionary = (request: Request<{ locale?: string }>, response: Response) => {
    const { locale } = request.params;

    // Checked against the supported list rather than trusted, because the value goes into a
    // filename. `listSupportedLocales` is derived from the directory itself, so anything not on
    // it cannot correspond to a file — which makes this both the 404 check and the traversal
    // guard (`../../etc/passwd` is not a supported locale).
    if (!locale || !listSupportedLocales().includes(locale))
        return rejectResponse(response, 404, [t('generic.error-invalid-data')]);

    return successResponse(response, {
        locale,
        messages: readLocaleDictionary(locale)
    });
};

