import type { Request, Response } from 'express';
import {
    CreateLocaleEntryBody,
    MergeLocaleEntriesBody,
    ReplaceLocaleEntriesBody,
    UpdateLocaleEntryBody
} from '@api/schemas.zod';
import type {
    CreateLocaleEntryRequest,
    LocaleEntryInput,
    LocaleTenant,
    MergeLocaleEntriesRequest,
    ReplaceLocaleEntriesRequest,
    UpdateLocaleEntryRequest
} from '@types';
import { refreshLocaleOverrides } from '@infrastructure/i18n';
import { successResponse } from '@infrastructure/http/response';
import { rejectDatabaseError } from '@infrastructure/http/errors';
import { callerContextOf } from '@infrastructure/http/request';
import { localeService } from '../services';
import { catchAs, refused, rejectValidation } from '@infrastructure/http/controller';

/**
 * The four write routes on a language's entries: one key at a time, and two bulk imports.
 *
 * ## Why both bulk routes exist, and why they are two METHODS
 *
 * Nobody types five hundred keys into a form, so without an import this admin surface is a demo.
 * And "does an import delete the keys it did not mention" is the question every translation tool
 * gets wrong — so the answer is spelled in the method rather than in a flag:
 *
 *   PUT   replaces — what is not sent is deleted
 *   PATCH merges   — what is not sent is left alone
 *
 * A client cannot ask for one and receive the other, and a mis-set boolean cannot silently empty a
 * dictionary. `tests/contract/` asserts the pair together, because this is the semantic most
 * likely to be implemented backwards.
 */

/**
 * Re-read the API's own overrides after a write that may have changed them.
 *
 * Fire-and-forget, and not awaited before answering: the caller edited a row, and whether THIS
 * worker's copy overlay has caught up is not something their 200 should wait on. It makes the edit
 * visible immediately on the worker that served the write; the others pick it up on their next
 * scheduled refresh.
 *
 * Called after frontend-tenant writes too. Those cannot affect the overlay, and checking would
 * mean threading the tenant through the two delete controllers to save a query that runs once per
 * admin keystroke at most.
 */
const refreshOverrides = () => void refreshLocaleOverrides();

/**
 * POST /locales/:locale/entries (admin)
 * Add one key.
 */
export const createLocaleEntry = (
    request: Request<{ locale: string }, unknown, CreateLocaleEntryRequest>,
    response: Response
) => {
    const parseResult = CreateLocaleEntryBody.safeParse(request.body);
    if (!parseResult.success) return rejectValidation(response, parseResult.error);

    return localeService
        .createEntry(request.params.locale, parseResult.data, callerContextOf(request))
        .then((result) => {
            if (refused(response, result)) return;

            refreshOverrides();

            return successResponse(response, result.data, 201);
        })
        .catch(catchAs(response, 'createLocaleEntry'));
};

/**
 * PUT /locales/:locale/entries/:entryId (admin)
 * Edit one value.
 *
 * The key is not editable: it is the identity a client looks the string up by, so changing it is a
 * delete plus an add, and the two collision checks that go with them.
 */
export const updateLocaleEntry = (
    request: Request<{ locale: string; entryId: string }, unknown, UpdateLocaleEntryRequest>,
    response: Response
) => {
    const parseResult = UpdateLocaleEntryBody.safeParse(request.body);
    if (!parseResult.success) return rejectValidation(response, parseResult.error);

    return localeService
        .updateEntry(
            request.params.locale,
            request.params.entryId,
            parseResult.data,
            callerContextOf(request)
        )
        .then((result) => {
            if (refused(response, result)) return;

            refreshOverrides();

            return successResponse(response, result.data);
        })
        .catch(catchAs(response, 'updateLocaleEntry'));
};

/** The two bulk routes differ by one word, so they are one handler and a mode. */
const importEntries = (
    request: Request<{ locale: string }, unknown, { entries?: LocaleEntryInput[] }>,
    response: Response,
    mode: 'replace' | 'merge',
    tenant: LocaleTenant,
    entries: LocaleEntryInput[]
) =>
    localeService
        .importEntries(request.params.locale, tenant, entries, mode, callerContextOf(request))
        .then((result) => {
            if (refused(response, result)) return;

            refreshOverrides();

            return successResponse(response, result.data);
        })
        .catch((error: Error) => rejectDatabaseError(response, `${mode}LocaleEntries`, error));

/**
 * PUT /locales/:locale/entries (admin)
 * Replace the whole set — anything stored and not sent is deleted.
 */
export const replaceLocaleEntries = (
    request: Request<{ locale: string }, unknown, ReplaceLocaleEntriesRequest>,
    response: Response
) => {
    const parseResult = ReplaceLocaleEntriesBody.safeParse(request.body);
    if (!parseResult.success) return rejectValidation(response, parseResult.error);

    return importEntries(
        request,
        response,
        'replace',
        parseResult.data.tenant,
        parseResult.data.entries
    );
};

/**
 * PATCH /locales/:locale/entries (admin)
 * Upsert what is sent, leave the rest alone. Nothing is ever deleted by this route.
 */
export const mergeLocaleEntries = (
    request: Request<{ locale: string }, unknown, MergeLocaleEntriesRequest>,
    response: Response
) => {
    const parseResult = MergeLocaleEntriesBody.safeParse(request.body);
    if (!parseResult.success) return rejectValidation(response, parseResult.error);

    return importEntries(
        request,
        response,
        'merge',
        parseResult.data.tenant,
        parseResult.data.entries
    );
};

import type { Request, Response } from 'express';
import { z } from 'zod';
import { CreateLocaleBody, UpdateLocaleBody } from '@api/schemas.zod';
import type { CreateLocaleRequest, UpdateLocaleRequest } from '@types';
import { successResponse } from '@infrastructure/http/response';
import { callerContextOf } from '@infrastructure/http/request';
import { localeService } from '../services';
import { catchAs, refused, rejectValidation } from '@infrastructure/http/controller';

/**
 * POST /locales and PUT /locales/:locale (admin)
 * Register a language in the dynamic tier, and edit the one thing about it that changes.
 *
 * Neither of these teaches the API to answer in a language. `listSupportedLocales()` is read once
 * per worker and i18next registers its resources from it at boot — deliberately, because a
 * per-request directory read would let the negotiated locale and the resolvable one disagree, and
 * a `Content-Language` header that lies is worse than a language being unavailable. A row written
 * here is `app`-scoped until a file is deployed for it, and the manifest says so.
 */

/**
 * A display name that survives being trimmed.
 *
 * `openapi.yaml` says `minLength: 1`, which a single space satisfies — and both the schema here and
 * Mongoose then trim, so `" "` arrives as `""` at a column declared `required: true`.
 *
 * Trimming BEFORE the length check is what makes the refusal the request's own, answered by the
 * schema that declared the rule rather than by the database rejecting the write. `minLength` in
 * the contract cannot express it — JSON Schema has no trim — so the constraint lives here, the way
 * `feedback`'s `adminNotes` cap does. The error names the field; a `ValidationError` surfacing
 * from Mongoose is a 422 too (`@infrastructure/http/errors`) but says only that something was
 * invalid.
 */
const displayName = z.string().trim().min(1);

/**
 * POST /locales (admin)
 * Add a language.
 */
export const createLocale = (
    request: Request<Record<string, never>, unknown, CreateLocaleRequest>,
    response: Response
) => {
    const parseResult = CreateLocaleBody.extend({
        name: displayName,
        nativeName: displayName
    }).safeParse(request.body);
    if (!parseResult.success) return Promise.resolve(rejectValidation(response, parseResult.error));

    return localeService
        .createLanguage(parseResult.data, callerContextOf(request))
        .then((result) => {
            if (refused(response, result)) return;

            return successResponse(response, result.data, 201);
        })
        .catch(catchAs(response, 'createLocale'));
};

/**
 * PUT /locales/:locale (admin)
 * Edit a language's display names, direction or visibility.
 *
 * The tag is not editable, which is why it is not in the body schema: every entry references it,
 * so changing it would rename a whole dictionary rather than edit this record.
 */
export const updateLocale = (
    request: Request<{ locale: string }, unknown, UpdateLocaleRequest>,
    response: Response
) => {
    const parseResult = UpdateLocaleBody.extend({
        name: displayName.optional(),
        nativeName: displayName.optional()
    }).safeParse(request.body);
    if (!parseResult.success) return Promise.resolve(rejectValidation(response, parseResult.error));

    return localeService
        .updateLanguage(request.params.locale, parseResult.data, callerContextOf(request))
        .then((result) => {
            if (refused(response, result)) return;

            return successResponse(response, result.data);
        })
        .catch(catchAs(response, 'updateLocale'));
};

