import type { Request, Response } from 'express';
import { successResponse, rejectResponse } from '@infrastructure/http/response';
import { auditLogService } from '@modules/audit-logs';
import { t } from '@infrastructure/i18n';
import { catchAs, parseBody } from '@infrastructure/http/controller';
import { readInput } from '@infrastructure/http/request';
import { paginationSchema } from '@infrastructure/http/schemas';

/**
 * GET /observability/audit
 * A page of audit events, filtered by actor, action, outcome and since.
 */
export const getObservabilityAuditLogs = (request: Request, response: Response) => {
    // Through `readInput` like every other route, rather than reaching into `request.query`: the
    // sources a surface reads are a property of the route, not of this handler.
    const input = readInput(request, {
        // `list`: a GET-only route, so the query string is the whole input surface.
        surface: 'list',
        // Declared as ids so a repeated `?since=` collapses to its first entry rather than
        // arriving as an array — these are scalars, and `new Date([…])` is not a date.
        ids: ['actor', 'action', 'outcome', 'since']
    });

    // `page` / `pageSize` are bounded here and answer 422, as on every paged read: this trail
    // has pages, so a page the caller cannot reach is a broken request rather than one to
    // quietly rewrite. `normalizePagination` still owns what an absent page means.
    const pagination = parseBody(paginationSchema, input, response);
    if (!pagination) return;

    const { actor, action, outcome, since } = input;
    const sinceDate = since ? new Date(since) : undefined;

    if (sinceDate !== undefined && Number.isNaN(sinceDate.getTime()))
        return rejectResponse(response, 422, [t('observability.audit-since-invalid')]);

    return auditLogService
        .search({
            // `readInput` answers `unknown` because a query value can arrive repeated; these three
            // are scalars the repository matches verbatim, so they are read as the strings they are.
            actor,
            action,
            // The repository matches `outcome` verbatim, so anything outside the enum is dropped
            // rather than passed through — an unrecognised value must not silently return
            // everything, which is what treating it as "no filter" would do if it reached Mongo.
            outcome: outcome === 'success' || outcome === 'failure' ? outcome : undefined,
            since: sinceDate,
            ...pagination
        })
        .then((result) => successResponse(response, result))
        .catch(catchAs(response, 'getObservabilityAuditLogs'));
};

import type { Request, Response } from 'express';
import os from 'node:os';
import { successResponse } from '@infrastructure/http/response';
import { resolveAnalyticsProvider } from '@infrastructure/observability/analytics';
import { dependencyHealth, overallStatus } from '@infrastructure/observability/dependency-health';
import { processSnapshot } from '@infrastructure/observability/process-snapshot';

/**
 * GET /observability/health
 *
 * The READINESS answer: can this instance serve what it promises, and if not, which part is
 * missing. Liveness — is the process alive at all — is `GET /`, and it is what the container
 * HEALTHCHECK probes; the two are deliberately different endpoints, because an orchestrator
 * restarts on liveness and restarting this process would not bring a downed Redis back.
 *
 * `status` folds every backing service, so a deployment with Mongo up and Redis down reports
 * `degraded` rather than `ok`. `telemetry` sits apart from `dependencies` and is NOT part of that
 * fold: those are sinks this service writes to, and losing one costs visibility rather than
 * capability — an unreachable Loki does not make a checkout fail. They are also configuration
 * flags rather than probes, which is what the separate name says out loud.
 */
export const getObservabilityHealth = (_request: Request, response: Response) => {
    const snapshot = processSnapshot();
    const dependencies = dependencyHealth();
    const analyticsProvider = resolveAnalyticsProvider();

    successResponse(response, {
        status: overallStatus(dependencies),
        environment: process.env.NODE_ENV ?? 'development',
        service: process.env.NODE_SERVICE_NAME ?? 'boilerplate-node-backend',
        runtimeVersion: process.version,
        uptimeSeconds: snapshot.uptimeSeconds,
        /*
         * One vocabulary for three unlike services, so the payload reads without a legend. Objects
         * rather than bare strings: a per-dependency latency or last-error is the obvious next
         * field, and this way adding one is additive.
         */
        dependencies: {
            database: { status: dependencies.database },
            cache: { status: dependencies.cache },
            queue: { status: dependencies.queue }
        },
        /*
         * Which telemetry sinks this deployment is wired to. Booleans read off the environment,
         * never reachability — the previous name, `integrations`, read like a health check and was
         * the reason this block kept being mistaken for one.
         */
        telemetry: {
            loki: Boolean(process.env.NODE_LOKI_HOST),
            otel: Boolean(process.env.OTEL_EXPORTER_OTLP_ENDPOINT),
            /*
             * Frontend observability: the origin a browser loads the Umami tracking script from,
             * plus the Faro collector. Declarative, and NOT the backend's own analytics wiring —
             * that is `analytics` below, which needs a website id this origin says nothing about.
             */
            umami: Boolean(process.env.NODE_UMAMI_HOST),
            faro: Boolean(process.env.NODE_FARO_COLLECTOR_URL),
            /*
             * Which backend receives product events, and whether it can actually deliver them.
             *
             * The name is a deployment choice between three, so `posthog: false` could not
             * distinguish "PostHog is unconfigured" from "this deployment uses Umami". `configured`
             * is the half that was missing: a provider selected without its credentials warns once
             * and then discards every event for the life of the process, and this endpoint —
             * whose job is "which part is missing" — reported a name and looked healthy.
             */
            analytics: {
                provider: analyticsProvider.name,
                configured: analyticsProvider.configured()
            }
        },
        /*
         * Bytes, not megabytes, and the same four fields the SSE stream publishes — so a dashboard
         * showing this card beside the live feed is comparing numbers rather than doing unit
         * arithmetic to find out whether they agree.
         */
        memory: snapshot.memory,
        system: {
            platform: os.platform(),
            cpuCount: os.cpus().length,
            loadAvg: os.loadavg()
        },
        timestamp: new Date().toISOString()
    });
};

import type { Request, Response } from 'express';
import { successResponse, rejectResponse } from '@infrastructure/http/response';
import {
    getHttpRequestCounters,
    httpInflightRequests,
    getLatencyPercentiles,
    metricsRegistry
} from '@infrastructure/observability/metrics-http';
import { processSnapshot } from '@infrastructure/observability/process-snapshot';

/** One sample of a prom-client counter. */
interface MetricSample {
    value: number;
    labels: Record<string, string | number | undefined>;
}

/**
 * Read a domain counter's samples by metric NAME rather than by importing the counter.
 *
 * This is what keeps the dashboard from depending on the domains it reports on. The counters
 * belong to `account`, `cart` and `orders` now; importing them would give this module a
 * `dependsOn` on three domains and make deleting any of them a compile error here — in the one
 * place whose whole job is to survive them.
 *
 * An absent metric is a normal state, not an error: it means the module that owns it is not in
 * this build, and the overview reports zero for that row. The response shape is fixed by
 * `openapi.yaml` and is the same either way, so a client never has to know which modules exist.
 */
const readCounter = async (name: string): Promise<MetricSample[]> => {
    const metric = metricsRegistry.getSingleMetric(name);
    if (!metric) return [];
    const result = (await metric.get()) as { values?: MetricSample[] };
    return result.values ?? [];
};

/**
 * Sum values for a specific label across a prom-client metric result.
 */
const sumByLabel = (values: MetricSample[], labelKey: string, labelValue: string): number =>
    values.filter((v) => v.labels[labelKey] === labelValue).reduce((sum, v) => sum + v.value, 0);

/**
 * GET /observability/metrics/overview
 * Structured JSON overview of key operational metrics.
 */
export const getObservabilityMetricsOverview = (_request: Request, response: Response) =>
    Promise.all([
        getHttpRequestCounters(),
        httpInflightRequests.get(),
        getLatencyPercentiles(),
        readCounter('auth_login_total'),
        readCounter('auth_signup_total'),
        readCounter('cart_checkout_total'),
        readCounter('order_created_total'),
        // Gauges, but read identically: `collect` recounts at scrape time, and an absent metric
        // (inventory module deleted) reads as zero like every other row here.
        readCounter('products_low_stock_total'),
        readCounter('inventory_reserved_units_total')
    ])
        .then(
            ([
                { totalRequests, totalErrors },
                inflightMetric,
                latency,
                loginValues,
                signupValues,
                checkoutValues,
                orderValues,
                lowStockValues,
                reservedValues
            ]) => {
                const snapshot = processSnapshot();
                const inFlight = inflightMetric.values.reduce((s, v) => s + v.value, 0);

                const data = {
                    http: {
                        totalRequests,
                        totalErrors,
                        errorRate: totalRequests > 0 ? totalErrors / totalRequests : 0,
                        inFlight,
                        latencyMs: { p50: latency.p50, p95: latency.p95 }
                    },
                    auth: {
                        loginSuccess: sumByLabel(loginValues, 'status', 'success'),
                        loginFailure: sumByLabel(loginValues, 'status', 'failure'),
                        signupSuccess: sumByLabel(signupValues, 'status', 'success')
                    },
                    business: {
                        checkoutSuccess: sumByLabel(checkoutValues, 'status', 'success'),
                        ordersCreated: orderValues.reduce((s, v) => s + v.value, 0),
                        lowStockProducts: lowStockValues.reduce((s, v) => s + v.value, 0),
                        reservedUnits: reservedValues.reduce((s, v) => s + v.value, 0)
                    },
                    database: {
                        queriesTotal: 0,
                        errorsTotal: 0
                    },
                    process: {
                        uptimeSeconds: snapshot.uptimeSeconds,
                        memory: snapshot.memory
                    },
                    timestamp: new Date().toISOString()
                };

                successResponse(response, data);
            }
        )
        .catch(() => {
            rejectResponse(response, 500);
        });

