import path from 'node:path';
import type { Request, Response } from 'express';
import { getDefaultLocale, t } from '@infrastructure/i18n';
import { orderService } from '../service';
import type { OrderDocument } from '../model';
import { invoiceDocument } from '../emails';
import { rejectResponse } from '@infrastructure/http/response';
import ejs from 'ejs';
import { renderHtmlToPdf } from '@infrastructure/adapters/pdf';
import { isValidObjectId } from '@infrastructure/http/request';
import { catchAs } from '@infrastructure/http/controller';

/**
 * GET /orders/:id/invoice
 * Generate and return a PDF invoice for the order.
 * Non-admin users can only access their own orders.
 *
 * WARNING: Images and other link-related resources will NOT work in the PDF.
 * To embed them, convert images to base64.
 */
export const getOrderInvoice = (request: Request<{ id?: string }>, response: Response) => {
    // 404 on an unusable id, and checked before the query for the reason `get-order-item.ts`
    // spells out: the two role branches raise different error classes for it.
    if (!isValidObjectId(request.params.id)) {
        rejectResponse(response, 404, [t('orders.not-found')]);
        return;
    }

    return orderService
        .getById(request.params.id, orderService.callerScope(request.authContext))
        .then((order) => {
            if (!order) {
                rejectResponse(response, 404, [t('orders.not-found')]);
                return;
            }

            /*
             * `id`, not `_id`. `getById` is polymorphic by scope (see `findByIdScoped`): an admin
             * gets a hydrated document, an owner gets a transformed plain object whose `_id` the
             * serializer deleted. `id` is the half that resolves on both — reading `_id` here put
             * the literal string `undefined` in the filename and in the document's own title for
             * every non-admin. The cast is what `OrderDocument` cannot say: it omits `id`, the
             * house convention for a type that describes the STORED shape, and the wire `id`
             * arrives from the virtual on one branch and the transform on the other.
             */
            const orderId = String((order as OrderDocument & { id?: string }).id ?? order._id);

            /**
             * Create PDF file using the invoice EJS template
             */
            return ejs
                .renderFile(
                    path.resolve('shared', 'views', 'templates-files', 'orders.invoice.ejs'),
                    // Same convention as the email templates: the copy is resolved here, in the
                    // request's language, and the template only interpolates. That is what lets
                    // the identical render run from `workers/pdf.worker.ts`, where there is no
                    // request and no locale to resolve against.
                    invoiceDocument(request.locale ?? getDefaultLocale(), order)
                )
                .then((html) => renderHtmlToPdf(html))
                .then((pdf) => {
                    response
                        .status(200)
                        .setHeader('Content-Type', 'application/pdf')
                        .setHeader(
                            'Content-Disposition',
                            `attachment; filename="invoice-${orderId}.pdf"`
                        )
                        .send(pdf);
                });
        })
        .catch(catchAs(response, 'Invoice generation failed'));
};

import type { Request, Response } from 'express';
import { t } from '@infrastructure/i18n';
import { orderService } from '../service';
import { successResponse, rejectResponse } from '@infrastructure/http/response';
import { isValidObjectId } from '@infrastructure/http/request';
import { catchAs } from '@infrastructure/http/controller';

/**
 * GET /orders/:id
 * Get a single order by path id.
 * Non-admin users can only access their own orders.
 *
 * An id that is not a usable ObjectId is a 404 here, as it is on every other single-item read
 * (`get-product-item.ts`, `get-user-item.ts`): it names no order, which is the same thing a
 * well-formed id matching nothing means.
 *
 * It is checked BEFORE the query rather than caught after it, because the two role branches fail
 * differently. The admin branch is a `findById`, which raises a Mongoose `CastError`; the scoped
 * branch is an aggregate whose `$match` coerces the id itself, which raises a driver `BSONError`
 * — and the response layer reads that one as 422. Answering on the error class therefore made the
 * status depend on WHO asked, for the same malformed value.
 */
export const getOrderItem = (request: Request<{ id?: string }>, response: Response) => {
    if (!isValidObjectId(request.params.id)) {
        rejectResponse(response, 404, [t('orders.not-found')]);
        return;
    }

    /**
     * User role filters:
     * Only admin can see all orders. Regular users can only see their own.
     */
    return orderService
        .getById(request.params.id, orderService.callerScope(request.authContext))
        .then((order) => {
            if (!order) {
                rejectResponse(response, 404, [t('orders.not-found')]);
                return;
            }
            // The body carries what THIS caller may do to the order, so the client renders its
            // controls from the server's answer rather than from a copy of the lifecycle.
            successResponse(response, orderService.withActions(order, request.authContext));
        })
        .catch(catchAs(response, 'getOrderItem'));
};

import type { Request, Response } from 'express';
import type { ParamsDictionary } from 'express-serve-static-core';
import { SearchOrdersBody } from '@api/schemas.zod';
import { orderService } from '../service';
import { successResponse } from '@infrastructure/http/response';
import { readInput, callerContextOf } from '@infrastructure/http/request';
import { pageSchema, pageSizeSchema } from '@infrastructure/http/schemas';
import type { SearchOrdersRequest } from '@types';
import { catchAs, parseBody } from '@infrastructure/http/controller';

/**
 * Query parameters generated by the search form (they are the same as SearchOrdersRequest keys)
 */
export type GetOrdersQuery = Partial<Record<keyof SearchOrdersRequest, string>>;

/**
 * Built on the orval-generated SearchOrdersBody (kept in sync with
 * openapi.yaml); page/pageSize are coerced from strings since GET requests
 * carry them as query-string text, not JSON numbers.
 *
 * `page`/`pageSize` come from `@infrastructure/http/schemas` so all four search endpoints agree on what a
 * legal one is; absent stays absent, because `normalizePagination` owns the defaults.
 */
const searchOrdersQuerySchema = SearchOrdersBody.extend({
    page: pageSchema,
    pageSize: pageSizeSchema
});

/**
 * Query parameters that change this endpoint's answer, and therefore its cache key.
 *
 * Derived from the schema rather than hand-listed, because the two must not drift: a parameter
 * the controller reads but the key omits would let two different requests share one cached
 * response. Anything outside this list is stripped by the validator and changes nothing.
 */
export const searchOrdersKeyParameters = Object.keys(searchOrdersQuerySchema.shape);

/**
 * GET /orders
 * List/search orders via query parameters or request body.
 * Non-admin users are automatically scoped to their own orders; the userId filter is ignored for non-admin callers.
 */
export const getOrders = (
    request: Request<ParamsDictionary, unknown, SearchOrdersRequest, GetOrdersQuery>,
    response: Response
) => {
    const isAdmin = Boolean(request.authContext?.admin);
    // One declaration instead of a per-field assembly — see docs/theory/request-input.md.
    const input = readInput(request, { surface: 'search', ids: ['id'] });

    const parsed = parseBody(
        searchOrdersQuerySchema,
        {
            ...input,
            /* Non-admin callers cannot filter by arbitrary userId; orderService.callerScope enforces their own. */
            userId: isAdmin ? (input.userId as string | undefined) : undefined
        },
        response
    );
    if (!parsed) return;

    return orderService
        .search(parsed, orderService.callerScope(request.authContext), callerContextOf(request))
        .then((result) => {
            successResponse(response, result);
        })
        .catch(catchAs(response, 'getOrders'));
};

