import type { Request, Response } from 'express';
import { successResponse } from '@infrastructure/http/response';
import { ConfirmPaymentBody } from '@api/schemas.zod';
import { paymentConfirmTotal } from '../metrics';
import { paymentService } from '../service';
import { callerContextOf } from '@infrastructure/http/request';
import { catchAs, refused, rejectValidation } from '@infrastructure/http/controller';

/**
 * POST /payments/:id/confirm
 * The card dialog's submit — where the money moves, so where the events fire.
 *
 * A decline is reported like any refusal (409, `PAYMENT_DECLINED`) but still counted and
 * audited: a support thread about a payment starts with "was it us or the card", and the audit
 * row answers it.
 */
export const postPaymentConfirm = (request: Request<{ id?: string }>, response: Response) => {
    const parseResult = ConfirmPaymentBody.safeParse(request.body ?? {});
    if (!parseResult.success) {
        rejectValidation(response, parseResult.error);
        return Promise.resolve();
    }

    const paymentId = String(request.params.id);
    return paymentService
        .confirmPayment(
            paymentId,
            { cardNumber: parseResult.data.cardNumber },
            request.authContext,
            callerContextOf(request)
        )
        .then((result) => {
            const declined =
                !result.success && result.errors.some(({ code }) => code === 'PAYMENT_DECLINED');
            if (result.success || declined)
                paymentConfirmTotal.inc({ outcome: result.success ? 'succeeded' : 'declined' });

            if (refused(response, result)) return;
            successResponse(response, result.data, 200, result.message);
        })
        .catch(catchAs(response, 'postPaymentConfirm'));
};

import type { Request, Response } from 'express';
import { successResponse } from '@infrastructure/http/response';
import { CreatePaymentIntentBody } from '@api/schemas.zod';
import { paymentService } from '../service';
import { catchAs, refused, rejectValidation } from '@infrastructure/http/controller';

/**
 * POST /payments/intent
 * Freeze an order's price into a payment intent, ready to confirm.
 *
 * Thin on purpose: ownership, the `pending` gate and the amount all live in the service. No
 * audit and no analytics here — an intent is a page load's preparation, not a business event;
 * the events fire on the confirm, where money actually moves.
 */
export const postPaymentIntent = (request: Request, response: Response) => {
    const parseResult = CreatePaymentIntentBody.safeParse(request.body ?? {});
    if (!parseResult.success) {
        rejectValidation(response, parseResult.error);
        return Promise.resolve();
    }

    return paymentService
        .createIntent(parseResult.data.orderId, request.authContext)
        .then((result) => {
            if (refused(response, result)) return;
            successResponse(response, result.data, 201);
        })
        .catch(catchAs(response, 'postPaymentIntent'));
};

import type { Request, Response } from 'express';
import { successResponse } from '@infrastructure/http/response';
import { paymentService } from '../service';
import { catchAs, refused } from '@infrastructure/http/controller';

/**
 * POST /payments/order/:orderId/refund
 * Return an order's money without touching its status — the operator's standalone refund.
 *
 * Admin-only at the route. "Cancel and refund" is a client sending this and the order cancel;
 * keeping them separate is what lets an operator do either one alone.
 */
export const postPaymentRefund = (request: Request<{ orderId?: string }>, response: Response) =>
    paymentService
        .refundByOrder(String(request.params.orderId), request.authContext)
        .then((result) => {
            if (refused(response, result)) return;
            successResponse(response, result.data, 200, result.message);
        })
        .catch(catchAs(response, 'postPaymentRefund'));

