/**
 * The database overlay: admin-edited copy applied on top of the deployed dictionaries.
 *
 * The files under `./catalog` are DEFAULTS; this tier overrides them. Three properties it keeps:
 * nothing here is awaited on the request path, a refresh restores the file baseline BEFORE
 * re-applying, and only a language with a file can be overridden.
 *
 * This is the tier a project is most likely to want gone. It imports `./catalog` and nothing
 * imports it back, so deleting this file and its two lines in the boot sequence removes the
 * feature — which is the point of it being a file rather than a section.
 *
 * See: docs/tools/i18n.md#database-overrides
 */

import i18next from 'i18next';
import { logger } from '@infrastructure/adapters/logger';
import { listSupportedLocales, readLocaleDictionary } from './catalog';
import { environmentNumber } from '@infrastructure/runtime/environment';

/**
 * Supplies the current overrides, keyed by locale, already nested.
 *
 * Nested rather than flat because the rows are flat and only the `locales` module knows how to
 * expand a dotted key safely — that expansion refuses `__proto__` and reports a key that is both a
 * string and a group, neither of which `infrastructure` should be reimplementing.
 *
 * Registered from the composition root for the same reason `registerLocaleDirectories` is:
 * `infrastructure` sits below every module and may not import one.
 */
export type LocaleOverrideProvider = () => Promise<Record<string, Record<string, unknown>>>;

let overrideProvider: LocaleOverrideProvider | undefined;

/**
 * Declare where overrides come from, replacing any previous provider.
 *
 * Unregistered is a valid state and the default one: unit tests that resolve a key without booting
 * the app get the deployed files and nothing else.
 */
export const registerLocaleOverrideProvider = (provider?: LocaleOverrideProvider): void => {
    overrideProvider = provider;
};

/**
 * Restore every supported language to its deployed files, dropping any applied override.
 *
 * The path a failed refresh does NOT take — a provider that throws leaves the last good overlay in
 * place, because stale copy beats copy that reverts itself every time Mongo hiccups. This exists
 * for shutdown and for tests, which need a clean instance rather than a plausible one.
 */
export const resetLocaleOverrides = (): void => {
    for (const locale of listSupportedLocales())
        i18next.addResourceBundle(locale, 'translation', readLocaleDictionary(locale), true, true);
};

/**
 * Re-apply the file baseline and layer the current overrides on top of it.
 *
 * `deep` and `overwrite` are both on: an override names one leaf, and the other keys of its
 * namespace must survive the merge.
 *
 * @param overridesByLocale - nested override trees, keyed by locale
 */
export const applyLocaleOverrides = (
    overridesByLocale: Record<string, Record<string, unknown>>
): void => {
    const supported = new Set(listSupportedLocales());

    /*
     * EVERY supported language is restored, not only the ones this call carries overrides for —
     * otherwise deleting the last override of a language would restore nothing and change nothing.
     *
     * Synchronous to the end of the loop below, so nothing observes a language briefly back on its
     * file.
     */
    resetLocaleOverrides();

    const skipped: string[] = [];

    for (const [locale, overrides] of Object.entries(overridesByLocale)) {
        if (!supported.has(locale)) {
            skipped.push(locale);
            continue;
        }

        i18next.addResourceBundle(locale, 'translation', overrides, true, true);
    }

    if (skipped.length > 0)
        logger.warn(
            'applyLocaleOverrides - overrides stored for languages this API cannot answer',
            {
                detail: `no dictionary file is deployed for ${skipped.join(', ')}; rows ignored`
            }
        );
};

/**
 * Pull the current overrides and apply them. Never rejects.
 *
 * Swallowing the failure is the whole point: this runs at boot, on a timer and after every admin
 * write, and none of those callers has a user to report to. A database that cannot be read costs
 * the overrides and nothing else.
 */
export const refreshLocaleOverrides = (): Promise<void> => {
    if (!overrideProvider) return Promise.resolve();

    return overrideProvider()
        .then((overrides) => applyLocaleOverrides(overrides))
        .catch((error: unknown) => {
            logger.warn(
                'refreshLocaleOverrides - locale overrides unavailable, keeping the last set',
                {
                    detail: error instanceof Error ? error.message : String(error)
                }
            );
        });
};

/** How long a worker may serve copy edited by another worker. */
export const getOverrideRefreshMs = (): number =>
    environmentNumber('NODE_LOCALE_OVERRIDE_REFRESH_MS', 60_000, 1);

let refreshTimer: NodeJS.Timeout | undefined;

/**
 * Start re-reading the overrides on an interval, so an edit made on one worker reaches the others.
 *
 * `unref` so the timer never holds the process open — a worker with nothing left to do must exit,
 * and a pending copy refresh is not a reason to stay.
 */
export const startLocaleOverrideRefresh = (): void => {
    if (refreshTimer) return;
    refreshTimer = setInterval(() => void refreshLocaleOverrides(), getOverrideRefreshMs());
    refreshTimer.unref();
};

/** Stop the interval. Called by the shutdown path and by tests. */
export const stopLocaleOverrideRefresh = (): void => {
    if (!refreshTimer) return;
    clearInterval(refreshTimer);
    refreshTimer = undefined;
};

src/infrastructure/observability/analyti.source:
/**
 * Product analytics — the port, and the registry of implementations behind it.
 *
 * Distinct from metrics and tracing: this answers PRODUCT questions ("how many users abandon
 * checkout?") rather than operational ones. Callers do not know where an event lands; which
 * implementation answers is a deployment decision (`NODE_ANALYTICS_PROVIDER`), the same shape
 * `NODE_PAYMENT_PROVIDER` uses.
 *
 * Default `umami` — the one this repo's compose stack starts. `posthog` when the funnel is
 * identity-shaped, `none` for a deployment that collects nothing.
 *
 * See: docs/tools/analytics.md
 */

import { getActiveSpanContext } from '@infrastructure/observability/tracer';
import type { CallerContext } from '@infrastructure/http/request';
import { umamiAnalyticsProvider } from './umami';
import { posthogAnalyticsProvider } from './posthog';
import { noneAnalyticsProvider } from './none';

// ─── Event taxonomy ───────────────────────────────────────────────────────────

/**
 * Module name → that module's event names. Augmented per module; see `modules/cart/analytics.ts`.
 *
 * Intentionally empty here, exactly like `AuditActionMap` in `../audit.ts` and `DomainEventMap` in
 * `kernel/events.ts`: this is the extension point, and its members live with the domains that emit
 * them. The augmentation is type-only, so the vocabulary stays closed and `infrastructure` still
 * imports nothing from a module.
 *
 * `PRODUCTS_SEARCHED` is a fact about products and `CART_ITEM_ADDED` one about the cart. Both used
 * to be declared here, in the layer that must know no domain at all; now deleting a module takes
 * its names out of the funnel with it, and this file is left holding the transport.
 */
// eslint-disable-next-line @typescript-eslint/no-empty-object-type -- a declaration-merging seam: each module augments this map with its own events
export interface AnalyticsEventMap {}

/**
 * Every name this build can emit — whatever the enabled modules declare.
 *
 * The union is exactly the SERVER's half of one namespace shared with the paired frontend. The
 * client's half is declared in `shared/contracts/analytics.frontend.ts` and deliberately augments
 * nothing here, so `emitAnalyticsEvent` rejects a client name: this service cannot report a moment
 * it never observed, and no event can be written into Umami twice.
 */
export type AnalyticsEventName = AnalyticsEventMap[keyof AnalyticsEventMap];

// ─── Payload schema ───────────────────────────────────────────────────────────

/**
 * Core fields shared by every analytics event.
 *
 * The last three are attribution, and they exist because a server-side event has no browser
 * behind it: without the caller's address and user-agent forwarded on, every event the API emits
 * would be attributed to the API itself, collapsing an entire product's traffic onto one
 * "visitor". They are optional because a provider keyed on user id has no use for them.
 */
export interface AnalyticsEvent {
    /** Authenticated user ID, or `anonymous`. PostHog's `distinct_id`; a property under Umami. */
    distinctId: string;
    /** Event name, from the declaring module's own catalogue. */
    event: AnalyticsEventName;
    /**
     * When the event happened, if that is not now. PostHog-only: Umami's `/api/send` declares no
     * timestamp field (checked against v2.14.0, the pinned image) and stamps ingest time, so an
     * event replayed by a backfill lands under the wrong date there.
     */
    timestamp?: Date;
    /** OTel trace ID for cross-signal correlation. */
    traceId?: string;
    /** Any domain-specific context. */
    properties?: Record<string, unknown>;
    /** Address of the client that caused this event, for visitor attribution. */
    clientIp?: string;
    /** User-agent of that client. Umami DISCARDS an event that arrives without one — see `umami.ts`. */
    userAgent?: string;
    /** Host the request was addressed to, so events can be split per deployment. */
    hostname?: string;
}

// ─── The port ────────────────────────────────────────────────────────────────

/** The seam an analytics backend plugs into. Three implementations ship; see the registry below. */
export interface AnalyticsProvider {
    /** Reported by `GET /observability/health` as `integrations.analytics`. */
    name: string;

    /**
     * Record one event. Fire-and-forget by contract: analytics must never delay or fail a user
     * request, so this returns nothing and an implementation that fails does so quietly.
     */
    capture(event: AnalyticsEvent): void;

    /**
     * Whether this provider has what it needs to deliver an event.
     *
     * `capture` is fire-and-forget, so a provider selected without its credentials warns once and
     * then discards silently for the life of the process — the most common analytics failure there
     * is, and one nothing outside the provider could observe. `none` answers `true`: collecting
     * nothing IS its configuration.
     */
    configured(): boolean;

    /**
     * Flush anything buffered and release the client.
     *
     * Called last in the shutdown chain (`runtime/server-lifecycle`). A provider that batches
     * loses its buffer on every deploy without this.
     */
    shutdown(): Promise<void>;
}

// ─── Registry ────────────────────────────────────────────────────────────────

/** Every implementation this build knows. A typo'd env value must fail loudly, not fall back. */
const PROVIDERS: Record<string, AnalyticsProvider> = {
    umami: umamiAnalyticsProvider,
    posthog: posthogAnalyticsProvider,
    none: noneAnalyticsProvider
};

let provider: AnalyticsProvider | undefined;

/**
 * The configured provider, memoised on first use.
 *
 * Read lazily rather than at import time because tests vary the environment per case, and
 * because an env var read during module evaluation is fixed before `.env` has necessarily
 * been loaded.
 *
 * @returns the implementation `NODE_ANALYTICS_PROVIDER` names (default `umami`)
 * @throws when the env names a provider this build does not carry — a deployment
 *   misconfiguration that must surface at boot, not as analytics that silently record nothing
 */
export const resolveAnalyticsProvider = (): AnalyticsProvider => {
    if (provider) return provider;
    const name = process.env.NODE_ANALYTICS_PROVIDER ?? 'umami';
    const resolved = PROVIDERS[name] as (typeof PROVIDERS)[string] | undefined;
    if (!resolved)
        throw new Error(
            `Unknown analytics provider "${name}" — known: ${Object.keys(PROVIDERS).join(', ')}`
        );
    provider = resolved;
    return provider;
};

/** Test seam, like the mailer's `resetTransporter`. */
export const resetAnalyticsProvider = (): void => {
    provider = undefined;
};

// ─── Emit helpers ────────────────────────────────────────────────────────────

/**
 * Build the fields every call site would otherwise repeat.
 *
 * Typed as `Pick<...>` so it stays in lockstep with `AnalyticsEvent`: renaming a field there
 * breaks this signature at compile time instead of silently producing a wrong shape.
 * Usage: `emitAnalyticsEvent({ ...buildAnalyticsBase(context), event: cartAnalyticsEvents.CART_VIEWED })`
 *
 * @param context - the caller context built once in the controller, see `callerContextOf`
 */
export const buildAnalyticsBase = (
    context: CallerContext
): Pick<AnalyticsEvent, 'distinctId' | 'traceId' | 'clientIp' | 'userAgent' | 'hostname'> => ({
    // CAVEAT: unauthenticated traffic all collapses onto the literal 'anonymous' id, so
    // pre-login events cannot be told apart per visitor *by this field*. Under Umami the
    // IP + user-agent hash below still separates them; under PostHog they do not separate.
    distinctId: context.caller.id ?? 'anonymous',
    // Read from the ambient OTel context — no plumbing needed at the call site. Safe unlike a
    // "current request" accessor would be: OTel's context manager is built to survive exactly
    // the async hops a service-tier call adds, which is not true of an ad hoc ALS lookup.
    traceId: getActiveSpanContext().traceId,
    clientIp: context.ip,
    userAgent: context.userAgent,
    hostname: context.host
});

/**
 * Send one product analytics event to the configured provider.
 *
 * Returns `void` (fire-and-forget): analytics must never delay or fail a user request, so there
 * is nothing to await and nothing to handle.
 */
export const emitAnalyticsEvent = (event: AnalyticsEvent): void => {
    resolveAnalyticsProvider().capture(event);
};

/**
 * Flush pending events and release the provider's client on server stop.
 *
 * Resolves without doing anything when no provider was ever resolved — a process that emitted
 * no events has nothing to flush, and resolving one here purely to shut it down would turn a
 * misconfigured `NODE_ANALYTICS_PROVIDER` into a crash on the way out.
 */
export const shutdownAnalytics = (): Promise<void> => {
    if (!provider) return Promise.resolve();
    return provider.shutdown().then(() => {
        // Clear the handle so a restarted app (or a test) builds a fresh client rather than
        // reusing a shut-down one, whose `capture()` calls would silently do nothing.
        provider = undefined;
    });
};

src/infrastructure/observability/process.source:
/**
 * One reading of the process, in the units the process reports.
 *
 * Three payloads describe this process: the SSE frame built in `./stream.ts`, and the two REST
 * endpoints in `modules/observability/controllers/`. All three read from here, and the cost of
 * each calling `process.memoryUsage()` and `process.uptime()` for itself is larger than the
 * duplication suggests: three readings taken at three instants can disagree, and a rounding that
 * differs between them — `Math.round` against `Math.floor` — has the health endpoint and the live
 * stream reporting uptimes a second apart forever, with no bug behind it.
 *
 * The wire units are bytes everywhere. Megabytes is a
 * PRESENTATION decision and a lossy one: `heapUsedMb: 41` cannot tell a leak hunter whether the
 * heap moved by 400 KB between two polls, which is exactly what a dashboard differencing
 * consecutive frames is looking for. The API states the measurement; whoever renders it states the
 * formatting.
 *
 * ## The one reading that must NOT come from here
 *
 * `./metrics-http.ts` reads `process.uptime()` inside a prom-client `Gauge`, whose `collect()` runs
 * at scrape time. It is not composing a payload — it is answering someone else's contract at the
 * instant that contract asks. Folding it in here would make it report a value from the wrong
 * moment. `tests/cross-cutting/process-snapshot.test.ts` allows that one call by name and forbids
 * every other reading in `src/`, so the fourth copy has somewhere to go instead of somewhere to
 * appear.
 */

/** Process memory in bytes — the four fields every payload publishes, and no more. */
export interface ProcessMemorySnapshot {
    /**
     * Resident Set Size — total physical memory held by the process, the number that matters
     * against a container memory limit.
     */
    rss: number;
    /** Live JS objects. Steady growth across restart-free uptime = likely leak. */
    heapUsed: number;
    /** Heap currently allocated from the OS (`heapUsed` <= `heapTotal`). */
    heapTotal: number;
    /** Off-heap memory bound to JS objects — Buffers, and native addon allocations. */
    external: number;
}

/** The process at one instant: memory in bytes, uptime in whole seconds. */
export interface ProcessSnapshot {
    /**
     * Seconds since process start, floored.
     *
     * Floored rather than rounded, and the same way in all three payloads. Every contract types
     * this `integer`, so the choice decides nothing except whether two endpoints polled together
     * are allowed to disagree — and they are not.
     */
    uptimeSeconds: number;
    memory: ProcessMemorySnapshot;
}

/**
 * Read the process once.
 *
 * Both underlying calls happen together, so every number in one snapshot describes the same
 * instant — which is the property three separate readings could not offer.
 */
export const processSnapshot = (): ProcessSnapshot => {
    const memory = process.memoryUsage();

    return {
        uptimeSeconds: Math.floor(process.uptime()),
        /*
         * Picked field by field rather than spread. `process.memoryUsage()` also returns
         * `arrayBuffers`, which appears in none of the three contracts — a spread would publish it,
         * and would publish whatever Node adds next along with it.
         */
        memory: {
            rss: memory.rss,
            heapUsed: memory.heapUsed,
            heapTotal: memory.heapTotal,
            external: memory.external
        }
    };
};

