/**
 * Order rules. Pure: data in, verdict out — no status codes, no i18n; `service.ts` maps verdicts.
 * See `docs/theory/domain-layer.md`.
 */

/** A line as the rules see it. Absent `product` means the reference no longer resolves. */
export interface OrderLineCandidate {
    quantity?: number;
    product?: unknown;
}

export type OrderLinesVerdict =
    | { ok: true }
    | { ok: false; reason: 'no-lines' }
    | { ok: false; reason: 'product-missing' };

/**
 * Can these lines become an order?
 * Order matters: the two reasons map to different status codes.
 * @param lines - candidate lines, already joined to their products
 * @returns `ok`, or the reason the whole set is refused
 */
export const checkOrderLines = (lines: readonly OrderLineCandidate[]): OrderLinesVerdict => {
    if (lines.length === 0) return { ok: false, reason: 'no-lines' };
    if (lines.some(({ product }) => product === undefined || product === null))
        return { ok: false, reason: 'product-missing' };
    return { ok: true };
};

src/modules/orders/domain/totals.ts.source:
/**
 * Order totals — what a list of priced lines adds up to, and what the customer owes on top of it.
 *
 * Owned by `orders`; `cart` and `payments` read it through the barrel, so a cart summary, the
 * order it previews and the intent that freezes it can never disagree. Same number, three names,
 * because `openapi.yaml` names it per resource:
 *
 * | here       | Order           | CartSummary     |
 * |------------|-----------------|-----------------|
 * | `count`    | `totalItems`    | `itemsCount`    |
 * | `quantity` | `totalQuantity` | `totalQuantity` |
 * | `price`    | `totalPrice`    | `total`         |
 *
 * The arithmetic runs in minor units and converts once on the way out — see `money.ts`. Nothing
 * here rounds, because there is nothing to round.
 */

import {
    addMoney,
    scaleMoney,
    toDecimalAmount,
    toMinorUnits,
    wholeCount,
    type Money,
    NO_MONEY
} from './money';

/** A priced line. Loose: order items arrive as raw aggregate output, cart items as DTOs. */
export interface LineItem {
    quantity?: unknown;
    /** `unknown` because it is raw aggregate output; `null` is an unpopulated ref. */
    product?: { price?: unknown } | null;
}

export interface LineItemTotals {
    /** Number of distinct line items. */
    count: number;
    /** Sum of `quantity` across every line, as whole units. */
    quantity: number;
    /** Sum of `product.price × quantity` across every line, as a decimal amount. */
    price: number;
}

/**
 * Sum a list of priced line items.
 *
 * Total by construction: `toMinorUnits` and `wholeCount` absorb junk, so a line whose product
 * failed to populate contributes nothing rather than turning the total into `NaN`.
 *
 * @param items - the priced lines
 * @returns line count, total quantity and the total as a decimal amount
 */
export const sumLineItems = (items: readonly LineItem[]): LineItemTotals => {
    let quantity = 0;
    let price: Money = NO_MONEY;

    for (const item of items) {
        // One reading of the quantity for both columns — counted and charged must be the same units.
        const itemQuantity = wholeCount(item.quantity);
        quantity += itemQuantity;
        price = addMoney(price, scaleMoney(toMinorUnits(item.product?.price), itemQuantity));
    }

    // `count` is lines as given; `quantity` is units. A dropped line still counts as a line.
    return { count: items.length, quantity, price: toDecimalAmount(price) };
};

/** An order, as far as its grand total is concerned. */
export interface OrderTotalInput {
    items: readonly LineItem[];
    /**
     * The shipping cost frozen at checkout. `unknown` because it arrives as raw aggregate output,
     * optional because a checkout that chose no delivery method owes nothing for shipping.
     */
    shippingCost?: unknown;
}

/**
 * What the customer owes: the lines plus the shipping frozen against them.
 *
 * `money.ts` owns rounding; this owns composition. Three callers must agree on this number — the
 * order, the payment intent and the confirmation email — so none of them sums it themselves.
 *
 * @param order - the order's lines and its frozen shipping cost
 * @returns the grand total as the decimal amount the contract publishes
 */
export const orderTotal = ({ items, shippingCost }: OrderTotalInput): number =>
    toDecimalAmount(addMoney(toMinorUnits(sumLineItems(items).price), toMinorUnits(shippingCost)));

