src/modules/payments/providers/index.ts.source:
/**
 * The payment provider port — the seam a real PSP plugs into.
 *
 * The module's service talks to this interface and nothing else: amounts, cards and refunds go
 * through it, and which implementation answers is a deployment decision (`NODE_PAYMENT_PROVIDER`),
 * not a code path. The boilerplate ships `fake` (see `./fake`); a project that goes live writes
 * `stripe.ts` beside it, adds one line to the registry below, and changes one env var — the
 * contract, the service and the frontend never hear about it.
 *
 * Same shape as `ImageStore` in `@infrastructure/adapters/image-store`, with the selection made
 * env-driven the way the mailer picks its transport: read lazily inside the function (tests vary
 * the environment per case) and memoised. No `reset` seam, unlike the mailer's: one build ships one
 * provider, so nothing has ever needed to swap it mid-run.
 */

import { fakePaymentProvider } from './fake';
import type { CardDetails } from './card';

export { cardLastFour, type CardDetails } from './card';

/** What a charge attempt can come back as. Everything else a provider can say is a throw. */
export type ChargeOutcome = 'succeeded' | 'declined';

export interface PaymentProvider {
    /** The name persisted on each payment document, so a row says who handled it. */
    name: string;

    /**
     * Attempt to take the money.
     *
     * @param charge - the frozen amount and its currency
     * @param card - the customer's card
     * @returns the outcome — a decline is an answer, not an error; only transport-level
     *   failures throw
     */
    charge(charge: { amount: number; currency: string }, card: CardDetails): Promise<ChargeOutcome>;

    /**
     * Return the money of a succeeded charge. Idempotent at the provider's side; the caller
     * guards its own side by only refunding a `succeeded` payment.
     */
    refund(charge: { amount: number; currency: string }): Promise<void>;
}

/** Every implementation this build knows. A typo'd env value must fail loudly, not fall back. */
const PROVIDERS: Record<string, PaymentProvider> = {
    fake: fakePaymentProvider
};

let provider: PaymentProvider | undefined;

/**
 * The configured provider, memoised on first use.
 *
 * @returns the implementation `NODE_PAYMENT_PROVIDER` names (default `fake`)
 * @throws when the env names a provider this build does not carry — a deployment
 *   misconfiguration that must surface at the first payment, not as silent fake charges
 */
export const resolvePaymentProvider = (): PaymentProvider => {
    if (provider) return provider;
    const name = process.env.NODE_PAYMENT_PROVIDER ?? 'fake';
    const resolved = PROVIDERS[name] as (typeof PROVIDERS)[string] | undefined;
    if (!resolved)
        throw new Error(
            `Unknown payment provider "${name}" — known: ${Object.keys(PROVIDERS).join(', ')}`
        );
    provider = resolved;
    return provider;
};

src/infrastructure/observability/metrics.source:
/**
 * Cache metrics (Prometheus).
 *
 * One counter, and it exists because a log line is not alertable. See `metrics-http.ts` for why
 * infrastructure registers its own metrics against the shared registry.
 */

import { Counter } from 'prom-client';
import { metricsRegistry } from './metrics-http';

/**
 * Invalidations that could not reach Redis, by tag.
 *
 * The failure this makes visible: a write succeeds, its cached predecessor is NOT removed, and the
 * stale response is served for the endpoint's full TTL. The response has already been sent by the
 * time this is known, so observability is the only possible action — which is the point. A rate
 * above zero here means the catalogue is lying to somebody.
 */
export const cacheInvalidationFailuresTotal = new Counter({
    name: 'cache_invalidation_failures_total',
    help: 'Cache invalidations that could not reach Redis, so stale responses survive their write.',
    // Bounded by construction: tags are literals declared on the routes, never request data.
    labelNames: ['tag'] as const,
    registers: [metricsRegistry]
});

src/infrastructure/persistence/factory.t.source:
/**
 * The bit of fixture-building every module's `factory.ts` would otherwise repeat: an `_id`, a pair
 * of timestamps, and the type of the overrides bag. In `infrastructure` for the same reason
 * `./seed` is — it knows a document has an `_id` and nothing about what the document means.
 *
 * TIMESTAMPS ARE PINNED, not left to Mongoose: the seed export commits what it reads back, so a
 * `createdAt` of "whenever the export ran" would make the artefact permanently stale. Fixtures
 * state their own dates and the seeder saves with `{ timestamps: false }`.
 *
 * It does NOT guarantee the three dates make sense together — a test that cares about ordering
 * states the dates it needs, and every factory takes them.
 */

import { Types } from 'mongoose';

/** What every factory accepts on top of its own fields. */
export interface FactoryIdentity {
    /** 24-char hex. Omitted outside the seed dataset, where a fresh id is what a test wants. */
    id?: string;
    createdAt?: Date | string;
    updatedAt?: Date | string;
}

/**
 * A factory's overrides bag, derived from the contract entity it builds.
 *
 * This exists so a factory never restates a field list. `openapi.yaml` is the source of truth in
 * this repo, orval turns it into `api/models`, and those models already say what a Product or a
 * User has — so a hand-written `{ title?: string; price?: number; … }` beside them is a second
 * declaration that a contract change cannot reach. Deriving means a field renamed in the spec turns
 * every stale call site red at `tsc` time instead of at nobody's time.
 *
 * Three fields are replaced rather than inherited, and all for the same reason: the wire carries ISO
 * strings where Mongoose stores `Date`s. `id`, `createdAt` and `updatedAt` come from
 * `FactoryIdentity`; `deletedAt` is widened here to accept either.
 */
export type OverridesFor<TEntity> = FactoryIdentity &
    Partial<Omit<TEntity, 'id' | 'createdAt' | 'updatedAt' | 'deletedAt'>> & {
        deletedAt?: Date | string;
    };

/**
 * Drop keys whose value is `undefined`.
 *
 * A factory spreads its caller's overrides over its own defaults, and `{ stock: undefined }` from a
 * caller that built the object conditionally would otherwise WIN — turning "I did not say" into an
 * explicit `undefined` that shadows the default. It also matters downstream: the whole point of a
 * factory that omits a field is to let the model's own `default:` fill it, so the export records
 * what the schema really does instead of what a fixture guessed it does.
 */
export const compact = <T extends Record<string, unknown>>(source: T): T =>
    Object.fromEntries(Object.entries(source).filter(([, value]) => value !== undefined)) as T;

/**
 * A wire date as the document stores it, `undefined` passing straight through.
 *
 * The contract carries ISO strings and Mongoose stores `Date`s, so every factory has one of these
 * on every date field. Paired with `compact`, an absent date leaves no key behind — which is what
 * keeps `deletedAt` a field that is either present or missing, never present-and-undefined.
 */
export const toDate = (value: Date | string | undefined): Date | undefined =>
    value === undefined ? undefined : new Date(value);

/** `undefined` → a fresh id, a string → the pinned one. */
export const toObjectId = (id?: string): Types.ObjectId =>
    id === undefined ? new Types.ObjectId() : new Types.ObjectId(id);

/**
 * Turn a factory's identity fields into the three columns a fixture pins.
 *
 * An unstated `createdAt` is read off the `_id`. An ObjectId's leading four bytes ARE a creation
 * timestamp, so a pinned fixture id already carries the date the record was made — `65dc8a99…` is
 * 2024-02-26 — and a fresh one carries now. That is one code path for both cases, it invents no
 * dates, and it needs no second constant maintained alongside the ids.
 *
 * `updatedAt` follows `createdAt` unless stated: a record that has never been edited should say so.
 *
 * Note the precision. `getTimestamp()` is second-granular, so fixtures built in the same tick share
 * a `createdAt` exactly. A test that sorts or paginates by it must pass its own dates; see the
 * header for why that is the caller's job rather than this file's.
 */
export const identityOf = ({
    id,
    createdAt,
    updatedAt
}: FactoryIdentity): { _id: Types.ObjectId; createdAt: Date; updatedAt: Date } => {
    const objectId = toObjectId(id);
    const created = createdAt === undefined ? objectId.getTimestamp() : new Date(createdAt);
    return {
        _id: objectId,
        createdAt: created,
        updatedAt: updatedAt === undefined ? created : new Date(updatedAt)
    };
};

