/**
 * Who the two demo accounts are: their ids, and how to log in as them.
 *
 * In the kernel rather than in `users` because four modules need a handle on these people and only
 * one owns the record — sharing six string literals here costs less than three registry edges.
 *
 * Two constraints before editing: the credentials must stay fixed (the frontend's e2e login types
 * them, both READMEs quote them), and the password stays PLAINTEXT (the schema's pre-save hook
 * hashes it; a hash written here would drift from that hook).
 *
 * See: docs/tools/demo-profile.md#the-two-seed-accounts
 */

/** 24-char hex, and a real ObjectId: its leading bytes date the account to February 2024. */
export const SEED_ADMIN_ID = '65dd2bdb923652b7800fe180';
export const SEED_USER_ID = '65de646a44f861fd83c13f13';

export const SEED_ADMIN_EMAIL = 'root@root.it';
export const SEED_ADMIN_PASSWORD = 'rootroot';
export const SEED_USER_EMAIL = 'gino@pino.it';
export const SEED_USER_PASSWORD = 'password';

/** What `demo-data.json` publishes so the frontend can log in as either demo account. */
export const seedCredentials = {
    admin: { email: SEED_ADMIN_EMAIL, password: SEED_ADMIN_PASSWORD },
    user: { email: SEED_USER_EMAIL, password: SEED_USER_PASSWORD }
} as const;

src/modules/account/factory.ts.source:
/**
 * How an address-book fixture is built.
 *
 * A book is addressed by its owner — `addressBooks.userId` is `unique` and no book id reaches the
 * wire — so, like the cart and the wishlist, this pins an `_id` it does not need as a handle. The
 * reason is the same one `../cart/factory` gives at length: `scripts/export-demo-dataset.ts` commits what
 * it reads back, and a generated id is 24 different characters on every run.
 *
 * ## Why an ENTRY pins its id too, unlike a cart line
 *
 * A cart line is addressed by its product and carries `_id: false`. An address entry is the
 * opposite case — two entries may hold identical fields and still be "home" and "office", so
 * `addressItemSchema` keeps its `_id` and every endpoint takes that id as its handle. Which means
 * a fixture that let mongod assign them would publish two unstable ids per book instead of one.
 *
 * Entries arrive as the contract's `Address`, the shape `GET /account/addresses` answers with, so
 * a fixture states an entry the way a client would read it back.
 */

import { Types } from 'mongoose';
import { compact, identityOf, type FactoryIdentity } from '@infrastructure/persistence/factory';
import type { Address, Id } from '@types';
import type { AddressBookDocument, AddressItem } from './model';

/** What a caller may pin on a book. */
export interface AddressBookOverrides extends FactoryIdentity {
    /** 24-char hex of the owning user. */
    userId: Id;
    /** Absent leaves the schema's `default: []` to apply — a book with no entries. */
    items?: Address[];
}

/**
 * A book ready for `addressBookRepository.create`.
 *
 * `userId` is required for the same reason the cart's is: a book cannot be built without an owner,
 * and leaving it optional under `Partial` only moves the assertion to the caller.
 */
export type AddressBookFixture = Partial<AddressBookDocument> & Pick<AddressBookDocument, 'userId'>;

/** The contract's `id` becomes the subdocument's `_id`; absent optionals leave no key behind. */
const toEntry = ({ id, label, phone, ...fields }: Address): AddressItem => ({
    _id: new Types.ObjectId(id),
    ...fields,
    ...compact({ label, phone })
});

export const makeAddressBook = ({
    userId,
    items,
    ...identity
}: AddressBookOverrides): AddressBookFixture => ({
    userId: new Types.ObjectId(userId),
    ...identityOf(identity),
    ...(items === undefined ? {} : { items: items.map((item) => toEntry(item)) })
});

src/modules/account/metrics.ts.source:
/**
 * Domain counters this module owns.
 *
 * Registered on the shared `metricsRegistry` so one `/metrics` scrape carries these alongside the
 * HTTP metrics. Importing `infrastructure` downward is fine; what changed when the domains became modules is
 * that the counters no longer live in `infrastructure`, which had no business naming `auth` or `cart`.
 *
 * Nothing imports these to *read* them. `GET /observability/metrics/overview` resolves values by
 * metric name off the registry, so deleting this module removes its counters from the scrape and
 * leaves the overview reporting zero rather than failing to compile.
 *
 * Why counters at all, when the same events are audited and sent to analytics: each signal answers
 * a different question at a different cost. Analytics is for per-user product funnels, audit is the
 * per-event compliance record, and these are cheap always-on aggregates you can *alert* on —
 * "signup failure ratio above 20% for 5 minutes" needs a counter, not a query over an event store.
 *
 * The `status` label (typically 'success' / 'failure') is what makes each counter usable as both a
 * volume and a success-ratio signal.
 */

import { Counter } from 'prom-client';
import { metricsRegistry } from '@infrastructure/observability/metrics-http';

/**
 * Login attempts split by outcome (success / failure).
 * The failure series is the security-relevant one: a sudden spike suggests credential stuffing.
 */
export const authLoginTotal = new Counter({
    // Prometheus naming: `<domain>_<subject>_total` for a counter.
    name: 'auth_login_total',
    help: 'Total login attempts, labelled by outcome.',
    // `as const` narrows the label names to literals, so `inc({ status })` is type-checked
    // against them instead of accepting any string key.
    labelNames: ['status'] as const,
    registers: [metricsRegistry]
});

/**
 * Sign-up attempts split by outcome.
 * Top-of-funnel volume, and a failure rate that catches a broken registration flow faster
 * than a user report would.
 */
export const authSignupTotal = new Counter({
    name: 'auth_signup_total',
    help: 'Total sign-up attempts, labelled by outcome.',
    labelNames: ['status'] as const,
    registers: [metricsRegistry]
});

/**
 * Password-reset request attempts (initial request only).
 * "Initial request only" matters: this counts the *request* for a reset link, not the
 * confirmation step, so the two cannot be conflated when reading the funnel.
 */
export const authPasswordResetTotal = new Counter({
    name: 'auth_password_reset_total',
    help: 'Total password-reset request attempts.',
    labelNames: ['status'] as const,
    registers: [metricsRegistry]
});

/**
 * Refresh-token operations.
 * Rising failures here mean sessions are being dropped — users get logged out unexpectedly,
 * which rarely shows up as an explicit error report.
 */
export const authRefreshTotal = new Counter({
    name: 'auth_refresh_total',
    help: 'Total token-refresh attempts, labelled by outcome.',
    labelNames: ['status'] as const,
    registers: [metricsRegistry]
});

/**
 * Authenticated password changes (the current-password flow, not the email reset).
 * Kept separate from `auth_password_reset_total` for the same reason that one excludes the
 * confirmation step: two flows in one counter cannot be read as a funnel. The failure series
 * doubles as a security signal — repeated wrong current passwords against a live session
 * suggests a hijacked device probing for the credential it does not have.
 */
export const authPasswordChangeTotal = new Counter({
    name: 'auth_password_change_total',
    help: 'Total authenticated password-change attempts, labelled by outcome.',
    labelNames: ['status'] as const,
    registers: [metricsRegistry]
});

/**
 * Email-verification confirmations (the token-spending step, not the send).
 * The send is not counted: it rides the email queue, whose own metrics say whether mail moves.
 * What no other signal answers is how many verification links actually get clicked — the
 * success/failure split here is the closest thing this stack has to a deliverability check.
 */
export const authEmailVerifyTotal = new Counter({
    name: 'auth_email_verify_total',
    help: 'Total email-verification confirmation attempts, labelled by outcome.',
    labelNames: ['status'] as const,
    registers: [metricsRegistry]
});

/**
 * Expired-token cleanup runs (admin endpoint).
 * Note: no `labelNames` — a maintenance job either ran or did not, so there is no outcome
 * dimension worth slicing by. Useful mainly to confirm the job is still running at all.
 */
export const authTokenCleanupTotal = new Counter({
    name: 'auth_token_cleanup_total',
    help: 'Total expired-token cleanup operations.',
    registers: [metricsRegistry]
});

/**
 * Account deletion request attempts.
 * A churn signal, and one with regulatory weight (GDPR erasure requests).
 */
export const authAccountDeleteTotal = new Counter({
    name: 'auth_account_delete_total',
    help: 'Total account-deletion request attempts.',
    labelNames: ['status'] as const,
    registers: [metricsRegistry]
});

src/modules/account/model.ts.source:
import { model, Schema, Types } from 'mongoose';
import type { Document, Model } from 'mongoose';
import { applySerialization } from '@infrastructure/persistence/serialize';

/**
 * Address book Model
 *
 * One document per user, keyed by `userId` — the cart's pattern, chosen over an array on the
 * user document for the cart's reasons: a user response cannot leak a book it does not carry,
 * and editing an address reads and writes one small document instead of the whole account.
 * This makes `account` a module that owns a collection after all; its manifest says so.
 *
 * Unlike a cart line, an entry IS addressed by itself — two entries may hold identical fields
 * and still be "home" and "office" — so the subdocuments keep their `_id`, and that id is the
 * handle every endpoint takes.
 */

/** A stored address-book entry. */
export interface AddressItem {
    _id?: Types.ObjectId;
    label?: string;
    fullName: string;
    street: string;
    city: string;
    zip: string;
    country: string;
    phone?: string;
    /**
     * Exactly one entry carries `true` whenever the book is non-empty — maintained by the
     * repository's writes, never trusted from the client. Named `default` because that is the
     * wire name and a mapping layer for one field is a place for the two to drift.
     */
    default: boolean;
}

/** Address book Document interface. A book id never reaches the wire. */
export interface AddressBookDocument extends Document {
    userId: Types.ObjectId;
    items: AddressItem[];
    createdAt?: Date;
    updatedAt?: Date;
}

/** Address book Document model type. Queries live in `./repository`. */
export type AddressBookModel = Model<AddressBookDocument>;

const addressItemSchema = new Schema(
    {
        label: { type: String },
        fullName: { type: String, required: true },
        street: { type: String, required: true },
        city: { type: String, required: true },
        zip: { type: String, required: true },
        country: { type: String, required: true },
        phone: { type: String },
        default: { type: Boolean, default: false }
    },
    /* `_id: true` is mongoose's default; spelled out because the WISH to have one is the whole
     * difference from the cart/wishlist line schemas next door. */
    { _id: true }
);

/*
 * An entry serializes as the contract's `Address` — `_id` renamed to `id`, exactly as the product
 * snapshot embedded in an order line does.
 *
 * `./services/addresses` maps entries by hand for the wire and does not go through this, so nothing
 * in a request path changes. What does go through it is `scripts/export-demo-dataset.ts`, which publishes
 * stored rows via `toJSON()`: without this, the demo dataset would be the only place in the repo
 * where an addressable record announced itself as `_id`.
 */
applySerialization(addressItemSchema);

/**
 * Mongoose schema for persisted address books.
 *
 * `unique: true` on `userId` — one book per user is a database fact, and every mutation is a
 * single `findOneAndUpdate({ userId }, …)`.
 */
export const addressBookSchema = new Schema<AddressBookDocument>(
    {
        userId: {
            type: Schema.Types.ObjectId,
            ref: 'User',
            required: true,
            unique: true
        },
        items: {
            type: [addressItemSchema],
            default: []
        }
    },
    {
        timestamps: true
    }
);

/**
 * Normalizes a serialized book: `_id` → `id`, drops `__v`. Owed to the base factory for its
 * lean reads (see `normalize` in @infrastructure/persistence/base-repository).
 */
export const applyAddressBookTransform = applySerialization(addressBookSchema);

/**
 * Model
 */
export const addressBookModel = model<AddressBookDocument, AddressBookModel>(
    'AddressBook',
    addressBookSchema
);

