/**
 * Authorization middlewares — `src/kernel/middlewares/authorizations.ts`.
 *
 * Three middlewares with deliberately different failure modes, and the difference is the point:
 *
 *   `getAuth`  — *optional* identification. Fails open by design: a bad token means "anonymous",
 *                not "rejected", because it also guards public routes. It must always call
 *                `next()` exactly once, on every path, or the request hangs.
 *   `isAuth`   — *required* identification. Fails closed with 401.
 *   `isAdmin`  — *required* elevation. Fails closed, and the status says which check refused:
 *                401 with no credentials at all (as `isAuth` does), 403 for a known non-admin.
 *                Both bodies stay generic; the reason is recorded in the audit trail only.
 *
 * The response layer is real (not mocked) so the asserted status codes are the ones a client
 * actually receives; only the audit sink and the JWT/DB boundaries are stubbed.
 */

import { asStub } from '@tests/stub';
import type { Request, Response, NextFunction } from 'express';
import {
    getTokenBearer,
    getAuth,
    isAuth,
    isAdmin,
    isAdminViaCookie
} from '@kernel/middlewares/authorizations';
import { registerAuthResolver } from '@kernel/authentication';
import { emitAuditEvent, coreAuditActions } from '@infrastructure/observability/audit';
import { makeResponseStub } from '@tests/express';

// Only the sink is replaced; `buildAuditEvent` and the `coreAuditActions` vocabulary stay real, so an
// event that stops matching the real builder's shape fails here rather than in production.
jest.mock('@infrastructure/observability/audit', () => ({
    ...jest.requireActual('@infrastructure/observability/audit'),
    emitAuditEvent: jest.fn()
}));

/*
 * The guards no longer look a user up themselves — they ask `kernel/authentication` for one, and
 * `account` supplies the implementation at boot. So the fake here is the RESOLVER, which is also
 * the whole contract these guards depend on:
 *
 *   - a rejection means the token is bad;
 *   - resolving `undefined` means the token was fine but names nobody.
 *
 * `isAdminViaCookie` turns the first into 401 and the second into 403, so the two must stay
 * distinguishable in the fake exactly as they are in production.
 */
const fromAccessToken = jest.fn<Promise<unknown>, [string]>();
const fromRefreshToken = jest.fn<Promise<unknown>, [string]>();
registerAuthResolver({
    fromAccessToken: (token) => fromAccessToken(token) as never,
    fromRefreshToken: (token) => fromRefreshToken(token) as never
});

const mockedVerifyAccessToken = fromAccessToken;
const mockedVerifyRefreshToken = fromRefreshToken;
const mockedEmitAuditEvent = emitAuditEvent as jest.MockedFunction<typeof emitAuditEvent>;

/** Request stub carrying an optional Authorization header and auth context. */
const makeRequest = (options: { authorization?: string; authContext?: unknown } = {}) =>
    asStub<Request>({
        header: jest.fn((name: string) =>
            name === 'Authorization' ? options.authorization : undefined
        ),
        authContext: options.authContext,
        path: '/protected',
        method: 'GET',
        headers: {}
    });

/** Request stub carrying a refresh cookie, for the cookie-authenticated middleware. */
const makeCookieRequest = (jwt?: string) =>
    asStub<Request>({
        cookies: jwt === undefined ? {} : { jwt },
        header: jest.fn(),
        path: '/orders/1/invoice',
        method: 'GET',
        headers: {}
    });

/** Response stub with a chainable status().json(), capturing the real envelope. */

/** Runs an async middleware and resolves once it has called `next()`. */
const runUntilNext = async (
    middleware: (request: Request, response: Response, next: NextFunction) => void,
    request: Request,
    response: Response
) => {
    const next = jest.fn();
    const called = new Promise<void>((resolve) => {
        next.mockImplementation(() => resolve());
    });
    middleware(request, response, asStub<NextFunction>(next));
    await called;
    return next;
};

describe('getTokenBearer', () => {
    it('strips the Bearer prefix and returns the token', () => {
        expect(getTokenBearer(makeRequest({ authorization: 'Bearer abc.def.ghi' }))).toBe(
            'abc.def.ghi'
        );
    });

    it('returns undefined when the header is absent', () => {
        expect(getTokenBearer(makeRequest())).toBeUndefined();
    });

    it('returns undefined when the header has a scheme but no token', () => {
        // 'Bearer'.split(' ')[1] is undefined — the caller's falsy check must still catch it.
        expect(getTokenBearer(makeRequest({ authorization: 'Bearer' }))).toBeUndefined();
    });
});

describe('getAuth', () => {
    it('calls next without an auth context when no token is present', async () => {
        const request = makeRequest();

        const next = await runUntilNext(getAuth, request, makeResponseStub());

        expect(next).toHaveBeenCalledTimes(1);
        expect(request.authContext).toBeUndefined();
        // The JWT boundary must not even be reached — verifying an absent token would be work
        // done to produce a guaranteed failure.
        expect(mockedVerifyAccessToken).not.toHaveBeenCalled();
    });

    it('attaches the identity of the user the token names', async () => {
        mockedVerifyAccessToken.mockResolvedValue({
            id: 'user-1',
            email: 'user@example.com',
            username: 'tester',
            admin: true,
            imageUrl: '/images/a.png'
        } as never);

        const request = makeRequest({ authorization: 'Bearer valid.token' });
        await runUntilNext(getAuth, request, makeResponseStub());

        expect(request.authContext).toEqual({
            id: 'user-1',
            email: 'user@example.com',
            username: 'tester',
            admin: true,
            imageUrl: '/images/a.png'
        });
    });

    it('resolves a missing admin flag to false rather than undefined', async () => {
        // `admin ?? false`. An undefined `admin` would be falsy at most call sites and so would
        // "work", but `isAdmin` and `orderService.callerScope` both branch on it — an explicit
        // false is the only value that cannot be misread as "unknown".
        mockedVerifyAccessToken.mockResolvedValue({
            id: 'user-2',
            email: 'plain@example.com',
            username: 'plain'
        } as never);

        const request = makeRequest({ authorization: 'Bearer valid.token' });
        await runUntilNext(getAuth, request, makeResponseStub());

        expect(request.authContext?.admin).toBe(false);
    });

    it('proceeds anonymously when the token is invalid or expired', async () => {
        // Fails open on purpose: this middleware also runs on public routes, where a stale token
        // in a browser must not turn a public page into an error.
        mockedVerifyAccessToken.mockRejectedValue(new Error('jwt expired'));

        const request = makeRequest({ authorization: 'Bearer expired.token' });
        const next = await runUntilNext(getAuth, request, makeResponseStub());

        expect(next).toHaveBeenCalledTimes(1);
        expect(request.authContext).toBeUndefined();
    });

    it('proceeds anonymously when the token is valid but the user no longer exists', async () => {
        // A deleted account holding a still-valid JWT must not be granted an identity.
        mockedVerifyAccessToken.mockResolvedValue(undefined as never);

        const request = makeRequest({ authorization: 'Bearer valid.token' });
        const next = await runUntilNext(getAuth, request, makeResponseStub());

        expect(next).toHaveBeenCalledTimes(1);
        expect(request.authContext).toBeUndefined();
    });

    it('proceeds anonymously when the user lookup itself fails', async () => {
        mockedVerifyAccessToken.mockRejectedValue(new Error('database unavailable'));

        const request = makeRequest({ authorization: 'Bearer valid.token' });
        const next = await runUntilNext(getAuth, request, makeResponseStub());

        expect(next).toHaveBeenCalledTimes(1);
        expect(request.authContext).toBeUndefined();
    });

    it('never sends a response of its own', async () => {
        // It identifies; it does not authorize. Any status set here would pre-empt the route.
        mockedVerifyAccessToken.mockRejectedValue(new Error('nope'));
        const response = makeResponseStub();

        await runUntilNext(getAuth, makeRequest({ authorization: 'Bearer x' }), response);

        expect(response.status).not.toHaveBeenCalled();
        expect(response.json).not.toHaveBeenCalled();
    });
});

describe('isAuth', () => {
    it('passes through when both an auth context and a token are present', () => {
        const next = jest.fn();
        const response = makeResponseStub();

        isAuth(
            makeRequest({ authorization: 'Bearer valid.token', authContext: { id: 'user-1' } }),
            response,
            next
        );

        expect(next).toHaveBeenCalledTimes(1);
        expect(response.status).not.toHaveBeenCalled();
    });

    it('rejects with 401 when there is no auth context', () => {
        const next = jest.fn();
        const response = makeResponseStub();

        isAuth(makeRequest({ authorization: 'Bearer stale.token' }), response, next);

        expect(next).not.toHaveBeenCalled();
        expect(response.status).toHaveBeenCalledWith(401);
        expect(response.json).toHaveBeenCalledWith(
            expect.objectContaining({ success: false, status: 401 })
        );
    });

    it('rejects with 401 when a context exists but the bearer token is gone', () => {
        // Both conditions are required. Accepting a context without its token would let an
        // already-populated request object stand in for a credential.
        const next = jest.fn();
        const response = makeResponseStub();

        isAuth(makeRequest({ authContext: { id: 'user-1' } }), response, next);

        expect(next).not.toHaveBeenCalled();
        expect(response.status).toHaveBeenCalledWith(401);
    });

    it('records an anonymous unauthorized audit event on rejection', () => {
        isAuth(makeRequest(), makeResponseStub(), jest.fn());

        expect(mockedEmitAuditEvent).toHaveBeenCalledTimes(1);
        expect(mockedEmitAuditEvent).toHaveBeenCalledWith(
            expect.objectContaining({
                action: coreAuditActions.SECURITY_UNAUTHORIZED,
                actor_user_id: 'anonymous',
                actor_role: 'anonymous',
                outcome: 'failure'
            })
        );
    });

    it('records nothing when the request is allowed through', () => {
        isAuth(
            makeRequest({ authorization: 'Bearer valid.token', authContext: { id: 'user-1' } }),
            makeResponseStub(),
            jest.fn()
        );

        expect(mockedEmitAuditEvent).not.toHaveBeenCalled();
    });
});

describe('isAdmin', () => {
    it('passes an admin through', () => {
        const next = jest.fn();
        const response = makeResponseStub();

        isAdmin(makeRequest({ authContext: { id: 'user-1', admin: true } }), response, next);

        expect(next).toHaveBeenCalledTimes(1);
        expect(response.status).not.toHaveBeenCalled();
    });

    it('rejects an authenticated non-admin with 403', () => {
        const next = jest.fn();
        const response = makeResponseStub();

        isAdmin(makeRequest({ authContext: { id: 'user-1', admin: false } }), response, next);

        expect(next).not.toHaveBeenCalled();
        expect(response.status).toHaveBeenCalledWith(403);
    });

    it('rejects a caller whose admin flag is absent', () => {
        // Absent must mean "not an admin". The fail-safe direction, asserted separately from the
        // explicit-false case because they take different code paths.
        const next = jest.fn();
        const response = makeResponseStub();

        isAdmin(makeRequest({ authContext: { id: 'user-1' } }), response, next);

        expect(next).not.toHaveBeenCalled();
        expect(response.status).toHaveBeenCalledWith(403);
    });

    it('answers 403, not 401, for an unauthenticated caller', () => {
        // Deliberate: this middleware runs after `isAuth`, so reaching it without a context is a
        // routing mistake rather than a missing credential, and 401 would invite a pointless
        // re-login attempt.
        const next = jest.fn();
        const response = makeResponseStub();

        isAdmin(makeRequest(), response, next);

        expect(next).not.toHaveBeenCalled();
        expect(response.status).toHaveBeenCalledWith(401);
    });

    it('distinguishes not-authenticated from not-admin in the audit trail', () => {
        isAdmin(makeRequest(), makeResponseStub(), jest.fn());

        expect(mockedEmitAuditEvent).toHaveBeenCalledWith(
            expect.objectContaining({
                // An absent session is an authentication failure, so it is audited as one — the
                // same action `isAuth` emits, rather than a permission denial.
                action: coreAuditActions.SECURITY_UNAUTHORIZED,
                actor_user_id: 'anonymous',
                actor_role: 'anonymous',
                metadata: expect.objectContaining({ reason: 'not_authenticated' })
            })
        );
    });

    it('attributes a not-admin denial to the actual user, not to anonymous', () => {
        // The whole value of the audit record: "who tried". Falling back to 'anonymous' here
        // would erase the identity of a real user probing admin routes.
        isAdmin(
            makeRequest({ authContext: { id: 'user-9', admin: false } }),
            makeResponseStub(),
            jest.fn()
        );

        expect(mockedEmitAuditEvent).toHaveBeenCalledWith(
            expect.objectContaining({
                action: coreAuditActions.SECURITY_FORBIDDEN,
                actor_user_id: 'user-9',
                metadata: expect.objectContaining({ reason: 'not_admin' })
            })
        );
    });

    it('separates "not authenticated" (401) from "not permitted" (403)', () => {
        /*
         * The statuses differ because the client's next move differs: 401 means "authenticate and
         * retry", which the frontend turns into a login redirect that returns the visitor to where
         * they were aiming; 403 means "you are known and still refused", where logging in again
         * would only loop. Answering 403 to an expired session sent it to the error page.
         *
         * The bodies stay generic and identical — which check refused is recorded in the audit
         * trail (`reason`, asserted above), not disclosed to whoever is probing.
         */
        const unauthenticated = makeResponseStub();
        isAdmin(makeRequest(), unauthenticated, jest.fn());

        const nonAdmin = makeResponseStub();
        isAdmin(makeRequest({ authContext: { id: 'user-9', admin: false } }), nonAdmin, jest.fn());

        expect(unauthenticated.status).toHaveBeenCalledWith(401);
        expect(nonAdmin.status).toHaveBeenCalledWith(403);
    });
});

/**
 * `isAdminViaCookie` — admin elevation proved by the refresh COOKIE rather than a bearer header.
 *
 * It exists for the requests a browser makes without JavaScript setting a header: a PDF invoice
 * opened in a new tab, an `EventSource` stream. Those cannot carry `Authorization`, so the
 * `HttpOnly` refresh cookie is the credential — verified for signature *and* presence on the user
 * document, so a logged-out or revoked token is rejected rather than merely an expired one.
 *
 * It had NO tests at all: 35 of its mutants had no coverage, which is why the file scored 49.40%
 * overall while scoring 85.42% on the part that was covered. That split is the diagnosis — the
 * assertions that existed were good, this middleware simply wasn't reached by any of them.
 *
 * It is worth more than its size suggests: it is an admin gate, it is agnostic boilerplate every
 * derived project inherits, and its failure mode is silent. A mutant that turns `!user?.admin`
 * into `false` hands every logged-in user an admin-only document.
 */
describe('isAdminViaCookie', () => {
    /** An admin user document, as `findById` resolves one. */
    const adminUser = {
        id: 'admin-1',
        email: 'root@example.com',
        username: 'root',
        admin: true,
        imageUrl: '/images/root.png'
    };

    it('rejects with 401 when there is no session cookie at all', () => {
        const response = makeResponseStub();
        const next = jest.fn();

        isAdminViaCookie(makeCookieRequest(), response, asStub<NextFunction>(next));

        expect(response.status).toHaveBeenCalledWith(401);
        expect(next).not.toHaveBeenCalled();
        // The token is never even verified — no point paying for a signature check.
        expect(mockedVerifyRefreshToken).not.toHaveBeenCalled();
    });

    it('rejects an empty cookie value the same way as a missing one', () => {
        const response = makeResponseStub();

        isAdminViaCookie(makeCookieRequest(''), response, asStub<NextFunction>(jest.fn()));

        expect(response.status).toHaveBeenCalledWith(401);
    });

    it('verifies the REFRESH token, not the access token', async () => {
        // The whole design decision: the cookie holds a refresh token, and verifying it against
        // the access-token secret would either always fail or, worse, accept the wrong audience.
        mockedVerifyRefreshToken.mockResolvedValueOnce(adminUser as never);

        await runUntilNext(isAdminViaCookie, makeCookieRequest('cookie.jwt'), makeResponseStub());

        expect(mockedVerifyRefreshToken).toHaveBeenCalledWith('cookie.jwt');
        expect(mockedVerifyAccessToken).not.toHaveBeenCalled();
    });

    it('admits an admin and calls next exactly once', async () => {
        mockedVerifyRefreshToken.mockResolvedValueOnce(adminUser as never);

        const next = await runUntilNext(
            isAdminViaCookie,
            makeCookieRequest('cookie.jwt'),
            makeResponseStub()
        );

        expect(next).toHaveBeenCalledTimes(1);
    });

    it('populates authContext with the admin flag set', async () => {
        // Downstream handlers read `request.authContext.admin`; a context that arrives without it
        // turns an authorized request into a confusing 403 further down.
        mockedVerifyRefreshToken.mockResolvedValueOnce(adminUser as never);
        const request = makeCookieRequest('cookie.jwt');

        await runUntilNext(isAdminViaCookie, request, makeResponseStub());

        expect(request.authContext).toEqual({
            id: adminUser.id,
            email: adminUser.email,
            username: adminUser.username,
            admin: true,
            imageUrl: adminUser.imageUrl
        });
    });

    it('rejects a valid session belonging to a NON-admin with 403', async () => {
        // The mutant that matters most: `!user?.admin` forced to `false` would hand every
        // logged-in user an admin-only document.
        mockedVerifyRefreshToken.mockResolvedValueOnce({
            ...adminUser,
            id: 'user-1',
            admin: false
        } as never);
        const response = makeResponseStub();
        const next = jest.fn();

        isAdminViaCookie(makeCookieRequest('cookie.jwt'), response, asStub<NextFunction>(next));
        await new Promise((resolve) => setImmediate(resolve));

        expect(response.status).toHaveBeenCalledWith(403);
        expect(next).not.toHaveBeenCalled();
    });

    it('rejects with 403 when the token is valid but the user is gone', async () => {
        // `user?.admin` on `null` — a deleted account holding a still-signed cookie.
        mockedVerifyRefreshToken.mockResolvedValueOnce(undefined as never);
        const response = makeResponseStub();

        isAdminViaCookie(
            makeCookieRequest('cookie.jwt'),
            response,
            asStub<NextFunction>(jest.fn())
        );
        await new Promise((resolve) => setImmediate(resolve));

        expect(response.status).toHaveBeenCalledWith(403);
    });

    it('records a forbidden attempt in the audit trail', async () => {
        mockedVerifyRefreshToken.mockResolvedValueOnce({
            ...adminUser,
            id: 'user-1',
            admin: false
        } as never);

        isAdminViaCookie(
            makeCookieRequest('cookie.jwt'),
            makeResponseStub(),
            asStub<NextFunction>(jest.fn())
        );
        await new Promise((resolve) => setImmediate(resolve));

        expect(mockedEmitAuditEvent).toHaveBeenCalledWith(
            expect.objectContaining({
                action: coreAuditActions.SECURITY_FORBIDDEN,
                actor_user_id: 'user-1',
                outcome: 'failure'
            })
        );
    });

    it('names the anonymous actor when the user could not be loaded', async () => {
        // `user?.id ?? 'anonymous'` — an audit row with an empty actor is a row nobody can act on.
        mockedVerifyRefreshToken.mockResolvedValueOnce(undefined as never);

        isAdminViaCookie(
            makeCookieRequest('cookie.jwt'),
            makeResponseStub(),
            asStub<NextFunction>(jest.fn())
        );
        await new Promise((resolve) => setImmediate(resolve));

        expect(mockedEmitAuditEvent).toHaveBeenCalledWith(
            expect.objectContaining({ actor_user_id: 'anonymous' })
        );
    });

    it('rejects a cookie whose signature does not verify, with 401 not 403', async () => {
        // 401 and 403 are different statements: "I do not know who you are" versus "I know, and
        // no". A forged cookie is the first.
        mockedVerifyRefreshToken.mockRejectedValueOnce(new Error('invalid signature'));
        const response = makeResponseStub();
        const next = jest.fn();

        isAdminViaCookie(makeCookieRequest('forged.jwt'), response, asStub<NextFunction>(next));
        await new Promise((resolve) => setImmediate(resolve));

        expect(response.status).toHaveBeenCalledWith(401);
        expect(next).not.toHaveBeenCalled();
    });

    it('rejects with 401 when the user lookup itself fails', async () => {
        // The `.catch()` covers the whole chain, not just the token verification — a database
        // outage must not become an unhandled rejection in a middleware.
        mockedVerifyRefreshToken.mockRejectedValueOnce(new Error('mongo is down'));
        const response = makeResponseStub();

        isAdminViaCookie(
            makeCookieRequest('cookie.jwt'),
            response,
            asStub<NextFunction>(jest.fn())
        );
        await new Promise((resolve) => setImmediate(resolve));

        expect(response.status).toHaveBeenCalledWith(401);
    });
});

tests/unit/infrastructure/adapters/logge.source:
/**
 * `src/infrastructure/adapters/logger.ts` — redaction and error serialization.
 *
 * This is agnostic boilerplate in the strictest sense: every project built from this repo
 * inherits it unchanged, and its job is to stop credentials reaching a log aggregator. A gap here
 * is not a bug in a feature, it is a password in Datadog forever.
 *
 * It scored 25.74% on mutation with 73 survivors, and the survivors clustered in three places the
 * existing cases never reached: the production stack-trace guard, the winston format that wires
 * redaction into the pipeline, and the two INVARIANTS the docblock claims but nothing checked —
 * that redaction never mutates its input, and that the format returns the same object identity
 * winston handed it.
 */
import fc from 'fast-check';
import {
    redactSensitiveFields,
    serializeError,
    SENSITIVE_FIELDS,
    redactFormat,
    resolveLogLevel,
    resolveConsoleFormat
} from '@infrastructure/adapters/logger';

describe('redactSensitiveFields', () => {
    it('returns primitives unchanged', () => {
        expect(redactSensitiveFields('hello')).toBe('hello');
        expect(redactSensitiveFields(42)).toBe(42);
        expect(redactSensitiveFields(true)).toBe(true);
        expect(redactSensitiveFields(void 0)).toBeUndefined();
    });

    it('redacts password and token fields', () => {
        const input = { username: 'alice', password: 's3cr3t', access_token: 'tok' };
        expect(redactSensitiveFields(input)).toEqual({
            username: 'alice',
            password: '[REDACTED]',
            access_token: '[REDACTED]'
        });
    });

    it('redacts authorization and cookie headers', () => {
        const input = {
            authorization: 'Bearer abc',
            cookie: 'jwt=xyz',
            contentType: 'application/json'
        };
        const result = redactSensitiveFields(input) as Record<string, unknown>;
        expect(result.authorization).toBe('[REDACTED]');
        expect(result.cookie).toBe('[REDACTED]');
        expect(result.contentType).toBe('application/json');
    });

    it('is case-insensitive for sensitive field names', () => {
        const input = { Password: 'secret', PASSWORD: 'secret' };
        const result = redactSensitiveFields(input) as Record<string, unknown>;
        expect(result.Password).toBe('[REDACTED]');
        expect(result.PASSWORD).toBe('[REDACTED]');
    });

    it('redacts nested sensitive fields', () => {
        const input = { user: { email: 'a@b.com', password: 'secret' } };
        expect(redactSensitiveFields(input)).toEqual({
            user: { email: 'a@b.com', password: '[REDACTED]' }
        });
    });

    it('redacts inside arrays', () => {
        const input = [{ password: 'a' }, { password: 'b', name: 'carol' }];
        expect(redactSensitiveFields(input)).toEqual([
            { password: '[REDACTED]' },
            { password: '[REDACTED]', name: 'carol' }
        ]);
    });
});

describe('serializeError', () => {
    it('extracts name and message from an Error instance', () => {
        const result = serializeError(new Error('something went wrong'));
        expect(result.name).toBe('Error');
        expect(result.message).toBe('something went wrong');
    });

    it('wraps non-Error values in a raw field', () => {
        expect(serializeError('plain string')).toEqual({ raw: 'plain string' });
        expect(serializeError(42)).toEqual({ raw: '42' });
    });

    it('preserves custom error names', () => {
        class ValidationError extends Error {
            constructor(message: string) {
                super(message);
                this.name = 'ValidationError';
            }
        }
        const result = serializeError(new ValidationError('bad input'));
        expect(result.name).toBe('ValidationError');
        expect(result.message).toBe('bad input');
    });
});

describe('serializeError — the production stack guard', () => {
    const originalEnvironment = process.env.NODE_ENV;

    afterEach(() => {
        if (originalEnvironment === undefined) delete process.env.NODE_ENV;
        else process.env.NODE_ENV = originalEnvironment;
    });

    it('includes the stack outside production, where it is the useful part', () => {
        process.env.NODE_ENV = 'development';

        expect(serializeError(new Error('boom'))).toHaveProperty('stack');
    });

    it('OMITS the stack in production', () => {
        // A stack trace names absolute paths and dependency internals. Locally that is debugging;
        // in an aggregated production log it is a map of the filesystem handed to anyone with
        // read access to the log tool. Nothing asserted this, so both mutants of the guard lived.
        process.env.NODE_ENV = 'production';

        expect(serializeError(new Error('boom'))).not.toHaveProperty('stack');
    });

    it('still reports name and message in production', () => {
        // Omitting the stack must not degrade into omitting the error.
        process.env.NODE_ENV = 'production';

        expect(serializeError(new Error('boom'))).toMatchObject({
            name: 'Error',
            message: 'boom'
        });
    });

    it('treats an unset NODE_ENV as non-production', () => {
        // The comparison is `!== 'production'`, so an unset variable keeps the stack — which is
        // the right default for a developer running the app with no env file.
        delete process.env.NODE_ENV;

        expect(serializeError(new Error('boom'))).toHaveProperty('stack');
    });
});

/*
 * Properties. `redactSensitiveFields` walks arbitrary caller-supplied metadata, so "for every
 * input" is the only honest way to state what it guarantees — and two of these are claims the
 * docblock makes in prose and nothing verified.
 */
const RUN = { seed: 20_260_809, numRuns: 200, endOnFailure: true } as const;

/** Every string VALUE in a structure, ignoring keys — what a leak actually looks like. */
const stringValuesOf = (input: unknown): string[] => {
    if (typeof input === 'string') return [input];
    if (Array.isArray(input)) return input.flatMap((item) => stringValuesOf(item));
    if (input !== null && typeof input === 'object')
        return Object.values(input as Record<string, unknown>).flatMap((value) =>
            stringValuesOf(value)
        );
    return [];
};

/** Arbitrary log metadata, including keys that are and are not sensitive. */
const metadata = () =>
    fc.dictionary(
        fc.oneof(fc.constantFrom('password', 'token', 'authorization', 'user', 'id'), fc.string()),
        fc.jsonValue(),
        { maxKeys: 6 }
    );

describe('redactSensitiveFields — invariants', () => {
    it('NEVER mutates the object it was given', () => {
        // The docblock is explicit that callers pass live request and domain objects, so mutating
        // them would corrupt the actual request rather than merely the log line. That is the most
        // dangerous thing this function could do and nothing was checking it.
        fc.assert(
            fc.property(metadata(), (input) => {
                const before = JSON.stringify(input);

                redactSensitiveFields(input);

                expect(JSON.stringify(input)).toBe(before);
            }),
            RUN
        );
    });

    it('is idempotent — redacting twice changes nothing further', () => {
        fc.assert(
            fc.property(metadata(), (input) => {
                const once = redactSensitiveFields(input);

                expect(redactSensitiveFields(once)).toEqual(once);
            }),
            RUN
        );
    });

    it('leaves no sensitive VALUE anywhere in the output, at any depth', () => {
        // The claim that matters. Generated nesting reaches shapes no example enumerates.
        //
        // Asserted over the output's string VALUES rather than over `JSON.stringify` of the whole
        // thing, and the difference is not pedantry — the naive version failed on the generated
        // counterexample `secret = "p"`, because "p" occurs inside the KEY "password". The claim
        // was never about key names.
        fc.assert(
            fc.property(fc.string({ minLength: 1 }), fc.nat({ max: 5 }), (secret, depth) => {
                let payload: Record<string, unknown> = { password: secret };
                for (let level = 0; level < depth; level++) payload = { nested: payload };

                expect(stringValuesOf(redactSensitiveFields(payload))).not.toContain(secret);
            }),
            RUN
        );
    });

    it('keeps arrays as arrays rather than rebuilding them as objects', () => {
        // `typeof [] === 'object'`, so without the Array.isArray branch an array comes back as
        // `{ '0': ..., '1': ... }` — valid JSON, and a log shape no dashboard can read.
        fc.assert(
            fc.property(fc.array(fc.jsonValue(), { maxLength: 6 }), (input) => {
                expect(Array.isArray(redactSensitiveFields(input))).toBe(true);
            }),
            RUN
        );
    });

    it('preserves array length and non-sensitive primitives', () => {
        fc.assert(
            fc.property(
                fc.array(fc.oneof(fc.string(), fc.integer()), { maxLength: 6 }),
                (input) => {
                    expect(redactSensitiveFields(input)).toEqual(input);
                }
            ),
            RUN
        );
    });

    it('never throws, for any input', () => {
        fc.assert(
            fc.property(fc.anything(), (input) => {
                expect(() => redactSensitiveFields(input)).not.toThrow();
            }),
            RUN
        );
    });
});

describe('the sensitive-field policy, entry by entry', () => {
    /*
     * Table-driven over the REAL set rather than over a list copied into the test.
     *
     * Two things follow, and the second is the point. A field added to the policy is tested
     * automatically — nobody has to remember. And a field REMOVED from the policy makes its case
     * disappear silently, which is why the guard below pins the size: a security list that
     * quietly shrinks is the failure worth catching.
     */
    it.each([...SENSITIVE_FIELDS])('redacts %s', (field) => {
        const redacted = redactSensitiveFields({ [field]: 'the-secret' }) as Record<
            string,
            unknown
        >;

        expect(redacted[field]).toBe('[REDACTED]');
    });

    it.each([...SENSITIVE_FIELDS])('redacts %s regardless of case', (field) => {
        // Keys are lowercased before the lookup, so `AUTHORIZATION` and `Authorization` are the
        // same entry. Header casing is not something a caller controls.
        const shouty = field.toUpperCase();
        const redacted = redactSensitiveFields({ [shouty]: 'the-secret' }) as Record<
            string,
            unknown
        >;

        expect(redacted[shouty]).toBe('[REDACTED]');
    });

    it('covers the whole policy, so a shrinking list cannot pass unnoticed', () => {
        // Deliberately a floor, not an exact count: adding a field should not fail a test, and
        // removing one should.
        expect(SENSITIVE_FIELDS.size).toBeGreaterThanOrEqual(20);
    });

    it('does not redact an ordinary field that merely contains a sensitive word', () => {
        // The lookup is exact, not substring. `passwordPolicy` and `tokenCount` are metadata
        // worth keeping; over-redaction quietly destroys the logs' usefulness.
        const redacted = redactSensitiveFields({
            passwordPolicy: 'strong',
            tokenCount: 3
        }) as Record<string, unknown>;

        expect(redacted.passwordPolicy).toBe('strong');
        expect(redacted.tokenCount).toBe(3);
    });
});

/** Drive the format the way winston does: one `info` record in, the same object out. */
const transform = (info: Record<string, unknown>) =>
    redactFormat().transform(info as never) as Record<string, unknown>;

describe('redactFormat — the winston wiring', () => {
    it('redacts caller metadata on the way to the transport', () => {
        // The end-to-end claim. `redactSensitiveFields` being correct is worth nothing if the
        // format that applies it is not wired in.
        const output = transform({ level: 'info', message: 'login', password: 's3cr3t' });

        expect(output.password).toBe('[REDACTED]');
    });

    it('returns the SAME object winston handed it', () => {
        // Winston requires object identity back; returning a copy silently drops the record's
        // symbol-keyed internals, and returning `false` drops the record entirely.
        const info = { level: 'info', message: 'hello' };

        expect(transform(info)).toBe(info);
    });

    it('preserves level and message, which are winston’s own fields', () => {
        const output = transform({ level: 'warn', message: 'careful', password: 'x' });

        expect(output.level).toBe('warn');
        expect(output.message).toBe('careful');
    });

    it('serialises an Error BEFORE redacting, so it does not become an empty object', () => {
        // `JSON.stringify(new Error('x'))` is `{}` — Error's fields are non-enumerable, so the
        // redaction walk would return nothing at all and the log line would lose the failure.
        const output = transform({
            level: 'error',
            message: 'failed',
            error: new Error('boom')
        });

        expect(output.error).toMatchObject({ name: 'Error', message: 'boom' });
    });

    it('redacts INSIDE a serialised error', () => {
        const error = Object.assign(new Error('boom'), { password: 'leaked' });
        const output = transform({ level: 'error', message: 'failed', error });

        expect(JSON.stringify(output)).not.toContain('leaked');
    });

    it('leaves a non-Error `error` field alone rather than mangling it', () => {
        // `throw 'string'` is legal JS, and the guard is `instanceof Error`.
        const output = transform({ level: 'error', message: 'failed', error: 'plain string' });

        expect(output.error).toBe('plain string');
    });
});

describe('resolveLogLevel', () => {
    const originalLevel = process.env.NODE_LOG_LEVEL;
    const originalEnvironment = process.env.NODE_ENV;

    afterEach(() => {
        if (originalLevel === undefined) delete process.env.NODE_LOG_LEVEL;
        else process.env.NODE_LOG_LEVEL = originalLevel;
        if (originalEnvironment === undefined) delete process.env.NODE_ENV;
        else process.env.NODE_ENV = originalEnvironment;
    });

    it('prefers an explicit NODE_LOG_LEVEL over anything else', () => {
        process.env.NODE_LOG_LEVEL = 'silly';
        process.env.NODE_ENV = 'production';

        expect(resolveLogLevel()).toBe('silly');
    });

    it('is quiet in production, to avoid paying ingestion cost for noise', () => {
        delete process.env.NODE_LOG_LEVEL;
        process.env.NODE_ENV = 'production';

        expect(resolveLogLevel()).toBe('info');
    });

    it('is verbose everywhere else, because that is where someone is watching', () => {
        delete process.env.NODE_LOG_LEVEL;
        process.env.NODE_ENV = 'development';

        expect(resolveLogLevel()).toBe('debug');
    });

    it('treats an unset NODE_ENV as non-production', () => {
        delete process.env.NODE_LOG_LEVEL;
        delete process.env.NODE_ENV;

        expect(resolveLogLevel()).toBe('debug');
    });

    it('treats an empty NODE_LOG_LEVEL as unset rather than as a level', () => {
        // An empty string in the environment is a variable someone meant to fill in; passing it
        // to winston would silence the logger completely.
        process.env.NODE_LOG_LEVEL = '';
        process.env.NODE_ENV = 'development';

        expect(resolveLogLevel()).toBe('debug');
    });
});

/**
 * `resolveConsoleFormat` decides whether a log line is machine-readable, and getting it wrong is
 * invisible: the app keeps logging, the container keeps writing, and only the *labels* in Loki go
 * missing — `{service="api"}` and `{level="error"}` silently match nothing, because Promtail
 * parses each line as JSON and colourised prose is not JSON.
 *
 * So the assertions are made on the rendered line rather than on which format object came back:
 * the property that matters downstream is "can a collector parse this", not "is this the
 * prettyFormat constant".
 */

/** Pretend stdout is (or is not) an interactive terminal for the duration of one case. */
const setTty = (isTty: boolean) => {
    Object.defineProperty(process.stdout, 'isTTY', { value: isTty, configurable: true });
};

describe('resolveConsoleFormat', () => {
    /** Winston stashes the finished output line on the record under this well-known symbol. */
    const MESSAGE = Symbol.for('message');
    /**
     * And the *uncoloured* level under this one. `colorize` looks the colour up by this symbol
     * rather than by `info.level`, precisely so it still works after it has rewritten
     * `info.level` into an escape-wrapped string — so a record without it throws instead of
     * colouring.
     */
    const LEVEL = Symbol.for('level');

    const originalEnvironment = process.env.NODE_ENV;
    const originalIsTty = process.stdout.isTTY;

    afterEach(() => {
        if (originalEnvironment === undefined) delete process.env.NODE_ENV;
        else process.env.NODE_ENV = originalEnvironment;
        setTty(originalIsTty);
    });

    /**
     * Render one record through whichever format the resolver picks, and return the line.
     *
     * The record is shaped the way winston hands one to a format — including the `LEVEL` symbol,
     * without which the colourising branch cannot run at all.
     */
    const render = (): string => {
        const format = resolveConsoleFormat();
        const rendered = format.transform({ level: 'info', message: 'hello', [LEVEL]: 'info' });
        return (rendered as Record<symbol, string>)[MESSAGE];
    };

    it('emits parseable JSON when stdout is not a terminal, which is every collected runtime', () => {
        // A container writing to its log file, a pipe, a CI job: nobody is reading this by eye
        // and something downstream has to parse it.
        process.env.NODE_ENV = 'development';
        setTty(false);

        expect(() => JSON.parse(render())).not.toThrow();
        expect(JSON.parse(render())).toMatchObject({ level: 'info', message: 'hello' });
    });

    it('emits the human layout only when a person is watching a terminal', () => {
        process.env.NODE_ENV = 'development';
        setTty(true);

        const line = render();

        expect(() => JSON.parse(line)).toThrow();
        expect(line).toContain('hello');
    });

    it('stays JSON in production even on a terminal', () => {
        // A production container started interactively still has its logs collected, so the
        // terminal says nothing about who ends up reading them.
        process.env.NODE_ENV = 'production';
        setTty(true);

        expect(() => JSON.parse(render())).not.toThrow();
    });
});

/** Re-import the module so both loggers are rebuilt from the environment as it stands now. */
const loadLoggers = async () => {
    jest.resetModules();
    return await import('@infrastructure/adapters/logger');
};

describe('the two loggers are configured independently', () => {
    /**
     * `auditLogger` carries a compliance guarantee that lives only in a comment: it "must not be
     * silenced by `NODE_LOG_LEVEL`" and "must not be reformatted for human reading in dev".
     *
     * Both are one-word changes away from being false, and neither failure is visible — the app
     * keeps running, the ordinary log keeps flowing, and the audit trail quietly stops recording.
     * Which is exactly the situation an audit trail exists to prevent.
     *
     * The module is re-imported per case because both loggers are constructed at import time
     * from the environment as it stands then.
     */
    const originalLevel = process.env.NODE_LOG_LEVEL;
    const originalEnvironment = process.env.NODE_ENV;

    afterEach(() => {
        if (originalLevel === undefined) delete process.env.NODE_LOG_LEVEL;
        else process.env.NODE_LOG_LEVEL = originalLevel;
        if (originalEnvironment === undefined) delete process.env.NODE_ENV;
        else process.env.NODE_ENV = originalEnvironment;
        jest.resetModules();
    });

    it('lets NODE_LOG_LEVEL quieten the ordinary logger', async () => {
        process.env.NODE_LOG_LEVEL = 'error';

        const { logger: appLogger } = await loadLoggers();

        expect(appLogger.level).toBe('error');
    });

    it('does NOT let NODE_LOG_LEVEL quieten the audit logger', async () => {
        // The compliance property. Set the app to `error` and audit records must still be
        // written — otherwise one environment variable erases the trail.
        process.env.NODE_LOG_LEVEL = 'error';

        const { auditLogger: audit } = await loadLoggers();

        expect(audit.level).toBe('info');
    });

    it('keeps the audit logger at info even in production', async () => {
        delete process.env.NODE_LOG_LEVEL;
        process.env.NODE_ENV = 'production';

        const { auditLogger: audit } = await loadLoggers();

        expect(audit.level).toBe('info');
    });

    it('gives both loggers at least one transport, so neither writes into the void', async () => {
        const { logger: appLogger, auditLogger: audit } = await loadLoggers();

        expect(appLogger.transports.length).toBeGreaterThan(0);
        expect(audit.transports.length).toBeGreaterThan(0);
    });
});

tests/cross-cutting/seed-conformance.tes.source:
/**
 * Does the demo dataset still match the contract it is supposed to be a specimen of?
 *
 * MIRROR of `tests/cross-cutting/seedConformance.spec.ts` in the paired frontend. Same assertions,
 * different import paths — `db/demo/demo-data.json` is byte-identical to the copy over there, so a
 * check living in only one repo would let the other's copy rot until the next
 * `check:spec-identity`. That job compares the two copies to each other; nothing compared either of
 * them to `openapi.yaml`.
 *
 * WHICH DIRECTION OF DRIFT THIS CATCHES, because only one of the two was ever covered. Renaming a
 * field in the SEED is already loud: the fixtures are typed against the mongoose documents, so a
 * `makeProduct({ imageUrl })` that no longer matches the schema is a compile error. Renaming it in
 * `openapi.yaml` was silent — the seeders keep writing the old field, the serializer keeps emitting
 * it, and nothing in either repo ever compared the result to the contract. That is the gap this
 * file closes, and it is the direction a contract-first project actually drifts in.
 *
 * WHAT CHANGED WHEN THE DATASET STARTED BEING EXPORTED. This used to parse `seed-identities.ts`, a
 * file of hand-written FACTS, which meant every schema here needed surgery before it could be used:
 * the user schema was `.extend()`ed with a `password` and a `cart` the API never returns, and the
 * order schema was `.pick()`ed down to four fields because a fixture had no business stating a
 * total or a status.
 *
 * `demo-data.json` holds what the API actually answered, so the schemas are used AS GENERATED. The
 * totals and the status are in there now — derived by `applyOrderTransform`, and therefore worth
 * checking, where a seeded guess at them would only have tested the guess.
 *
 * `.strict()` is what makes these catch a RENAME in both directions. Orval emits a plain
 * `zod.object()` even though `openapi.yaml` says `additionalProperties: false`, and almost every
 * property is optional because a client must tolerate a sparse server. Parsed as generated, a row
 * still carrying `imageUrl` after the contract renamed it to `image` would pass twice over: the
 * stale key is STRIPPED as unknown, and the new one is absent-but-optional. `.strict()` fails on
 * the stale key; the `.required()` masks fail on the missing one.
 */

import {
    CreateLocaleEntryResponse,
    CreateLocaleResponse,
    CreateUserBody,
    GetAddressesResponse,
    GetCartResponse,
    GetOrderByIdResponse,
    GetProductByIdResponse,
    GetUserByIdResponse,
    GetWishlistResponse
} from '@api/schemas.zod';
import { listSupportedLocales } from '@infrastructure/i18n';
import dataset from '../../db/demo/demo-data.json';

const { _meta, credentials, collections } = dataset;

/*
 * The `.required()` masks are where "a seeded record is a complete specimen" stops being a comment.
 * The wire type is permissive on purpose; every seeded row promises these fields, and both repos
 * read them with no `?? fallback`. `deletedAt` stays optional throughout: it is present on exactly
 * one product and one order, by design.
 */
const productSchema = GetProductByIdResponse.shape.data
    .required({
        // All three stock fields, including the derived one: `available` is required on the wire
        // and computed at serialization, so a seeded row missing it would mean the transform did
        // not run — exactly the kind of silent gap this mask exists to catch.
        onHand: true,
        reserved: true,
        available: true,
        description: true,
        active: true,
        imageUrl: true,
        categories: true,
        tags: true
    })
    .strict();

const userSchema = GetUserByIdResponse.shape.data
    .required({ admin: true, active: true, imageUrl: true })
    .strict();

const orderSchema = GetOrderByIdResponse.shape.data.strict();

/** `{ productId, quantity }` — one line of a stored cart. */
const cartItemSchema = GetCartResponse.shape.data.shape.items.element.strict();

/**
 * One entry of a stored address book, which is the contract's `Address` exactly.
 *
 * A book is never served raw — `GET /account/addresses` answers `{ addresses: [...] }` — but its
 * ENTRIES are what that array carries, so the stored subdocument and the wire object are the same
 * shape by construction. `.strict()` is doing real work here: an entry serializing as `_id`
 * instead of `id` is precisely the drift this catches, and it is what the collection published
 * before `addressItemSchema` carried the shared serializer.
 */
const addressSchema = GetAddressesResponse.shape.data.shape.addresses.element.strict();

const wishlistProductIdSchema = GetWishlistResponse.shape.data.shape.items.element.shape.productId;

/**
 * The two dynamic-locale collections.
 *
 * Taken from the CREATE responses rather than from a read: a stored row and the row a write
 * answers with are the same object here, and those are the only operations whose `data` is a
 * single language or a single entry. `.required()` masks the fields every seeded row promises —
 * `active` and `direction` are schema defaults, so a row missing one would mean the default
 * stopped applying, which is exactly the kind of drift an exported dataset exists to catch.
 */
const languageSchema = CreateLocaleResponse.shape.data
    .required({ createdAt: true, updatedAt: true })
    .strict();

const localeEntrySchema = CreateLocaleEntryResponse.shape.data
    .required({ createdAt: true, updatedAt: true })
    .strict();

const idSchema = GetUserByIdResponse.shape.data.shape.id;

describe('the exported dataset conforms to the generated contract', () => {
    describe('products', () => {
        it('parse against the generated product schema', () => {
            expect(collections.products.length).toBeGreaterThan(0);
            for (const product of collections.products) {
                expect(() => productSchema.parse(product)).not.toThrow();
            }
        });

        it('carry exactly one soft-deleted and one inactive specimen', () => {
            /* Both branches of `publicScope()` need a fixture behind them, and a branch with no
             * fixture is a branch nothing exercises. */
            expect(collections.products.filter((product) => 'deletedAt' in product)).toHaveLength(
                1
            );
            expect(collections.products.filter((product) => !product.active)).toHaveLength(1);
        });
    });

    describe('users', () => {
        it('parse against the generated user schema', () => {
            expect(collections.users.length).toBeGreaterThan(0);
            for (const user of collections.users) {
                expect(() => userSchema.parse(user)).not.toThrow();
            }
        });

        it('never publish a password or a token', () => {
            /* `applyUserTransform` omits both and the schema marks them `select: false`. This is the
             * assertion that would fail if the export ever started reading rows some other way. */
            for (const user of collections.users) {
                expect(user).not.toHaveProperty('password');
                expect(user).not.toHaveProperty('tokens');
            }
        });

        it('include one admin and one ordinary account', () => {
            expect(collections.users.filter((user) => user.admin)).toHaveLength(1);
            expect(collections.users.filter((user) => !user.admin)).toHaveLength(1);
        });
    });

    describe('credentials', () => {
        it('would be accepted by the real signup policy', () => {
            /* `CreateUserBody.shape.password` IS the policy — a published credential the API would
             * reject is a demo nobody can re-register by hand, and the frontend's `cy.loginAs()`
             * types these into a real form. */
            for (const account of Object.values(credentials)) {
                expect(() => CreateUserBody.shape.password.parse(account.password)).not.toThrow();
            }
        });

        it('name accounts the dataset actually contains', () => {
            const emails = new Set(collections.users.map((user) => user.email));
            for (const account of Object.values(credentials)) {
                expect(emails).toContain(account.email);
            }
        });
    });

    describe('orders', () => {
        it('parse against the generated order schema, totals included', () => {
            expect(collections.orders.length).toBeGreaterThan(0);
            for (const order of collections.orders) {
                expect(() => orderSchema.parse(order)).not.toThrow();
            }
        });

        it('carry the totals the serializer derived rather than stored values', () => {
            /* Recomputed here from the lines, which is the one place restating the arithmetic is
             * the point: if `applyOrderTransform` ever stops agreeing with its own inputs, the
             * published dataset would carry the disagreement into the frontend's mocks. */
            for (const order of collections.orders) {
                const quantity = order.items.reduce((sum, item) => sum + item.quantity, 0);
                const price = order.items.reduce(
                    (sum, item) => sum + item.product.price * item.quantity,
                    0
                );
                expect(order.totalItems).toBe(order.items.length);
                expect(order.totalQuantity).toBe(quantity);
                /* Plus the shipping frozen at checkout, which `applyOrderTransform` folds into the
                 * total. Written out rather than assumed zero: one fixture chose a method, and an
                 * assertion that ignored the column would go green on an order whose published
                 * total silently dropped it. */
                expect(order.totalPrice).toBe(price + (order.shippingCost ?? 0));
            }
        });

        it('include one soft-deleted order, owned by the NON-admin account', () => {
            /* The case this exercises is "the owner cannot see their own soft-deleted order", which
             * ownership-only scoping would wrongly allow and an admin-owned fixture could not
             * catch. */
            const deleted = collections.orders.filter((order) => 'deletedAt' in order);
            expect(deleted).toHaveLength(1);

            const admin = collections.users.find((user) => user.admin);
            expect(deleted[0].userId).not.toBe(admin?.id);
        });
    });

    describe('address books', () => {
        it('parse their entries against the generated address schema', () => {
            const entries = collections.addressBooks.flatMap((book) => book.items);
            expect(entries.length).toBeGreaterThan(0);
            for (const entry of entries) {
                expect(() => addressSchema.parse(entry)).not.toThrow();
            }
        });

        it('carry exactly one default per book, the invariant the repository maintains', () => {
            /* `addEntry`/`updateEntry`/`removeEntry` all exist to keep this true of a non-empty
             * book. A dataset that broke it would hand the paired frontend a book its checkout
             * cannot pick a default from — and would do it silently, since no endpoint validates
             * a book it did not write. */
            expect(collections.addressBooks.length).toBeGreaterThan(0);
            for (const book of collections.addressBooks) {
                expect(book.items.filter((entry) => entry.default)).toHaveLength(1);
            }
        });

        it('include one entry with no phone, so an absent optional has a specimen', () => {
            const entries = collections.addressBooks.flatMap((book) => book.items);
            expect(entries.some((entry) => !('phone' in entry))).toBe(true);
        });
    });

    describe('carts', () => {
        it('parse their lines against the generated cart item schema', () => {
            const items = collections.carts.flatMap((cart) => cart.items);
            expect(items.length).toBeGreaterThan(0);
            for (const item of items) {
                expect(() => cartItemSchema.parse(item)).not.toThrow();
            }
        });
    });

    describe('languages', () => {
        it('parse against the generated language schema', () => {
            expect(collections.locales.length).toBeGreaterThan(0);
            for (const language of collections.locales) {
                expect(() => languageSchema.parse(language)).not.toThrow();
            }
        });

        it('carry both a published language and a draft', () => {
            /* Both branches of the visibility rule need a fixture behind them: an inactive
             * language must be absent from `GET /locales` and 404 on its dictionary, and neither
             * is checkable against a dataset where every language is active. */
            expect(
                collections.locales.filter((language) => language.active).length
            ).toBeGreaterThan(0);
            expect(
                collections.locales.filter((language) => !language.active).length
            ).toBeGreaterThan(0);
        });

        it('include a language the API also has a deployed file for', () => {
            /* The row that makes the manifest's merge real — one entry carrying both tenants and
             * `source: 'both'`. A dataset of languages the API cannot answer in would exercise
             * only half of it, which is exactly what happened while `es` played this part: it has
             * since become the database-only fixture and carries no deployed file at all. Read
             * from `listSupportedLocales()` rather than naming a tag, so this keeps asserting the
             * property and not one repository's current spelling of it. */
            const deployed = new Set(listSupportedLocales());

            expect(collections.locales.some((language) => deployed.has(language.tag))).toBe(true);
        });

        it('include a language with no deployed file, which is the tier this module exists for', () => {
            /* The converse, and the one the split is FOR: a language a client can download a
             * dictionary for and the API cannot answer a single request in. Without it the whole
             * dataset would be languages the filesystem already provides, and `tenants` would never
             * be observed carrying anything but both of them. */
            const deployed = new Set(listSupportedLocales());

            expect(collections.locales.some((language) => !deployed.has(language.tag))).toBe(true);
        });

        it('include a language with nothing translated into it yet', () => {
            /* The state between `POST /locales` and the first entry. Every count that reads this
             * collection has to survive it — `entryCount` of 0, a `revision` still at its default
             * — and a dataset where every language has rows checks none of that. */
            const translated = new Set(collections.localeMessages.map((entry) => entry.locale));
            const untranslated = collections.locales.filter(
                (language) => !translated.has(language.tag)
            );

            expect(untranslated.length).toBeGreaterThan(0);
            expect(untranslated.every((language) => language.revision === 0)).toBe(true);
        });
    });

    describe('locale entries', () => {
        it('parse against the generated entry schema', () => {
            expect(collections.localeMessages.length).toBeGreaterThan(0);
            for (const entry of collections.localeMessages) {
                expect(() => localeEntrySchema.parse(entry)).not.toThrow();
            }
        });

        it('name only languages the dataset also publishes', () => {
            /* The referential integrity a tag string buys instead of an ObjectId reference. An
             * entry pointing at a language nobody registered would render as a dictionary the
             * manifest never lists — and `scripts/export-demo-dataset.ts`'s dangling-reference sweep
             * cannot see it, because it matches keys ending in `Id`. */
            const tags = new Set(collections.locales.map((language) => language.tag));
            for (const entry of collections.localeMessages) {
                expect(tags).toContain(entry.locale);
            }
        });

        it('carry a key nested at least three levels deep', () => {
            /* A flat fixture set would let a tree builder that only ever nests once pass its own
             * tests and the contract suite alike. */
            expect(
                collections.localeMessages.some((entry) => entry.key.split('.').length >= 3)
            ).toBe(true);
        });

        it('never carry a key that collides with another in the same language', () => {
            /* `products.list` alongside `products.list.title` cannot be expressed as one tree, so
             * a dataset containing the pair would make `GET /locales/:locale/messages` throw for
             * the seeded language — and would do it in the paired frontend's mocks too. */
            const byLanguage = new Map<string, string[]>();
            for (const entry of collections.localeMessages)
                byLanguage.set(entry.locale, [...(byLanguage.get(entry.locale) ?? []), entry.key]);

            for (const [, keys] of byLanguage)
                for (const key of keys)
                    for (const other of keys)
                        if (other !== key) expect(other.startsWith(`${key}.`)).toBe(false);
        });
    });

    describe('wishlists', () => {
        it('parse their owner and their saved products against the generated id scalars', () => {
            expect(collections.wishlists.length).toBeGreaterThan(0);
            for (const wishlist of collections.wishlists) {
                expect(() => idSchema.parse(wishlist.userId)).not.toThrow();
                for (const item of wishlist.items) {
                    expect(() => wishlistProductIdSchema.parse(item.productId)).not.toThrow();
                }
            }
        });

        it('save only products the storefront would actually show', () => {
            /* A saved line pointing at the soft-deleted or inactive fixture renders as a hole in the
             * wishlist page: the row resolves to a product the scoping rules then refuse. */
            const visible = new Set(
                collections.products
                    .filter((product) => product.active && !('deletedAt' in product))
                    .map((product) => product.id)
            );
            for (const wishlist of collections.wishlists) {
                for (const item of wishlist.items) {
                    expect(visible).toContain(item.productId);
                }
            }
        });
    });

    /**
     * `_meta.shapes` — what the consumer is allowed to do with each collection.
     *
     * The map is the artefact's answer to the only question a mock author asks of it: can I return
     * this row as it stands? `scripts/export-demo-dataset.ts` refuses to publish an unclassified
     * collection, so these cases are the second net — they hold the COMMITTED file to the rule, in
     * both repos, which is what covers the frontend's copy between exports.
     */
    describe('the shapes map', () => {
        it('names every published collection, and only those', () => {
            expect(Object.keys(_meta.shapes).toSorted()).toStrictEqual(
                Object.keys(collections).toSorted()
            );
        });

        it('classifies each one as either servable or not', () => {
            /* A JSON import widens the values to `string`, so the union the manifest declares is
             * not checked on the way back in. A third value would be a consumer reading a label it
             * has no branch for. */
            for (const shape of Object.values(_meta.shapes)) {
                expect(['response', 'stored']).toContain(shape);
            }
        });

        it('calls a collection servable exactly when this file parses it as a whole response', () => {
            /* The tripwire on a mislabel, which is the failure the map introduces: a wrong label is
             * worse than none, because the reader stops checking. Every collection above parses
             * against SOMETHING, but only these three parse against a whole `Get<X>ByIdResponse`
             * payload — the rest are checked through an element or a nested field, which is itself
             * the evidence that no endpoint serves the row. Relabel a collection and this list has
             * to move with it, deliberately. */
            const parsedAsWholeResponses = ['orders', 'products', 'users'];

            const servable = Object.entries(_meta.shapes)
                .filter(([, shape]) => shape === 'response')
                .map(([name]) => name);

            expect(servable.toSorted()).toStrictEqual(parsedAsWholeResponses);
        });
    });
});

