import { asStub } from '@tests/stub';
import type { Request } from 'express';
import type { FileFilterCallback } from 'multer';
import { existsSync } from 'node:fs';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import {
    fileFilter,
    maxUploadBytes,
    resolveUploadDestination,
    resolveUploadFilename,
    uploadStagingPath,
    validateUploadedImages
} from '@infrastructure/adapters/storage';

/**
 * The upload callbacks.
 *
 * They look like plumbing and are actually the whole of this repo's upload security: a field
 * whitelist, a name that is never derived from client input, and a type check. Each is a
 * `(request, file, callback)` that multer's storage engine keeps to itself, so they were
 * unreachable from a test until they were exported — which is why none of this was asserted.
 *
 * Written against behaviour a reviewer would want guaranteed, not against the current lines: a
 * refactor that keeps the guarantees should keep these green.
 */

const fileOf = (overrides: Partial<Express.Multer.File> = {}) =>
    ({
        fieldname: 'imageUpload',
        originalname: 'holiday.png',
        mimetype: 'image/png',
        ...overrides
    }) as Express.Multer.File;

const request = {} as Request;

/** Whether `fileFilter` accepted the file. */
const accepted = (file: Express.Multer.File) => {
    let result: boolean | undefined;
    fileFilter(
        request,
        file,
        asStub<FileFilterCallback>((_error: Error | null, accept: boolean) => {
            result = accept;
        })
    );
    return result;
};

/** Runs a `(error, value)` callback style function and returns both arms. */
const capture = (
    run: (callback: (error: Error | null, value: string) => void) => void
): { error: Error | null; value: string } => {
    let captured: { error: Error | null; value: string } = {
        error: null,
        value: ''
    };
    run((error, value) => {
        captured = { error, value };
    });
    return captured;
};

/** The async form of {@link capture}: the destination callback now waits on a `mkdir`. */
const captureAsync = (run: (callback: (error: Error | null, value: string) => void) => void) =>
    new Promise<{ error: Error | null; value: string }>((resolve) => {
        run((error, value) => resolve({ error, value }));
    });

describe('maxUploadBytes', () => {
    const original = process.env.NODE_MAX_UPLOAD_BYTES;
    afterEach(() => {
        if (original === undefined) delete process.env.NODE_MAX_UPLOAD_BYTES;
        else process.env.NODE_MAX_UPLOAD_BYTES = original;
    });

    /*
     * Read at call time, not at import. Multer freezes `limits` when the instance is constructed,
     * so building it at module scope fixed the cap before `.env` was necessarily loaded — and left
     * a test setting the variable with no way to tell whether its value had been used.
     */
    it('answers the configured value rather than one captured at import', () => {
        process.env.NODE_MAX_UPLOAD_BYTES = '2048';

        expect(maxUploadBytes()).toBe(2048);
    });

    it.each(['', 'not-a-number', '0', '-1'])(
        'falls back to the default for %p, which is not a size',
        (value) => {
            process.env.NODE_MAX_UPLOAD_BYTES = value;

            expect(maxUploadBytes()).toBe(5 * 1024 * 1024);
        }
    );
});

describe('resolveUploadDestination', () => {
    const originalStagingPath = process.env.NODE_UPLOAD_STAGING_PATH;
    let staging: string;

    beforeEach(async () => {
        // Deliberately a path that does NOT exist yet — multer will not create its destination, so
        // the resolver has to, and an upload against a fresh container must not fail on that.
        staging = path.join(await mkdtemp(path.join(tmpdir(), 'staging-test-')), 'uploads');
        process.env.NODE_UPLOAD_STAGING_PATH = staging;
    });

    afterEach(async () => {
        await rm(path.dirname(staging), { recursive: true, force: true });
        if (originalStagingPath === undefined) delete process.env.NODE_UPLOAD_STAGING_PATH;
        else process.env.NODE_UPLOAD_STAGING_PATH = originalStagingPath;
    });

    it('stages a known upload field in the configured directory, creating it', async () => {
        const { error, value } = await captureAsync((callback) =>
            resolveUploadDestination(request, fileOf(), callback)
        );

        expect(error).toBeNull();
        expect(value).toBe(staging);
        expect(existsSync(staging)).toBe(true);
    });

    /**
     * The property the staging directory exists for. While a request is in flight its upload has
     * passed no check yet — not the content check, not validation — so it must not be sitting
     * somewhere `express.static` will hand to anyone who asks.
     */
    it('never stages inside the served public directory', () => {
        delete process.env.NODE_UPLOAD_STAGING_PATH;
        const publicRoot = path.resolve(process.env.NODE_PUBLIC_PATH ?? 'public');

        expect(path.resolve(uploadStagingPath()).startsWith(publicRoot + path.sep)).toBe(false);
    });

    /**
     * A whitelist, not a blacklist. An unexpected field name is more likely an attack or a client
     * bug than a legitimate upload, and defaulting it into a shared directory is how uploads end
     * up somewhere nobody is watching.
     */
    it.each(['pdfUpload', 'avatar', '', '../../etc'])(
        'rejects the unknown field %p instead of defaulting it somewhere',
        (fieldname) => {
            const { error, value } = capture((callback) =>
                resolveUploadDestination(request, fileOf({ fieldname }), callback)
            );

            expect(error).toBeInstanceOf(Error);
            expect(value).toBe('');
        }
    );
});

describe('resolveUploadFilename', () => {
    /**
     * The property that matters: nothing a client controls reaches the filesystem path. Reusing
     * `originalname` would allow traversal, silent overwrites by collision, and enumeration of
     * other users' uploads.
     */
    it.each([
        ['a traversal attempt', '../../etc/passwd.png'],
        ['an absolute path', '/etc/shadow.png'],
        ['a null byte', 'evil�.png'],
        ['an ordinary name', 'holiday.png']
    ])('derives a random name, discarding %s', (_label, originalname) => {
        const { error, value } = capture((callback) =>
            resolveUploadFilename(request, fileOf({ originalname }), callback)
        );

        expect(error).toBeNull();
        expect(value).toMatch(/^[\da-f]{32}\.png$/);
    });

    it('produces a different name every time, so an upload cannot overwrite another', () => {
        const names = new Set(
            Array.from(
                { length: 50 },
                () =>
                    capture((callback) => resolveUploadFilename(request, fileOf(), callback)).value
            )
        );

        expect(names.size).toBe(50);
    });

    /**
     * A type outside the accepted set cannot reach here — `fileFilter` rejects it first — but if
     * one ever did, it must not become an extension a static server would honour.
     */
    it('falls back to an inert extension for an unrecognised type', () => {
        const { value } = capture((callback) =>
            resolveUploadFilename(request, fileOf({ mimetype: 'text/html' }), callback)
        );

        expect(value.endsWith('.bin')).toBe(true);
    });
});

describe('fileFilter', () => {
    it.each(['image/png', 'image/jpeg', 'image/jpg'])('accepts %s', (mimetype) => {
        expect(accepted(fileOf({ mimetype }))).toBe(true);
    });

    it.each(['application/pdf', 'text/html', 'image/svg+xml', 'application/octet-stream'])(
        'rejects %s',
        (mimetype) => {
            expect(accepted(fileOf({ mimetype }))).toBe(false);
        }
    );

    /**
     * A rejected file is DROPPED, not errored: the request still succeeds with no `request.file`,
     * so every handler must treat a missing file as a validation failure. Pinned here because the
     * alternative reading — "rejection surfaces as a request error" — is the intuitive one and is
     * wrong.
     */
    it('drops a rejected file rather than failing the request', () => {
        let error: unknown = 'not called';
        fileFilter(
            request,
            fileOf({ mimetype: 'application/pdf' }),
            asStub<FileFilterCallback>((callbackError: Error | null) => {
                error = callbackError;
            })
        );

        expect(error).toBeNull();
    });
});

// ─── validateUploadedImages: the content check ───────────────────────────────
/**
 * The middleware that decides whether an upload's BYTES are what its headers claimed.
 *
 * This is the security control the rest of the upload path is arranged around, and it had no
 * test at all — every branch reported "no coverage". `fileFilter` sees only the declared
 * `Content-Type`, which the client chooses freely, so a file disguised as an image passes it
 * without difficulty. Only this check reads the leading bytes, and only it runs late enough to
 * do so: the bytes do not exist until multer has written them.
 *
 * Two distinct rejections, and the second is easy to miss:
 *
 *   1. the bytes are not a recognised image at all — the disguised-upload case;
 *   2. the bytes ARE an image, but not the one that was declared.
 *
 * (2) matters because the declared type chose the stored file EXTENSION, and the extension is
 * what a static file server reads to pick the `Content-Type` it serves. JPEG bytes stored as
 * `.png` would be served as `image/png` — the same class of mismatch this check exists to
 * remove.
 *
 * A rejected file must also be DELETED. Leaving it costs disk on every probe, and the whole
 * argument for staging uploads privately is that a rejected file's lifetime is measured in
 * milliseconds.
 */
const mockIdentifyImageFile = jest.fn<Promise<string | undefined>, [string]>();
const mockDeleteFile = jest.fn<Promise<void>, [string]>();

jest.mock('@infrastructure/adapters/image-signatures', () => ({
    ...jest.requireActual('@infrastructure/adapters/image-signatures'),
    identifyImageFile: (filePath: string) => mockIdentifyImageFile(filePath)
}));

jest.mock('@infrastructure/adapters/filesystem', () => ({
    ...jest.requireActual('@infrastructure/adapters/filesystem'),
    deleteFile: (filePath: string) => mockDeleteFile(filePath)
}));

jest.mock('@infrastructure/adapters/logger', () => ({
    logger: { info: jest.fn(), warn: jest.fn(), error: jest.fn(), debug: jest.fn() }
}));

/**
 * A request carrying one staged file, the `multer.single()` shape.
 *
 * `request.file` is also where the DECLARED type lives, so this is the only shape in which
 * the declared-vs-actual comparison has anything to compare.
 */
const requestWithFile = (filePath: string, mimetype?: string) =>
    asStub<Request>({ file: { path: filePath, mimetype }, requestId: 'test-request' });

/**
 * A request carrying several staged files, the `multer.array()` shape.
 *
 * Note there is no `request.file` here and therefore no declared type — `getFormFiles`
 * prefers the single-file field when both are present. With nothing declared, only the
 * "these bytes are not an image" rejection can fire, which is the behaviour, not a
 * limitation of the fixture.
 */
const requestWithFiles = (paths: string[]) =>
    asStub<Request>({
        files: paths.map((filePath) => ({ path: filePath })),
        requestId: 'test-request'
    });

/** Run the middleware and resolve with whatever it handed `next`. */
const runMiddleware = (request: Request): Promise<unknown> =>
    new Promise((resolve) => {
        validateUploadedImages(request, {} as never, resolve as never);
    });

describe('validateUploadedImages', () => {
    beforeEach(() => {
        mockDeleteFile.mockImplementation(() => Promise.resolve());
    });

    it('passes a request with no uploads straight through', async () => {
        const error = await runMiddleware(asStub<Request>({ requestId: 'x' }));

        expect(error).toBeUndefined();
        expect(mockIdentifyImageFile).not.toHaveBeenCalled();
    });

    it('accepts a file whose bytes match what was declared', async () => {
        mockIdentifyImageFile.mockImplementation(() => Promise.resolve('image/png'));

        const error = await runMiddleware(requestWithFile('/tmp/a.png', 'image/png'));

        expect(error).toBeUndefined();
        expect(mockDeleteFile).not.toHaveBeenCalled();
    });

    it('rejects and deletes a file whose bytes are not an image at all', async () => {
        // The disguised upload: a script named `.png` and declared `image/png`. `fileFilter` let
        // it through, because everything it can see says image.
        // `undefined` is `identifyImageFile`'s answer for "these bytes are not an image".
        mockIdentifyImageFile.mockResolvedValue(undefined);

        const error = (await runMiddleware(requestWithFile('/tmp/evil.png', 'image/png'))) as {
            httpCode?: number;
        };

        expect(error?.httpCode).toBe(422);
        expect(mockDeleteFile).toHaveBeenCalledWith('/tmp/evil.png');
    });

    it('rejects an image of the wrong kind, not merely a non-image', async () => {
        // Real JPEG bytes, declared as PNG. Every "is it an image" check passes; this is the
        // comparison against the DECLARED type, and it is the half a simpler implementation
        // leaves out.
        mockIdentifyImageFile.mockImplementation(() => Promise.resolve('image/jpeg'));

        const error = (await runMiddleware(
            requestWithFile('/tmp/mislabelled.png', 'image/png')
        )) as { httpCode?: number };

        expect(error?.httpCode).toBe(422);
        expect(mockDeleteFile).toHaveBeenCalledWith('/tmp/mislabelled.png');
    });

    it('treats image/jpg as image/jpeg rather than a mismatch', async () => {
        // A widespread client-side spelling that is not a real MIME type. Rejecting it would fail
        // legitimate uploads, so it is normalised before the comparison.
        mockIdentifyImageFile.mockImplementation(() => Promise.resolve('image/jpeg'));

        const error = await runMiddleware(requestWithFile('/tmp/photo.jpg', 'image/jpg'));

        expect(error).toBeUndefined();
    });

    it('still requires a recognised image when nothing was declared', async () => {
        // With no declared type there is nothing to compare against, so only the first rejection
        // applies — but it must still apply. Skipping the check when the header is absent would
        // make the whole control opt-out by the client.
        // `undefined` is `identifyImageFile`'s answer for "these bytes are not an image".
        mockIdentifyImageFile.mockResolvedValue(undefined);

        const error = (await runMiddleware(requestWithFile('/tmp/unknown.bin'))) as {
            httpCode?: number;
        };

        expect(error?.httpCode).toBe(422);
    });

    it('deletes only the files it rejected, in a mixed batch', async () => {
        // Deleting the accepted ones too would destroy a valid upload because a sibling was bad;
        // deleting none leaves the rejected bytes on disk. Both are one line away.
        mockIdentifyImageFile.mockImplementation((filePath) =>
            Promise.resolve(filePath === '/tmp/bad.png' ? undefined : 'image/png')
        );

        const error = (await runMiddleware(
            requestWithFiles(['/tmp/good.png', '/tmp/bad.png'])
        )) as { httpCode?: number };

        expect(error?.httpCode).toBe(422);
        expect(mockDeleteFile).toHaveBeenCalledWith('/tmp/bad.png');
        expect(mockDeleteFile).not.toHaveBeenCalledWith('/tmp/good.png');
    });

    it('surfaces an identification failure instead of accepting the upload', async () => {
        // Failing open here would mean an unreadable staging directory silently disables the
        // content check — the control would be off exactly when the system is unhealthy.
        mockIdentifyImageFile.mockImplementation(() => Promise.reject(new Error('EIO')));

        const error = (await runMiddleware(requestWithFile('/tmp/a.png', 'image/png'))) as Error;

        expect(error).toBeInstanceOf(Error);
    });
});

