/**
 * The SSE metrics stream.
 *
 * This was one of two honest zeros in the mutation report: a suite could reach it and
 * none did. Three things here are only observable from outside the module, and each fails silently:
 *
 *   - **The wire format.** `event:`/`data:` and the blank line that ends a frame are
 *     whitespace-significant. Drop the trailing newline and every client buffers forever while the
 *     server looks healthy.
 *   - **Teardown.** A disconnect that does not clear both intervals leaves timers writing to a dead
 *     socket for the life of the process, and a `Set` entry that is never deleted pins the whole
 *     `Response` in memory. Neither shows up as an error anywhere.
 *   - **Error absorption.** A rejected metrics read, or a `write()` to a socket the client already
 *     dropped, must not escape an interval callback — an unhandled rejection there takes the
 *     process down.
 *
 * `getHttpRequestCounters` is mocked and the clock is faked, so the frames are deterministic.
 */
import { asStub } from '@tests/stub';
import type { Response } from 'express';

const getHttpRequestCounters = jest.fn(() =>
    Promise.resolve({ totalRequests: 10, totalErrors: 2 })
);

jest.mock('@infrastructure/observability/metrics-http', () => ({
    getHttpRequestCounters: () => getHttpRequestCounters()
}));

import {
    buildObservabilityPayload,
    getActiveSseClients,
    streamObservabilityMetrics
} from '@infrastructure/observability/stream';

/** The intervals the module schedules, as documented in its own constants. */
const UPDATE_INTERVAL_MS = 5000;
const HEARTBEAT_INTERVAL_MS = 15_000;

interface FakeResponse {
    response: Response;
    /** Every string handed to `write`, in order. */
    frames: string[];
    headers: Record<string, string>;
    status: jest.Mock;
    flushHeaders: jest.Mock;
    write: jest.Mock;
    /** Fires the `close` handler the module registered, as a real disconnect would. */
    disconnect: () => void;
}

/**
 * A `Response` with only the surface this module touches.
 *
 * Hand-built rather than a real Express response: the point is to read the exact bytes written and
 * to fire `close` on demand, neither of which a real socket makes easy.
 */
const makeResponse = (): FakeResponse => {
    const frames: string[] = [];
    const headers: Record<string, string> = {};
    const closeHandlers: (() => void)[] = [];

    const status = jest.fn();
    const flushHeaders = jest.fn();
    const write = jest.fn((frame: string) => {
        frames.push(frame);
        return true;
    });

    const response = asStub<Response>({
        status,
        flushHeaders,
        write,
        setHeader: jest.fn((name: string, value: string) => {
            headers[name] = value;
        }),
        on: jest.fn((event: string, handler: () => void) => {
            if (event === 'close') closeHandlers.push(handler);
        })
    });

    return {
        response,
        frames,
        headers,
        status,
        flushHeaders,
        write,
        disconnect: () => {
            for (const handler of closeHandlers) handler();
        }
    };
};

/** A written frame, split back into the parts the SSE format defines. */
const parseFrame = (frame: string) => {
    const [eventLine, dataLine, ...rest] = frame.split('\n');
    return {
        event: eventLine?.replace('event: ', ''),
        payload: JSON.parse(dataLine?.replace('data: ', '') ?? '{}') as Record<string, unknown>,
        /** The frame terminator: two newlines mean two empty strings after the data line. */
        terminator: rest
    };
};

describe('the SSE metrics stream', () => {
    /** Responses opened by a test, disconnected afterwards so the module-level Set starts empty. */
    let opened: FakeResponse[] = [];

    const open = () => {
        const fake = makeResponse();
        streamObservabilityMetrics(fake.response);
        opened.push(fake);
        return fake;
    };

    beforeEach(() => {
        jest.useFakeTimers();
        getHttpRequestCounters.mockImplementation(() =>
            Promise.resolve({ totalRequests: 10, totalErrors: 2 })
        );
    });

    afterEach(() => {
        for (const fake of opened) fake.disconnect();
        opened = [];
        jest.useRealTimers();
    });

    describe('buildObservabilityPayload', () => {
        it('reports memory, http counters and connection count in one frame', async () => {
            jest.spyOn(process, 'memoryUsage').mockReturnValue({
                rss: 100,
                heapUsed: 40,
                heapTotal: 60,
                external: 5,
                arrayBuffers: 1
            });

            const payload = await buildObservabilityPayload();

            expect(payload.memory).toEqual({ rss: 100, heapUsed: 40, heapTotal: 60, external: 5 });
            expect(payload.http).toEqual({ totalRequests: 10, totalErrors: 2 });
            expect(payload.realtime).toEqual({ sseClients: 0 });
        });

        it('stamps an ISO-8601 timestamp, so the client can compute its own skew', async () => {
            const { timestamp } = await buildObservabilityPayload();

            expect(timestamp).toBe(new Date(timestamp).toISOString());
        });

        it('floors uptime to whole seconds, like every other payload that publishes it', async () => {
            /*
             * Floor rather than round, and that is the whole point of the shared reader in
             * `infrastructure/observability/process-snapshot.ts`. A dashboard shows this frame
             * beside `GET /observability/health`; while this one rounded and that one floored, the
             * two reported uptimes a second apart with nothing wrong in either.
             */
            jest.spyOn(process, 'uptime').mockReturnValue(12.7);

            await expect(buildObservabilityPayload()).resolves.toMatchObject({ uptimeSeconds: 12 });
        });
    });

    describe('getActiveSseClients', () => {
        it('counts one entry per open stream and releases it on disconnect', () => {
            expect(getActiveSseClients()).toBe(0);

            const first = open();
            const second = open();
            expect(getActiveSseClients()).toBe(2);

            first.disconnect();
            expect(getActiveSseClients()).toBe(1);

            second.disconnect();
            expect(getActiveSseClients()).toBe(0);
        });

        it('is reported inside the payload the connections themselves feed', async () => {
            open();

            await expect(buildObservabilityPayload()).resolves.toMatchObject({
                realtime: { sseClients: 1 }
            });
        });
    });

    describe('opening a stream', () => {
        it('answers 200 with the headers that make a response an SSE stream', () => {
            const fake = open();

            expect(fake.status).toHaveBeenCalledWith(200);
            expect(fake.headers).toEqual({
                'Content-Type': 'text/event-stream',
                'Cache-Control': 'no-cache, no-transform',
                Connection: 'keep-alive'
            });
        });

        it('flushes the headers immediately, rather than leaving the client waiting', () => {
            const fake = open();

            expect(fake.flushHeaders).toHaveBeenCalledTimes(1);
        });

        it('sends a snapshot at once, so the dashboard is not blank until the first interval', async () => {
            const fake = open();

            await jest.advanceTimersByTimeAsync(0);

            expect(fake.frames).toHaveLength(1);
            expect(parseFrame(fake.frames[0]).event).toBe('observability.metrics.snapshot');
        });

        it('writes a frame the SSE format actually terminates', async () => {
            const fake = open();
            await jest.advanceTimersByTimeAsync(0);

            const frame = fake.frames[0];

            expect(frame.startsWith('event: ')).toBe(true);
            expect(frame).toContain('\ndata: ');
            // The blank line IS the frame boundary; without it the client buffers indefinitely
            expect(frame.endsWith('\n\n')).toBe(true);
            expect(parseFrame(frame).terminator).toEqual(['', '']);
        });

        it('keeps each payload on one line, as the data field requires', async () => {
            const fake = open();
            await jest.advanceTimersByTimeAsync(0);

            const [, dataLine] = fake.frames[0].split('\n');

            expect(dataLine).toBeDefined();
            expect(dataLine).not.toContain('\n');
            expect(() => JSON.parse(dataLine.replace('data: ', ''))).not.toThrow();
        });
    });

    describe('the two timers', () => {
        it('pushes an update every five seconds', async () => {
            const fake = open();
            await jest.advanceTimersByTimeAsync(0);

            await jest.advanceTimersByTimeAsync(UPDATE_INTERVAL_MS);

            expect(fake.frames.map((frame) => parseFrame(frame).event)).toEqual([
                'observability.metrics.snapshot',
                'observability.metrics.updated'
            ]);
        });

        it('does not push an update before the interval elapses', async () => {
            const fake = open();
            await jest.advanceTimersByTimeAsync(UPDATE_INTERVAL_MS - 1);

            expect(fake.frames).toHaveLength(1);
        });

        it('heartbeats on its own slower timer', async () => {
            const fake = open();
            await jest.advanceTimersByTimeAsync(HEARTBEAT_INTERVAL_MS);

            const events = fake.frames.map((frame) => parseFrame(frame).event);

            // 15s is three update ticks and one heartbeat, on two independent timers
            expect(events.filter((event) => event === 'observability.heartbeat')).toHaveLength(1);
            expect(
                events.filter((event) => event === 'observability.metrics.updated')
            ).toHaveLength(3);
        });
    });

    describe('teardown', () => {
        it('stops both timers when the client disconnects', async () => {
            const fake = open();
            await jest.advanceTimersByTimeAsync(0);
            const writtenBeforeClose = fake.frames.length;

            fake.disconnect();
            await jest.advanceTimersByTimeAsync(HEARTBEAT_INTERVAL_MS * 2);

            // Uncleared intervals would write to a dead socket for the life of the process
            expect(fake.frames).toHaveLength(writtenBeforeClose);
        });

        it('leaves the other clients streaming', async () => {
            const first = open();
            const second = open();
            await jest.advanceTimersByTimeAsync(0);

            first.disconnect();
            await jest.advanceTimersByTimeAsync(UPDATE_INTERVAL_MS);

            expect(first.frames).toHaveLength(1);
            expect(second.frames).toHaveLength(2);
            expect(getActiveSseClients()).toBe(1);
        });
    });

    describe('failures that must not escape', () => {
        it('drops a frame rather than rejecting when the metrics read fails', async () => {
            getHttpRequestCounters.mockRejectedValueOnce(new Error('registry down'));
            const fake = open();

            await expect(jest.advanceTimersByTimeAsync(0)).resolves.toBeUndefined();
            expect(fake.frames).toHaveLength(0);
        });

        it('recovers on the next tick after a failed read', async () => {
            getHttpRequestCounters.mockRejectedValueOnce(new Error('registry down'));
            const fake = open();
            await jest.advanceTimersByTimeAsync(0);

            await jest.advanceTimersByTimeAsync(UPDATE_INTERVAL_MS);

            expect(fake.frames.map((frame) => parseFrame(frame).event)).toEqual([
                'observability.metrics.updated'
            ]);
        });

        it('survives a write to a socket the client already dropped', async () => {
            const fake = open();
            fake.write.mockImplementationOnce(() => {
                throw new Error('EPIPE');
            });

            await expect(jest.advanceTimersByTimeAsync(0)).resolves.toBeUndefined();
            expect(fake.frames).toHaveLength(0);
        });
    });
});

tests/unit/infrastructure/runtime/manage.source:
/**
 * The lifecycle both optional dependencies now run on.
 *
 * Redis and RabbitMQ used to state these rules separately, and drifted: `cacheState()` read
 * `connecting` off the client's socket flag while `queueState()` read it off whether a connect was
 * in flight, so one health payload answered the same question two ways. The rules live here now,
 * which means they can be tested once — against a fake handle, with no Redis and no broker.
 *
 * Four properties are load-bearing and each has its own block below: never rejecting, never
 * opening a second connection while one is in flight, warning exactly once per outage, and
 * closing on the way out even when the handle is mid-open.
 */
import { manageConnection } from '@infrastructure/runtime/managed-connection';
import { logger } from '@infrastructure/adapters/logger';

jest.mock('@infrastructure/adapters/logger', () => ({
    logger: { info: jest.fn(), warn: jest.fn(), error: jest.fn(), debug: jest.fn() }
}));

const mockedLogger = jest.mocked(logger);

/** A handle standing in for a Redis client or an AMQP channel: it only has to be identifiable. */
interface FakeHandle {
    id: number;
    live: boolean;
}

/** A promise plus the controls to settle it, so a test can hold a connect open mid-flight. */
const deferred = <T>() => {
    let resolve!: (value: T) => void;
    let reject!: (error: unknown) => void;
    const promise = new Promise<T>((resolveIt, rejectIt) => {
        resolve = resolveIt;
        reject = rejectIt;
    });
    return { promise, resolve, reject };
};

/**
 * A managed connection over fake handles, with every callback observable.
 *
 * `connect` hands back a fresh live handle by default; a case that needs to control the timing
 * overrides the implementation.
 */
const setup = () => {
    let opened = 0;
    const connect = jest.fn(() =>
        Promise.resolve<FakeHandle | undefined>({ id: ++opened, live: true })
    );
    const close = jest.fn(() => Promise.resolve());
    const isEnabled = jest.fn(() => true);

    const connection = manageConnection<FakeHandle>({
        unavailableMessage: 'Fake dependency unavailable.',
        isEnabled,
        connect,
        isReady: (handle) => handle.live,
        close
    });

    return { connection, connect, close, isEnabled };
};

describe('when the dependency is switched off', () => {
    it('reports disabled and opens nothing', async () => {
        const { connection, connect, isEnabled } = setup();
        isEnabled.mockReturnValue(false);

        await expect(connection.get()).resolves.toBeUndefined();

        expect(connection.state()).toBe('disabled');
        expect(connect).not.toHaveBeenCalled();
    });

    /*
     * `disabled` is not a failure: a deployment without Redis is supported, and reporting it as
     * broken would train every reader of the health payload to ignore the field.
     */
    it('stays disabled even after a handle was opened while it was on', async () => {
        const { connection, isEnabled } = setup();
        await connection.get();
        expect(connection.state()).toBe('ready');

        isEnabled.mockReturnValue(false);

        expect(connection.state()).toBe('disabled');
    });
});

/*
 * The reason this file exists. `connecting` means one thing — an attempt is in flight — for every
 * dependency that reports through it, so two entries in one health payload cannot disagree about
 * what the word means. The production HEALTHCHECK allows a start period, during which
 * "not yet" and "broken" look identical on the wire and mean opposite things to whoever is
 * watching a deploy.
 */
describe('the reported state', () => {
    it('walks unavailable → connecting → ready → unavailable', async () => {
        const { connection, connect } = setup();
        const attempt = deferred<FakeHandle | undefined>();
        connect.mockReturnValue(attempt.promise);

        expect(connection.state()).toBe('unavailable');

        const opening = connection.get();
        expect(connection.state()).toBe('connecting');

        attempt.resolve({ id: 1, live: true });
        const handle = await opening;
        expect(connection.state()).toBe('ready');

        handle!.live = false;
        expect(connection.state()).toBe('unavailable');
    });
});

describe('the handle', () => {
    it('is opened once and reused', async () => {
        const { connection, connect } = setup();

        const first = await connection.get();
        const second = await connection.get();

        expect(first).toBe(second);
        expect(connect).toHaveBeenCalledTimes(1);
    });

    // The reason `isReady` exists: a dependency that died since the last call must be reconnected
    // rather than handed back dead, or every caller gets a corpse whose methods throw.
    it('is replaced once it stops being ready', async () => {
        const { connection, connect } = setup();

        const first = await connection.get();
        first!.live = false;
        const second = await connection.get();

        expect(second).not.toBe(first);
        expect(connect).toHaveBeenCalledTimes(2);
    });

    // `forget` is the whole reconnect strategy for a handle that announces its own close.
    it('is re-opened after forget(), without being closed', async () => {
        const { connection, connect, close } = setup();
        await connection.get();

        connection.forget();
        await connection.get();

        expect(connect).toHaveBeenCalledTimes(2);
        expect(close).not.toHaveBeenCalled();
    });

    /*
     * A burst at startup — every worker's first request arriving at once — must not open a
     * connection per caller. The second caller joins the attempt already running.
     */
    it('is not opened twice by concurrent callers', async () => {
        const { connection, connect } = setup();
        const attempt = deferred<FakeHandle | undefined>();
        connect.mockReturnValue(attempt.promise);

        const both = Promise.all([connection.get(), connection.get()]);
        expect(connection.state()).toBe('connecting');

        attempt.resolve({ id: 1, live: true });
        const [first, second] = await both;

        expect(connect).toHaveBeenCalledTimes(1);
        expect(first).toBe(second);
    });
});

describe('a connect that fails', () => {
    /*
     * The property every fail-open adapter is built on. A rejection here would become a 500 on a
     * request the cache was only ever an optimisation for, and would skip the queue's inline
     * fallback entirely.
     */
    it('resolves undefined rather than rejecting', async () => {
        const { connection, connect } = setup();
        connect.mockRejectedValue(new Error('ECONNREFUSED'));

        await expect(connection.get()).resolves.toBeUndefined();
        expect(connection.state()).toBe('unavailable');
    });

    it('is retried by the next call, so recovery follows traffic', async () => {
        const { connection, connect } = setup();
        connect.mockRejectedValueOnce(new Error('ECONNREFUSED'));

        await connection.get();
        const recovered = await connection.get();

        expect(connect).toHaveBeenCalledTimes(2);
        expect(recovered).toEqual({ id: 1, live: true });
    });

    // An unreachable dependency emits per failed operation. One line, not one per request.
    it('logs one warning however many times it is asked', async () => {
        const { connection, connect } = setup();
        connect.mockRejectedValue(new Error('ECONNREFUSED'));

        await connection.get();
        await connection.get();
        await connection.get();

        expect(mockedLogger.warn).toHaveBeenCalledTimes(1);
    });

    // Latched, not disabled: a later outage is a different outage and has to be visible.
    it('re-arms the warning once a connect succeeds', async () => {
        const { connection, connect } = setup();
        connect.mockRejectedValueOnce(new Error('ECONNREFUSED'));

        await connection.get();
        await connection.get();
        connection.forget();
        connect.mockRejectedValueOnce(new Error('ECONNRESET'));
        await connection.get();

        expect(mockedLogger.warn).toHaveBeenCalledTimes(2);
    });

    /*
     * `reportUnavailable` shares that latch with failures arriving from outside `connect` — an
     * `error` event on a live handle, a command rejected mid-publish. They are the same outage.
     */
    it('shares its latch with failures reported from outside', async () => {
        const { connection, connect } = setup();
        connect.mockRejectedValue(new Error('ECONNREFUSED'));

        await connection.get();
        connection.reportUnavailable(new Error('socket hang up'));

        expect(mockedLogger.warn).toHaveBeenCalledTimes(1);
    });
});

/*
 * `connect` resolving `undefined` means "cannot be built" — configuration `isEnabled` could not
 * rule out, such as a URL that assembles to nothing. Nothing failed, so nothing is logged.
 */
describe('a connect that declines to build a handle', () => {
    it('reports unavailable without a warning', async () => {
        const { connection, connect } = setup();
        connect.mockResolvedValue(undefined);

        await expect(connection.get()).resolves.toBeUndefined();

        expect(connection.state()).toBe('unavailable');
        expect(mockedLogger.warn).not.toHaveBeenCalled();
    });
});

describe('stop()', () => {
    it('closes the live handle and forgets it', async () => {
        const { connection, close, connect } = setup();
        const handle = await connection.get();

        await connection.stop();

        expect(close).toHaveBeenCalledWith(handle);
        expect(connection.state()).toBe('unavailable');

        // A restarted app — or a test that boots one in-process — gets a fresh handle rather than
        // a closed one.
        await connection.get();
        expect(connect).toHaveBeenCalledTimes(2);
    });

    /*
     * A connect still in flight owns the handle `stop` is about to close. Without waiting, the
     * socket finishes opening after shutdown with nobody left to close it, and holds the process
     * open past the point the server stopped listening.
     */
    it('waits for an in-flight connect before closing it', async () => {
        const { connection, connect, close } = setup();
        const attempt = deferred<FakeHandle | undefined>();
        connect.mockReturnValue(attempt.promise);

        void connection.get();
        const stopped = connection.stop();

        expect(close).not.toHaveBeenCalled();

        attempt.resolve({ id: 9, live: true });
        await stopped;

        expect(close).toHaveBeenCalledWith({ id: 9, live: true });
    });

    /*
     * Called with `undefined` rather than skipped: an adapter that opened more than the handle —
     * `queue.ts` holds the TCP connection under its channel — still has to release it.
     */
    it('calls close even when no handle is live', async () => {
        const { connection, close } = setup();

        await connection.stop();

        expect(close).toHaveBeenCalledWith(undefined);
    });

    // Shutdown is the one path that must not raise: an already-dead socket rejecting its own
    // close is the ordinary case, and the process is on its way out regardless.
    it('resolves even when close fails', async () => {
        const { connection, close } = setup();
        await connection.get();
        close.mockRejectedValue(new Error('socket already gone'));

        await expect(connection.stop()).resolves.toBeUndefined();
    });
});

