/**
 * The filesystem image store.
 *
 * This is the only module allowed to turn an `imageUrl` into a filesystem path, so it is also the
 * only place where getting that translation wrong deletes the wrong file. Real files in a real
 * temp directory: a mocked `fs` would assert that the code calls unlink with a string, which is
 * not the property that matters — *which* string is.
 */
import { mkdtemp, mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { filesystemImageStore } from '@infrastructure/adapters/image-store';

const ORIGINAL_PUBLIC_PATH = process.env.NODE_PUBLIC_PATH;

let root: string;

/** Creates `<root>/images/<name>` and returns both halves: the real path and the stored url. */
const makeImage = async (name: string) => {
    const file = path.join(root, 'images', name);
    await writeFile(file, 'not really a png');
    return { file, imageUrl: '/images/' + name };
};

beforeEach(async () => {
    root = await mkdtemp(path.join(tmpdir(), 'image-store-test-'));
    await mkdir(path.join(root, 'images'));
    process.env.NODE_PUBLIC_PATH = root;
});

afterEach(async () => {
    await rm(root, { recursive: true, force: true });
    process.env.NODE_PUBLIC_PATH = ORIGINAL_PUBLIC_PATH;
});

/** A file standing in for a staged upload, in its own directory outside the public root. */
const stageUpload = async (name: string, contents = 'image bytes') => {
    const staging = path.join(root, 'staging');
    await mkdir(staging, { recursive: true });
    const file = path.join(staging, name);
    await writeFile(file, contents);
    return file;
};

describe('filesystemImageStore.put', () => {
    it('commits the staged file into the public images directory', async () => {
        const staged = await stageUpload('abc123.png', 'the uploaded bytes');

        const url = await filesystemImageStore.put(staged);

        expect(url).toBe('/images/abc123.png');
        expect(await readFile(path.join(root, 'images', 'abc123.png'), 'utf8')).toBe(
            'the uploaded bytes'
        );
    });

    /* Staging exists so an unchecked upload is never publicly readable; leaving a copy behind
       would defeat it, and would leak a file per upload besides. */
    it('consumes the staged file', async () => {
        const staged = await stageUpload('abc123.png');

        await filesystemImageStore.put(staged);

        expect(existsSync(staged)).toBe(false);
    });

    /**
     * The url is built from literals, not from the destination path, so a Windows separator cannot
     * reach a stored value however the filesystem spells it.
     */
    it('returns a url, never a path', async () => {
        const staged = await stageUpload('abc123.png');

        const url = await filesystemImageStore.put(staged);

        expect(url).not.toMatch(/\\/);
        expect(url.startsWith('/')).toBe(true);
    });

    it('round-trips: what put returns, remove deletes', async () => {
        const staged = await stageUpload('abc123.png');

        const url = await filesystemImageStore.put(staged);

        await expect(filesystemImageStore.remove(url)).resolves.toBe(true);
        expect(existsSync(path.join(root, 'images', 'abc123.png'))).toBe(false);
    });

    /* Unlike `remove`, this one must fail loudly: the caller is about to persist the url. */
    it('rejects when the images directory does not exist', async () => {
        await rm(path.join(root, 'images'), { recursive: true, force: true });
        const staged = await stageUpload('abc123.png');

        await expect(filesystemImageStore.put(staged)).rejects.toThrow();
    });
});

describe('filesystemImageStore.remove', () => {
    it('deletes the file a stored url names', async () => {
        const { file, imageUrl } = await makeImage('stored.png');

        await expect(filesystemImageStore.remove(imageUrl)).resolves.toBe(true);
        expect(existsSync(file)).toBe(false);
    });

    it('reports false for a url whose file is already gone', async () => {
        await expect(filesystemImageStore.remove('/images/never-existed.png')).resolves.toBe(false);
    });

    it.each([
        ['undefined', undefined],
        ['an empty string', '']
    ])('does nothing for %s', async (_label, value) => {
        await expect(filesystemImageStore.remove(value)).resolves.toBe(false);
    });

    /**
     * `NODE_DEFAULT_IMAGE_USER` / `NODE_DEFAULT_IMAGE_PRODUCT` are absolute URLs, and every row
     * that never had an upload holds one. They belong to someone else's server, and once an
     * S3-backed store exists they will be the normal shape of a stored value too.
     */
    it.each([
        'https://cdn.example.com/x.png',
        'http://cdn.example.com/x.png',
        '//cdn.example.com/x.png'
    ])('does not treat %s as a local file', async (imageUrl) => {
        const { file } = await makeImage('untouched.png');

        await expect(filesystemImageStore.remove(imageUrl)).resolves.toBe(false);
        expect(existsSync(file)).toBe(true);
    });

    /**
     * The reason containment lives here: `imageUrl` is client-supplied on create/update, the
     * contract declares it `uri-reference` (which permits this), and the code this replaced fed
     * `publicPath + imageUrl` straight to unlink. An admin could delete any file the process could
     * reach by hard-deleting a product whose image url pointed at it.
     */
    it.each([
        '/../outside.png',
        '/images/../../outside.png',
        '/images/subdir/../../../outside.png'
    ])('refuses to escape the public directory via %s', async (imageUrl) => {
        const outside = path.join(root, '..', 'outside.png');
        await writeFile(outside, 'someone else');

        try {
            await expect(filesystemImageStore.remove(imageUrl)).resolves.toBe(false);
            expect(existsSync(outside)).toBe(true);
        } finally {
            await rm(outside, { force: true });
        }
    });

    /**
     * The case that separates "rejected because it is remote" from "rejected by a later guard".
     *
     * Every other remote url in this file (`https://cdn.example.com/x.png`) would also be refused
     * with `isRemoteUrl` removed entirely, because read as a local path it lands in a
     * subdirectory and the images-directory check catches it. So none of them actually pins the
     * remote check — they pass either way.
     *
     * This one does: `//images/flat.png` is protocol-relative (host `images`), but read as a
     * local path it is exactly `<public>/images/flat.png`, a flat file this store could have
     * written. If the protocol-relative half of `isRemoteUrl` stops working, someone else's file
     * is deleted.
     */
    it('does not delete a local-looking file named by a protocol-relative url', async () => {
        const { file } = await makeImage('flat.png');

        await expect(filesystemImageStore.remove('//images/flat.png')).resolves.toBe(false);
        expect(existsSync(file)).toBe(true);
    });

    it('refuses to delete the public directory itself', async () => {
        await expect(filesystemImageStore.remove('/')).resolves.toBe(false);
        expect(existsSync(root)).toBe(true);
    });

    /*
     * `put` lands a flat name in `<public>/images/`, so a subdirectory of it holds files this
     * store did not write. `images/seed/` is the demo fixtures, committed to the repository:
     * replacing a seeded record's image must not unlink one, or every later re-seed points at a
     * 404 and the asset is gone outside version control.
     */
    it('refuses to delete a file in a subdirectory of the images directory', async () => {
        const seedDirectory = path.join(root, 'images', 'seed');
        await mkdir(seedDirectory, { recursive: true });
        const fixture = path.join(seedDirectory, 'fixture.jpg');
        await writeFile(fixture, 'committed asset');

        await expect(filesystemImageStore.remove('/images/seed/fixture.jpg')).resolves.toBe(false);
        expect(existsSync(fixture)).toBe(true);
    });

    it('still deletes a file directly in the images directory', async () => {
        const { file, imageUrl } = await makeImage('flat.png');

        await expect(filesystemImageStore.remove(imageUrl)).resolves.toBe(true);
        expect(existsSync(file)).toBe(false);
    });

    /* Defensive: nothing writes this shape today, but a stored value without its leading slash
       must resolve to `<root>/images/x.png`, not to a hidden file named `.images`. */
    it('accepts a stored url that lost its leading slash', async () => {
        const { file } = await makeImage('slashless.png');

        await expect(filesystemImageStore.remove('images/slashless.png')).resolves.toBe(true);
        expect(existsSync(file)).toBe(false);
    });

    /* multer builds paths with `path.join`, so a Windows-shaped value can reach the database. */
    it('accepts a windows-shaped stored url', async () => {
        const { file } = await makeImage('windows.png');

        await expect(filesystemImageStore.remove(String.raw`\images\windows.png`)).resolves.toBe(
            true
        );
        expect(existsSync(file)).toBe(false);
    });

    it('resolves the public directory at call time, not at import time', async () => {
        const { file, imageUrl } = await makeImage('relocated.png');
        process.env.NODE_PUBLIC_PATH = path.join(root, 'elsewhere');

        await expect(filesystemImageStore.remove(imageUrl)).resolves.toBe(false);
        expect(existsSync(file)).toBe(true);

        process.env.NODE_PUBLIC_PATH = root;
        await expect(filesystemImageStore.remove(imageUrl)).resolves.toBe(true);
    });

    /**
     * The `?? 'public'` fallback, exercised with the variable genuinely absent.
     *
     * Every other case here SETS `NODE_PUBLIC_PATH` — reasonably, since deployments do — which left
     * the default itself untested: nothing here distinguished `'public'` from any other string, or
     * from none. It showed up as a mutation-score flip that depended on cross-test environment
     * state rather than on the code.
     *
     * `process.chdir` rather than writing into the repository's own `public/`: the fallback is
     * relative, so it resolves against the working directory, and moving that is what lets a real
     * file stand in for a real deployment without touching a committed directory.
     */
    it('falls back to ./public relative to the working directory', async () => {
        const originalCwd = process.cwd();
        const publicImages = path.join(root, 'public', 'images');
        await mkdir(publicImages, { recursive: true });
        const file = path.join(publicImages, 'default-root.png');
        await writeFile(file, 'not really a png');

        try {
            delete process.env.NODE_PUBLIC_PATH;
            process.chdir(root);

            await expect(filesystemImageStore.remove('/images/default-root.png')).resolves.toBe(
                true
            );
            expect(existsSync(file)).toBe(false);
        } finally {
            process.chdir(originalCwd);
        }
    });
});

tests/unit/infrastructure/http/response..source:
/**
 * Response envelope — `src/infrastructure/http/response.ts`.
 *
 * Every endpoint answers in this shape, so the rules encoded here are the API's public dialect
 * rather than an implementation detail:
 *
 *   **`errors` is never empty on a failure.** A reject with `errors: []` forces every client to
 *   special-case it, so a fallback item is synthesised. That guarantee is asserted from several
 *   directions because it is the one a well-meaning simplification would drop.
 *
 *   **`code` is what clients branch on, `message` is what they display.** The status → code map
 *   is therefore pinned per status, including the two catch-alls: any unmapped 4xx collapses to
 *   `REQUEST_ERROR`, and every 5xx collapses to `INTERNAL_ERROR` so the flavour of a server
 *   failure cannot leak.
 *
 *   **Status is written twice** — HTTP status and body — specifically so the two cannot disagree.
 */

import {
    generateReject,
    generateSuccess,
    resolveErrorMessage,
    successResponse,
    rejectResponse
} from '@infrastructure/http/response';
import { makeResponseStub } from '@tests/express';

/** Express response stub with a chainable status().json(). */

describe('generateSuccess', () => {
    it('returns plain objects unchanged (no implicit Mongo normalization)', () => {
        const responseData = { _id: '507f1f77bcf86cd799439011', title: 'Keyboard' };
        Reflect.set(responseData, '__v', 3);
        const response = generateSuccess(responseData);

        expect(response.data).toEqual(responseData);
    });

    it('keeps primitives untouched', () => {
        const response = generateSuccess('ok');
        expect(response.data).toBe('ok');
    });

    it('defaults to status 200 and an empty message', () => {
        const response = generateSuccess({ id: 'x' });

        expect(response.success).toBe(true);
        expect(response.status).toBe(200);
        expect(response.message).toBe('');
    });

    it('honours an explicit status and message', () => {
        const response = generateSuccess({ id: 'x' }, 201, 'Created');

        expect(response.status).toBe(201);
        expect(response.message).toBe('Created');
    });

    it('carries no errors key at runtime', () => {
        // `errors: never` exists only to drive type narrowing; emitting the key would put an
        // `errors` field on every successful response.
        const response = generateSuccess({ id: 'x' });

        expect(Object.keys(response).toSorted()).toEqual(['data', 'message', 'status', 'success']);
    });

    it('preserves undefined data rather than dropping the key', () => {
        const response = generateSuccess(undefined);

        expect(response).toHaveProperty('data');
        expect(response.data).toBeUndefined();
    });
});

/** The `code` a given status maps to — the single fact every status test below asserts. */
const codeFor = (status: number) => generateReject(status, ['y']).errors[0].code;

describe('generateReject', () => {
    it('builds structured error items from plain string errors', () => {
        const response = generateReject(400, ['Field is required']);

        expect(response).toEqual({
            success: false,
            status: 400,
            message: 'Bad Request',
            data: undefined,
            errors: [
                {
                    code: 'BAD_REQUEST',
                    message: 'Field is required'
                }
            ]
        });
    });

    it('preserves provided structured error items', () => {
        const response = generateReject(422, [
            {
                code: 'VALIDATION_ERROR',
                message: 'Invalid email format',
                details: { field: 'email' }
            }
        ]);

        expect(response.errors).toEqual([
            {
                code: 'VALIDATION_ERROR',
                message: 'Invalid email format',
                details: { field: 'email' }
            }
        ]);
    });

    it('defaults to status 400 with a generic message', () => {
        // 400 is "a safer accidental default than 500" — an unannotated reject must not report
        // a server fault for what is usually a client one.
        const response = generateReject();

        expect(response.status).toBe(400);
        expect(response.message).toBe('Bad Request');
        expect(response.errors).toEqual([{ code: 'BAD_REQUEST', message: 'Bad Request' }]);
    });

    it('synthesises an item when no errors are supplied', () => {
        const response = generateReject(404);

        expect(response.errors).toEqual([{ code: 'NOT_FOUND', message: 'Not Found' }]);
    });

    /*
     * The one convention: callers cannot pass a message, so a given status always reads the same
     * way, rather than a bare 'Not Found' next to an operation-prefixed
     * 'getProductItem - not found' whose prefix leaks the handler layout into every 404.
     *
     * Every mapped status is asserted, and the two catch-alls with it. Partial coverage here is
     * worse than none: an unasserted branch is a wording nobody has ever read, in a field that
     * reaches the client on every failure.
     */
    it.each([
        [400, 'Bad Request'],
        [401, 'Unauthorized'],
        [403, 'Forbidden'],
        [404, 'Not Found'],
        [409, 'Conflict'],
        [422, 'Unprocessable Entity'],
        [429, 'Too Many Requests'],
        [500, 'Internal Server Error'],
        [502, 'Internal Server Error'],
        [418, 'Request Error'],
        [499, 'Request Error']
    ])('%i reads as %s', (status, message) => {
        expect(generateReject(status).message).toBe(message);
        expect(resolveErrorMessage(status)).toBe(message);
    });

    it('uses the same wording whatever the caller passed as errors', () => {
        expect(generateReject(404, ['anything']).message).toBe(generateReject(404).message);
    });

    it('falls back to the status wording for the synthesised error item too', () => {
        // `normalizeErrors` reuses it when `errors` is empty, so the two cannot drift apart.
        expect(generateReject(429).errors).toEqual([
            { code: 'REQUEST_ERROR', message: 'Too Many Requests' }
        ]);
    });

    it('always carries a present-but-undefined data key', () => {
        // Explicitly present so `result.data` type-checks on both branches of the union.
        const response = generateReject(404);

        expect(response).toHaveProperty('data');
        expect(response.data).toBeUndefined();
    });

    it('maps each status to its own stable code', () => {
        // Clients branch on `code`, never on `message`. Distinct statuses must not collapse.

        expect(codeFor(400)).toBe('BAD_REQUEST');
        expect(codeFor(401)).toBe('UNAUTHORIZED');
        expect(codeFor(403)).toBe('FORBIDDEN');
        expect(codeFor(404)).toBe('NOT_FOUND');
        expect(codeFor(409)).toBe('CONFLICT');
    });

    it('collapses any 5xx to a single internal code', () => {
        expect(codeFor(500)).toBe('INTERNAL_ERROR');
        expect(codeFor(502)).toBe('INTERNAL_ERROR');
        expect(codeFor(599)).toBe('INTERNAL_ERROR');
    });

    it('treats 499 as a client error, not a server one', () => {
        // The `>= 500` boundary from below. With `> 500`, a plain 500 would fall through to
        // REQUEST_ERROR and clients would stop recognising server failures.
        expect(generateReject(499, ['y']).errors[0].code).toBe('REQUEST_ERROR');
    });

    it('falls back to REQUEST_ERROR for unmapped 4xx statuses', () => {
        expect(codeFor(422)).toBe('REQUEST_ERROR');
        expect(codeFor(429)).toBe('REQUEST_ERROR');
    });

    it('normalises a mixed list of strings and structured items', () => {
        const response = generateReject(422, [
            'Email is required',
            { code: 'TOO_SHORT', message: 'Password too short' }
        ]);

        expect(response.errors).toEqual([
            { code: 'REQUEST_ERROR', message: 'Email is required' },
            { code: 'TOO_SHORT', message: 'Password too short' }
        ]);
    });

    it('fills a structured item missing its code from the status', () => {
        const response = generateReject(409, [{ code: '', message: 'Email already used' }]);

        expect(response.errors[0].code).toBe('CONFLICT');
    });

    it('fills a structured item missing its message from the envelope message', () => {
        const response = generateReject(409, [{ code: 'DUPLICATE', message: '' }]);

        expect(response.errors[0]).toEqual({ code: 'DUPLICATE', message: 'Conflict' });
    });

    it('omits details entirely rather than serialising it as undefined', () => {
        // A `"details": undefined` key survives some serialisers as `null` and shows up in
        // contract validation as an undeclared field.
        const response = generateReject(422, [{ code: 'X', message: 'Y' }]);

        expect(response.errors[0]).not.toHaveProperty('details');
    });

    it('keeps details when provided', () => {
        const response = generateReject(422, [
            { code: 'X', message: 'Y', details: { field: 'email' } }
        ]);

        expect(response.errors[0].details).toEqual({ field: 'email' });
    });
});

describe('successResponse', () => {
    it('applies the same status to the HTTP response and the body', () => {
        const response = makeResponseStub();

        successResponse(response, { id: 'x' }, 201, 'Created');

        // Written twice on purpose, so the two can never disagree — a proxy that rewrites the
        // HTTP status still leaves the body's copy intact.
        expect(response.status).toHaveBeenCalledWith(201);
        expect(response.json).toHaveBeenCalledWith(
            expect.objectContaining({ success: true, status: 201, message: 'Created' })
        );
    });

    it('defaults to 200', () => {
        const response = makeResponseStub();

        successResponse(response, { id: 'x' });

        expect(response.status).toHaveBeenCalledWith(200);
    });
});

describe('rejectResponse', () => {
    it('applies the same status to the HTTP response and the body', () => {
        const response = makeResponseStub();

        rejectResponse(response, 404, ['No such product']);

        expect(response.status).toHaveBeenCalledWith(404);
        expect(response.json).toHaveBeenCalledWith({
            success: false,
            status: 404,
            message: 'Not Found',
            data: undefined,
            errors: [{ code: 'NOT_FOUND', message: 'No such product' }]
        });
    });

    it('defaults to 400', () => {
        const response = makeResponseStub();

        rejectResponse(response);

        expect(response.status).toHaveBeenCalledWith(400);
    });

    it('does not throw, so controllers must return it', () => {
        // Documented: forgetting the `return` lets execution continue and trips Express'
        // "headers already sent". Pinned so the contract cannot change silently.
        const response = makeResponseStub();

        expect(() => rejectResponse(response, 500)).not.toThrow();
    });
});

tests/cross-cutting/search.property.test.source:
/**
 * Property-based tests — `src/infrastructure/persistence/search.ts`.
 *
 * Two functions here are security-relevant rather than merely correct, and both are stated as
 * properties because both are claims about EVERY input:
 *
 *   **`escapeRegex` is a denial-of-service control.** `$regex` with unescaped user text lets an
 *   anonymous caller hand MongoDB a catastrophic-backtracking pattern that it evaluates
 *   server-side against every candidate document — seconds of CPU per document from a handful of
 *   characters. `POST /products/search` and `GET /products?text=` are public. A table of examples
 *   proves the metacharacters someone thought of are escaped; only generation over arbitrary
 *   strings supports "no input reaches the engine as a pattern".
 *
 *   The property that expresses this exactly is: for any subject `s`, `new RegExp(escapeRegex(s))`
 *   matches `s` and matches nothing else it should not — i.e. escaping is LITERAL matching. That
 *   is checked below by round-tripping through the real `RegExp` engine rather than by asserting
 *   on the escaped string's shape, because the shape is an implementation detail and the
 *   behaviour is the contract.
 *
 *   **`normalizePagination` must never produce a skip Mongo cannot use.** A negative or `NaN`
 *   skip is a driver error, i.e. a 500 on a search. The values arrive straight off a request,
 *   where a repeated query key is an array and a JSON body can hold anything.
 *
 * Seeded, and any counterexample gets written back as an example with its seed.
 *
 * ── SPLIT WITH `search-regex.test.ts` / `search-pagination.test.ts` ──────────────────────────
 * Those two files are example-based and they are NOT redundant with this one; each owns the facts
 * the other cannot state, and the division is deliberate:
 *
 *   they own — a named case per metacharacter (better diagnostics than a generated blob), the
 *              TIMING assertion that a catastrophic pattern is defused (a property cannot measure
 *              elapsed time), and the negative case that `1.5` must not match `1x5`;
 *   this owns — totality over ARBITRARY input, generated COMBINATIONS of metacharacters rather
 *              than one at a time, and the non-idempotence of `escapeRegex`.
 *
 * Before adding a case here, check there. A fact asserted twice is a fact maintained twice — and
 * it is worse than it looks in this repo, because a static mutant replays the entire suite.
 */
import fc from 'fast-check';
import {
    addRegexFilter,
    addTextFilter,
    buildPaginatedMeta,
    escapeRegex,
    normalizePagination
} from '@infrastructure/persistence/search';

const RUN = { seed: 20_260_809, numRuns: 300, endOnFailure: true } as const;

/**
 * Anything a request can put in a pagination field.
 *
 * `page` and `pageSize` are typed `unknown` on purpose — a repeated query key arrives as an array
 * and a JSON body can hold anything — so the arbitrary has to be at least as wide as the type.
 */
const requestValue = () =>
    fc.oneof(fc.anything(), fc.integer(), fc.string(), fc.constant(undefined));

describe('escapeRegex', () => {
    it('never produces a pattern the engine refuses to compile', () => {
        // A lone `(` in a search box is a syntax error the driver raises as a 500. This is the
        // property that says "no user string can do that", for any string.
        fc.assert(
            fc.property(fc.string(), (value) => {
                expect(() => new RegExp(escapeRegex(value))).not.toThrow();
            }),
            RUN
        );
    });

    it('matches its own input literally', () => {
        // The round trip. Escaping that broke matching would be "safe" and useless.
        fc.assert(
            fc.property(fc.string(), (value) => {
                expect(new RegExp(escapeRegex(value)).test(value)).toBe(true);
            }),
            RUN
        );
    });

    it('strips every metacharacter of its power', () => {
        // The heart of it: a pattern built from user text must behave as a literal. `.` must not
        // match an arbitrary character, `^`/`$` must not anchor, `+`/`*` must not quantify.
        //
        // Generated over strings drawn from the metacharacter alphabet itself, which is where an
        // incomplete escape list shows up — the previous version of this rule was a fixed table
        // and could only ever prove the characters already in it.
        const metacharacters = String.raw`$()*+.?[\]^{|}`;
        fc.assert(
            fc.property(
                // Built from an array rather than a character-alphabet helper, whose name has
                // moved between fast-check majors; this spelling does not care which one is
                // installed.
                fc
                    // eslint-disable-next-line @typescript-eslint/no-misused-spread -- ASCII regex metacharacters only; no surrogate pairs to mishandle
                    .array(fc.constantFrom(...metacharacters), { minLength: 1, maxLength: 12 })
                    .map((characters) => characters.join('')),
                (pattern) => {
                    const escaped = new RegExp(escapeRegex(pattern));

                    // It matches itself...
                    expect(escaped.test(pattern)).toBe(true);
                    // ...and not a string that only a live metacharacter could match.
                    expect(escaped.test('literally-unrelated-text')).toBe(false);
                }
            ),
            RUN
        );
    });

    it('leaves ANY alphanumeric text untouched, not just the sampled phrase', () => {
        // No over-escaping either: mangling plain words would quietly break search.
        fc.assert(
            fc.property(fc.stringMatching(/^[\d A-Za-z]*$/), (value) => {
                expect(escapeRegex(value)).toBe(value);
            }),
            RUN
        );
    });

    it('is not idempotent, and that is why it is applied exactly once', () => {
        // Escaping twice doubles the backslashes and stops matching. Stated as a property so
        // nobody "hardens" a call site by wrapping it again.
        expect(escapeRegex(escapeRegex('a.b'))).not.toBe(escapeRegex('a.b'));
        expect(new RegExp(escapeRegex(escapeRegex('a.b'))).test('a.b')).toBe(false);
    });
});

describe('addTextFilter / addRegexFilter', () => {
    it('never writes an uncompilable pattern into a filter', () => {
        fc.assert(
            fc.property(fc.string(), (text) => {
                const where: Record<string, unknown> = {};
                addTextFilter(where, text, ['title', 'description']);

                const clauses = (where.$or ?? []) as Record<string, { $regex: string }>[];
                for (const clause of clauses)
                    for (const field of Object.values(clause))
                        expect(() => new RegExp(field.$regex)).not.toThrow();
            }),
            RUN
        );
    });

    it('adds nothing at all for input that is empty or only whitespace', () => {
        // An empty search box must not become a filter — `$regex: ''` matches every document and
        // costs a full scan to say so.
        fc.assert(
            fc.property(
                fc
                    .array(fc.constantFrom(' ', '\t', '\n', ''), { maxLength: 10 })
                    .map((characters) => characters.join('')),
                (blank) => {
                    const where: Record<string, unknown> = {};
                    addTextFilter(where, blank, ['title']);
                    addRegexFilter(where, 'title', blank);

                    expect(where).toEqual({});
                }
            ),
            RUN
        );
    });

    it('produces one clause per searched field', () => {
        fc.assert(
            fc.property(
                fc.string({ minLength: 1 }),
                fc.uniqueArray(fc.stringMatching(/^[a-z]{1,8}$/), { minLength: 1, maxLength: 5 }),
                (text, fields) => {
                    fc.pre(text.trim().length > 0);
                    const where: Record<string, unknown> = {};
                    addTextFilter(where, text, fields);

                    expect((where.$or as unknown[]).length).toBe(fields.length);
                }
            ),
            RUN
        );
    });
});

describe('normalizePagination', () => {
    it('never yields a skip Mongo cannot use, for any input', () => {
        // The structural guard. A negative or NaN skip is a driver error, i.e. a 500 on a search,
        // and these values come straight off a request.
        fc.assert(
            fc.property(requestValue(), requestValue(), (page, pageSize) => {
                const {
                    page: resolvedPage,
                    pageSize: size,
                    skip
                } = normalizePagination({
                    page,
                    pageSize
                });

                expect(Number.isInteger(skip) || skip >= 0).toBe(true);
                expect(Number.isNaN(skip)).toBe(false);
                expect(skip).toBeGreaterThanOrEqual(0);
                expect(resolvedPage).toBeGreaterThanOrEqual(1);
                expect(size).toBeGreaterThan(0);
            }),
            RUN
        );
    });

    it('keeps skip consistent with page and pageSize', () => {
        fc.assert(
            fc.property(
                fc.integer({ min: 1, max: 10_000 }),
                fc.integer({ min: 1, max: 100 }),
                (page, pageSize) => {
                    const result = normalizePagination({ page, pageSize });

                    // The identity the paging depends on. `search` issues count and page as two
                    // queries; a skip that disagreed with the reported page would drop rows.
                    expect(result.skip).toBe((result.page - 1) * result.pageSize);
                }
            ),
            RUN
        );
    });

    it('starts page 1 at skip 0', () => {
        fc.assert(
            fc.property(fc.integer({ min: 1, max: 100 }), (pageSize) => {
                expect(normalizePagination({ page: 1, pageSize }).skip).toBe(0);
            }),
            RUN
        );
    });

    it('reports zero pages for zero items', () => {
        expect(buildPaginatedMeta(normalizePagination({}), 0).totalPages).toBe(0);
    });
});

