/**
 * `enqueueEmail` — the queue-or-send-inline dispatch in `src/infrastructure/adapters/mailer.ts`.
 *
 * The docblock promises that "two fallbacks keep it safe: the queue being unconfigured, and the
 * queue being configured but momentarily unreachable. In both cases the email is still sent."
 * That is a three-branch claim, and it was asserted by nothing — `tests/unit/i18n/
 * email-locale.test.ts` drives this function, but only to check the locale that rides on the
 * payload, and it pins the queue as enabled and publishing successfully throughout.
 *
 * Which branch runs decides whether a password-reset email is delivered or silently dropped, and
 * the failure is invisible: `enqueueEmail` resolves `void` either way, so a caller cannot tell a
 * queued job from a lost one. It is also agnostic boilerplate — "publish to a broker, fall back to
 * doing it inline" is the pattern every project built on this repo inherits, whatever it sends.
 *
 * The three paths:
 *
 *   1. no broker configured           → send inline, now
 *   2. broker configured, publish OK  → enqueue, log at debug, do NOT send inline
 *   3. broker configured, publish NOT OK → send inline after all
 *
 * Path 3 is the one worth the most: it is the only one that only happens when something else is
 * already broken.
 */
import type { EmailRequest } from '@infrastructure/adapters/mailer';
import type { Data } from 'ejs';

const sendMailMock = jest.fn().mockResolvedValue({ messageId: 'smtp-1' });
jest.mock('nodemailer', () => ({
    createTransport: () => ({ sendMail: sendMailMock })
}));

const publishToQueueMock = jest.fn();
const isQueueEnabledMock = jest.fn();
jest.mock('@infrastructure/adapters/queue', () => ({
    isQueueEnabled: () => isQueueEnabledMock(),
    publishToQueue: (job: unknown) => publishToQueueMock(job)
}));

const loggerMock = { info: jest.fn(), debug: jest.fn(), warn: jest.fn(), error: jest.fn() };
/*
 * Getters rather than `logger: loggerMock`, and the difference is not stylistic.
 *
 * `jest.mock` is hoisted above everything, so the factory runs the moment the mocked module is
 * first required. How soon that is depends on the transform: TypeScript emits each `require` where
 * its `import` stood, which puts it after the `const` above, while swc follows ESM and hoists
 * imports to the top — which puts it BEFORE, and reading `loggerMock` there throws
 * `Cannot access 'loggerMock' before initialization`.
 *
 * A getter body runs on property access instead of at factory time, by which point the `const` is
 * initialised under either. The two mocks above are already safe for the same reason: each reaches
 * its variable from inside a function rather than at the top level of the object.
 */
jest.mock('@infrastructure/adapters/logger', () => ({
    __esModule: true,
    get logger() {
        return loggerMock;
    },
    get auditLogger() {
        return loggerMock;
    }
}));

import { enqueueEmail } from '@infrastructure/adapters/mailer';

const REQUEST: EmailRequest = { to: 'ada@example.com', subject: 'Reset your password' };
const TEMPLATE = 'account.reset-request';
/**
 * Every variable the chosen template interpolates — which, since templates stopped translating,
 * means the finished copy a producer would have resolved. The inline paths RENDER for real (only
 * the SMTP transport is mocked), so a missing variable is an EJS ReferenceError rather than a
 * silently blank line — which is itself a useful property of this setup.
 */
const DATA: Data = {
    locale: 'en',
    pageMetaTitle: 'Reset',
    pageMetaLinks: [],
    greeting: 'Hello, Ada!',
    intro: 'We received a request to reset your password.',
    linkLabel: 'Reset my password',
    linkUrl: 'https://example.com/account/reset/reset-token-value',
    ignore: 'If you did not request this, you can safely ignore this email.',
    footer: 'Sent by the Ecommerce Demo team.'
};

beforeEach(() => {
    jest.clearAllMocks();
    sendMailMock.mockResolvedValue({ messageId: 'smtp-1' });
});

describe('enqueueEmail — path 1: no broker configured', () => {
    beforeEach(() => {
        isQueueEnabledMock.mockReturnValue(false);
    });

    it('sends the email inline rather than dropping it', async () => {
        await enqueueEmail(REQUEST, TEMPLATE, DATA);

        expect(sendMailMock).toHaveBeenCalledTimes(1);
    });

    it('does not attempt to publish anything', async () => {
        await enqueueEmail(REQUEST, TEMPLATE, DATA);

        expect(publishToQueueMock).not.toHaveBeenCalled();
    });

    it('resolves undefined, not the SMTP info object', async () => {
        // Both branches share a `Promise<void>` return type so callers cannot accidentally start
        // depending on a `SentMessageInfo` that only exists on one path.
        await expect(enqueueEmail(REQUEST, TEMPLATE, DATA)).resolves.toBeUndefined();
    });
});

describe('enqueueEmail — path 2: broker configured, publish succeeds', () => {
    beforeEach(() => {
        isQueueEnabledMock.mockReturnValue(true);
        publishToQueueMock.mockResolvedValue(true);
    });

    it('publishes the job', async () => {
        await enqueueEmail(REQUEST, TEMPLATE, DATA);

        expect(publishToQueueMock).toHaveBeenCalledTimes(1);
    });

    it('does NOT also send the email inline', async () => {
        // The duplicate-delivery bug: enqueue and send. The user gets two reset emails and the
        // second token invalidates the first.
        await enqueueEmail(REQUEST, TEMPLATE, DATA);

        expect(sendMailMock).not.toHaveBeenCalled();
    });

    it('carries the template NAME and data, not rendered HTML', async () => {
        // Rendering happens on the consumer side, so the payload must stay small and
        // JSON-serializable. A payload carrying HTML would work and quietly bloat the broker.
        await enqueueEmail(REQUEST, TEMPLATE, DATA);

        const { payload } = publishToQueueMock.mock.calls[0][0] as {
            payload: Record<string, unknown>;
        };
        expect(payload.templateName).toBe(TEMPLATE);
        // The caller's data, plus the chrome `enqueueEmail` resolves on its behalf — still copy
        // and a template name, still no markup.
        // Exactly what the caller passed — `enqueueEmail` adds nothing and resolves nothing.
        expect(payload.data).toEqual(DATA);
        expect(payload).not.toHaveProperty('html');
    });

    it('logs the enqueue at debug, not info', async () => {
        // Enqueueing is routine; the worker logs the actual delivery. At info this is one line
        // per email in production for an event that has not happened yet.
        await enqueueEmail(REQUEST, TEMPLATE, DATA);

        expect(loggerMock.debug).toHaveBeenCalledTimes(1);
        expect(loggerMock.info).not.toHaveBeenCalled();
    });
});

describe('enqueueEmail — path 3: broker configured, publish fails', () => {
    beforeEach(() => {
        isQueueEnabledMock.mockReturnValue(true);
        publishToQueueMock.mockResolvedValue(false);
    });

    it('falls back to sending inline, so the email is not lost', async () => {
        // The branch that only runs when the broker is already having a bad day — and the one
        // nothing was checking. Without it, a RabbitMQ blip silently swallows every password
        // reset, and `enqueueEmail` still resolves as if it had worked.
        await enqueueEmail(REQUEST, TEMPLATE, DATA);

        expect(sendMailMock).toHaveBeenCalledTimes(1);
    });

    it('does not log an enqueue it did not achieve', async () => {
        await enqueueEmail(REQUEST, TEMPLATE, DATA);

        expect(loggerMock.debug).not.toHaveBeenCalled();
    });

    it('still resolves undefined', async () => {
        await expect(enqueueEmail(REQUEST, TEMPLATE, DATA)).resolves.toBeUndefined();
    });
});

/**
 * Path 3 exists only because `publishToQueue` promises a boolean. This is what the promise is
 * worth: `enqueueEmail` reads `published` and has no rejection handler, so an adapter that
 * rejected instead of answering `false` would skip the inline fallback entirely — and every
 * producer writes `void enqueueEmail(...)`, so the loss would surface as an `unhandledRejection`
 * with no request id rather than as a failed request.
 *
 * The guard against that lives in `queue.test.ts`, which pins the adapter to `false`. This case
 * pins the reason it has to.
 */
describe('enqueueEmail — path 3 depends on the adapter never rejecting', () => {
    beforeEach(() => {
        isQueueEnabledMock.mockReturnValue(true);
        publishToQueueMock.mockRejectedValue(new Error('Channel closed'));
    });

    it('has no fallback left when the publish rejects instead of answering false', async () => {
        await expect(enqueueEmail(REQUEST, TEMPLATE, DATA)).rejects.toThrow('Channel closed');

        expect(sendMailMock).not.toHaveBeenCalled();
    });
});

describe('enqueueEmail — the paths are mutually exclusive', () => {
    // Stated as a table over all three configurations: exactly one delivery attempt happens,
    // whichever way the broker behaves. This is what fails when a branch condition is inverted.
    it.each([
        ['no broker', false, false],
        ['publish succeeds', true, true],
        ['publish fails', true, false]
    ])('%s → exactly one delivery path is taken', async (_label, queueEnabled, published) => {
        isQueueEnabledMock.mockReturnValue(queueEnabled);
        publishToQueueMock.mockResolvedValue(published);

        await enqueueEmail(REQUEST, TEMPLATE, DATA);

        const enqueued = publishToQueueMock.mock.calls.length > 0 && published ? 1 : 0;
        const sentInline = sendMailMock.mock.calls.length;

        expect(enqueued + sentInline).toBe(1);
    });
});

src/modules/orders/tests/unit/totals.pro.source:
/**
 * Property-based tests — `src/modules/orders/domain/totals.ts`.
 *
 * `sumLineItems` is the arithmetic behind every order total and every cart summary. It is total by
 * construction — a line whose product failed to populate contributes nothing rather than turning
 * the total into `NaN`, which reaches the customer as a blank price.
 *
 * Additivity and scaling are asserted EXACTLY, in cents. That is what the minor-unit arithmetic
 * buys, and a float accumulator satisfies them only up to a tolerance — so an implementation that
 * went back to summing decimals fails here.
 *
 * Determinism, both halves:
 *   - the run is SEEDED, so a failure is reproducible and a passing run is not luck;
 *   - any counterexample this finds gets written back as an ordinary `it()` with its seed in a
 *     comment. The property states the rule; the example remembers the bug.
 */
import fc from 'fast-check';
import { sumLineItems, orderTotal, type LineItem } from '../../domain/totals';

/** One seed for the file, and one place to change it. */
const RUN = { seed: 20_260_809, numRuns: 300, endOnFailure: true } as const;

/**
 * The two nullish spellings a failed populate can leave behind.
 *
 * Both are in scope for `Number(...) || 0` and both must contribute 0 rather than NaN, so neither
 * can be dropped to satisfy a lint rule that would rather this codebase had only `undefined`.
 */
const nullish = () => fc.constantFrom(null, undefined);

/** A line item as the two callers actually produce one. */
const lineItem = () =>
    fc.record({
        quantity: fc.integer({ min: 0, max: 1000 }),
        product: fc.record({ price: fc.integer({ min: 0, max: 100_000 }) })
    });

/** A line item with any of the junk a failed populate or a malformed aggregate can leave. */
const hostileLineItem = () =>
    fc.record(
        {
            quantity: fc.oneof(fc.integer(), fc.double(), fc.string(), nullish(), fc.boolean()),
            product: fc.oneof(
                fc.record({ price: fc.oneof(fc.double(), fc.string(), nullish()) }),
                nullish(),
                fc.string(),
                fc.record({})
            )
        },
        { requiredKeys: [] }
    ) as fc.Arbitrary<LineItem>;

describe('sumLineItems — totality', () => {
    it('never produces NaN, for any input at all', () => {
        // The single most important property here. A NaN total renders as a blank price, and it
        // propagates: one unpopulated product poisons the whole order.
        fc.assert(
            fc.property(fc.array(hostileLineItem()), (items) => {
                const { count, quantity, price } = sumLineItems(items);

                expect(Number.isNaN(count)).toBe(false);
                expect(Number.isNaN(quantity)).toBe(false);
                expect(Number.isNaN(price)).toBe(false);
            }),
            RUN
        );
    });

    it('never throws, for any input at all', () => {
        fc.assert(
            fc.property(fc.array(hostileLineItem()), (items) => {
                expect(() => sumLineItems(items)).not.toThrow();
            }),
            RUN
        );
    });

    it('counts every line, whatever is in it', () => {
        // `count` is the array length and nothing else — a line that contributes 0 to the money
        // still exists. `CartSummary.itemsCount` depends on that distinction.
        fc.assert(
            fc.property(fc.array(hostileLineItem()), (items) => {
                expect(sumLineItems(items).count).toBe(items.length);
            }),
            RUN
        );
    });
});

describe('sumLineItems — arithmetic invariants', () => {
    it('is zero on every axis for an empty cart', () => {
        expect(sumLineItems([])).toEqual({ count: 0, quantity: 0, price: 0 });
    });

    it('is order-independent', () => {
        // Two clients holding the same cart in a different order must be charged the same. This
        // is the property that would catch an accumulator whose rounding depended on sequence.
        fc.assert(
            fc.property(fc.array(lineItem()), (items) => {
                const forwards = sumLineItems(items);
                const backwards = sumLineItems(items.toReversed());

                expect(backwards).toEqual(forwards);
            }),
            RUN
        );
    });

    it('is non-negative for non-negative input', () => {
        fc.assert(
            fc.property(fc.array(lineItem()), (items) => {
                const { quantity, price } = sumLineItems(items);

                expect(quantity).toBeGreaterThanOrEqual(0);
                expect(price).toBeGreaterThanOrEqual(0);
            }),
            RUN
        );
    });

    it('is additive over concatenation, to the cent', () => {
        // Compared in cents because the only imprecision left is the single division on the way
        // out: `0.1 + 0.2` is not `0.3`, however exact the cents behind them were.
        fc.assert(
            fc.property(fc.array(lineItem()), fc.array(lineItem()), (left, right) => {
                const combined = sumLineItems([...left, ...right]);
                const separate = sumLineItems(left);
                const other = sumLineItems(right);

                expect(combined.count).toBe(separate.count + other.count);
                expect(combined.quantity).toBe(separate.quantity + other.quantity);
                expect(Math.round(combined.price * 100)).toBe(
                    Math.round(separate.price * 100) + Math.round(other.price * 100)
                );
            }),
            RUN
        );
    });

    it('scales the price with the quantity', () => {
        // Doubling every quantity doubles the money. Catches a `+` where a `*` belongs, which
        // an example with quantity 1 cannot distinguish.
        fc.assert(
            fc.property(fc.array(lineItem(), { maxLength: 20 }), (items) => {
                const single = sumLineItems(items);
                const doubled = sumLineItems(
                    items.map((item) => ({ ...item, quantity: item.quantity * 2 }))
                );

                expect(doubled.quantity).toBe(single.quantity * 2);
                expect(Math.round(doubled.price * 100)).toBe(Math.round(single.price * 100) * 2);
            }),
            RUN
        );
    });

    it('ignores a line with zero quantity in the money but not in the count', () => {
        fc.assert(
            fc.property(
                fc.array(lineItem()),
                fc.integer({ min: 0, max: 100_000 }),
                (items, price) => {
                    const withFreeLine = sumLineItems([
                        ...items,
                        { quantity: 0, product: { price } }
                    ]);
                    const without = sumLineItems(items);

                    expect(withFreeLine.price).toBe(without.price);
                    expect(withFreeLine.count).toBe(without.count + 1);
                }
            ),
            RUN
        );
    });
});

/**
 * `orderTotal` is the COMPOSITION rule — lines plus the shipping frozen against them — and it has
 * three callers who each owe the customer the same number: the order serializer, the payment
 * intent and the confirmation email. What it must never do is disagree with `sumLineItems` about
 * the part they share, or turn an order with no shipping into a different order.
 */
describe('orderTotal', () => {
    it('is the line total when nothing was charged for shipping', () => {
        // Covers both spellings of absence. An order placed before delivery existed carries no
        // `shippingCost` at all, and `pickup` is a real method priced at zero.
        fc.assert(
            fc.property(
                fc.array(lineItem(), { maxLength: 20 }),
                fc.constantFrom(undefined, null, 0),
                (items, shippingCost) => {
                    expect(orderTotal({ items, shippingCost })).toBe(sumLineItems(items).price);
                }
            ),
            RUN
        );
    });

    it('adds the shipping exactly, in cents', () => {
        // Exact, not within a tolerance: 100 + 15 must be 115 and 0.1 + 0.2 must be 0.3. A float
        // `+` here is the reason the composition rule has a home at all.
        fc.assert(
            fc.property(
                fc.array(lineItem(), { maxLength: 20 }),
                fc.integer({ min: 0, max: 100_000 }),
                (items, shippingCost) => {
                    expect(Math.round(orderTotal({ items, shippingCost }) * 100)).toBe(
                        Math.round(sumLineItems(items).price * 100) + shippingCost * 100
                    );
                }
            ),
            RUN
        );
    });

    it('never produces NaN, whatever the order carries', () => {
        fc.assert(
            fc.property(
                fc.array(hostileLineItem()),
                fc.oneof(fc.double(), fc.string(), nullish(), fc.boolean()),
                (items, shippingCost) => {
                    expect(Number.isNaN(orderTotal({ items, shippingCost }))).toBe(false);
                }
            ),
            RUN
        );
    });
});

tests/cross-cutting/serialize.property.t.source:
/**
 * Property-based tests — `src/infrastructure/persistence/serialize.ts`.
 *
 * This is the one place a stored document becomes a wire payload, and its guarantees are
 * universal by nature: `_id` → `id`, `__v` gone, every `omit` key gone — for ANY input shape, not
 * for the five shapes the models happen to have today.
 *
 * That universality is load-bearing rather than aesthetic. 95 of `openapi.yaml`'s schemas are
 * `additionalProperties: false`, so a single leaked `_id` or `__v` is a contract violation the
 * suite in `tests/contract/` fails on. And the transform runs on TWO very different inputs: the
 * `toJSON` path, where Mongoose has already supplied `id` and dropped `__v`, and the
 * `.lean()`/`.aggregate()` path, which hands over raw BSON with neither done. Generation over
 * arbitrary objects is what covers the second case, which is the one with no help from Mongoose.
 *
 * The `omit` list is where a property earns its keep most directly: it is how `password` and
 * `tokens` are kept off a user response, and "the omitted keys are absent" is a statement about
 * every possible document, including ones with keys nobody anticipated.
 *
 * Seeded. Any counterexample gets written back as an example with its seed in a comment.
 */
import fc from 'fast-check';
import { applySerialization, type SerializeTransform } from '@infrastructure/persistence/serialize';

const RUN = { seed: 20_260_809, numRuns: 300, endOnFailure: true } as const;

/** A stand-in for the one method the wiring touches — see `SerializableSchema` in the source. */
const fakeSchema = () => ({ set: () => 0 });

/** Build a transform without needing a real Mongoose schema. */
const buildTransform = (options?: Parameters<typeof applySerialization>[1]): SerializeTransform =>
    applySerialization(fakeSchema(), options);

/**
 * A key a Mongo document can actually carry.
 *
 * `__proto__` is excluded, and the exclusion is about JavaScript rather than about this module:
 * spreading an object with a `__proto__` key sets the PROTOTYPE of the copy instead of creating a
 * key on it, so the fixture would silently lose the field before the transform ever saw it. That
 * is a property of the spread operator, not a behaviour of the serializer, and generating it only
 * produces counterexamples about the test.
 */
const documentKey = () => fc.string().filter((key) => key !== '__proto__');

/**
 * An arbitrary document body — any keys, any JSON-ish values — with the two reserved fields
 * layered on top so every generated case exercises the rename and the version-key deletion.
 */
const documentLike = () =>
    fc
        .dictionary(documentKey(), fc.jsonValue(), { maxKeys: 8 })
        .map((body) => ({ ...body }) as Record<string, unknown>);

const withReservedFields = () =>
    fc
        .tuple(documentLike(), fc.string({ minLength: 1 }), fc.integer())
        .map(([body, id, version]) => ({
            ...body,
            _id: id,
            __v: version
        }));

describe('applySerialization — universal guarantees', () => {
    it('never leaves _id on the output, whatever the document held', () => {
        // A stray `_id` is a contract violation against 95 `additionalProperties: false` schemas,
        // not a cosmetic detail.
        fc.assert(
            fc.property(withReservedFields(), (document_) => {
                const serialized = buildTransform()({ ...document_ });

                expect(Object.hasOwn(serialized, '_id')).toBe(false);
            }),
            RUN
        );
    });

    it('never leaves __v on the output', () => {
        // The `toJSON` path gets this from `versionKey: false`; the lean/aggregate path gets it
        // only from the explicit delete in the transform. This covers the second.
        fc.assert(
            fc.property(withReservedFields(), (document_) => {
                expect(Object.hasOwn(buildTransform()({ ...document_ }), '__v')).toBe(false);
            }),
            RUN
        );
    });

    it('renames _id to a string id, for any id representation', () => {
        // `.lean()` yields a real ObjectId, `.aggregate()` can yield anything. `toString()` is
        // what makes both land on the wire as a string.
        fc.assert(
            fc.property(documentLike(), fc.string({ minLength: 1 }), (body, id) => {
                const serialized = buildTransform()({ ...body, _id: id });

                expect(serialized.id).toBe(id);
                expect(typeof serialized.id).toBe('string');
            }),
            RUN
        );
    });

    it('drops the id entirely under dropId, rather than renaming it', () => {
        // For collections with no addressable endpoint: exposing an id there would invite one to
        // be built. Both spellings of "gone" are asserted, since `id` appearing would be the bug.
        fc.assert(
            fc.property(withReservedFields(), (document_) => {
                const serialized = buildTransform({ dropId: true })({ ...document_ });

                expect(Object.hasOwn(serialized, '_id')).toBe(false);
                expect(Object.hasOwn(serialized, 'id')).toBe(false);
            }),
            RUN
        );
    });

    it('removes every omitted key, whatever else the document contains', () => {
        // This is how `password` and `tokens` stay off a user response.
        fc.assert(
            fc.property(
                documentLike(),
                fc.uniqueArray(
                    documentKey().filter((key) => key.length > 0),
                    {
                        minLength: 1,
                        maxLength: 4
                    }
                ),
                (body, omit) => {
                    const secrets = Object.fromEntries(omit.map((key) => [key, 'secret']));
                    const serialized = buildTransform({ omit })({ ...body, ...secrets });

                    // `Object.hasOwn`, not `toHaveProperty`: the latter walks the prototype
                    // chain, so it reports `toString` as present on every object ever made. What
                    // matters for a wire payload is the OWN keys, which is what gets serialized.
                    for (const key of omit) expect(Object.hasOwn(serialized, key)).toBe(false);
                }
            ),
            RUN
        );
    });

    it('keeps every key it was not asked to touch', () => {
        // The other half: a transform that dropped too much would satisfy every assertion above.
        fc.assert(
            fc.property(documentLike(), (body) => {
                const reserved = new Set(['_id', '__v', 'id']);
                const serialized = buildTransform()({ ...body });

                for (const key of Object.keys(body))
                    if (!reserved.has(key)) expect(Object.hasOwn(serialized, key)).toBe(true);
            }),
            RUN
        );
    });

    it('returns the same object it was handed, mutated in place', () => {
        // The lean path relies on this: `normalize` in @infrastructure/persistence/base-repository maps over rows and
        // keeps the returned value, while the toJSON path discards it and keeps the mutation.
        // Both work only because they are the same object.
        fc.assert(
            fc.property(withReservedFields(), (document_) => {
                const input = { ...document_ };

                expect(buildTransform()(input)).toBe(input);
            }),
            RUN
        );
    });

    it('is idempotent', () => {
        // Applied twice — which happens when a lean row is normalized and then serialized again
        // — the result must not change.
        fc.assert(
            fc.property(withReservedFields(), (document_) => {
                const transform = buildTransform({ omit: ['password'] });
                const once = transform({ ...document_ });
                const twice = transform({ ...once });

                expect(twice).toEqual(once);
            }),
            RUN
        );
    });

    it('never throws, for any document shape', () => {
        fc.assert(
            fc.property(fc.dictionary(documentKey(), fc.anything(), { maxKeys: 8 }), (body) => {
                expect(() => buildTransform({ omit: ['password'] })(body)).not.toThrow();
            }),
            RUN
        );
    });

    it('runs the after hook once, after the shared steps', () => {
        // Ordering matters: `after` is where models do nested normalization, and it must see the
        // document already stripped rather than racing the shared steps.
        fc.assert(
            fc.property(withReservedFields(), (document_) => {
                let sawId: unknown;
                let calls = 0;
                const transform = buildTransform({
                    after: (serialized) => {
                        calls += 1;
                        sawId = '_id' in serialized;
                    }
                });

                transform({ ...document_ });

                expect(calls).toBe(1);
                expect(sawId).toBe(false);
            }),
            RUN
        );
    });
});

tests/cross-cutting/module-shape.test.ts.source:
/**
 * A module's manifest, its folder and the registry all describe the same domain — and agree.
 *
 * `src/modules.ts` is the enumeration: one folder under `src/modules/`, one import, one entry in
 * `enabledModules`. Three facts hold that together, and the type system checks none of them,
 * because each is an agreement between a value and the filesystem:
 *
 *   1. **`name` matches the folder.** The manifest's docblock already requires it ("Must match the
 *      folder name under `src/modules/`") and nothing enforced it. The name is what every other
 *      guard keys on — `context-map.test.ts` resolves `dependsOn` edges by it, the registry logs
 *      by it, `docs/modules/<name>.md` is named for it — so a manifest naming itself something
 *      the folder is not makes each of those quietly describe a module that does not exist.
 *   2. **Every folder is enabled, or is deliberately not.** A domain added and never listed
 *      compiles, lints, tests clean and serves nothing: its routes are never mounted, its
 *      subscribers never attached, its seeds never run. There is no error anywhere — the folder is
 *      simply inert, and looks exactly like a working one.
 *   3. **Routed and headless are what the folder looks like.** A `controllers/` directory is HTTP
 *      code; a module holding one and declaring no `basePath` has written handlers nothing mounts.
 *      The union in `kernel/registry.ts` makes `basePath` and `routes` inseparable from each
 *      other, which is as far as a type can go — it cannot see the directory.
 *
 * ── Overlap, and what this file leaves alone ──────────────────────────────────────────────────
 * `controller-naming.test.ts` holds controller FILENAMES to the verb they serve, and
 * `service-namespaces.test.ts` holds each service to one complete namespace. Both are about a
 * module's insides. This file is only about its outline: the three places a module announces
 * itself. Nothing here re-checks either.
 */

import { existsSync, readdirSync, readFileSync, statSync } from 'node:fs';
import path from 'node:path';
import { enabledModules } from '../../src/modules';

const MODULES_ROOT = path.join(__dirname, '../../src/modules');

/**
 * Folders that exist and are deliberately not registered.
 *
 * Empty, and meant to stay that way: an unregistered module is inert, so the honest states are
 * "listed" or "deleted". An entry here needs an argument in review — it is a domain someone is
 * paying to keep compiling and choosing not to serve.
 */
const DELIBERATELY_DISABLED: string[] = [];

/** Every directory under `src/modules/`, which is the only place a module may live. */
const moduleFolders = (): string[] =>
    readdirSync(MODULES_ROOT).filter((entry) =>
        statSync(path.join(MODULES_ROOT, entry)).isDirectory()
    );

const hasControllers = (module: string): boolean =>
    existsSync(path.join(MODULES_ROOT, module, 'controllers'));

describe('the shape every module declares', () => {
    it('finds the modules it means to check', () => {
        // A canary: a moved root or a renamed registry export would otherwise leave every case
        // below sweeping an empty list, which passes and proves nothing.
        expect(moduleFolders().length).toBeGreaterThanOrEqual(10);
        expect(enabledModules.length).toBeGreaterThanOrEqual(10);
    });

    it('names each module after the folder it lives in', () => {
        /*
         * Read from the registry rather than from disk: what matters is the name the RUNNING app
         * uses, and that is the manifest's, whatever the folder is called.
         */
        const misnamed = enabledModules
            .filter(({ name }) => !moduleFolders().includes(name))
            .map(
                ({ name }) =>
                    `${name}: registered under a name no folder matches — the manifest's name must be its directory`
            );

        expect(misnamed).toEqual([]);
    });

    it('enables every module that exists', () => {
        /*
         * The inert-domain check. Nothing fails when a folder goes unlisted, which is what makes
         * it worth a test: the symptom is a 404 on routes someone is certain they wrote.
         */
        const registered = new Set(enabledModules.map(({ name }) => name));
        const unregistered = moduleFolders()
            .filter((folder) => !registered.has(folder))
            .filter((folder) => !DELIBERATELY_DISABLED.includes(folder))
            .map((folder) => `${folder}: a module folder that src/modules.ts never lists`);

        expect(unregistered).toEqual([]);
    });

    it('keeps the disabled list free of modules that no longer exist', () => {
        // A stale exemption silently excuses a folder someone may re-add under the same name.
        const stale = DELIBERATELY_DISABLED.filter((folder) => !moduleFolders().includes(folder));

        expect(stale).toEqual([]);
    });

    it('mounts every module that has controllers', () => {
        /*
         * Handlers nothing routes. The type union already refuses `routes` without `basePath`; it
         * cannot refuse a `controllers/` folder with neither.
         */
        const unmounted = enabledModules
            .filter(({ name }) => hasControllers(name))
            .filter(({ basePath }) => !basePath)
            .map(
                ({ name }) =>
                    `${name}: has controllers/ but declares no basePath — nothing mounts them`
            );

        expect(unmounted).toEqual([]);
    });

    it('gives every mounted module the controllers to justify it', () => {
        /*
         * The reverse, and the cheaper mistake: a `basePath` reserved for routes that were never
         * written claims a URL prefix the API does not answer on.
         */
        const empty = enabledModules
            .filter(({ basePath }) => Boolean(basePath))
            .filter(({ name }) => !hasControllers(name))
            .map(
                ({ name, basePath }) => `${name}: mounts ${String(basePath)} with no controllers/`
            );

        expect(empty).toEqual([]);
    });

    it('gives every module unit specs of its own', () => {
        /*
         * The canary for the unit-layer wall in `eslint.config.ts`, which forbids booting the app
         * from a module's co-located `tests/unit` directory. A rule is only worth what it covers,
         * and a module without that directory is a module the rule says nothing about — so the
         * sweep must not be able to pass by finding nothing.
         */
        const untested = enabledModules
            .filter(({ name }) => !existsSync(path.join(MODULES_ROOT, name, 'tests/unit')))
            .map(({ name }) => `${name}: no tests/unit — the unit-layer rules cover nothing here`);

        expect(untested).toEqual([]);
    });

    it('never re-exports demo data through a barrel', () => {
        /*
         * The half of the two-door rule that `eslint-plugin-boundaries` cannot state.
         *
         * A module publishes `index.ts` for its runtime API and `demo.ts` for its fixtures, and
         * the plugin holds every module to taking the second door only from a seeder. It weighs
         * edges BETWEEN elements, though, and a barrel re-exporting its own `demo.ts` is an edge
         * inside one — invisible to it, and the one move that would undo the split from the other
         * side: every caller of the runtime API would get the fixtures too.
         *
         * `products/index.ts` published `SEED_PRODUCT_IDS` and `productFixtures` beside
         * `productService` before the doors were separated, which is the state this prevents
         * returning to.
         */
        const leaky = enabledModules
            .filter(({ name }) => existsSync(path.join(MODULES_ROOT, name, 'index.ts')))
            .filter(({ name }) =>
                /from '\.\/demo'|require\('\.\/demo'\)/.test(
                    readFileSync(path.join(MODULES_ROOT, name, 'index.ts'), 'utf8')
                )
            )
            .map(({ name }) => `${name}: index.ts re-exports its own demo.ts`);

        expect(leaky).toEqual([]);
    });

    it('starts every base path with a single slash and no trailing one', () => {
        /*
         * `app.ts` concatenates these. A missing leading slash mounts at a path nobody can guess,
         * and a trailing one produces `//` in every URL below it — both are routing bugs that
         * present as 404s rather than as anything naming the manifest.
         */
        const malformed = enabledModules
            .filter(({ basePath }) => Boolean(basePath))
            .filter(({ basePath }) => !/^(?:\/[\da-z][\da-z-]*)+$/.test(basePath!))
            .map(({ name, basePath }) => `${name}: ${String(basePath)}`);

        expect(malformed).toEqual([]);
    });
});

src/modules/orders/tests/unit/invoice-lo.source:
import { asStub } from '@tests/stub';
import type { NextFunction, Request, Response } from 'express';
import { runWithLocale, getLocaleContext } from '@infrastructure/i18n';
import enOrders from '@modules/orders/locales/en.json';
import itOrders from '@modules/orders/locales/it.json';
import { invoiceDocument } from '../../emails';

/**
 * The invoice PDF comes out in the language its producer resolved.
 *
 * The code under test is the generic PDF worker, but the scenario is this module's: the order
 * invoice is the only document the app renders, and the copy it must come out in is this module's
 * dictionary. It lives here so that deleting `orders` takes the template, the copy and this spec
 * together, rather than leaving a worker test asserting against strings that no longer exist.
 *
 * `invoiceDocument` resolves the copy up front and the worker only interpolates, so the guard
 * runs in that direction: prove the worker cannot re-colour a document it was handed. An ambient
 * `t` resolving against the boot language instead would fail silently — nothing throws, and
 * nothing looks wrong in a test written in English.
 *
 * The second half of this file covers the upload chain, which still re-enters the locale by hand
 * because multer consumes the stream mid-request — the one place an in-request store must be
 * restored rather than avoided.
 */

/**
 * EJS `<%= %>` escapes its output — deliberately, since these templates interpolate
 * user-supplied product titles — so `L'ordine` reaches the page as `L&#39;ordine`. Expectations
 * are escaped the same way rather than the templates being loosened to `<%- %>`.
 */
const escaped = (value: string) =>
    value
        .replaceAll('&', '&amp;')
        .replaceAll('<', '&lt;')
        .replaceAll('>', '&gt;')
        .replaceAll('"', '&#34;')
        .replaceAll("'", '&#39;');

const renderHtmlToPdfMock = jest.fn().mockResolvedValue(Buffer.from('pdf'));
jest.mock('@infrastructure/adapters/pdf', () => ({
    renderHtmlToPdf: (html: string, options?: unknown) => renderHtmlToPdfMock(html, options)
}));

/** The HTML handed to the (mocked) PDF renderer. */
const renderedHtml = () => renderHtmlToPdfMock.mock.calls[0][0] as string;

/**
 * A job as a producer would publish it: the builder's output, unmodified. No locale field on the
 * envelope — the only trace of the language is the `<html lang>` value inside the copy.
 */
const invoiceJob = (locale = 'en') => ({
    templatePath: 'shared/views/templates-files/orders.invoice.ejs',
    outputPath: '/tmp/invoice-test.pdf',
    templateData: invoiceDocument(locale, {
        id: 'an-order-id',
        items: [{ product: { title: 'A product', price: 10 }, quantity: 2 }]
    })
});

/**
 * Drives a middleware the way express does, from OUTSIDE any locale scope — which is the
 * situation multer leaves the chain in.
 */
const runMiddleware = async (middleware: unknown, request: Request) =>
    new Promise<string | undefined>((resolve) => {
        (middleware as (r: Request, s: Response, n: NextFunction) => void)(
            request,
            {} as Response,
            (() => resolve(getLocaleContext()?.locale)) as NextFunction
        );
    });

describe('the PDF worker renders the copy it was given', () => {
    beforeEach(() => jest.clearAllMocks());

    it('renders the Italian copy an Italian request produced', async () => {
        const { handlePdfJob } = await import('@infrastructure/adapters/pdf.worker');

        await expect(handlePdfJob(invoiceJob('it'))).resolves.toBe(true);

        expect(renderedHtml()).toContain(escaped(itOrders.orders.invoice.title));
        expect(renderedHtml()).toContain('<html lang="it"');
    });

    it('renders English copy as English', async () => {
        const { handlePdfJob } = await import('@infrastructure/adapters/pdf.worker');

        await expect(handlePdfJob(invoiceJob('en'))).resolves.toBe(true);

        expect(renderedHtml()).toContain(escaped(enOrders.orders.invoice.title));
    });

    /**
     * The document names the order it is for — and it has to do so for the caller who actually
     * downloads invoices, which is the customer.
     *
     * `invoiceJob`'s order is deliberately the shape an OWNER's read produces: a plain object
     * carrying `id`, with no `_id`, because `orderRepository.findByIdScoped` runs a scoped read
     * through `applyOrderTransform` and the serializer deletes `_id` after writing `id`. An
     * admin's unscoped read resolves a hydrated document instead, which carries both — so code
     * reading `_id` works for an admin, and interpolates the literal string `undefined` for
     * everyone else. That is precisely what shipped, in this title and in the PDF's filename,
     * and no assertion existed to see it: the two shapes serialize identically on the wire, so
     * only a value read before serialization can tell them apart.
     */
    it('names the order in the title for an owner-shaped read, not `undefined`', async () => {
        const { handlePdfJob } = await import('@infrastructure/adapters/pdf.worker');

        await expect(handlePdfJob(invoiceJob('en'))).resolves.toBe(true);

        expect(renderedHtml()).toContain(
            escaped(enOrders.orders.invoice['meta-title'].replace('{{order}}', 'an-order-id'))
        );
        expect(renderedHtml()).not.toContain('undefined');
    });

    /**
     * The point of the design: draining a queue from inside an unrelated locale scope cannot
     * colour the output, because the worker never consults a dictionary at all.
     */
    it('ignores the ambient locale entirely', async () => {
        const { handlePdfJob } = await import('@infrastructure/adapters/pdf.worker');

        await runWithLocale('en', () => handlePdfJob(invoiceJob('it')));

        expect(renderedHtml()).toContain(escaped(itOrders.orders.invoice.title));
    });

    it('discards a malformed job rather than rendering one', async () => {
        const { handlePdfJob } = await import('@infrastructure/adapters/pdf.worker');

        await expect(handlePdfJob({ outputPath: '/tmp/x.pdf' })).resolves.toBe(false);

        expect(renderHtmlToPdfMock).not.toHaveBeenCalled();
    });

    it('lets a failed render reject, so the invoice is retried rather than dropped', async () => {
        renderHtmlToPdfMock.mockRejectedValueOnce(new Error('puppeteer died'));
        const { handlePdfJob } = await import('@infrastructure/adapters/pdf.worker');

        // A dead browser says nothing about the job. `false` would dead-letter it; a rejection
        // puts it back on the queue — see the worker's own docblock.
        await expect(handlePdfJob(invoiceJob('it'))).rejects.toThrow('puppeteer died');
    });
});

/**
 * `upload` wraps every multer method so the request's locale survives the stream being consumed
 * (see `infrastructure/adapters/storage.ts`). The integration suite proves it for the one method the routes
 * actually mount; this proves the wrapper is applied uniformly, so a route that later reaches for
 * `upload.fields()` does not quietly lose the language.
 */
describe('every upload method restores the locale', () => {
    const methods = ['single', 'array', 'fields', 'none', 'any'] as const;

    /**
     * Each method returns the whole pipeline — the locale-restoring multer wrapper, then the
     * content check, then the commit to the image store. Asserted rather than assumed, because a
     * route mounting only the first would type-check and silently accept a file whose bytes are
     * not an image, and one mounting only the first two would leave every upload staged in a temp
     * directory with nothing ever pointing at it.
     */
    it.each(methods)('upload.%s returns the full guard chain', async (method) => {
        const { upload } = await import('@infrastructure/adapters/storage');
        const handlers =
            method === 'fields' ? upload.fields([]) : (upload[method] as () => unknown[])();

        expect(handlers).toHaveLength(3);
    });

    it.each(methods)('upload.%s re-enters the request locale', async (method) => {
        const { upload } = await import('@infrastructure/adapters/storage');
        const [localeAware] =
            method === 'fields' ? upload.fields([]) : (upload[method] as () => unknown[])();

        const observed = await runMiddleware(
            localeAware,
            asStub<Request>({
                locale: 'it',
                headers: {}
            })
        );

        expect(observed).toBe('it');
    });

    it('leaves the chain alone when no locale was negotiated', async () => {
        const { upload } = await import('@infrastructure/adapters/storage');
        const [localeAware] = upload.none();

        const observed = await runMiddleware(localeAware, asStub<Request>({ headers: {} }));

        expect(observed).toBeUndefined();
    });
});

tests/unit/infrastructure/adapters/worke.source:
/**
 * The two queue consumers — `email.worker.ts` and `pdf.worker.ts`.
 *
 * Both answer the same question for the broker, and it has THREE outcomes, not two:
 *
 *   - resolve `true`  → ack — done
 *   - resolve `false` → nack without requeue → the dead-letter queue, permanently
 *   - reject          → nack WITH requeue → tried again when the world is healthier
 *
 * The line between the last two is the one worth guarding, because it is the line between "this
 * email will be sent when SMTP comes back" and "this email is lost". A payload that names no
 * recipient will never become valid, so it is refused; an SMTP timeout says nothing about the job,
 * so it is left to reject and the broker redelivers it.
 *
 * The side effect each one exists for — SMTP, puppeteer — is mocked. What is under test is the
 * decision, not the delivery: which payloads are refused before any work starts, and which
 * failures are allowed to escape.
 */

import { logger } from '@infrastructure/adapters/logger';

jest.mock('@infrastructure/adapters/mailer', () => ({ nodemailer: jest.fn() }));
jest.mock('@infrastructure/adapters/pdf', () => ({ renderHtmlToPdf: jest.fn() }));
jest.mock('ejs', () => ({ renderFile: jest.fn() }));

import { nodemailer } from '@infrastructure/adapters/mailer';
import { renderHtmlToPdf } from '@infrastructure/adapters/pdf';
import ejs from 'ejs';
import { EMAIL_QUEUE, PDF_QUEUE } from '@infrastructure/adapters/queue';
import {
    handleEmailJob,
    EMAIL_QUEUE as workerEmailQueue
} from '@infrastructure/adapters/email.worker';
import { handlePdfJob, PDF_QUEUE as workerPdfQueue } from '@infrastructure/adapters/pdf.worker';

const mockedMailer = nodemailer as jest.MockedFunction<typeof nodemailer>;
const mockedPdf = renderHtmlToPdf as jest.MockedFunction<typeof renderHtmlToPdf>;
const mockedEjs = jest.mocked(ejs.renderFile) as jest.Mock;

beforeEach(() => {
    jest.clearAllMocks();
    jest.spyOn(logger, 'warn').mockImplementation(() => logger);
    jest.spyOn(logger, 'error').mockImplementation(() => logger);
    jest.spyOn(logger, 'info').mockImplementation(() => logger);
});

afterAll(() => jest.restoreAllMocks());

/**
 * The queue name each worker re-exports.
 *
 * `queue.ts` owns both spellings so that a producer and its consumer cannot drift — a typo on
 * either side is not an error anywhere, it is a message published to a queue nobody drains. The
 * worker re-exports its own so the registry that wires consumer to queue reads one import rather
 * than two, and identity is the assertion: a re-export resolving to a different value is exactly
 * the drift `queue.ts` centralises the constant to prevent.
 */
describe('the queue names', () => {
    it('re-exports the email queue unchanged', () => {
        expect(workerEmailQueue).toBe(EMAIL_QUEUE);
    });

    it('re-exports the pdf queue unchanged', () => {
        expect(workerPdfQueue).toBe(PDF_QUEUE);
    });

    it('keeps the two queues distinct', () => {
        // One name for both would have the PDF consumer draining email jobs, which `handlePdfJob`
        // discards as malformed — a queue that silently eats every message.
        expect(workerEmailQueue).not.toBe(workerPdfQueue);
    });
});

describe('handleEmailJob', () => {
    const job = {
        request: { to: 'ada@example.com' },
        templateName: 'welcome',
        data: { name: 'Ada' }
    } as Parameters<typeof handleEmailJob>[0];

    it('sends the job and acks it', async () => {
        mockedMailer.mockResolvedValue(undefined as never);

        await expect(handleEmailJob(job)).resolves.toBe(true);
        // The producer resolved the copy before publishing, so the worker forwards `data`
        // untouched — re-resolving it here would render in the worker's language, not the
        // requester's.
        expect(mockedMailer).toHaveBeenCalledWith(job.request, 'welcome', { name: 'Ada' });
    });

    it('defaults absent template data to an empty object rather than passing undefined', async () => {
        mockedMailer.mockResolvedValue(undefined as never);

        await handleEmailJob({ request: job.request, templateName: 'welcome' });

        expect(mockedMailer).toHaveBeenCalledWith(job.request, 'welcome', {});
    });

    /*
     * Every payload the guard rejects. `Partial` is honest about the broker: an older producer, or
     * a hand-published message, can deliver any of these — and each must be discarded rather than
     * reaching nodemailer with a missing recipient.
     */
    it.each([
        ['no recipient', { request: { to: '' }, templateName: 'welcome' }],
        ['no request at all', { templateName: 'welcome' }],
        ['no template name', { request: { to: 'ada@example.com' } }],
        ['an empty job', {}],
        // `job?.` guards the job itself, not only its fields: a broker can deliver a null body.
        ['a null job', null],
        ['an undefined job', undefined]
    ])('refuses a job with %s, without sending', async (_label, malformed) => {
        await expect(
            handleEmailJob(malformed as Parameters<typeof handleEmailJob>[0])
        ).resolves.toBe(false);
        expect(mockedMailer).not.toHaveBeenCalled();
        expect(logger.warn).toHaveBeenCalled();
    });

    it('lets a failed send reject, so the broker requeues it', async () => {
        mockedMailer.mockRejectedValue(new Error('SMTP refused'));

        // Not `false`. A refused connection, a timeout, greylisting — none of them are facts about
        // this job, and `consumeFromQueue` requeues a rejection for exactly that reason. Answering
        // `false` here dead-letters a password reset because SMTP blinked.
        await expect(handleEmailJob(job)).rejects.toThrow('SMTP refused');
        // Logged on the way out: the requeue is what saves the email, the log is what makes a job
        // that keeps failing visible instead of a queue that quietly refills.
        expect(logger.error).toHaveBeenCalledWith(
            expect.objectContaining({ error: 'SMTP refused' })
        );
    });
});

describe('handlePdfJob', () => {
    const job = {
        templatePath: 'shared/views/invoice.ejs',
        outputPath: '/tmp/invoice.pdf',
        templateData: { locale: 'it', total: 10 }
    } as Parameters<typeof handlePdfJob>[0];

    it('renders the template, writes the PDF and acks', async () => {
        mockedEjs.mockResolvedValue('<html lang="it"></html>');
        mockedPdf.mockResolvedValue(undefined as never);

        await expect(handlePdfJob(job)).resolves.toBe(true);
        // `templateData` reaches the template as-is, `locale` included — that is what puts the
        // right language in `<html lang>` without the worker knowing which one it is.
        expect(mockedEjs).toHaveBeenCalledWith(expect.stringContaining('invoice.ejs'), {
            locale: 'it',
            total: 10
        });
        expect(mockedPdf).toHaveBeenCalledWith('<html lang="it"></html>', {
            format: 'A4',
            path: '/tmp/invoice.pdf'
        });
    });

    it.each([
        ['no template path', { outputPath: '/tmp/invoice.pdf' }],
        ['no output path', { templatePath: 'shared/views/invoice.ejs' }],
        ['an empty job', {}],
        ['a null job', null],
        ['an undefined job', undefined]
    ])('refuses a job with %s, without rendering', async (_label, malformed) => {
        await expect(handlePdfJob(malformed as Parameters<typeof handlePdfJob>[0])).resolves.toBe(
            false
        );
        expect(mockedEjs).not.toHaveBeenCalled();
        expect(logger.warn).toHaveBeenCalled();
    });

    it('lets a failed template render reject, so the broker requeues it', async () => {
        mockedEjs.mockRejectedValue(new Error('template missing'));

        await expect(handlePdfJob(job)).rejects.toThrow('template missing');
        expect(mockedPdf).not.toHaveBeenCalled();
        expect(logger.error).toHaveBeenCalledWith(
            expect.objectContaining({ error: 'template missing' })
        );
    });

    it('lets a failed PDF render reject after a successful template render', async () => {
        mockedEjs.mockResolvedValue('<html></html>');
        mockedPdf.mockRejectedValue(new Error('puppeteer crashed'));

        // The second half of the chain has its own failure mode: the markup was fine and the
        // browser died. A dead browser is the most transient failure this file has — it must not
        // ack an unwritten file, and it must not throw the job away either.
        await expect(handlePdfJob(job)).rejects.toThrow('puppeteer crashed');
        expect(logger.error).toHaveBeenCalledWith(
            expect.objectContaining({ error: 'puppeteer crashed' })
        );
    });
});

