/**
 * `src/modules/audit-logs/service.ts` — the persistence sink behind `@infrastructure/observability/audit`.
 *
 * The two functions in this module are deliberately asymmetric about failure, and that asymmetry
 * is the only thing worth testing here:
 *
 *   - `record` is **fail-open**. It is called while answering requests — including failing ones —
 *     so a Mongo hiccup must not turn a rejected login into a 500. It returns `void`, swallows
 *     every rejection into a log line, and must never produce an unhandled rejection. The
 *     compliance record is the audit *logger*, which has already written the entry by the time
 *     this runs; losing the queryable copy degrades a dashboard and nothing else.
 *   - `search` is **fail-closed**. It answers an admin's explicit request for the data, so a
 *     failed read is a failed request rather than something to hide.
 *
 * Swap either behaviour and the suite stays green everywhere else in the repo: nothing observes
 * `record`'s return value, and nothing else calls `search` directly. Hence these cases.
 *
 * The repository is mocked rather than driven against the in-memory Mongo, because what is under
 * test is the error contract, and a real repository cannot be made to fail on demand.
 */
import { auditLogService } from '@modules/audit-logs';
import { auditLogRepository } from '@modules/audit-logs/repository';
import { logger } from '@infrastructure/adapters/logger';
import { type AuditEntry } from '@infrastructure/observability/audit';
import type { AuditLogDocument } from '@modules/audit-logs/model';
import { auditSinkFailuresTotal } from '@modules/audit-logs/metrics';

/**
 * The counter's current value, read back through prom-client rather than from a local tally: the
 * point of the metric is that it reaches the registry the `/observability/metrics` scrape reads.
 */
const readCounter = async (): Promise<number> => {
    const { values } = await auditSinkFailuresTotal.get();
    return values[0]?.value ?? 0;
};

jest.mock('@modules/audit-logs/repository', () => ({
    AUDIT_SORT: { timestamp: -1, _id: -1 },
    auditLogRepository: {
        create: jest.fn(),
        search: jest.fn(),
        // The real fragment builder, not a stub: what the service must be shown to do is hand
        // `since` to `scope`, and a stubbed one would pass whether it did or not.
        sinceScope: (since?: Date) => (since ? { timestamp: { $gt: since } } : {})
    }
}));

jest.mock('@infrastructure/adapters/logger', () => ({
    logger: { warn: jest.fn(), error: jest.fn(), info: jest.fn() }
}));

const mockedRepository = auditLogRepository as jest.Mocked<typeof auditLogRepository>;
const mockedLogger = logger as jest.Mocked<typeof logger>;

const makeEntry = (overrides: Partial<AuditEntry> = {}): AuditEntry =>
    ({
        actor_user_id: 'user-1',
        actor_role: 'user',
        action: 'auth.login.succeeded',
        outcome: 'success',
        timestamp: new Date('2026-08-01T10:00:00.000Z'),
        level: 'info',
        ...overrides
    }) as AuditEntry;

describe('auditLogService.record', () => {
    it('hands the entry to the repository unchanged', () => {
        mockedRepository.create.mockResolvedValue({} as AuditLogDocument);
        const entry = makeEntry({ target_id: 'prod-9' });

        auditLogService.record(entry);

        expect(mockedRepository.create).toHaveBeenCalledWith(entry);
    });

    it('returns void rather than the write, so no caller can await it', () => {
        // The signature is the contract: a caller that could await this would be able to make a
        // request wait on the audit trail, which is the coupling `record` exists to avoid.
        mockedRepository.create.mockResolvedValue({} as AuditLogDocument);

        // eslint-disable-next-line @typescript-eslint/no-confusing-void-expression -- the assertion IS that record() returns undefined (fire-and-forget contract)
        expect(auditLogService.record(makeEntry())).toBeUndefined();
    });

    it('swallows a failed write into a warning instead of throwing', async () => {
        mockedRepository.create.mockRejectedValue(new Error('mongo is down'));

        expect(() => auditLogService.record(makeEntry())).not.toThrow();

        // The rejection is handled on a later tick, so the assertion has to wait for one.
        await Promise.resolve();
        await Promise.resolve();

        expect(mockedLogger.warn).toHaveBeenCalledWith(
            expect.objectContaining({
                message: 'audit entry not persisted',
                action: 'auth.login.succeeded',
                error: 'mongo is down'
            })
        );
    });

    it('counts the lost row so an empty dashboard is distinguishable from a quiet one', async () => {
        /* The gap the fail-open leaves behind: `GET /observability/audit` answering `{ items: [] }`
         * looks exactly like "nothing happened". The counter is the only thing that can tell those
         * two apart, and it must be incremented on the SAME path that swallows the error. */
        const before = await readCounter();
        mockedRepository.create.mockRejectedValue(new Error('mongo is down'));

        auditLogService.record(makeEntry());
        await Promise.resolve();
        await Promise.resolve();

        expect(await readCounter()).toBe(before + 1);
    });

    it('leaves the counter alone when the write succeeds', async () => {
        const before = await readCounter();
        mockedRepository.create.mockResolvedValue({} as AuditLogDocument);

        auditLogService.record(makeEntry());
        await Promise.resolve();
        await Promise.resolve();

        expect(await readCounter()).toBe(before);
    });

    it('produces no unhandled rejection when the write fails', async () => {
        // The `.catch()` is what makes the floating promise safe. Without it this is an
        // unhandled rejection, which — unlike the lost audit row — can take the process down.
        const unhandled = jest.fn();
        process.on('unhandledRejection', unhandled);

        mockedRepository.create.mockRejectedValue(new Error('mongo is down'));
        auditLogService.record(makeEntry());

        await new Promise((resolve) => setImmediate(resolve));
        process.off('unhandledRejection', unhandled);

        expect(unhandled).not.toHaveBeenCalled();
    });

    it('names the failing action in the warning, so a lost entry is identifiable', async () => {
        mockedRepository.create.mockRejectedValue(new Error('boom'));

        auditLogService.record(makeEntry({ action: 'auth.login.failed' }));

        // The rejection is handled a couple of microtasks later, same as the case above.
        await Promise.resolve();
        await Promise.resolve();

        expect(mockedLogger.warn).toHaveBeenCalledWith(
            expect.objectContaining({ action: 'auth.login.failed' })
        );
    });
});

describe('auditLogService.search', () => {
    const emptyPage = {
        items: [] as AuditLogDocument[],
        meta: { page: 1, pageSize: 10, totalItems: 0, totalPages: 0 }
    };

    it('passes the filters through untouched, and pages them', async () => {
        mockedRepository.search.mockResolvedValue(emptyPage);
        const filters = { actor: 'user-1', outcome: 'failure' as const, page: 3, pageSize: 25 };

        await expect(auditLogService.search(filters)).resolves.toBe(emptyPage);
        expect(mockedRepository.search).toHaveBeenCalledWith(
            filters,
            {},
            { timestamp: -1, _id: -1 }
        );
    });

    it('hands `since` to the scope rather than to the filters', async () => {
        // The scope is merged after `buildWhere` and never passes through it, which is what
        // keeps the bound a Date instead of the number `Number()` would make of it.
        mockedRepository.search.mockResolvedValue(emptyPage);
        const since = new Date('2026-08-02T10:00:00.000Z');

        await auditLogService.search({ since });

        expect(mockedRepository.search).toHaveBeenCalledWith(
            { since },
            { timestamp: { $gt: since } },
            { timestamp: -1, _id: -1 }
        );
    });

    it('propagates a failed read rather than swallowing it', async () => {
        // The opposite of `record`: this one is answering an admin, so a failure is a failure.
        mockedRepository.search.mockRejectedValue(new Error('mongo is down'));

        await expect(auditLogService.search({})).rejects.toThrow('mongo is down');
        expect(mockedLogger.warn).not.toHaveBeenCalled();
    });
});

src/modules/account/tests/unit/token-cle.source:
/**
 * `runTokenCleanup` — the scheduled job that drops expired tokens from every user.
 *
 * ── Why this file is worth reading as an example ─────────────────────────────────────────────
 * The obvious test — call the job, assert the repository method ran — is true in BOTH branches,
 * so writing one per branch produces the same test twice: full line coverage, and a mutation
 * score near zero because nothing observes what the branches do DIFFERENTLY. `if (success)`
 * forced to `true` and forced to `false` both stay green.
 *
 * The logging IS the behaviour here. This job runs unattended on a schedule; nobody watches it
 * succeed. Its entire output is the log line an operator reads afterwards to find out whether
 * tokens are still being cleaned up — so "which line was logged, at which level, saying what" is
 * the contract, not incidental detail. A silent failure here means expired refresh tokens
 * accumulate indefinitely and nobody knows.
 *
 * So every case below asserts on the log, and the two branches are asserted to be mutually
 * exclusive — which is what makes a forced `true`/`false` fail.
 */
import { userModel as Users } from '@modules/users';
import { runTokenCleanup, accountService } from '@modules/account/services';
import { logger } from '@infrastructure/adapters/logger';
import { testCallerContext } from '@tests/caller-context';
import * as auditPort from '@infrastructure/observability/audit';
import { accountAuditActions } from '../../audit';

/*
 * Only `userModel` is replaced. The rest has to stay REAL because this file reaches the job through
 * `@modules/account/services`, and that barrel evaluates every service beside it — `profile.ts`
 * builds its zod schema from `zodUserSchema` at module scope, so a mock that omits it throws before
 * a single test runs. Spreading the actual module keeps the barrel loadable and still lets the one
 * call this job makes be observed.
 */
jest.mock('@modules/users', () => ({
    ...jest.requireActual('@modules/users'),
    __esModule: true,
    userModel: {
        tokenRemoveExpired: jest.fn()
    }
}));

jest.mock('@infrastructure/adapters/logger', () => ({
    __esModule: true,
    logger: {
        info: jest.fn(),
        error: jest.fn(),
        warn: jest.fn()
    }
}));

/*
 * `emitAuditEvent` is replaced too, rather than reached with `jest.spyOn(auditPort, ...)` on the
 * namespace import below. TypeScript's CommonJS `__importStar` interop copies a namespace import's
 * properties as non-configurable getters, which `jest.spyOn` cannot redefine — a mismatch some
 * transpile paths mask and some (Stryker's instrumented sandbox, at minimum) do not. Mocking the
 * module gives every consumer a plain, always-configurable `jest.fn()` instead.
 */
jest.mock('@infrastructure/observability/audit', () => ({
    __esModule: true,
    ...jest.requireActual('@infrastructure/observability/audit'),
    emitAuditEvent: jest.fn()
}));

const mockTokenRemoveExpired = Users.tokenRemoveExpired as jest.MockedFunction<
    typeof Users.tokenRemoveExpired
>;
const mockedLogger = logger as jest.Mocked<typeof logger>;

/** Every message the job passed to `logger.info`, flattened for substring assertions. */
const infoMessages = () =>
    mockedLogger.info.mock.calls.map(([message]) =>
        typeof message === 'string' ? message : JSON.stringify(message)
    );
const errorMessages = () =>
    mockedLogger.error.mock.calls.map(([message]) =>
        typeof message === 'string' ? message : JSON.stringify(message)
    );

beforeEach(() => {
    jest.clearAllMocks();
});

describe('runTokenCleanup — the work', () => {
    it('asks the model to remove expired tokens exactly once', async () => {
        mockTokenRemoveExpired.mockResolvedValueOnce({ status: 200, success: true });

        await runTokenCleanup();

        expect(mockTokenRemoveExpired).toHaveBeenCalledTimes(1);
    });

    it('announces that it started, before knowing the outcome', async () => {
        // The start line is what tells an operator the schedule fired at all. Without it, a job
        // that never ran and a job that ran and did nothing look identical in the log.
        mockTokenRemoveExpired.mockResolvedValueOnce({ status: 200, success: true });

        await runTokenCleanup();

        expect(infoMessages()[0]).toContain('starting');
    });
});

describe('runTokenCleanup — the success branch', () => {
    beforeEach(() => {
        mockTokenRemoveExpired.mockResolvedValueOnce({ status: 200, success: true });
    });

    it('logs completion at info level', async () => {
        await runTokenCleanup();

        expect(infoMessages().some((message) => message.includes('completed'))).toBe(true);
    });

    it('logs NOTHING at error level', async () => {
        // Half of what makes the branch condition observable: success must not reach the error
        // path. Without this, `if (success)` forced to `false` still passes.
        await runTokenCleanup();

        expect(mockedLogger.error).not.toHaveBeenCalled();
    });
});

describe('runTokenCleanup — the failure branch', () => {
    beforeEach(() => {
        mockTokenRemoveExpired.mockResolvedValueOnce({ status: 500, success: false });
    });

    it('logs the failure at ERROR level, not info', async () => {
        // Level matters operationally: an alerting rule keys on it. A failure logged at info is
        // a failure nobody is paged for.
        await runTokenCleanup();

        expect(mockedLogger.error).toHaveBeenCalledTimes(1);
    });

    it('includes the status in the failure message, so the log says WHY', async () => {
        // The template literal is the only place the status reaches a human. Emptied out, the
        // operator learns that cleanup failed and nothing else.
        await runTokenCleanup();

        expect(errorMessages()[0]).toContain('500');
    });

    it('does not also claim completion', async () => {
        // The other half of the mutual exclusion: a failure must not log "completed
        // successfully" as well. This is what fails when `if (success)` is forced to `true`.
        await runTokenCleanup();

        expect(infoMessages().some((message) => message.includes('completed'))).toBe(false);
    });
});

describe('runTokenCleanup — the two branches are mutually exclusive', () => {
    // Stated as a table over both outcomes rather than as two more cases: the property is that
    // exactly one of the two log paths is taken, whichever way the model answers.
    it.each([
        [true, 200],
        [false, 500]
    ])('success=%s takes exactly one of the two paths', async (success, status) => {
        mockTokenRemoveExpired.mockResolvedValueOnce({ status, success });

        await runTokenCleanup();

        const completed = infoMessages().filter((message) => message.includes('completed')).length;
        const failed = mockedLogger.error.mock.calls.length;

        expect(completed + failed).toBe(1);
    });
});

describe('adminTokenCleanup — the admin-triggered, audited counterpart', () => {
    const mockedEmitAuditEvent = auditPort.emitAuditEvent as jest.MockedFunction<
        typeof auditPort.emitAuditEvent
    >;

    it('audits a successful cleanup', async () => {
        mockTokenRemoveExpired.mockResolvedValueOnce({ status: 200, success: true });

        const result = await accountService.adminTokenCleanup(testCallerContext);

        expect(result).toEqual({ status: 200, success: true });
        expect(mockedEmitAuditEvent).toHaveBeenCalledWith(
            expect.objectContaining({
                action: accountAuditActions.AUTH_TOKEN_EXPIRED_CLEANUP,
                outcome: 'success'
            })
        );
    });

    it('does not audit a failed cleanup — nothing to report happened', async () => {
        mockTokenRemoveExpired.mockResolvedValueOnce({ status: 500, success: false });

        const result = await accountService.adminTokenCleanup(testCallerContext);

        expect(result).toEqual({ status: 500, success: false });
        expect(mockedEmitAuditEvent).not.toHaveBeenCalled();
    });
});

