/**
 * Cart rules — `src/modules/cart/domain/rules.ts`.
 *
 * No mocks, no database. The verdict-to-status mapping is covered in `service.test.ts`.
 */

import { evaluateCheckout, type CartLineCandidate } from '../../domain/rules';
import { availabilityOf } from '@modules/inventory';

/**
 * A line asking for `quantity`, against a product holding `onHand` with `reserved` spoken for.
 *
 * Both counters are stated rather than only the total, because the whole point of the pre-flight
 * now is that it reads the DIFFERENCE — a fixture that could only set one number could not tell
 * "nothing on the shelf" apart from "everything on it is promised", which is the distinction
 * these cases exist to check.
 */
const line = (quantity = 1, onHand?: number, reserved = 0): CartLineCandidate => ({
    quantity,
    product: onHand === undefined ? {} : { onHand, reserved }
});

describe('evaluateCheckout', () => {
    it('refuses an empty cart', () => {
        expect(evaluateCheckout([])).toEqual({ ok: false, reason: 'empty' });
    });

    it('accepts a cart whose lines all resolved', () => {
        expect(evaluateCheckout([line(1, 10), line(2, 10)])).toEqual({ ok: true });
    });

    // `null` is the real case: `populate()` writes it when the product was deleted.
    it.each([
        ['a deleted product (null)', null],
        ['an absent product (undefined)', undefined]
    ])('refuses a cart holding %s', (_label, product) => {
        expect(evaluateCheckout([line(1, 10), { quantity: 1, product }])).toEqual({
            ok: false,
            reason: 'product-unavailable'
        });
    });

    // Order matters: the two reasons map to different status codes and analytics categories.
    it('reports emptiness before availability', () => {
        expect(evaluateCheckout([])).toEqual({ ok: false, reason: 'empty' });
    });

    it('refuses a line asking for more than the shelf holds', () => {
        expect(evaluateCheckout([line(1, 5), line(6, 5)])).toMatchObject({
            ok: false,
            reason: 'insufficient-stock',
            shortfalls: [{ requested: 6, available: 5 }]
        });
    });

    it('accepts a line taking exactly the last units', () => {
        expect(evaluateCheckout([line(5, 5)])).toEqual({ ok: true });
    });

    /*
     * ── The case the reservation model added ─────────────────────────────────────────────────
     *
     * Forty units on the shelf and all forty promised to open orders. Under the old single-count
     * model this line read as comfortably in stock and was refused later, by the write; now it is
     * refused here, because availability — not the pile in the warehouse — is what a customer can
     * buy. This is the case that could not be expressed before, so it is the one worth asserting.
     */
    it('refuses a line whose units are all reserved', () => {
        expect(evaluateCheckout([line(1, 40, 40)])).toMatchObject({
            ok: false,
            reason: 'insufficient-stock',
            // Forty units exist and none is sellable — the shortfall reports availability.
            shortfalls: [{ requested: 1, available: 0 }]
        });
    });

    it('accepts a line that fits in what is left after the holds', () => {
        expect(evaluateCheckout([line(3, 40, 37)])).toEqual({ ok: true });
    });

    /*
     * A missing count means REFUSE, not allow — the counter-intuitive half of this rule.
     *
     * Reading absence as "unconstrained" is the natural instinct and the wrong direction to be
     * wrong in for a rule whose only job is to refuse: it lets any quantity through on exactly the
     * documents nothing is known about. The safe reading of "we do not know how many there are" is
     * "do not sell it".
     *
     * Nothing is lost by it: `db/migrations/20260817120000-inventory-counters.js` backfills every
     * row, so this defends against a document that should not exist rather than a state the shop
     * relies on.
     */
    it('treats absent counters as nothing to sell', () => {
        expect(evaluateCheckout([line(1)])).toMatchObject({
            ok: false,
            reason: 'insufficient-stock',
            shortfalls: [{ requested: 1, available: 0 }]
        });
    });

    // Resolution outranks availability: a vanished product is the harder failure, and its 404
    // must not be masked by a 409 about a count nobody can see.
    it('reports an unresolved product before an unavailable one', () => {
        expect(evaluateCheckout([{ quantity: 9, product: null }, line(6, 5)])).toEqual({
            ok: false,
            reason: 'product-unavailable'
        });
    });
});

/**
 * The duplication guard.
 *
 * `rules.ts` carries its own copy of the availability subtraction, because the domain layer may
 * not import a sibling module (see the note there, and `eslint.config.ts`). A copy that nothing
 * compares is a copy that drifts, so this compares it — against `inventory`'s `availabilityOf`,
 * which is the authority — through the only observable the pure rule exposes: its verdict.
 *
 * A test file is allowed the import the rule is not. That asymmetry is the whole trick.
 */
describe('availability agrees with the inventory authority', () => {
    const cases: { onHand: number; reserved: number }[] = [
        { onHand: 0, reserved: 0 },
        { onHand: 10, reserved: 0 },
        { onHand: 10, reserved: 3 },
        { onHand: 10, reserved: 10 },
        // The state that should be unreachable. Both copies clamp at zero; asserting it here is
        // what stops one of them quietly starting to return a negative.
        { onHand: 5, reserved: 8 }
    ];

    it.each(cases)('onHand $onHand, reserved $reserved', ({ onHand, reserved }) => {
        const available = availabilityOf({ onHand, reserved });

        /*
         * The boundary, pinned from both sides — which is what makes a copy that is off by one
         * fail rather than merely look different.
         *
         * The `available > 0` guard is not a get-out: a line for zero units is not a thing a cart
         * can hold (`CartItem.quantity` has `minimum: 1`), so there is no boundary below to pin
         * when nothing is available. The assertion that still runs in that case — one unit is
         * refused — is the one that matters there.
         */
        if (available > 0)
            expect(evaluateCheckout([line(available, onHand, reserved)])).toEqual({ ok: true });

        expect(evaluateCheckout([line(available + 1, onHand, reserved)])).toMatchObject({
            ok: false,
            reason: 'insufficient-stock',
            shortfalls: [{ requested: available + 1, available }]
        });
    });
});

tests/unit/infrastructure/runtime/enviro.source:
/**
 * `src/infrastructure/runtime/environment.ts` — the fail-fast boot check.
 *
 * Small on purpose and tested exhaustively for it: this is the code that decides whether the
 * process starts at all, and a hole here is a server that accepts traffic and 500s on the first
 * login. Uncovered since the file moved from `src/infrastructure/` into `runtime/` — the
 * coverage glob did not follow, which is exactly the drift this suite closes.
 */
import {
    environmentFlag,
    environmentNumber,
    validateRequiredEnvironment
} from '@infrastructure/runtime/environment';

const KEYS = [
    'NODE_TOKEN_ACCESS',
    'NODE_TOKEN_REFRESH',
    'NODE_DB_URI',
    'NODE_MONGODB_PORT'
] as const;

let saved: Record<string, string | undefined>;

beforeEach(() => {
    saved = Object.fromEntries(KEYS.map((key) => [key, process.env[key]]));
    process.env.NODE_TOKEN_ACCESS = 'access-secret';
    process.env.NODE_TOKEN_REFRESH = 'refresh-secret';
    process.env.NODE_DB_URI = 'mongodb://127.0.0.1:27017/test';
    delete process.env.NODE_MONGODB_PORT;
});

afterEach(() => {
    for (const key of KEYS) {
        if (saved[key] === undefined) delete process.env[key];
        else process.env[key] = saved[key];
    }
});

it('passes with both token secrets and a database URI', () => {
    expect(() => validateRequiredEnvironment()).not.toThrow();
});

it('accepts host/port fragments in place of a full URI', () => {
    delete process.env.NODE_DB_URI;
    process.env.NODE_MONGODB_PORT = '27017';
    expect(() => validateRequiredEnvironment()).not.toThrow();
});

it('names every missing secret at once, not one per restart cycle', () => {
    delete process.env.NODE_TOKEN_ACCESS;
    delete process.env.NODE_TOKEN_REFRESH;
    expect(() => validateRequiredEnvironment()).toThrow(/NODE_TOKEN_ACCESS, NODE_TOKEN_REFRESH/);
});

it('treats a whitespace-only value as missing — the CI empty-secret accident', () => {
    process.env.NODE_TOKEN_ACCESS = '   ';
    expect(() => validateRequiredEnvironment()).toThrow(/NODE_TOKEN_ACCESS/);
});

it('requires SOME database configuration: a blank URI and no port is a refusal to boot', () => {
    process.env.NODE_DB_URI = '  ';
    delete process.env.NODE_MONGODB_PORT;
    expect(() => validateRequiredEnvironment()).toThrow(/NODE_DB_URI or NODE_MONGODB_PORT/);
});

/**
 * The two coercions every reader shares.
 *
 * Exhaustive on the unusable inputs rather than the working one, because the working one was never
 * the problem: a variable is always a string, and the failures worth a suite are the strings that
 * are not the number or the switch someone meant. The pre-share spellings answered `NaN` for a
 * typo, which propagates into a `Date` or a `maxAge` and misbehaves with no error attached.
 */
const CANARY = 'NODE_TEST_CANARY';

const withValue = <T>(value: string | undefined, read: () => T): T => {
    const previous = process.env[CANARY];
    if (value === undefined) delete process.env[CANARY];
    else process.env[CANARY] = value;
    try {
        return read();
    } finally {
        if (previous === undefined) delete process.env[CANARY];
        else process.env[CANARY] = previous;
    }
};

describe('environmentNumber', () => {
    it('reads an integer a deployment set', () => {
        expect(withValue('900', () => environmentNumber(CANARY, 30))).toBe(900);
    });

    it('parses base 10, so a zero-padded value is not read as octal', () => {
        expect(withValue('0900', () => environmentNumber(CANARY, 30))).toBe(900);
    });

    it('tolerates surrounding whitespace, which .env files and CI injection both produce', () => {
        expect(withValue('  900  ', () => environmentNumber(CANARY, 30))).toBe(900);
    });

    it.each([
        ['unset', undefined],
        ['blank', ''],
        ['whitespace', '   '],
        ['prose', 'thirty']
    ])('falls back rather than answering NaN for %s', (_label, value) => {
        // The defect this helper exists for. `Number(process.env.X ?? 30)` answers NaN here, and
        // NaN minutes becomes an Invalid Date rather than an error anyone sees.
        expect(withValue(value, () => environmentNumber(CANARY, 30))).toBe(30);
    });

    it.each(['30m', '5mb', '1.5', '9 0 0'])(
        'refuses %p rather than reading the numeric prefix off it',
        (value) => {
            // Bare `parseInt` reads `5mb` as 5, so a mistyped upload ceiling becomes a five-BYTE
            // limit — an answer that looks configured and rejects every upload.
            expect(withValue(value, () => environmentNumber(CANARY, 90))).toBe(90);
        }
    );

    it('accepts zero and negatives when no minimum is declared', () => {
        expect(withValue('0', () => environmentNumber(CANARY, 30))).toBe(0);
        expect(withValue('-5', () => environmentNumber(CANARY, 30))).toBe(-5);
    });

    it('falls back below the declared minimum, because a size of zero is broken not smaller', () => {
        expect(withValue('0', () => environmentNumber(CANARY, 30, 1))).toBe(30);
        expect(withValue('-5', () => environmentNumber(CANARY, 30, 1))).toBe(30);
        expect(withValue('1', () => environmentNumber(CANARY, 30, 1))).toBe(1);
    });
});

describe('environmentFlag', () => {
    it.each(['1', 'true', 'TRUE', 'yes', 'on', ' true '])('reads %p as on', (value) => {
        expect(withValue(value, () => environmentFlag(CANARY, false))).toBe(true);
    });

    it.each(['0', 'false', 'FALSE', 'no', 'off', ' 0 '])('reads %p as off', (value) => {
        expect(withValue(value, () => environmentFlag(CANARY, true))).toBe(false);
    });

    it('accepts both vocabularies for the same flag', () => {
        // The bug this closes: kill switches were `!== '0'` and opt-ins `=== 'true'`, so
        // `NODE_DEMO=1` turned demo mode off and `NODE_RABBITMQ_ENABLED=false` left the queue on.
        expect(withValue('1', () => environmentFlag(CANARY, false))).toBe(true);
        expect(withValue('true', () => environmentFlag(CANARY, false))).toBe(true);
        expect(withValue('0', () => environmentFlag(CANARY, true))).toBe(false);
        expect(withValue('false', () => environmentFlag(CANARY, true))).toBe(false);
    });

    it.each([
        ['unset', undefined],
        ['blank', ''],
        ['unrecognised', 'maybe']
    ])('takes the default for %s rather than reading it as off', (_label, value) => {
        expect(withValue(value, () => environmentFlag(CANARY, true))).toBe(true);
        expect(withValue(value, () => environmentFlag(CANARY, false))).toBe(false);
    });
});

src/modules/account/tests/unit/cookies.t.source:
/**
 * Auth cookies — `src/modules/account/cookies.ts`.
 *
 * Four one-liners that together decide whether a session can be stolen. The flags are the whole
 * substance of the module, so they are asserted individually rather than as one blob:
 *
 *   - `jwt` (the refresh token) must be **httpOnly** — it is the credential, and script access
 *     to it is the difference between an XSS bug and an account takeover.
 *   - `isAuth` must NOT be httpOnly — it is a UI hint the frontend has to read, and it carries
 *     no secret. Getting these two backwards breaks either security or the login UI.
 *   - `secure` must track production, so local HTTP development still works while deployed
 *     traffic never sends the credential in the clear.
 *   - clearing must repeat the same flags: browsers only drop a cookie when name/path/flags
 *     match, so a mismatched `clearCookie` leaves the session cookie in place — a logout that
 *     silently does nothing.
 */

import { asStub } from '@tests/stub';
import type { Response } from 'express';
import {
    createRefreshCookie,
    destroyRefreshCookie,
    createLoggedCookie,
    destroyLoggedCookie
} from '@modules/account/session/cookies';
import { RefreshTokenExpiryTime } from '@modules/account/session/config';

/** Captures the (name, value, options) triples the module hands to Express. */
const makeResponse = () =>
    asStub<
        Response & {
            cookie: jest.Mock;
            clearCookie: jest.Mock;
        }
    >({
        cookie: jest.fn(),
        clearCookie: jest.fn()
    });

const originalNodeEnvironment = process.env.NODE_ENV;
const originalShort = process.env.NODE_TOKEN_REFRESH_TIME_SHORT;
const originalAccess = process.env.NODE_TOKEN_ACCESS_TIME;

beforeEach(() => {
    // Real values, so the maxAge assertions exercise the actual token-config wiring rather than
    // a mock that would agree with anything.
    process.env.NODE_TOKEN_REFRESH_TIME_SHORT = '3600';
    process.env.NODE_TOKEN_ACCESS_TIME = '900';
});

afterEach(() => {
    process.env.NODE_ENV = originalNodeEnvironment;
    if (originalShort === undefined) delete process.env.NODE_TOKEN_REFRESH_TIME_SHORT;
    else process.env.NODE_TOKEN_REFRESH_TIME_SHORT = originalShort;
    if (originalAccess === undefined) delete process.env.NODE_TOKEN_ACCESS_TIME;
    else process.env.NODE_TOKEN_ACCESS_TIME = originalAccess;
});

describe('createRefreshCookie', () => {
    it('sets the jwt cookie httpOnly, lax and site-wide', () => {
        const response = makeResponse();

        createRefreshCookie(response, 'signed.jwt.value');

        const [name, value, options] = response.cookie.mock.calls[0];
        expect(name).toBe('jwt');
        expect(value).toBe('signed.jwt.value');
        // httpOnly is the load-bearing flag: this cookie is the credential.
        expect(options.httpOnly).toBe(true);
        expect(options.sameSite).toBe('lax');
        expect(options.path).toBe('/');
    });

    it('marks the cookie secure in production', () => {
        process.env.NODE_ENV = 'production';
        const response = makeResponse();

        createRefreshCookie(response, 'token');

        expect(response.cookie.mock.calls[0][2].secure).toBe(true);
    });

    it('leaves the cookie non-secure outside production, so local HTTP still works', () => {
        process.env.NODE_ENV = 'development';
        const response = makeResponse();

        createRefreshCookie(response, 'token');

        expect(response.cookie.mock.calls[0][2].secure).toBe(false);
    });

    it('derives maxAge from the requested expiry tier', () => {
        const response = makeResponse();

        createRefreshCookie(response, 'token', RefreshTokenExpiryTime.SHORT);

        // 3600s from NODE_TOKEN_REFRESH_TIME_SHORT, in milliseconds.
        expect(response.cookie.mock.calls[0][2].maxAge).toBe(3_600_000);
    });

    it('falls back to the access-token window when no tier is given', () => {
        const response = makeResponse();

        createRefreshCookie(response, 'token');

        expect(response.cookie.mock.calls[0][2].maxAge).toBe(900_000);
    });
});

describe('destroyRefreshCookie', () => {
    it('clears jwt with the same flags it was set with', () => {
        const response = makeResponse();

        destroyRefreshCookie(response);

        const [name, options] = response.clearCookie.mock.calls[0];
        expect(name).toBe('jwt');
        // A browser drops a cookie only on a matching name/path/flags triple. Any drift here is
        // a logout that appears to succeed and leaves the session alive.
        expect(options).toEqual(
            expect.objectContaining({ httpOnly: true, sameSite: 'lax', path: '/' })
        );
    });

    it('matches the production secure flag when clearing', () => {
        process.env.NODE_ENV = 'production';
        const response = makeResponse();

        destroyRefreshCookie(response);

        expect(response.clearCookie.mock.calls[0][1].secure).toBe(true);
    });
});

describe('createLoggedCookie', () => {
    it('sets a readable isAuth hint rather than a credential', () => {
        const response = makeResponse();

        createLoggedCookie(response, RefreshTokenExpiryTime.SHORT);

        const [name, value, options] = response.cookie.mock.calls[0];
        expect(name).toBe('isAuth');
        expect(value).toBe('true');
        // Deliberately NOT httpOnly: the frontend has to read it. Asserted explicitly so the
        // two cookies can never be "hardened" into each other's role by mistake.
        expect(options.httpOnly).toBeUndefined();
        expect(options.sameSite).toBe('lax');
        expect(options.path).toBe('/');
    });

    it('expires in step with the refresh cookie it describes', () => {
        const response = makeResponse();

        createLoggedCookie(response, RefreshTokenExpiryTime.SHORT);

        // If the hint outlived the credential the UI would show a logged-in state for a session
        // the API has already stopped honouring.
        expect(response.cookie.mock.calls[0][2].maxAge).toBe(3_600_000);
    });
});

describe('destroyLoggedCookie', () => {
    it('clears isAuth on the same path it was set', () => {
        const response = makeResponse();

        destroyLoggedCookie(response);

        expect(response.clearCookie).toHaveBeenCalledWith('isAuth', { path: '/' });
    });
});

tests/unit/infrastructure/adapters/pdf.t.source:
/**
 * The HTML → PDF adapter.
 *
 * This was one of two honest zeros in the mutation report: a suite could reach it and
 * none did. What it holds is not rendering — that is Chromium's — but four decisions that are only
 * observable from outside:
 *
 *   - the browser binary is resolved at CALL time, so an environment set after import still counts;
 *   - the two `--no-sandbox` flags, which are a deliberate risk accepted for our own templates;
 *   - `networkidle0`, without which referenced assets print as blanks;
 *   - `finally`, which closes the browser even when the render throws. That one is the reason this
 *     file is worth testing at all: a leaked Chromium per failed invoice exhausts the container.
 *
 * `puppeteer-core` is mocked, so no browser is launched and none needs to be installed.
 */
const pdfBuffer = new Uint8Array([37, 80, 68, 70]);

const pdf = jest.fn((_options?: unknown) => Promise.resolve(pdfBuffer));
const setContent = jest.fn((_html?: string, _options?: unknown) => Promise.resolve());
const close = jest.fn(() => Promise.resolve());
const newPage = jest.fn(() => Promise.resolve({ setContent, pdf }));
const launch = jest.fn((_options?: unknown) => Promise.resolve({ newPage, close }));

jest.mock('puppeteer-core', () => ({
    __esModule: true,
    default: {
        launch: (options: unknown) => launch(options)
    }
}));

import { renderHtmlToPdf } from '@infrastructure/adapters/pdf';

/** The options object handed to the last `puppeteer.launch` call. */
const lastLaunchOptions = () =>
    launch.mock.calls.at(-1)?.[0] as { executablePath: string; args: string[] };

describe('renderHtmlToPdf', () => {
    const previousExecutablePath = process.env.PUPPETEER_EXECUTABLE_PATH;

    afterEach(() => {
        if (previousExecutablePath === undefined) delete process.env.PUPPETEER_EXECUTABLE_PATH;
        else process.env.PUPPETEER_EXECUTABLE_PATH = previousExecutablePath;
    });

    describe('the browser it launches', () => {
        it('reads PUPPETEER_EXECUTABLE_PATH at call time, not at import time', async () => {
            process.env.PUPPETEER_EXECUTABLE_PATH = '/opt/chrome/chrome';

            await renderHtmlToPdf('<p>hello</p>');

            expect(lastLaunchOptions().executablePath).toBe('/opt/chrome/chrome');
        });

        it('falls back to the distribution package path when the variable is unset', async () => {
            delete process.env.PUPPETEER_EXECUTABLE_PATH;

            await renderHtmlToPdf('<p>hello</p>');

            // puppeteer-core ships no browser of its own, so an absent path is not "use the default"
            expect(lastLaunchOptions().executablePath).toBe('/usr/bin/chromium-browser');
        });

        it('disables both Chromium sandboxes, which containers cannot grant', async () => {
            await renderHtmlToPdf('<p>hello</p>');

            expect(lastLaunchOptions().args).toEqual(['--no-sandbox', '--disable-setuid-sandbox']);
        });
    });

    describe('the render', () => {
        it('writes the HTML into the page rather than navigating to a url', async () => {
            await renderHtmlToPdf('<h1>Invoice</h1>');

            expect(setContent).toHaveBeenCalledWith('<h1>Invoice</h1>', {
                waitUntil: 'networkidle0'
            });
        });

        it('waits for the network to fall idle, so referenced assets are loaded before printing', async () => {
            await renderHtmlToPdf('<img src="https://cdn.example.com/logo.png" />');

            expect(setContent.mock.calls.at(-1)?.[1]).toEqual({ waitUntil: 'networkidle0' });
        });

        it('defaults to A4 portrait', async () => {
            await renderHtmlToPdf('<p>hello</p>');

            expect(pdf).toHaveBeenCalledWith({ format: 'A4' });
        });

        it('passes a caller-supplied page geometry through instead', async () => {
            await renderHtmlToPdf('<p>hello</p>', { format: 'Letter', landscape: true });

            expect(pdf).toHaveBeenCalledWith({ format: 'Letter', landscape: true });
        });

        it('resolves with the bytes, so the caller decides whether to stream, attach or store', async () => {
            await expect(renderHtmlToPdf('<p>hello</p>')).resolves.toBe(pdfBuffer);
        });

        it('opens one isolated page per call, so concurrent renders cannot see each other', async () => {
            await Promise.all([renderHtmlToPdf('<p>one</p>'), renderHtmlToPdf('<p>two</p>')]);

            expect(launch).toHaveBeenCalledTimes(2);
            expect(newPage).toHaveBeenCalledTimes(2);
        });
    });

    describe('teardown', () => {
        it('closes the browser after a successful render', async () => {
            await renderHtmlToPdf('<p>hello</p>');

            expect(close).toHaveBeenCalledTimes(1);
        });

        it('closes the browser when the page fails to open', async () => {
            newPage.mockRejectedValueOnce(new Error('no tab'));

            await expect(renderHtmlToPdf('<p>hello</p>')).rejects.toThrow('no tab');
            expect(close).toHaveBeenCalledTimes(1);
        });

        it('closes the browser when the HTML fails to load', async () => {
            setContent.mockRejectedValueOnce(new Error('bad html'));

            await expect(renderHtmlToPdf('<p>hello</p>')).rejects.toThrow('bad html');
            expect(close).toHaveBeenCalledTimes(1);
        });

        it('closes the browser when printing fails', async () => {
            pdf.mockRejectedValueOnce(new Error('print failed'));

            await expect(renderHtmlToPdf('<p>hello</p>')).rejects.toThrow('print failed');
            // Without the `finally`, a repeatedly failing invoice leaks one Chromium per attempt
            expect(close).toHaveBeenCalledTimes(1);
        });

        it('reports the close failure when the render failed too', async () => {
            pdf.mockRejectedValueOnce(new Error('print failed'));
            close.mockRejectedValueOnce(new Error('close failed'));

            // `finally` rejecting replaces the original reason: a browser that will not close is
            // the more serious of the two, and the render error is already lost to the caller
            await expect(renderHtmlToPdf('<p>hello</p>')).rejects.toThrow('close failed');
        });
    });
});

tests/unit/infrastructure/adapters/maile.source:
/**
 * Guards the email template path.
 *
 * A wrong `EMAIL_TEMPLATES_DIR` breaks every templated email and nothing else — no type catches
 * it, and a suite that mocks the filesystem away cannot see it either. So this asserts the path
 * points at real files, and renders them.
 */
import { existsSync, readdirSync } from 'node:fs';
import path from 'node:path';
import ejs from 'ejs';
import type { EmailContent } from '@infrastructure/adapters/mailer';
import { emailTemplatesDirectory } from '@infrastructure/adapters/mailer';
import { listSupportedLocales } from '@infrastructure/i18n';
import {
    registrationConfirmEmail,
    verifyRequestEmail,
    resetRequestEmail,
    resetConfirmEmail,
    deleteRequestEmail,
    deleteConfirmEmail
} from '@modules/account/emails';
import { contactRequestEmail } from '@modules/feedback/emails';
import { orderConfirmEmail, invoiceDocument } from '@modules/orders/emails';
import { shipmentShippedEmail } from '@modules/delivery/emails';

describe('email templates', () => {
    it('resolves to a directory that exists', () => {
        expect(existsSync(emailTemplatesDirectory())).toBe(true);
    });

    it('contains at least one .ejs template', () => {
        const templates = readdirSync(emailTemplatesDirectory()).filter((f) => f.endsWith('.ejs'));
        expect(templates.length).toBeGreaterThan(0);
    });

    it.each([
        'account.registration-confirm.ejs',
        'orders.order-confirm.ejs',
        'account.delete-confirm.ejs',
        'account.delete-request.ejs',
        'feedback.contact.ejs'
    ])('resolves %s to a real file', (template) => {
        expect(existsSync(path.resolve(emailTemplatesDirectory(), template))).toBe(true);
    });
});

/**
 * Every template, rendered for real, in every supported locale — through the builder that owns
 * its copy.
 *
 * A missing key is invisible until an email lands in someone's inbox: i18next returns the key
 * itself, which is a perfectly valid string, so nothing throws and nothing logs. Rendering each
 * template against each dictionary and asserting no dotted identifier survives is the only place
 * that shows up before delivery.
 *
 * Since templates stopped translating, the keys live in each module's `emails.ts` — so that is
 * what this drives. `CONTENT` maps every template to the builder that fills it, and the first
 * test below asserts the map covers the directory, which is what keeps a new template from
 * arriving with no locale coverage.
 *
 * Rendering goes through EJS directly rather than `nodemailer`, so no SMTP transport is involved —
 * this is about the copy, not the delivery.
 */
/**
 * Every template, against the builder that fills it, all asked for the same language.
 *
 * No locale scope anywhere: the builders take the language as an argument and the render takes
 * nothing but their output, which is exactly the production sequence.
 */
const contentFor = (locale: string): Record<string, EmailContent> => ({
    'account.registration-confirm.ejs': registrationConfirmEmail(locale, 'Ada'),
    'account.verify-request.ejs': verifyRequestEmail(locale, 'Ada', 'a-token'),
    'account.reset-request.ejs': resetRequestEmail(locale, 'Ada', 'a-token'),
    'account.reset-confirm.ejs': resetConfirmEmail(locale, 'Ada'),
    'account.delete-request.ejs': deleteRequestEmail(locale, 'Ada', 'a-token'),
    'account.delete-confirm.ejs': deleteConfirmEmail(locale, 'Ada'),
    'orders.order-confirm.ejs': orderConfirmEmail(locale, 'Ada', {
        items: [
            { quantity: 2, product: { title: 'Boiled sweets', price: 3.5 } },
            { quantity: 1, product: { title: 'A whole ham', price: 42 } }
        ]
    }),
    'delivery.shipment-shipped.ejs': shipmentShippedEmail(locale, 'Ada', 'TRK-0000TEST'),
    'feedback.contact.ejs': contactRequestEmail(locale, {
        name: 'Ada',
        email: 'ada@example.com',
        subject: 'A subject',
        message: 'A message',
        createdAt: '2026-08-06T00:00:00.000Z'
    })
});

describe('email templates render in every supported locale', () => {
    const templates = readdirSync(emailTemplatesDirectory()).filter((file) =>
        file.endsWith('.ejs')
    );

    const render = (template: string, locale: string) =>
        ejs.renderFile(
            path.resolve(emailTemplatesDirectory(), template),
            contentFor(locale)[template].data
        );

    it('has copy registered for every template in the directory', () => {
        expect(Object.keys(contentFor('en')).toSorted()).toEqual(templates.toSorted());
    });

    const cases = listSupportedLocales().flatMap((locale) =>
        templates.map((template) => [template, locale] as const)
    );

    it.each(cases)('renders %s in %s with no unresolved keys', async (template, locale) => {
        const html = await render(template, locale);

        expect(html).toContain(`<html lang="${locale}"`);
        // A raw i18next key is a dotted identifier with no spaces — the shape a missing
        // translation leaves behind.
        expect(html).not.toMatch(/>[^<>]*\b[a-z]+(?:\.[\da-z-]+){2,}\b[^<>]*</);
    });

    /**
     * The invoice PDF lives outside `templates-emails` but is the same kind of artefact — a
     * document a customer reads — so it is held to the same translation rule.
     */
    it.each(listSupportedLocales())('renders the invoice document in %s', async (locale) => {
        const html = await ejs.renderFile(
            path.resolve('shared', 'views', 'templates-files', 'orders.invoice.ejs'),
            invoiceDocument(locale, {
                id: 'an-order-id',
                items: [{ product: { title: 'A product', price: 10 }, quantity: 2 }]
            })
        );

        expect(html).toContain(`<html lang="${locale}"`);
        expect(html).not.toMatch(/>[^<>]*\b[a-z]+(?:\.[\da-z-]+){2,}\b[^<>]*</);
    });

    it('produces different copy per locale, so the dictionaries are actually consulted', async () => {
        const [english, italian] = await Promise.all([
            render('account.registration-confirm.ejs', 'en'),
            render('account.registration-confirm.ejs', 'it')
        ]);

        expect(english).not.toBe(italian);
    });
});

src/modules/orders/tests/unit/money.prop.source:
/**
 * Property-based tests — `src/modules/orders/domain/money.ts`.
 *
 * `Money` claims that no monetary arithmetic here can produce `NaN`, `Infinity` or a fraction of a
 * cent. That is a statement about EVERY input, so the arbitraries are hostile rather than realistic.
 *
 * Seeded, so a failure reproduces. Any counterexample found gets written back as an ordinary
 * `it()`: the property states the rule, the example remembers the bug.
 *
 * See `docs/theory/tactical-ddd.md` §3.
 */
import fc from 'fast-check';
import {
    addMoney,
    NO_MONEY,
    scaleMoney,
    toDecimalAmount,
    toMinorUnits,
    wholeCount
} from '../../domain/money';

/** One seed for the file, and one place to change it. */
const RUN = { seed: 20_260_819, numRuns: 300, endOnFailure: true } as const;

/** Anything a malformed document, a failed populate or a hostile client can put where a price goes. */
const anything = () =>
    fc.oneof(
        fc.double(),
        fc.integer(),
        fc.string(),
        fc.boolean(),
        fc.constantFrom(null, undefined, Number.MAX_VALUE, -Number.MAX_VALUE, '1e400')
    );

/** A plausible catalogue price, in decimals — the realistic half of the input space. */
const realisticPrice = () => fc.double({ noNaN: true, noDefaultInfinity: true, min: 0, max: 1e6 });

describe('toMinorUnits — totality', () => {
    it('returns a finite whole number for any input at all', () => {
        // Every other function takes its input from this one.
        fc.assert(
            fc.property(anything(), (value) => {
                const amount = toMinorUnits(value);

                expect(Number.isFinite(amount)).toBe(true);
                expect(Number.isInteger(amount)).toBe(true);
            }),
            RUN
        );
    });

    it('treats junk as nothing owed rather than as a number to argue with', () => {
        for (const junk of [undefined, null, 'free', {}, [], Number.NaN, Infinity, -Infinity])
            expect(toMinorUnits(junk)).toBe(NO_MONEY);
    });

    it('drops an amount whose minor units overflow, rather than carrying an Infinity', () => {
        // `Number.MAX_VALUE` is finite; a hundred times it is not. Checking the input alone misses it.
        expect(toMinorUnits(Number.MAX_VALUE)).toBe(NO_MONEY);
        expect(toMinorUnits(-Number.MAX_VALUE)).toBe(NO_MONEY);
    });
});

describe('toMinorUnits ↔ toDecimalAmount', () => {
    it('round-trips a realistic price to the cent', () => {
        fc.assert(
            fc.property(realisticPrice(), (price) => {
                const returned = toDecimalAmount(toMinorUnits(price));

                expect(Math.abs(returned - price)).toBeLessThanOrEqual(0.005 + 1e-9);
            }),
            RUN
        );
    });

    it('never returns more than two decimal places', () => {
        // Drift here reaches the wire as a price no invoice can add up.
        fc.assert(
            fc.property(anything(), (value) => {
                const returned = toDecimalAmount(toMinorUnits(value));

                expect(Math.abs(Math.round(returned * 100) - returned * 100)).toBeLessThan(1e-6);
            }),
            RUN
        );
    });

    it('is idempotent through a round trip', () => {
        fc.assert(
            fc.property(realisticPrice(), (price) => {
                const once = toDecimalAmount(toMinorUnits(price));

                expect(toDecimalAmount(toMinorUnits(once))).toBe(once);
            }),
            RUN
        );
    });
});

describe('addMoney', () => {
    it('is exact, associative and order-independent', () => {
        // The reason the type exists — float addition is none of these three.
        fc.assert(
            fc.property(fc.array(realisticPrice(), { maxLength: 30 }), (prices) => {
                const amounts = prices.map((price) => toMinorUnits(price));
                const forwards = addMoney(...amounts);

                expect(addMoney(...amounts.toReversed())).toBe(forwards);
                expect(addMoney(addMoney(...amounts), NO_MONEY)).toBe(forwards);
            }),
            RUN
        );
    });

    it('folds an empty list to nothing owed', () => {
        expect(addMoney()).toBe(NO_MONEY);
    });

    it('stays finite however hostile the terms', () => {
        fc.assert(
            fc.property(fc.array(anything(), { maxLength: 30 }), (values) => {
                expect(Number.isFinite(addMoney(...values.map((v) => toMinorUnits(v))))).toBe(true);
            }),
            RUN
        );
    });
});

describe('scaleMoney', () => {
    it('agrees with repeated addition', () => {
        // Catches a `+` where a `*` belongs; quantity 1 cannot distinguish them.
        fc.assert(
            fc.property(realisticPrice(), fc.integer({ min: 0, max: 50 }), (price, count) => {
                const unit = toMinorUnits(price);

                expect(scaleMoney(unit, count)).toBe(
                    addMoney(...Array.from({ length: count }, () => unit))
                );
            }),
            RUN
        );
    });

    it('charges nothing for a line of nothing', () => {
        fc.assert(
            fc.property(anything(), (value) => {
                expect(scaleMoney(toMinorUnits(value), 0)).toBe(NO_MONEY);
            }),
            RUN
        );
    });

    it('stays finite for any count at all', () => {
        fc.assert(
            fc.property(anything(), anything(), (price, count) => {
                expect(Number.isFinite(scaleMoney(toMinorUnits(price), count))).toBe(true);
            }),
            RUN
        );
    });
});

describe('wholeCount', () => {
    it('returns a finite whole number for any input at all', () => {
        fc.assert(
            fc.property(anything(), (value) => {
                expect(Number.isInteger(wholeCount(value))).toBe(true);
            }),
            RUN
        );
    });

    it('leaves a genuine count alone', () => {
        fc.assert(
            fc.property(fc.integer({ min: 0, max: 10_000 }), (count) => {
                expect(wholeCount(count)).toBe(count);
            }),
            RUN
        );
    });
});

tests/unit/infrastructure/adapters/maile.source:
/**
 * The SMTP transport configuration in `src/infrastructure/adapters/mailer.ts`.
 *
 * This is module-scope config, built once at import time from the environment, and the whole
 * production branch was unreachable from the test suite: `NODE_ENV === 'test'` selects the
 * `jsonTransport` branch, so nothing ever looked at the other one.
 *
 * It is worth looking at, because one line of it is a security decision rather than a setting:
 *
 *     secure: process.env.NODE_SMTP_PORT === '465'
 *
 * `secure: true` means TLS from the first byte, which is only correct on 465. On 587 the
 * connection MUST start plaintext and upgrade via STARTTLS, so `secure` has to be false there.
 * Get it backwards and you either cannot connect at all (true on 587) or you hand SMTP AUTH
 * credentials to a server over a channel you assumed was encrypted and is not (false on 465).
 *
 * `createTransport` is mocked so the options object can be inspected without opening a socket.
 */
const createTransportMock = jest.fn((_options?: unknown) => ({ sendMail: jest.fn() }));
jest.mock('nodemailer', () => ({
    createTransport: (options: unknown) => createTransportMock(options)
}));

import { nodemailer, resetTransporter } from '@infrastructure/adapters/mailer';

/**
 * The options the module handed to `createTransport` for a given environment.
 *
 * The transport is built on first use and memoised, so varying its configuration is `reset` plus
 * a send — not `jest.resetModules()` and a dynamic `import()`. That dance was only ever a way to
 * re-run module-scope code, and there is no module-scope code left to re-run.
 */
const transportOptions = async (
    environment: Record<string, string | undefined>
): Promise<Record<string, unknown>> => {
    createTransportMock.mockClear();
    resetTransporter();

    const previous: Record<string, string | undefined> = {};
    for (const [key, value] of Object.entries(environment)) {
        previous[key] = process.env[key];
        if (value === undefined) delete process.env[key];
        else process.env[key] = value;
    }

    // Any send builds the transport; the envelope itself is irrelevant here.
    await nodemailer({ to: 'ada@example.com' }, 'orders.order-confirm', {
        locale: 'en',
        pageMetaTitle: '',
        pageMetaLinks: [],
        greeting: '',
        body: '',
        lines: [],
        total: '',
        footer: ''
    }).catch(() => {});

    for (const [key, value] of Object.entries(previous)) {
        if (value === undefined) delete process.env[key];
        else process.env[key] = value;
    }

    return createTransportMock.mock.calls[0][0] as Record<string, unknown>;
};

const SMTP_ENVIRONMENT = {
    NODE_ENV: 'production',
    NODE_SMTP_HOST: 'smtp.example.com'
};

describe('the test environment uses a transport that sends nothing', () => {
    it('selects jsonTransport under NODE_ENV=test', async () => {
        // The guarantee that a stray test cannot email a real person. Losing this is not a
        // failing test, it is mail leaving the building.
        const options = await transportOptions({ NODE_ENV: 'test' });

        expect(options).toEqual({ jsonTransport: true });
    });
});

describe('TLS mode follows the port, which is a security decision', () => {
    it('uses implicit TLS on 465', async () => {
        const options = await transportOptions({
            ...SMTP_ENVIRONMENT,
            NODE_SMTP_PORT: '465'
        });

        expect(options.port).toBe(465);
        expect(options.secure).toBe(true);
    });

    it('does NOT use implicit TLS on 587, where the connection is upgraded instead', async () => {
        // `secure: true` here means the client speaks TLS to a server expecting plaintext, and
        // the connection simply fails. The inverse mistake is the dangerous one — see below.
        const options = await transportOptions({
            ...SMTP_ENVIRONMENT,
            NODE_SMTP_PORT: '587'
        });

        expect(options.port).toBe(587);
        expect(options.secure).toBe(false);
    });

    it('does not use implicit TLS on any other port', async () => {
        const options = await transportOptions({
            ...SMTP_ENVIRONMENT,
            NODE_SMTP_PORT: '25'
        });

        expect(options.secure).toBe(false);
    });

    it('defaults to 587 with implicit TLS off when no port is configured', async () => {
        // The safe default: submission with STARTTLS is the modern convention, and defaulting to
        // 465 instead would silently break every deployment that did not set the variable.
        const options = await transportOptions({
            ...SMTP_ENVIRONMENT,
            NODE_SMTP_PORT: undefined
        });

        expect(options.port).toBe(587);
        expect(options.secure).toBe(false);
    });
});

describe('credentials and identity', () => {
    it('passes the configured SMTP credentials through', async () => {
        const options = await transportOptions({
            ...SMTP_ENVIRONMENT,
            NODE_SMTP_USER: 'mailer',
            NODE_SMTP_PASS: 'hunter2'
        });

        expect(options.auth).toEqual({ user: 'mailer', pass: 'hunter2' });
    });

    it('falls back to empty credentials rather than undefined', async () => {
        // Deliberate: email is not a hard startup dependency, so an unconfigured mailer must not
        // stop the process from booting. The failure surfaces at send time instead, which is
        // where someone can act on it.
        const options = await transportOptions({
            ...SMTP_ENVIRONMENT,
            NODE_SMTP_USER: undefined,
            NODE_SMTP_PASS: undefined
        });

        expect(options.auth).toEqual({ user: '', pass: '' });
    });

    it('announces the configured EHLO name, empty when unset', async () => {
        // Some strict servers check it; an undefined here would be sent as the string
        // "undefined" rather than omitted.
        const options = await transportOptions({
            ...SMTP_ENVIRONMENT,
            NODE_SMTP_NAME: undefined
        });

        expect(options.name).toBe('');
    });
});

