import {
    addRegexFilter,
    addTextFilter,
    escapeRegex,
    toSearchPattern
} from '@infrastructure/persistence/search';

/**
 * Client text reaches MongoDB's `$regex`, and MongoDB evaluates the pattern server-side against
 * every candidate document. Unescaped, that is a remote denial of service on a PUBLIC endpoint:
 * `POST /products/search` and `GET /products?text=` need no token, and a catastrophic
 * backtracking pattern costs seconds of CPU per document from a handful of characters.
 *
 * It is also a correctness fix. `.` matches everything, `^` anchors, and a lone `(` is a syntax
 * error the driver raises as a 500 — so someone searching for "50% (off)" got an error rather
 * than products.
 */

/** Every metacharacter that changes how a pattern is interpreted. */
const METACHARACTERS = ['.', '*', '+', '?', '^', '$', '(', ')', '[', ']', '{', '}', '|', '\\'];

describe('escapeRegex', () => {
    it.each(METACHARACTERS)('escapes %s so it matches itself', (character) => {
        const escaped = escapeRegex(character);

        expect(new RegExp(escaped).test(character)).toBe(true);
    });

    it('leaves ordinary text untouched', () => {
        expect(escapeRegex('blue running shoes')).toBe('blue running shoes');
    });

    /**
     * The exploit, defused. Asserted structurally rather than by stopwatch: every metacharacter
     * in `(a+)+$` comes back escaped, which is precisely what leaves the engine nothing to
     * backtrack over. A wall-clock threshold would assert the same property by proxy and fail on
     * a loaded CI runner for reasons that have nothing to do with the code.
     */
    it('renders a catastrophic backtracking pattern harmless', () => {
        const evil = '(a+)+$';

        // Nothing left that the engine reads as a group, a quantifier or an anchor.
        expect(escapeRegex(evil)).toBe(String.raw`\(a\+\)\+\$`);
        expect(new RegExp(escapeRegex(evil)).test('a'.repeat(40) + '!')).toBe(false);
        // It still matches the one string it should: the literal text itself.
        expect(new RegExp(escapeRegex(evil)).test(`x${evil}y`)).toBe(true);
    });

    it('produces a pattern that matches the literal text a user typed', () => {
        expect(new RegExp(escapeRegex('50% (off)')).test('sale: 50% (off) today')).toBe(true);
        expect(new RegExp(escapeRegex('1.5')).test('1x5')).toBe(false);
    });

    /*
     * The cases above are the named, memorable ones: a specific metacharacter, a specific
     * expectation. The general claim — "escapes whatever it is given" — belongs in
     * `search.property.test.ts`, where it is generated over arbitrary input rather than sampled
     * over a handful of strings someone thought of. Hand-picked examples cannot support a claim
     * quantified over all inputs; they only illustrate it.
     */
});

describe('the filters that reach MongoDB', () => {
    it('escapes the text filter across every field', () => {
        const where: Record<string, unknown> = {};

        addTextFilter(where, '(a+)+$', ['title', 'description']);

        for (const clause of where.$or as Record<string, { $regex: string }>[])
            expect(Object.values(clause)[0].$regex).not.toBe('(a+)+$');
    });

    it('escapes a single-field filter', () => {
        const where: Record<string, unknown> = {};

        addRegexFilter(where, 'email', '.*');

        expect((where.email as { $regex: string }).$regex).toBe(String.raw`\.\*`);
    });

    it.each([undefined, null, '', '   '])('adds nothing for %p', (value) => {
        const where: Record<string, unknown> = {};

        addTextFilter(where, value, ['title']);
        addRegexFilter(where, 'email', value);

        expect(where).toEqual({});
    });
});

/**
 * A NUL reaching `$regex` was a **500 on a public endpoint**, found by `test:fuzz` with a rolled
 * seed (`RANDOM_DATA_SEED=108919307`) and reproduced on `tag`, `category` and `text` alike.
 *
 * MongoDB compiles the pattern as a C string, so it rejects one containing a NUL — and
 * `escapeRegex` never covered it, correctly: escaping is about metacharacters, and a NUL is not a
 * metacharacter but a byte the pattern language cannot hold at all. That is why the strip is a
 * separate step rather than another entry in the escape list.
 */
describe('control characters', () => {
    const NUL = String.fromCodePoint(0);

    it('strips a NUL but keeps the search the caller meant', () => {
        // The realistic shape: an injected NUL alongside real text. Dropping the whole term would
        // turn a valid search into "everything"; keeping the NUL is the 500.
        expect(toSearchPattern(`shoes${NUL}`)).toBe('shoes');
        expect(toSearchPattern(`${NUL}blue${NUL}shoes`)).toBe('blueshoes');
    });

    it.each([
        ['NUL', String.fromCodePoint(0)],
        ['bell', String.fromCodePoint(7)],
        ['backspace', String.fromCodePoint(8)],
        ['escape', String.fromCodePoint(27)],
        ['DEL', String.fromCodePoint(127)]
    ])('treats a term that is only %s as blank rather than as a match-all', (_name, character) => {
        // `undefined`, not `''`. `$regex: ''` matches every document, so returning an empty
        // pattern would invert the filter instead of dropping it.
        expect(toSearchPattern(character)).toBeUndefined();
    });

    it('drops the filter entirely, on all three paths that build a pattern', () => {
        const where: Record<string, unknown> = {};

        addTextFilter(where, NUL, ['title', 'description']);
        addRegexFilter(where, 'email', NUL);

        // Not "a filter matching nothing" and not "a filter matching everything" — no filter.
        expect(where).toEqual({});
    });

    it('still escapes metacharacters that survive the strip', () => {
        // The two steps compose: strip what cannot be held, escape what would be interpreted.
        expect(toSearchPattern(`(a+)+$${NUL}`)).toBe(String.raw`\(a\+\)\+\$`);
    });
});

src/modules/account/tests/unit/tokens.te.source:
/**
 * Token configuration — `src/modules/account/tokens.ts`.
 *
 * This module is pure env-var parsing, and every value it returns ends up controlling either a
 * JWT lifetime or a signing secret. That makes it worth pinning precisely: a tier that silently
 * reads the wrong variable produces sessions that are too long (a security problem) or too short
 * (a support problem), and neither shows up as a failing request anywhere else.
 *
 * Assertions are derived from the module's documented contract, not from re-reading its body:
 *   - each tier reads *its own* env var (the TOKEN_EXPIRY_ENV map),
 *   - no tier given falls back to NODE_TOKEN_ACCESS_TIME,
 *   - "seconds as integer, 0 if env var is unset",
 *   - the millisecond helper is exactly the second helper × 1000,
 *   - secrets fall back to '' rather than `undefined`.
 */

import {
    RefreshTokenExpiryTime,
    getExpiryTime,
    getExpiryTimeMilliseconds,
    getAccessTokenSecret,
    getRefreshTokenSecret,
    getAccessTokenTTL
} from '@modules/account/session/config';

/**
 * Every env var this module reads. Cleared before each test so a value leaking in from the
 * ambient environment (or from `tests/support/setup.ts`) can never make an assertion pass.
 */
const TOKEN_ENV_KEYS = [
    'NODE_TOKEN_REFRESH_TIME_SHORT',
    'NODE_TOKEN_REFRESH_TIME_MEDIUM',
    'NODE_TOKEN_REFRESH_TIME_LONG',
    'NODE_TOKEN_ACCESS_TIME',
    'NODE_TOKEN_ACCESS',
    'NODE_TOKEN_REFRESH'
] as const;

const originalEnvironment: Record<string, string | undefined> = {};

beforeEach(() => {
    for (const key of TOKEN_ENV_KEYS) {
        originalEnvironment[key] = process.env[key];
        delete process.env[key];
    }
});

afterEach(() => {
    for (const key of TOKEN_ENV_KEYS) {
        if (originalEnvironment[key] === undefined) delete process.env[key];
        else process.env[key] = originalEnvironment[key];
    }
});

describe('getExpiryTime', () => {
    it('reads a distinct env var per tier', () => {
        // Distinct values on purpose: if two tiers were wired to the same variable, or two
        // entries of the map were swapped, identical values would hide it.
        process.env.NODE_TOKEN_REFRESH_TIME_SHORT = '3600';
        process.env.NODE_TOKEN_REFRESH_TIME_MEDIUM = '86400';
        process.env.NODE_TOKEN_REFRESH_TIME_LONG = '2592000';

        expect(getExpiryTime(RefreshTokenExpiryTime.SHORT)).toBe(3600);
        expect(getExpiryTime(RefreshTokenExpiryTime.MEDIUM)).toBe(86_400);
        expect(getExpiryTime(RefreshTokenExpiryTime.LONG)).toBe(2_592_000);
    });

    it('falls back to the access-token variable when no tier is given', () => {
        process.env.NODE_TOKEN_ACCESS_TIME = '900';
        // Set the tiers too: the no-arg call must ignore them entirely.
        process.env.NODE_TOKEN_REFRESH_TIME_SHORT = '3600';

        expect(getExpiryTime()).toBe(900);
    });

    it('returns 0 when the variable is unset', () => {
        expect(getExpiryTime()).toBe(0);
        expect(getExpiryTime(RefreshTokenExpiryTime.LONG)).toBe(0);
    });

    it('returns 0 for an empty variable rather than NaN', () => {
        // `Number.parseInt('')` is NaN, which would flow into `expiresIn` and produce a token
        // jsonwebtoken rejects. The documented answer for "no usable value" is 0.
        process.env.NODE_TOKEN_ACCESS_TIME = '';

        expect(getExpiryTime()).toBe(0);
    });

    it('parses in base 10, so a zero-padded value is not read as octal', () => {
        process.env.NODE_TOKEN_ACCESS_TIME = '0900';

        expect(getExpiryTime()).toBe(900);
    });
});

describe('getExpiryTimeMilliseconds', () => {
    it('is the seconds value scaled by exactly 1000', () => {
        process.env.NODE_TOKEN_REFRESH_TIME_MEDIUM = '86400';

        expect(getExpiryTimeMilliseconds(RefreshTokenExpiryTime.MEDIUM)).toBe(86_400_000);
    });

    it('honours the same tier routing as getExpiryTime', () => {
        process.env.NODE_TOKEN_REFRESH_TIME_SHORT = '60';
        process.env.NODE_TOKEN_ACCESS_TIME = '900';

        expect(getExpiryTimeMilliseconds(RefreshTokenExpiryTime.SHORT)).toBe(60_000);
        expect(getExpiryTimeMilliseconds()).toBe(900_000);
    });

    it('stays 0 (not NaN) when the variable is unset', () => {
        // A NaN maxAge on a cookie is silently dropped by Express, producing a session cookie
        // instead of the intended persistent one — a bug with no error attached to it.
        expect(getExpiryTimeMilliseconds()).toBe(0);
    });
});

describe('token secrets', () => {
    it('returns the configured access and refresh secrets from separate variables', () => {
        process.env.NODE_TOKEN_ACCESS = 'access-secret';
        process.env.NODE_TOKEN_REFRESH = 'refresh-secret';

        expect(getAccessTokenSecret()).toBe('access-secret');
        expect(getRefreshTokenSecret()).toBe('refresh-secret');
    });

    it('falls back to an empty string when unset', () => {
        // `jsonwebtoken` throws on an `undefined` secret but accepts ''. Neither is good, but ''
        // is the documented shape and keeps the failure inside the signing call.
        expect(getAccessTokenSecret()).toBe('');
        expect(getRefreshTokenSecret()).toBe('');
    });
});

describe('getAccessTokenTTL', () => {
    it('reads NODE_TOKEN_ACCESS_TIME', () => {
        process.env.NODE_TOKEN_ACCESS_TIME = '900';

        expect(getAccessTokenTTL()).toBe(900);
    });

    it('returns 0 when unset', () => {
        expect(getAccessTokenTTL()).toBe(0);
    });

    it('does not read any refresh tier variable', () => {
        // Guards the access/refresh split: an access token inheriting a 30-day refresh TTL is
        // exactly the mistake this separation exists to prevent.
        process.env.NODE_TOKEN_REFRESH_TIME_LONG = '2592000';

        expect(getAccessTokenTTL()).toBe(0);
    });
});

tests/unit/infrastructure/http/middlewar.source:
/**
 * One connection needs one `connect()`.
 *
 * This is the fast guard on the bug `tests/cluster/rate-limit.test.ts` found: with a `connect()`
 * per command, two commands issued before the handshake finishes both try to open the same socket.
 * `isReady` stays false for the whole handshake, so both see it as false; node-redis rejects the
 * second with `Socket already opened`, and that failure path discards the client the FIRST one is
 * still using, which then fails with `The client is closed`.
 *
 * The interleaving is not rare — it is guaranteed. `RedisStore.init()` loads two Lua scripts back
 * to back, so the pair raced on the very first request of every worker, every request afterwards
 * passed unbudgeted, and the log reported Redis as unreachable while Redis was answering fine. A
 * rate limiter that is off is a security control that is off.
 *
 * ── Why this exists as well as the cluster suite ──────────────────────────────────────────────
 * The cluster suite proves the whole property — one budget spent across real forked workers — and
 * costs 25 seconds and a container, so it runs in `complete:manual` and in CI rather than in
 * `npm test`. That left the fix itself unguarded in the gate a contributor actually runs. This
 * file closes exactly that: no cluster, no Redis, no container, and it fails on the same
 * regression.
 */

import {
    rateLimitStore,
    stopRateLimitStore
} from '@infrastructure/http/middlewares/rate-limit-store';

/** How many times a `connect()` was asked for across the run, whatever the client instance. */
let connectCalls = 0;

/**
 * A client that behaves the way the real one does at the only moment that matters: `isReady` stays
 * false until the handshake resolves, and a second `connect()` while one is in flight throws — the
 * error node-redis raises, which is what made the original failure destructive rather than merely
 * duplicated.
 */
type FakeClient = ReturnType<typeof fakeClient>;

const fakeClient = () => {
    let ready = false;
    let opening = false;

    return {
        get isReady() {
            return ready;
        },
        connect: jest.fn(() => {
            connectCalls += 1;
            if (opening || ready) throw new Error('Socket already opened');
            opening = true;

            return new Promise((resolve) =>
                setTimeout(() => {
                    opening = false;
                    ready = true;
                    resolve(undefined);
                }, 10)
            );
        }),
        /*
         * Replies shaped the way `rate-limit-redis` insists on: `SCRIPT LOAD` must answer a string
         * sha or it throws before the connection is ever exercised, and the increment script
         * answers `[totalHits, resetMs]`.
         */
        sendCommand: jest.fn((command: string[]) =>
            Promise.resolve(command[0] === 'SCRIPT' ? 'a-fake-sha' : [1, 60_000])
        ),
        on: jest.fn(),
        destroy: jest.fn(() => {
            ready = false;
            opening = false;
        }),
        quit: jest.fn(() => Promise.resolve())
    };
};

/**
 * The seam the mock factory reads.
 *
 * `jest.mock` factories are hoisted above every `const` in the file, so the factory cannot close
 * over a module-scoped variable — it has to reach the client through something that exists at call
 * time. A property on `globalThis` is that something.
 */
const seam = globalThis as typeof globalThis & { rateLimitFakeClient?: FakeClient };

jest.mock('redis', () => ({
    createClient: jest.fn(() => (globalThis as typeof seam).rateLimitFakeClient)
}));

describe('the rate limiter’s Redis connection', () => {
    beforeEach(() => {
        connectCalls = 0;
        seam.rateLimitFakeClient = fakeClient();
        process.env.NODE_RATE_LIMIT_REDIS_ENABLED = '1';
        process.env.NODE_RATE_LIMIT_REDIS_URL = 'redis://127.0.0.1:6379';
    });

    afterEach(() => stopRateLimitStore());

    it('opens one socket for commands issued before the handshake finishes', () => {
        /*
         * The regression. Two commands, neither awaiting the other — which is what `RedisStore`
         * does with its two script loads — and exactly one `connect()`.
         */
        const store = rateLimitStore('unit');
        void store.init?.({ windowMs: 60_000 } as never);

        return Promise.all([store.increment('a'), store.increment('b')]).then(() => {
            expect(connectCalls).toBe(1);
        });
    });

    it('answers both of them rather than destroying the client one is using', () => {
        /*
         * The consequence, asserted separately: the original failure was not a duplicate connect
         * but what the duplicate's rejection did — `destroy()` on the shared client, so the command
         * that had done nothing wrong failed too and the limiter passed the request through.
         */
        const store = rateLimitStore('unit');
        void store.init?.({ windowMs: 60_000 } as never);

        return Promise.all([store.increment('a'), store.increment('b')]).then((results) => {
            expect(results).toHaveLength(2);
            expect(seam.rateLimitFakeClient?.destroy).not.toHaveBeenCalled();
        });
    });

    it('counts in memory when no Redis is configured', () => {
        // The other half of the choice, so the case above cannot pass by never reaching Redis.
        delete process.env.NODE_RATE_LIMIT_REDIS_URL;
        process.env.NODE_RATE_LIMIT_REDIS_ENABLED = '0';

        const store = rateLimitStore('unit');
        void store.init?.({ windowMs: 60_000 } as never);

        return Promise.resolve(store.increment('a')).then(() => {
            expect(connectCalls).toBe(0);
        });
    });
});

tests/unit/kernel/authorization.test.ts.source:
/**
 * The shared read-scoping rule — `src/kernel/authorization.ts`.
 *
 * Two combinators over one decision — *an admin is unrestricted, everyone else is narrowed* —
 * differing only in what the narrowing needs. `createOwnerScope` hands the caller's id to a
 * builder; `createVisibilityScope` calls one that takes nothing, because what a visitor may read
 * is a property of the row. These specs assert only the half the kernel owns, with stub builders,
 * so a failure here names the rule rather than one module's collection:
 *
 *   1. admin        → `undefined`, and the builder is never consulted.
 *   2. anyone else  → whatever the builder returns.
 *   3. no id at all → `createOwnerScope`'s builder is called with `''`, so a builder that rejects
 *                     an empty id throws. That delegation IS the fail-closed property: the
 *                     combinator must never substitute a default, skip the call, or swallow it.
 *
 * `orders/tests/unit/service-scope.test.ts` covers the composed behaviour over a real repository;
 * what is asserted here is the contract those modules are relying on.
 */

import { createOwnerScope, createVisibilityScope } from '@kernel/authorization';

const OWNED = { userId: 'scoped' };
const PUBLISHED = { active: true };

describe('createOwnerScope', () => {
    it('returns undefined for an admin, meaning no restriction', () => {
        const ownerScopeOf = jest.fn(() => OWNED);

        // Not `{}`: an empty object spreads into a filter that still matches everything, but it
        // is a different value from "no restriction" and a caller may branch on it.
        expect(createOwnerScope(ownerScopeOf)({ id: 'u1', admin: true })).toBeUndefined();
    });

    it('does not consult the scope builder at all for an admin', () => {
        const ownerScopeOf = jest.fn(() => OWNED);

        createOwnerScope(ownerScopeOf)({ id: 'u1', admin: true });

        // The builder coerces ids and can throw on a bad one. An admin must not be exposed to
        // that: their pass is the FIRST decision, not a filter computed then discarded.
        expect(ownerScopeOf).not.toHaveBeenCalled();
    });

    it("delegates to the scope builder with the caller's id", () => {
        const ownerScopeOf = jest.fn(() => OWNED);

        expect(createOwnerScope(ownerScopeOf)({ id: 'u1', admin: false })).toBe(OWNED);
        expect(ownerScopeOf).toHaveBeenCalledWith('u1');
    });

    it('treats an absent admin flag as not an admin', () => {
        const ownerScopeOf = jest.fn(() => OWNED);

        // `admin` is optional. Absent must mean "not an admin", never "unknown, so allow".
        expect(createOwnerScope(ownerScopeOf)({ id: 'u1' })).toBe(OWNED);
        expect(ownerScopeOf).toHaveBeenCalledWith('u1');
    });

    it('passes an empty id to the builder rather than skipping the restriction', () => {
        const ownerScopeOf = jest.fn(() => OWNED);

        createOwnerScope(ownerScopeOf)(undefined);

        // The load-bearing line. Returning `undefined` here — or omitting the owner clause —
        // would widen an anonymous request to every user's rows without failing anything.
        expect(ownerScopeOf).toHaveBeenCalledWith('');
    });

    it('propagates the builder throwing on an empty id', () => {
        const ownerScopeOf = jest.fn((userId: string) => {
            if (!userId) throw new Error('invalid id');
            return OWNED;
        });
        const callerScope = createOwnerScope(ownerScopeOf);

        // How the fail-closed property actually surfaces: a 500, never a disclosure.
        expect(() => callerScope(undefined)).toThrow('invalid id');
        expect(() => callerScope({ admin: false })).toThrow('invalid id');
    });

    it('builds independent scopes per repository', () => {
        // Two modules, two collections, one rule — the reason this is a factory and not a
        // function with a switch in it.
        const orders = createOwnerScope(() => ({ collection: 'orders' }));
        const payments = createOwnerScope(() => ({ collection: 'payments' }));

        expect(orders({ id: 'u1' })).toEqual({ collection: 'orders' });
        expect(payments({ id: 'u1' })).toEqual({ collection: 'payments' });
    });
});

describe('createVisibilityScope', () => {
    it('returns undefined for an admin, meaning no restriction', () => {
        const publicScopeOf = jest.fn(() => PUBLISHED);

        expect(createVisibilityScope(publicScopeOf)({ id: 'u1', admin: true })).toBeUndefined();
        expect(publicScopeOf).not.toHaveBeenCalled();
    });

    it('narrows a guest and a signed-in non-admin identically', () => {
        const publicScopeOf = jest.fn(() => PUBLISHED);
        const callerScope = createVisibilityScope(publicScopeOf);

        // The distinction the positional boolean could not express: these are two different
        // callers, and the rule says they see the same rows. A boolean makes them one input.
        expect(callerScope(undefined)).toBe(PUBLISHED);
        expect(callerScope({ id: 'u1', admin: false })).toBe(PUBLISHED);
        expect(callerScope({ id: 'u1' })).toBe(PUBLISHED);
    });

    it('never passes the caller to the builder', () => {
        const publicScopeOf = jest.fn(() => PUBLISHED);

        createVisibilityScope(publicScopeOf)({ id: 'u1', admin: false });

        // What a visitor may read is a property of the ROW. A builder that could see the caller
        // would invite an identity condition into a rule that must not have one.
        expect(publicScopeOf).toHaveBeenCalledWith();
    });
});

