/**
 * The readiness fold, with every dependency's state controlled.
 *
 * The contract suite can only assert that the payload speaks the four words, because which one each
 * dependency reports depends on the `.env` of whoever runs the suite. This is where the mapping
 * itself is pinned — including the two cases that are easy to get backwards and expensive to get
 * wrong: `disabled` must not degrade a service, and `connecting` must not read as broken.
 */

import { connection } from '@infrastructure/runtime/database';
import { cacheState } from '@infrastructure/adapters/cache';
import { queueState } from '@infrastructure/adapters/queue';
import {
    dependencyHealth,
    overallStatus,
    type DependencyHealth
} from '@infrastructure/observability/dependency-health';

jest.mock('@infrastructure/adapters/cache', () => ({ cacheState: jest.fn() }));
jest.mock('@infrastructure/adapters/queue', () => ({ queueState: jest.fn() }));

const mockedCacheState = cacheState as jest.MockedFunction<typeof cacheState>;
const mockedQueueState = queueState as jest.MockedFunction<typeof queueState>;

/** Drive `connection.readyState` without opening a database. */
const withReadyState = (state: number) => {
    Object.defineProperty(connection, 'readyState', {
        value: state,
        configurable: true
    });
};

beforeEach(() => {
    jest.clearAllMocks();
    mockedCacheState.mockReturnValue('ready');
    mockedQueueState.mockReturnValue('ready');
    withReadyState(1);
});

// ─── The reading ──────────────────────────────────────────────────────────────

describe('dependencyHealth', () => {
    it.each([
        [1, 'ready'],
        [2, 'connecting'],
        [0, 'unavailable'],
        /* Mongoose's `disconnecting`. Not `connecting`: it is on its way OUT and will not start
         * serving again, so reporting it as nearly-ready would show a shutdown as a startup. */
        [3, 'unavailable']
    ])('maps mongoose readyState %i to %s', (state, expected) => {
        withReadyState(state);

        expect(dependencyHealth().database).toBe(expected);
    });

    it('reports an unknown readyState as unavailable rather than crashing', () => {
        /* A future mongoose could add a state. Answering "unavailable" is the safe direction: it
         * degrades a healthy service, where the opposite would report a dead one as serving. */
        withReadyState(99);

        expect(dependencyHealth().database).toBe('unavailable');
    });

    it('asks each adapter for its own state rather than probing it', () => {
        mockedCacheState.mockReturnValue('disabled');
        mockedQueueState.mockReturnValue('connecting');

        expect(dependencyHealth()).toEqual({
            database: 'ready',
            cache: 'disabled',
            queue: 'connecting'
        });
    });
});

// ─── The fold ─────────────────────────────────────────────────────────────────

/** Every dependency ready, minus whatever the case under test wants broken. */
const health = (overrides: Partial<DependencyHealth> = {}): DependencyHealth => ({
    database: 'ready',
    cache: 'ready',
    queue: 'ready',
    ...overrides
});

describe('overallStatus', () => {
    it('is ok when everything is ready', () => {
        expect(overallStatus(health())).toBe('ok');
    });

    it('is ok when an optional dependency is disabled', () => {
        /* The single most important case here. A deployment without Redis or without RabbitMQ is
         * supported, not broken — reporting it as degraded would leave the field permanently red on
         * exactly the deployments that chose it, and a permanently red field is one nobody reads. */
        expect(overallStatus(health({ cache: 'disabled', queue: 'disabled' }))).toBe('ok');
    });

    it.each([['unavailable'], ['connecting']] as const)(
        'is degraded when the cache is %s',
        (state) => {
            /* The bug this whole finding was about: `status` used to read the database and nothing
             * else, so Mongo up + Redis down reported `ok` while every cache lookup missed. */
            expect(overallStatus(health({ cache: state }))).toBe('degraded');
        }
    );

    it('is degraded while the database is still connecting', () => {
        /* `connecting` is honest about not serving yet. It is a separate WORD from `unavailable` so
         * a deploy inside its start-up grace period is legible, but it is not a separate STATUS —
         * an instance that cannot answer yet must not claim it can. */
        expect(overallStatus(health({ database: 'connecting' }))).toBe('degraded');
    });

    it('is degraded when the only problem is one optional dependency', () => {
        expect(overallStatus(health({ queue: 'unavailable' }))).toBe('degraded');
    });
});

tests/unit/infrastructure/adapters/files.source:
/**
 * `moveFile` — the one filesystem operation an upload cannot survive getting wrong.
 *
 * It exists because `rename` cannot cross a device boundary, and this application crosses one by
 * default: uploads are staged in the system temp directory (frequently a tmpfs) and committed into
 * the public directory (a disk, or a mounted volume). So the EXDEV fallback is not a defensive
 * branch for an exotic host — on a normal Linux deployment it is the only branch that ever runs.
 */
import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';

let root: string;

const stage = async (name: string, contents = 'image bytes') => {
    const file = path.join(root, name);
    await writeFile(file, contents);
    return file;
};

beforeEach(async () => {
    root = await mkdtemp(path.join(tmpdir(), 'move-file-test-'));
});

afterEach(async () => {
    await rm(root, { recursive: true, force: true });
    jest.resetModules();
});

describe('moveFile', () => {
    it('moves the file, contents intact, leaving nothing behind', async () => {
        const { moveFile } = await import('@infrastructure/adapters/filesystem');
        const source = await stage('staged.png', 'the original bytes');
        const destination = path.join(root, 'committed.png');

        await moveFile(source, destination);

        expect(existsSync(source)).toBe(false);
        expect(await readFile(destination, 'utf8')).toBe('the original bytes');
    });

    it('overwrites an existing destination rather than failing', async () => {
        const { moveFile } = await import('@infrastructure/adapters/filesystem');
        const source = await stage('staged.png', 'new');
        const destination = await stage('committed.png', 'old');

        await moveFile(source, destination);

        expect(await readFile(destination, 'utf8')).toBe('new');
    });

    it('throws when the destination directory does not exist', async () => {
        const { moveFile } = await import('@infrastructure/adapters/filesystem');
        const source = await stage('staged.png');

        // Throwing is the contract: a silent failure here means the database is about to record a
        // url for bytes that are not there.
        await expect(
            moveFile(source, path.join(root, 'no-such-directory', 'committed.png'))
        ).rejects.toThrow();
    });

    /**
     * The cross-device case, forced rather than hoped for: whether the host's temp directory and
     * the repository share a filesystem is a property of the machine the suite happens to run on,
     * and this branch is too important to test only where the answer is "no".
     */
    describe('when the two paths are on different filesystems', () => {
        it('falls back to copy-then-unlink', async () => {
            jest.doMock('node:fs/promises', () => {
                const actual =
                    jest.requireActual<typeof import('node:fs/promises')>('node:fs/promises');
                return {
                    ...actual,
                    rename: jest.fn().mockRejectedValue(
                        Object.assign(new Error('EXDEV: cross-device link not permitted'), {
                            code: 'EXDEV'
                        })
                    )
                };
            });

            const { moveFile } = await import('@infrastructure/adapters/filesystem');
            const source = await stage('staged.png', 'the original bytes');
            const destination = path.join(root, 'committed.png');

            await moveFile(source, destination);

            // Identical outcome to the fast path — that is the whole requirement.
            expect(existsSync(source)).toBe(false);
            expect(await readFile(destination, 'utf8')).toBe('the original bytes');
        });

        it('still throws on a failure that is not a device boundary', async () => {
            jest.doMock('node:fs/promises', () => {
                const actual =
                    jest.requireActual<typeof import('node:fs/promises')>('node:fs/promises');
                return {
                    ...actual,
                    rename: jest.fn().mockRejectedValue(
                        Object.assign(new Error('EACCES: permission denied'), {
                            code: 'EACCES'
                        })
                    )
                };
            });

            const { moveFile } = await import('@infrastructure/adapters/filesystem');
            const source = await stage('staged.png');

            // A permissions problem must surface, not be retried as a copy that fails differently.
            await expect(moveFile(source, path.join(root, 'committed.png'))).rejects.toThrow(
                'EACCES'
            );
        });
    });
});

src/modules/inventory/tests/unit/transit.source:
/**
 * The transition table — `src/modules/inventory/domain/transitions.ts`.
 *
 * No mocks, no database: this is the model itself, and it is pure. What is asserted here is not
 * "the function returns what it returns" but the three INVARIANTS the table encodes, each of
 * which is a sentence about how a shop works:
 *
 *   1. Only a receipt or an adjustment can change how many units exist.
 *   2. A commit moves both columns by the same amount, so a sale does not change availability.
 *   3. Reserve and release/expire are exact inverses.
 *
 * A test that merely restated the table row by row would pass against a table that had been
 * copied wrong, because the copy and the expectation would be the same mistake twice.
 */

import { StockMovementReason } from '@types';
import { counterDeltaFor, availabilityOf } from '../../domain';

const EVERY_REASON = Object.values(StockMovementReason);

describe('counterDeltaFor', () => {
    it('covers every reason the contract declares', () => {
        // Not a formality: `counterDeltaFor` switches exhaustively, so a reason added to the
        // contract and not to the table is a compile error — but only if something calls it with
        // that reason, which is what this does.
        for (const reason of EVERY_REASON)
            expect(counterDeltaFor(reason, 1)).toEqual({
                onHandDelta: expect.any(Number),
                reservedDelta: expect.any(Number)
            });
    });

    it('lets only a receipt or an adjustment change how many units exist', () => {
        const changesOnHand = EVERY_REASON.filter(
            (reason) => counterDeltaFor(reason, 5).onHandDelta !== 0
        );

        // `commit` is here too, and that is correct — a sale removes units. The point of the
        // assertion is that nothing a CUSTOMER does before paying appears in this list.
        expect(changesOnHand.toSorted()).toEqual(
            [
                StockMovementReason.commit,
                StockMovementReason.receive,
                StockMovementReason.adjust
            ].toSorted()
        );
    });

    it('commits without changing availability', () => {
        const { onHandDelta, reservedDelta } = counterDeltaFor(StockMovementReason.commit, 7);

        // Both columns fall together, so `onHand - reserved` is untouched: the units stopped
        // being sellable when they were reserved, and this is only the moment they leave.
        expect(onHandDelta).toBe(reservedDelta);
        expect(onHandDelta - reservedDelta).toBe(0);
    });

    it.each([StockMovementReason.release, StockMovementReason.expire])(
        'makes %s the exact inverse of a reserve',
        (undoing) => {
            const held = counterDeltaFor(StockMovementReason.reserve, 4);
            const given = counterDeltaFor(undoing, 4);

            expect(held.onHandDelta + given.onHandDelta).toBe(0);
            expect(held.reservedDelta + given.reservedDelta).toBe(0);
        }
    );

    it('never lets a reserve or a release touch what exists', () => {
        for (const reason of [
            StockMovementReason.reserve,
            StockMovementReason.release,
            StockMovementReason.expire
        ])
            expect(counterDeltaFor(reason, 9).onHandDelta).toBe(0);
    });

    it('carries an adjustment’s sign rather than its magnitude', () => {
        // The one reason whose quantity is already signed. Shrinkage is the common case, and a
        // `Math.abs` sneaking in here would silently turn every write-off into a windfall.
        expect(counterDeltaFor(StockMovementReason.adjust, -3)).toEqual({
            onHandDelta: -3,
            reservedDelta: 0
        });
        expect(counterDeltaFor(StockMovementReason.adjust, 3)).toEqual({
            onHandDelta: 3,
            reservedDelta: 0
        });
    });
});

describe('availabilityOf', () => {
    it.each([
        [{ onHand: 10, reserved: 0 }, 10],
        [{ onHand: 10, reserved: 4 }, 6],
        [{ onHand: 10, reserved: 10 }, 0],
        // Absent counters read as nothing to sell, not as unlimited — the safe direction for a
        // number that decides whether to take someone's money.
        [{}, 0],
        [{ onHand: 5 }, 5],
        [{ reserved: 5 }, 0]
    ])('reads %j as %i', (counters, expected) => {
        expect(availabilityOf(counters)).toBe(expected);
    });

    it('clamps a would-be negative at zero', () => {
        // Should be unreachable — every transition guards against it — but a negative count must
        // never reach a screen, so the clamp is asserted rather than assumed.
        expect(availabilityOf({ onHand: 3, reserved: 8 })).toBe(0);
    });
});

tests/cross-cutting/module-file-shapes.t.source:
/**
 * Every file inside a module folder is a shape this repository has a name for.
 *
 * A module is a vocabulary, not a free-form directory: a manifest, a router, controllers, a
 * service tier, a repository, a model, the optional extension points, the contract slices and the
 * tests. `src/modules/<name>/` holding something outside that list is either a new shape worth
 * naming or a file in the wrong place, and both are worth stopping at review rather than
 * discovering later.
 *
 * WHAT THIS FILE IS NOT. It does not describe the shapes — `docs/reference/src-modules.md` does
 * that, in prose, for a reader. The catalogue below is patterns only, deliberately: descriptions
 * kept beside the patterns were a second copy of that page, and the two had already forked (the
 * page called `probes.ts` a readiness contribution, which it is not). One place says what a shape
 * IS; this one says which shapes EXIST.
 *
 * Adding a shape is therefore two lines in two files, and that is the point — a new kind of file in
 * the module vocabulary is a deliberate act.
 *
 * Ordering is irrelevant here. It mattered when each pattern carried a description and the most
 * specific had to win; membership is a set question, so `services/index.ts` and `domain/index.ts`
 * are gone — their parent patterns already match them.
 *
 * See: docs/reference/src-modules.md · docs/theory/modules.md#what-a-module-contains
 */

import { existsSync, readdirSync, statSync } from 'node:fs';
import path from 'node:path';
import { enabledModules } from '../../src/modules';

const MODULES_ROOT = path.join(__dirname, '../../src/modules');

/**
 * Every path shape allowed inside `src/modules/<name>/`, matched against the module-relative path.
 *
 * A file matching none of these fails the suite by name. That failure is the whole point: it says
 * "this shape has no name yet", and the fix is to add the pattern here and its row to
 * `docs/reference/src-modules.md` — or to move the file somewhere it belongs.
 */
const MODULE_FILE_SHAPES: readonly RegExp[] = [
    /^module\.ts$/,
    /^index\.ts$/,
    /^routes\.ts$/,
    /^controllers\/.+\.ts$/,
    /^services\/.+\.ts$/,
    /^service\.ts$/,
    /^repository\.ts$/,
    /^model\.ts$/,
    /^domain\/.+\.ts$/,
    /^openapi\.yaml$/,
    /^asyncapi\.yaml$/,
    /^locales\/.+\.json$/,
    /^events\.ts$/,
    /^audit\.ts$/,
    /^metrics\.ts$/,
    /^analytics\.ts$/,
    /^emails\.ts$/,
    /^probes\.ts$/,
    /^demo\.ts$/,
    /^factory\.ts$/,
    /^config\.ts$/,
    /^tenants\.ts$/,
    /^session\/.+\.ts$/,
    /^providers\/.+\.ts$/,
    /^tests\/factory\.ts$/,
    /^tests\/unit\/.+\.ts$/,
    /^tests\/integration\/.+\.ts$/,
    /^tests\/contract\/.+\.ts$/
];

/** Every file under `directory`, as paths relative to it, skipping jest's snapshot folders. */
const walk = (directory: string, base = directory): string[] => {
    if (!existsSync(directory)) return [];
    return readdirSync(directory).flatMap((entry) => {
        const full = path.join(directory, entry);
        if (statSync(full).isDirectory()) return entry === '__snapshots__' ? [] : walk(full, base);
        return [path.relative(base, full).replaceAll('\\', '/')];
    });
};

/** Every module-relative path in the tree, tagged with the module it belongs to. */
const everyModuleFile = (): { module: string; file: string }[] =>
    enabledModules.flatMap((appModule) =>
        walk(path.join(MODULES_ROOT, appModule.name)).map((file) => ({
            module: appModule.name,
            file
        }))
    );

describe('every file in a module folder is a named shape', () => {
    it('actually reads the module tree', () => {
        // The canary: an empty result must mean "all named", never "nothing was scanned".
        expect(everyModuleFile().length).toBeGreaterThan(0);
    });

    it('finds no file matching no shape in the catalogue', () => {
        const unnamed = everyModuleFile()
            .filter(({ file }) => !MODULE_FILE_SHAPES.some((shape) => shape.test(file)))
            .map(({ module, file }) => `src/modules/${module}/${file}`);

        expect(unnamed).toEqual([]);
    });

    it('keeps the catalogue free of shapes nothing matches', () => {
        // The reverse reading. A pattern no file matches is a shape that was deleted, renamed, or
        // never existed — it costs nothing at runtime and quietly widens what the check accepts.
        const files = everyModuleFile().map(({ file }) => file);
        const unused = MODULE_FILE_SHAPES.filter(
            (shape) => !files.some((file) => shape.test(file))
        ).map((shape) => shape.source);

        expect(unused).toEqual([]);
    });
});

tests/unit/infrastructure/http/middlewar.source:
/**
 * `attachLocale` — `src/infrastructure/http/middlewares/locale.ts`.
 *
 * The middleware does four separable things, and each one breaks a different consumer:
 *
 *   - it **negotiates** the locale from `Accept-Language` and puts it on the request, which is
 *     what `request.t` and every ambient `t()` downstream read;
 *   - it runs `next` **inside** the locale context, which is the whole mechanism — a service that
 *     imports `t` from `@infrastructure/i18n` gets the request's language only because it executes within
 *     this call. Hoisting `next()` out of `runWithLocaleContext` leaves `request.t` correct and
 *     every ambient `t()` silently falling back to English;
 *   - it states what the client actually got in `Content-Language`, which is not always what was
 *     asked for;
 *   - it appends `Vary: Accept-Language` so a shared cache does not answer an Italian request
 *     with the English body it stored a moment earlier.
 *
 * The last two are asserted for the append, not the assignment: `response.vary` must add to
 * whatever CORS already put there rather than replace it.
 */
import { asStub } from '@tests/stub';
import type { NextFunction, Request, Response } from 'express';
import { attachLocale } from '@infrastructure/http/middlewares/locale';
import { getCurrentLocale, getLocaleContext, listSupportedLocales } from '@infrastructure/i18n';

const makeRequest = (acceptLanguage?: string) =>
    asStub<Request>({
        get: (name: string) =>
            name.toLowerCase() === 'accept-language' ? acceptLanguage : undefined
    });

const makeResponse = () =>
    asStub<Response & { set: jest.Mock; vary: jest.Mock }>({
        set: jest.fn(),
        vary: jest.fn()
    });

describe('attachLocale', () => {
    it('puts the negotiated locale and its bound t on the request', () => {
        const request = makeRequest('it');
        const response = makeResponse();

        attachLocale(request, response, jest.fn() as NextFunction);

        expect(request.locale).toBe('it');
        expect(typeof request.t).toBe('function');
    });

    it('runs next inside the locale context, not merely alongside it', () => {
        // This is the assertion that the ambient `t` depends on. `getCurrentLocale()` reads the
        // AsyncLocalStorage store, so it can only see 'it' if `next` executes within
        // `runWithLocaleContext` — calling next() before or after would leave it at the default.
        const request = makeRequest('it');
        let seenInsideNext: string | undefined;
        let contextInsideNext: unknown;

        attachLocale(request, makeResponse(), (() => {
            seenInsideNext = getCurrentLocale();
            contextInsideNext = getLocaleContext();
        }) as NextFunction);

        expect(seenInsideNext).toBe('it');
        expect(contextInsideNext).toBeDefined();
    });

    it('leaves no locale context behind once the chain returns', () => {
        attachLocale(makeRequest('it'), makeResponse(), jest.fn() as NextFunction);

        expect(getLocaleContext()).toBeUndefined();
    });

    it('states the locale the client actually got, not the one it asked for', () => {
        // 'zz' is supported by nothing, so negotiation falls back — and the header has to say so,
        // otherwise a cache keys an English body under a Klingon request.
        const request = makeRequest('zz');
        const response = makeResponse();

        attachLocale(request, response, jest.fn() as NextFunction);

        expect(listSupportedLocales()).toContain(request.locale);
        expect(response.set).toHaveBeenCalledWith('Content-Language', request.locale);
    });

    it('varies on Accept-Language so a shared cache cannot cross languages', () => {
        const response = makeResponse();

        attachLocale(makeRequest('en'), response, jest.fn() as NextFunction);

        // `vary` rather than `set`: it appends, so CORS's `Vary: Origin` survives.
        expect(response.vary).toHaveBeenCalledWith('Accept-Language');
    });

    it('falls back rather than throwing on a header the client made up', () => {
        const request = makeRequest(';;;q=notanumber,');
        const response = makeResponse();

        expect(() => attachLocale(request, response, jest.fn() as NextFunction)).not.toThrow();
        expect(listSupportedLocales()).toContain(request.locale);
    });

    it('calls next exactly once', () => {
        const next = jest.fn();

        attachLocale(makeRequest('en'), makeResponse(), next as NextFunction);

        expect(next).toHaveBeenCalledTimes(1);
    });
});

tests/unit/infrastructure/adapters/store.source:
/**
 * `storeUploadedImages` — the step between "multer wrote a file" and "the API has an image".
 *
 * It is the only place that turns a staged upload into a stored one, so its failure behaviour is
 * what decides whether a bad day leaves temp files, orphaned images, or database rows pointing at
 * nothing. Each of those is asserted here; the store itself is mocked, because what is under test
 * is the middleware's handling of it, not where bytes land.
 */
import type { NextFunction, Request, Response } from 'express';
import { storeUploadedImages } from '@infrastructure/adapters/storage';

jest.mock('@infrastructure/adapters/image-store', () => ({
    imageStore: { put: jest.fn(), remove: jest.fn() }
}));

jest.mock('@infrastructure/adapters/filesystem', () => ({
    deleteFile: jest.fn().mockResolvedValue(true),
    moveFile: jest.fn()
}));

const { imageStore } = jest.requireMock<{ imageStore: { put: jest.Mock; remove: jest.Mock } }>(
    '@infrastructure/adapters/image-store'
);
const { deleteFile } = jest.requireMock<{ deleteFile: jest.Mock }>(
    '@infrastructure/adapters/filesystem'
);

const uploaded = (filePath: string) => ({ path: filePath }) as Express.Multer.File;

/** Runs the middleware and resolves with whatever it passed to `next`. */
const run = (request: Partial<Request>) =>
    new Promise<unknown>((resolve) => {
        storeUploadedImages(request as Request, {} as Response, resolve as NextFunction);
    });

describe('storeUploadedImages', () => {
    it('commits a single upload and records the url on the request', async () => {
        imageStore.put.mockResolvedValue('/images/a.png');
        const request: Partial<Request> = { file: uploaded('/staging/a.png') };

        await expect(run(request)).resolves.toBeUndefined();

        expect(imageStore.put).toHaveBeenCalledWith('/staging/a.png');
        expect(request.storedImageUrls).toEqual(['/images/a.png']);
    });

    /* multer's three shapes again: `.array()` and `.fields()` both arrive as `request.files`. */
    it('commits every file of a multi-file upload, in order', async () => {
        imageStore.put.mockImplementation((staged: string) =>
            Promise.resolve('/images/' + staged.split('/').pop())
        );
        const request: Partial<Request> = {
            files: [uploaded('/staging/a.png'), uploaded('/staging/b.png')]
        };

        await run(request);

        expect(request.storedImageUrls).toEqual(['/images/a.png', '/images/b.png']);
    });

    it('passes straight through when the request carried no file', async () => {
        await expect(run({})).resolves.toBeUndefined();

        expect(imageStore.put).not.toHaveBeenCalled();
    });

    /**
     * A failed commit fails the request. The alternative — carry on with no image — writes a
     * product whose picture silently never existed, and does it on the happy path.
     */
    it('fails the request when the store rejects', async () => {
        const failure = new Error('bucket unreachable');
        imageStore.put.mockRejectedValue(failure);

        await expect(run({ file: uploaded('/staging/a.png') })).resolves.toBe(failure);
    });

    it('deletes the staged files when the store rejects', async () => {
        imageStore.put.mockRejectedValue(new Error('bucket unreachable'));

        await run({ files: [uploaded('/staging/a.png'), uploaded('/staging/b.png')] });

        // Nobody owns them now: the request is over and no url was recorded. Left behind, they are
        // a slow disk leak in a directory nobody looks at.
        expect(deleteFile).toHaveBeenCalledWith('/staging/a.png');
        expect(deleteFile).toHaveBeenCalledWith('/staging/b.png');
    });

    /**
     * The nastiest case: one file made it into storage and the other did not. The request fails, so
     * no row will ever name the one that succeeded — it has to be removed, or it is an orphan that
     * costs storage forever and that nothing can ever find again.
     */
    it('removes what it managed to store when a sibling upload fails', async () => {
        imageStore.put
            .mockResolvedValueOnce('/images/a.png')
            .mockRejectedValueOnce(new Error('disk full'));
        const request: Partial<Request> = {
            files: [uploaded('/staging/a.png'), uploaded('/staging/b.png')]
        };

        await expect(run(request)).resolves.toBeInstanceOf(Error);

        expect(request.storedImageUrls).toBeUndefined();
        expect(imageStore.remove).toHaveBeenCalledWith('/images/a.png');
        expect(deleteFile).toHaveBeenCalledTimes(2);
    });
});

src/modules/account/tests/unit/auth-surf.source:
/**
 * `index.ts` is this module's front door, and it is one function wide.
 *
 * A barrel's only failure mode is a missing or misrouted name. A dropped line is a compile error in
 * a dozen files that TypeScript catches — but a line that re-exports the *wrong* binding, or a name
 * silently resolving to `undefined` after a refactor of the underlying file, is not caught by
 * anything. Both cases are covered here: the surface is pinned by name, and the function is checked
 * to be the same object `./services/addresses` exports rather than merely to exist.
 *
 * The token surface is deliberately not part of that front door: the kernel's auth port is what
 * every request goes through, and this module fills it from `module.ts` with relative imports, so
 * no sibling needs a token. `tests/cross-cutting/published-language.test.ts` is what stops such an
 * export being added on the theory that one might.
 */

import { existsSync, readdirSync, readFileSync, statSync } from 'node:fs';
import path from 'node:path';
import * as account from '@modules/account';
import * as addresses from '@modules/account/services';

/**
 * Re-exported from `./services/addresses` — the address book's ONE cross-module surface: the
 * cart's checkout resolves which address an order ships to. The CRUD stays internal, served by
 * this module's own routes.
 */
const ADDRESS_EXPORTS = ['addressForCheckout'] as const;

describe('the account barrel', () => {
    it.each(ADDRESS_EXPORTS)('re-exports %s from ./services/addresses unchanged', (name) => {
        // Identity, not existence: a re-export resolving to a different object means the barrel
        // and the implementation have forked, which is the failure a smoke test misses.
        expect(account[name]).toBe(addresses[name]);
    });

    it('exports nothing beyond the declared groups', () => {
        // Widening a barrel is a design decision — it is a promise to every other module that the
        // shape will not move. This case makes that deliberate rather than incidental: a new
        // export fails here until it is written down above.
        expect(Object.keys(account).toSorted()).toEqual([...ADDRESS_EXPORTS].toSorted());
    });
});

/**
 * The barrel is the boundary, asserted rather than asked for.
 *
 * A docblock claiming nothing imports the implementations directly is PROSE, and prose drifts: a
 * consumer reaching one function through the barrel and another straight from `./session/jwt` reads
 * as perfectly normal in review, and nothing says otherwise.
 *
 * Inside the module, relative imports ARE the right thing: a unit test of `session/jwt.ts` tests
 * `session/jwt.ts`, and `session/cookies.ts` uses `./config` because one implementation may use
 * another. What must not
 * happen is a file OUTSIDE `src/modules/account/` reaching past `index.ts`. ESLint enforces that
 * for files under `src/modules/**`, which is why the gap this test fills is everything else:
 * `src/middlewares/`, `src/bootstrap/`, `src/jobs/`, `src/workers/`, `src/infrastructure/`.
 */
describe('nothing outside the module reaches past the barrel', () => {
    const SOURCE_ROOT = path.join(__dirname, '..', '..', '..', '..');
    const ACCOUNT_ROOT = path.join(SOURCE_ROOT, 'modules', 'account');

    /** Every `.ts` file under `src/`, so a consumer anywhere is caught, not just a sibling. */
    const listSourceFiles = (directory: string): string[] =>
        readdirSync(directory).flatMap((entry) => {
            const entryPath = path.join(directory, entry);
            if (statSync(entryPath).isDirectory()) return listSourceFiles(entryPath);
            return entryPath.endsWith('.ts') ? [entryPath] : [];
        });

    it('finds the source tree it means to scan', () => {
        // A canary: a wrong root would make the assertion below pass over nothing.
        expect(existsSync(ACCOUNT_ROOT)).toBe(true);
        expect(listSourceFiles(SOURCE_ROOT).length).toBeGreaterThan(50);
    });

    it('no file outside src/modules/account imports its internals', () => {
        // The manifest is exempt, matching the cross-cutting boundary sweep: a sibling's test
        // that boots the registry legitimately names `@modules/account/module`.
        const offenders = listSourceFiles(SOURCE_ROOT)
            .filter((file) => !file.startsWith(ACCOUNT_ROOT))
            .filter((file) =>
                /from\s+'@modules\/account\/(?!module')[^']+'/.test(readFileSync(file, 'utf8'))
            )
            .map((file) => path.relative(SOURCE_ROOT, file));

        expect(offenders).toEqual([]);
    });
});

src/modules/account/tests/unit/token-cle.source:
import { asStub } from '@tests/stub';
import { postLogin } from '@modules/account/controllers/post-login';
import { getRefreshToken } from '@modules/account/controllers/get-refresh-token';
import { accountService, runTokenCleanup } from '@modules/account/services';

/*
 * One factory for the whole service folder. `runTokenCleanup` and `login` used to be two modules
 * (`../token-cleanup` and `../service`) and so took a `jest.mock` each; they are two members of one
 * barrel now, and a second `jest.mock` of the same path REPLACES the first rather than merging with
 * it — which would leave whichever half came first undefined at call time.
 *
 * `refreshAccessToken` joined the barrel this session: `getRefreshToken` no longer reaches
 * `../session/jwt`'s `createAccessToken` directly, it calls this wrapper, which is what now emits
 * the audit record — see `authentication.ts`. Mocked here rather than left to call through, so
 * this suite keeps testing only the one thing it owns: that cleanup runs BEFORE it.
 */
jest.mock('@modules/account/services', () => ({
    __esModule: true,
    runTokenCleanup: jest.fn(),
    accountService: {
        login: jest.fn(),
        refreshAccessToken: jest.fn()
    }
}));

jest.mock('@modules/account/session/cookies', () => ({
    __esModule: true,
    createRefreshCookie: jest.fn(),
    createLoggedCookie: jest.fn()
}));

jest.mock('@infrastructure/http/response', () => ({
    __esModule: true,
    successResponse: jest.fn(),
    rejectResponse: jest.fn()
}));

const mockRunTokenCleanup = runTokenCleanup as jest.MockedFunction<typeof runTokenCleanup>;
const mockLogin = accountService.login as jest.MockedFunction<typeof accountService.login>;
const mockRefreshAccessToken = accountService.refreshAccessToken as jest.MockedFunction<
    typeof accountService.refreshAccessToken
>;

describe('Auth controllers token cleanup trigger', () => {
    beforeEach(() => {
        jest.clearAllMocks();
        mockRunTokenCleanup.mockResolvedValue();
    });

    it('runs cleanup before login authentication', async () => {
        mockLogin.mockResolvedValue({
            success: false,
            status: 401,
            message: 'Unauthorized',
            errors: [
                {
                    code: 'UNAUTHORIZED',
                    message: 'invalid credentials'
                }
            ],
            data: undefined as never
        });

        const request = {
            body: {
                email: 'user@example.com',
                password: 'Password1!'
            }
        };
        const response = {} as Parameters<typeof postLogin>[1];

        await postLogin(asStub<Parameters<typeof postLogin>[0]>(request), response);

        expect(mockRunTokenCleanup).toHaveBeenCalledTimes(1);
        expect(mockLogin).toHaveBeenCalledTimes(1);
        expect(mockRunTokenCleanup.mock.invocationCallOrder[0]).toBeLessThan(
            mockLogin.mock.invocationCallOrder[0]
        );
    });

    it('runs cleanup before refresh-token access token creation', async () => {
        mockRefreshAccessToken.mockResolvedValue('new-access-token');

        const request = {
            params: {},
            cookies: {
                jwt: 'refresh-token'
            }
        };
        const response = {} as Parameters<typeof getRefreshToken>[1];

        await getRefreshToken(asStub<Parameters<typeof getRefreshToken>[0]>(request), response);

        expect(mockRunTokenCleanup).toHaveBeenCalledTimes(1);
        expect(mockRefreshAccessToken).toHaveBeenCalledWith('refresh-token', expect.anything());
        expect(mockRunTokenCleanup.mock.invocationCallOrder[0]).toBeLessThan(
            mockRefreshAccessToken.mock.invocationCallOrder[0]
        );
    });

    it('does not run cleanup in refresh flow when refresh token is missing', async () => {
        mockRefreshAccessToken.mockRejectedValue(new Error('Refresh token missing'));

        const request = {
            params: {},
            cookies: {}
        };
        const response = {} as Parameters<typeof getRefreshToken>[1];

        await getRefreshToken(asStub<Parameters<typeof getRefreshToken>[0]>(request), response);

        // A sweep of every user document, for a request that cannot succeed. The service is still
        // called: the missing cookie is a refusal it reports on, not one the controller decides.
        expect(mockRunTokenCleanup).not.toHaveBeenCalled();
        expect(mockRefreshAccessToken).toHaveBeenCalledWith(undefined, expect.anything());
    });
});

tests/unit/app/process-error-handlers.te.source:
/**
 * The process-level handlers installed by `src/app/error-handling.ts`.
 *
 * Registering an `uncaughtException` listener REPLACES Node's default behaviour — print the stack,
 * exit 1. So the listener is not an addition to what happens on a fatal throw; it is the whole of
 * what happens. A branch that returned before logging meant that in development and in CI the
 * process caught every uncaught exception, did nothing at all with it, and carried on in an
 * unknown state: no stack, no log line, no crash, no exit code. The symptom is "the server just
 * stops doing that thing", and a fatal defect passes a green suite.
 *
 * Two properties, and they pull in opposite directions:
 *   - outside a test runner, ALWAYS log and ALWAYS exit — the state after an uncaught exception is
 *     unknown, which is exactly as true in development as in production;
 *   - under a test runner, install nothing, because Jest's own handler is what reports the throw
 *     against the test that caused it.
 */

import { asStub } from '@tests/stub';
import { auditLogger } from '@infrastructure/adapters/logger';
import { installErrorHandling } from '@app/error-handling';

/** Enough of an Express app for `app.use(handler)`. */
const appStub = () => asStub<Parameters<typeof installErrorHandling>[0]>({ use: jest.fn() });

/**
 * Install the handlers under a given `NODE_ENV` and hand back the ones this call added.
 *
 * Listeners are process-global and this file installs real ones, so every case removes exactly
 * what it registered — a leaked handler would silence the runner for the rest of the suite.
 */
const installUnder = (nodeEnv: string) => {
    const before = process.listeners('uncaughtException');
    const originalEnv = process.env.NODE_ENV;

    process.env.NODE_ENV = nodeEnv;
    installErrorHandling(appStub());
    process.env.NODE_ENV = originalEnv;

    const added = process
        .listeners('uncaughtException')
        .filter((listener) => !before.includes(listener));
    const rejectionsAdded = process.listeners('unhandledRejection').at(-1)!;

    return {
        added,
        rejectionsAdded,
        remove: () => {
            for (const listener of added) process.off('uncaughtException', listener);
            process.off('unhandledRejection', rejectionsAdded);
        }
    };
};

describe('installErrorHandling — uncaughtException', () => {
    it('installs no handler under a test runner, leaving the reporting to it', () => {
        const { added, remove } = installUnder('test');

        expect(added).toHaveLength(0);

        remove();
    });

    it.each(['development', 'production'])('logs and exits under %s', (nodeEnv) => {
        const errorSpy = jest.spyOn(auditLogger, 'error').mockImplementation(() => auditLogger);
        // `process.exit` really does end the worker, so the one call under test is stubbed out.
        const exitSpy = jest.spyOn(process, 'exit').mockImplementation((() => undefined) as never);
        const { added, remove } = installUnder(nodeEnv);

        expect(added).toHaveLength(1);
        added[0](new Error('boom'), 'uncaughtException');

        // The order is the finding: the audit write happens BEFORE the exit, not behind it.
        expect(errorSpy).toHaveBeenCalledWith(
            'process.uncaughtException',
            expect.objectContaining({ message: 'boom', origin: 'uncaughtException' })
        );
        expect(exitSpy).toHaveBeenCalledWith(1);

        remove();
        errorSpy.mockRestore();
        exitSpy.mockRestore();
    });
});

describe('installErrorHandling — unhandledRejection', () => {
    it('is installed in every environment, including under a test runner', () => {
        const errorSpy = jest.spyOn(auditLogger, 'error').mockImplementation(() => auditLogger);
        const { rejectionsAdded, remove } = installUnder('test');

        // A rejection leaves the process in a defined state, so this one audits and continues —
        // the opposite call from the exception handler above, for the opposite reason.
        (rejectionsAdded as (reason: unknown) => void)(new Error('nobody caught me'));

        expect(errorSpy).toHaveBeenCalledWith(
            'process.unhandledRejection',
            expect.objectContaining({ reason: { name: 'Error', message: 'nobody caught me' } })
        );

        remove();
        errorSpy.mockRestore();
    });
});

