import { Router } from 'express';
import { registerModules, validateModules } from '@kernel/registry';
import type { AppModule } from '@kernel/registry';

/**
 * The registry is the file that decides what "this build" means, so its failures have to be loud
 * and specific. A misconfiguration that boots and then 500s on the first request crossing the gap
 * is strictly worse than one that refuses to boot with the offending path named.
 */

/**
 * Names alone here: the cases below are about the graph, and every one of them would read worse
 * with a relationship kind and a sentence attached to an arrow between two modules called `a` and
 * `b`. The kinds are asserted where they mean something, against the real manifests, in
 * `tests/cross-cutting/context-map.test.ts`.
 */
const makeModule = (name: string, dependsOn: string[] = []): AppModule => ({
    name,
    subdomain: 'supporting',
    basePath: `/${name}`,
    routes: Router(),
    dependsOn: dependsOn.map((module) => ({
        module,
        as: 'conformist' as const,
        because: `${name} reads ${module}`
    }))
});

describe('validateModules', () => {
    it('accepts a well-formed registry', () => {
        expect(() =>
            validateModules([makeModule('products'), makeModule('cart', ['products'])])
        ).not.toThrow();
    });

    it('rejects a module registered twice', () => {
        expect(() => validateModules([makeModule('products'), makeModule('products')])).toThrow(
            /registered twice/
        );
    });

    it('names the module and the dependency when a dependency is not enabled', () => {
        // The event-portal case from the plan: products is deleted, cart is not.
        expect(() => validateModules([makeModule('cart', ['products'])])).toThrow(
            /"cart" depends on "products", which is not enabled/
        );
    });

    it('reports the path of a dependency cycle rather than just its existence', () => {
        expect(() =>
            validateModules([makeModule('cart', ['products']), makeModule('products', ['cart'])])
        ).toThrow(/cycle: (cart → products → cart|products → cart → products)/);
    });

    it('catches a cycle that closes through a third module', () => {
        expect(() =>
            validateModules([
                makeModule('a', ['b']),
                makeModule('b', ['c']),
                makeModule('c', ['a'])
            ])
        ).toThrow(/cycle:/);
    });

    it('accepts a module that owns data but declares no router', () => {
        // `audit-logs` is the real one: it owns a collection, and the endpoint that reads it
        // belongs to `observability`. A headless module is a first-class registry entry, and
        // other modules may still depend on it.
        expect(() =>
            validateModules([
                { name: 'audit-logs', subdomain: 'generic' },
                makeModule('observability', ['audit-logs'])
            ])
        ).not.toThrow();
    });

    it('rejects a module that depends on itself, by name rather than as a cycle', () => {
        // Reported separately because it is a typo, not an architecture problem — and the cycle
        // walk would otherwise describe it as `products → products`, which reads like a finding.
        expect(() => validateModules([makeModule('products', ['products'])])).toThrow(
            /"products" declares a dependency on itself/
        );
    });

    it('accepts a diamond, which is not a cycle', () => {
        expect(() =>
            validateModules([
                makeModule('orders', ['products', 'users']),
                makeModule('products'),
                makeModule('users')
            ])
        ).not.toThrow();
    });
});

describe('registerModules', () => {
    it('subscribes every module that asks to', () => {
        const subscribe = jest.fn();
        registerModules([{ ...makeModule('products'), subscribe }]);

        expect(subscribe).toHaveBeenCalledTimes(1);
    });

    it('validates before subscribing, so a broken registry attaches no handlers', () => {
        const subscribe = jest.fn();

        expect(() =>
            registerModules([{ ...makeModule('cart', ['products']), subscribe }])
        ).toThrow();
        expect(subscribe).not.toHaveBeenCalled();
    });
});

src/modules/orders/tests/unit/service-sc.source:
/**
 * Order read scoping — `orderService.callerScope`.
 *
 * The authorization boundary for order reads: it is the difference between a user seeing their
 * own orders and seeing everyone's, and between seeing a soft-deleted order and not. It has three
 * documented properties, and each one is a distinct way to leak data if it breaks:
 *
 *   1. admin  → `undefined`, meaning "no restriction" (the caller spreads it).
 *   2. anyone else → a filter on their own `userId`, excluding soft-deleted rows.
 *   3. no auth context → *throws*, deliberately, rather than widening the scope.
 *
 * Property 2 additionally requires a real BSON `ObjectId`, not a string: `$match` inside an
 * aggregation pipeline does not apply schema casting, so a string id matches nothing and reads
 * as "you have no orders" instead of as an error. The coercion itself lives in
 * `orderRepository.ownerScope`, which `visibleScope` composes; these assert the behaviour
 * survives both delegations.
 */

import { Types } from 'mongoose';
import { orderService } from '@modules/orders';

const USER_ID = '507f1f77bcf86cd799439011';

describe('orderService.callerScope', () => {
    it('returns undefined for an admin, so the caller applies no restriction', () => {
        const scope = orderService.callerScope({ id: USER_ID, admin: true });

        // Not `toBeFalsy()`: `{}` is falsy-adjacent in review but would spread into a filter
        // that matches nothing. Only `undefined` spreads to nothing.
        expect(scope).toBeUndefined();
    });

    it('restricts a non-admin to their own userId', () => {
        const scope = orderService.callerScope({ id: USER_ID, admin: false });

        expect(scope).toEqual({
            userId: new Types.ObjectId(USER_ID),
            deletedAt: { $exists: false }
        });
    });

    it('hides soft-deleted orders from their own owner', () => {
        // The second axis of the scope, and the one an ownership-only assertion would miss: a
        // soft-deleted order still belongs to the caller, so `userId` alone still matches it.
        // `$exists: false` rather than `null` — `remove` unsets the field to restore.
        const scope = orderService.callerScope({ id: USER_ID, admin: false });

        expect(scope!.deletedAt).toEqual({ $exists: false });
    });

    it('lets an admin see soft-deleted orders, by restricting nothing', () => {
        expect(orderService.callerScope({ id: USER_ID, admin: true })).toBeUndefined();
    });

    it('restricts a caller whose admin flag is absent entirely', () => {
        // `admin` is optional on the context; absent must mean "not an admin", never "unknown,
        // so allow". This is the fail-safe direction.
        const scope = orderService.callerScope({ id: USER_ID });

        expect(scope).toEqual({
            userId: new Types.ObjectId(USER_ID),
            deletedAt: { $exists: false }
        });
    });

    it('emits a BSON ObjectId rather than a string, so aggregation $match can compare it', () => {
        const scope = orderService.callerScope({ id: USER_ID, admin: false });

        // The distinction that a `toEqual` on ids alone would miss: a plain string would satisfy
        // a loose comparison but silently match zero documents inside a pipeline.
        expect(scope!.userId).toBeInstanceOf(Types.ObjectId);
        expect(String(scope!.userId)).toBe(USER_ID);
    });

    it('throws when there is no auth context at all', () => {
        // The documented safe direction: an unauthenticated request must error out rather than
        // fall through to an unscoped query. `toObjectId('')` is what enforces it.
        expect(() => orderService.callerScope(undefined)).toThrow();
    });

    it('throws when the auth context carries no id', () => {
        expect(() => orderService.callerScope({ admin: false })).toThrow();
    });

    it('throws on a malformed id instead of scoping to nothing', () => {
        expect(() => orderService.callerScope({ id: 'not-an-object-id', admin: false })).toThrow();
    });
});

tests/unit/db/run-script.test.ts.source:
/**
 * Script entry-point wrapper.
 *
 * The three behaviours a bare promise chain does not provide: a non-zero exit code, cleanup on
 * the failure path, and a logged reason. The middle one is load-bearing — without it `db:seed`
 * leaves its Mongo and Redis sockets open on a throw, and the process hangs instead of exiting.
 */
import { runScript } from '../../../db/run-script';
import { logger } from '@infrastructure/adapters/logger';

// Inline `jest.fn()`s rather than outer consts: `jest.mock` is hoisted above the imports, so a
// factory closing over a `const` would read it before initialisation.
jest.mock('@infrastructure/adapters/logger', () => ({
    logger: { info: jest.fn(), warn: jest.fn(), error: jest.fn(), debug: jest.fn() }
}));

const mockError = jest.mocked(logger.error);
const mockWarn = jest.mocked(logger.warn);

const ORIGINAL_EXIT_CODE = process.exitCode;

afterEach(() => {
    process.exitCode = ORIGINAL_EXIT_CODE;
});

describe('runScript', () => {
    it('runs the body, then the cleanup, and leaves the exit code alone', async () => {
        const order: string[] = [];

        await runScript(
            () => {
                order.push('main');
                return Promise.resolve();
            },
            () => {
                order.push('cleanup');
                return Promise.resolve();
            }
        );

        expect(order).toEqual(['main', 'cleanup']);
        expect(process.exitCode).toBe(ORIGINAL_EXIT_CODE);
        expect(mockError).not.toHaveBeenCalled();
    });

    it('sets exit code 1 and logs the reason when the body throws', async () => {
        await runScript(
            () => Promise.reject(new Error('Redis is unreachable')),
            () => Promise.resolve()
        );

        expect(process.exitCode).toBe(1);
        expect(mockError).toHaveBeenCalledWith(
            expect.objectContaining({ error: 'Redis is unreachable' })
        );
    });

    /* The hang: cleanup as the last statement of the happy path is cleanup a throw skips. */
    it('still runs cleanup when the body throws', async () => {
        const cleanup = jest.fn().mockImplementation(() => Promise.resolve());

        await runScript(() => Promise.reject(new Error('boom')), cleanup);

        expect(cleanup).toHaveBeenCalledTimes(1);
        expect(process.exitCode).toBe(1);
    });

    it('never rejects, so the caller needs no .catch of its own', async () => {
        await expect(
            runScript(
                () => Promise.reject(new Error('boom')),
                () => Promise.resolve()
            )
        ).resolves.toBeUndefined();
    });

    it('does not fail a successful run because cleanup failed', async () => {
        await runScript(
            () => Promise.resolve(),
            () => Promise.reject(new Error('quit on a dead socket'))
        );

        expect(process.exitCode).toBe(ORIGINAL_EXIT_CODE);
        expect(mockWarn).toHaveBeenCalledWith(
            expect.objectContaining({ error: 'quit on a dead socket' })
        );
    });

    it('keeps the failure verdict when both the body and cleanup fail', async () => {
        await runScript(
            () => Promise.reject(new Error('boom')),
            () => Promise.reject(new Error('and cleanup too'))
        );

        expect(process.exitCode).toBe(1);
        expect(mockError).toHaveBeenCalled();
        expect(mockWarn).toHaveBeenCalled();
    });

    it('reports a non-Error throw without crashing on `.message`', async () => {
        await runScript(
            // eslint-disable-next-line @typescript-eslint/prefer-promise-reject-errors -- the non-Error rejection IS the case under test
            () => Promise.reject('a bare string'),
            () => Promise.resolve()
        );

        expect(process.exitCode).toBe(1);
        expect(mockError).toHaveBeenCalledWith(
            expect.objectContaining({ error: 'a bare string', stack: undefined })
        );
    });
});

src/modules/orders/tests/unit/serializat.source:
/**
 * The defensive branches in this module's serialization transform.
 *
 * These are the "cannot happen" halves of guards, and they are exactly the halves nothing
 * exercised. That matters more here than it usually does, because the transform runs at the one
 * serialization point every response passes through: a transform that throws turns a successful
 * read into a 500 for every order in the collection, not for one.
 *
 * `applyOrderItems` and `applyOrderTotals` both guard on `Array.isArray(serialized.items)`, and
 * the reason is not paranoia — `items` is `select: false`-free but a projected query
 * (`.select('email createdAt')`) yields a document with no `items` at all, and the transform runs
 * on it just the same. The `!Array.isArray` branch is what keeps that from throwing; delete it
 * and the failure appears only on the projections, which is the hardest place to notice it.
 */
import { applyOrderTransform } from '@modules/orders/model';

describe('order serialization guards', () => {
    it('derives the three totals from the line items', () => {
        // The happy path, stated first so the guards below are read as the exceptions they are.
        const serialized: Record<string, unknown> = {
            items: [
                { product: { price: 10 }, quantity: 2 },
                { product: { price: 5 }, quantity: 3 }
            ]
        };

        applyOrderTransform(serialized);

        expect(serialized.totalItems).toBe(2);
        expect(serialized.totalQuantity).toBe(5);
        expect(serialized.totalPrice).toBe(35);
    });

    it('survives a projection that never selected items', () => {
        // `.select('email createdAt')` produces exactly this shape. Without the Array.isArray
        // guard the transform throws, and every projected order read becomes a 500.
        const serialized: Record<string, unknown> = { email: 'buyer@example.com' };

        expect(() => applyOrderTransform(serialized)).not.toThrow();
    });

    it('reports zero totals rather than omitting them when items are absent', () => {
        // `openapi.yaml` marks the three fields required, so "absent" is a contract violation
        // while "zero" is merely an empty order. The fallback to `[]` is what makes that true.
        const serialized: Record<string, unknown> = { email: 'buyer@example.com' };

        applyOrderTransform(serialized);

        expect(serialized.totalItems).toBe(0);
        expect(serialized.totalQuantity).toBe(0);
        expect(serialized.totalPrice).toBe(0);
    });

    it('strips a leftover _id from an embedded line item', () => {
        // Documents written before `orderItemSchema`'s `_id: false` took effect still carry one
        // at the BSON level, and the contract declares the item shape closed.
        const serialized: Record<string, unknown> = {
            items: [{ _id: 'legacy-id', product: { price: 1 }, quantity: 1 }]
        };

        applyOrderTransform(serialized);

        expect((serialized.items as Record<string, unknown>[])[0]).not.toHaveProperty('_id');
    });

    it('leaves a line item whose product was not populated alone', () => {
        // `item.product && typeof item.product === 'object'` — an unpopulated ref is an ObjectId
        // or a string, and recursing into it is what the guard prevents.
        const serialized: Record<string, unknown> = {
            items: [{ product: undefined, quantity: 1 }, { quantity: 2 }]
        };

        expect(() => applyOrderTransform(serialized)).not.toThrow();
    });

    it('tolerates items being present but not an array', () => {
        const serialized: Record<string, unknown> = { items: 'not-an-array' };

        expect(() => applyOrderTransform(serialized)).not.toThrow();
        expect(serialized.totalItems).toBe(0);
    });
});

tests/cross-cutting/locale-parity.test.t.source:
/**
 * Every language declares the same keys — across the shared file and every module at once.
 *
 * Asserted against the MERGED dictionaries, so a module that ships `en.json` and forgets `it.json`
 * fails here, and so does a shared key translated on one side only. Nothing else notices: each
 * dictionary is valid JSON on its own, and a missing key surfaces as the raw key printed to a user
 * in the wrong language.
 *
 * Per-module copy is asserted by each module's own `validation-messages` spec. This file
 * deliberately names no domain — it is the one property that must hold however many modules exist.
 *
 * ── This is about TIER 1, and must stay that way ─────────────────────────────────────────────
 * The dictionaries here are the deployed files — the API's own copy, loaded at boot. Do not extend
 * this over the database rows `src/modules/locales` serves: static parity is a build-time property
 * of this repository, dynamic completeness is `entryCount` in `GET /locales`, and conflating them
 * would make a half-translated language fail the test suite of a repo that does not own the
 * translation.
 *
 * ── Why the languages are read rather than named ─────────────────────────────────────────────
 * This file used to compare `en` and `it` by name, while a third language sat in `src/locales/`
 * and in every module's locale directory with its completeness checked by nothing — a key could go
 * missing there and the suite stayed green.
 *
 * Iterating `listSupportedLocales()` means a language added tomorrow is covered by existing, a
 * language REMOVED tomorrow stops being asserted about without a test to edit, and the answer
 * stays right when `NODE_SUPPORTED_LOCALES` narrows the set for a deployment.
 */

import { listSupportedLocales, readLocaleDictionary } from '@infrastructure/i18n';

/** Every leaf key of a nested dictionary, dot-joined and sorted. */
const flattenKeys = (dictionary: Record<string, unknown>, prefix = ''): string[] =>
    Object.entries(dictionary)
        .flatMap(([key, value]) =>
            value !== null && typeof value === 'object'
                ? flattenKeys(value as Record<string, unknown>, `${prefix}${key}.`)
                : [`${prefix}${key}`]
        )
        .toSorted();

const supported = listSupportedLocales();

/*
 * One language is the reference and the rest are compared to it — any of them would do, since
 * "they all declare the same keys" is symmetric, and comparing every pair would report the same
 * defect once per pair.
 */
const [reference = 'en', ...others] = supported;
const referenceKeys = flattenKeys(readLocaleDictionary(reference));

describe('locale files', () => {
    it('has more than one language to compare, so the assertions below are not vacuous', () => {
        // A canary. With a single supported locale `others` is empty, `it.each` runs zero cases,
        // and this file would pass while checking nothing.
        expect(supported.length).toBeGreaterThan(1);
    });

    it.each(others)('%s declares exactly the same keys as %s, across every module', (locale) => {
        expect(flattenKeys(readLocaleDictionary(locale))).toEqual(referenceKeys);
    });

    it('carries more than the shared dictionary, so the module merge actually ran', () => {
        // A canary: if `registerLocaleDirectories` were never called, every language would still
        // agree — on the shared half alone — and the parity assertion above would pass vacuously.
        expect(referenceKeys.length).toBeGreaterThan(20);
    });
});

tests/cross-cutting/search-pagination.te.source:
/**
 * `normalizePagination` is the single authority on page DEFAULTS.
 *
 * It runs on every search, after the request layer has passed the caller's raw values through
 * untouched — so what it decides here is what the query gets. Anything that defaulted earlier
 * would be overwritten, which is why nothing does.
 *
 * It is deliberately not the authority on BOUNDS. `openapi.yaml` declares `minimum: 1` /
 * `maximum: 100`, `@infrastructure/http/schemas` enforces that on every search endpoint, and an
 * out-of-range request is answered with a 422 rather than quietly turned into a different
 * request. Clamping here as well would mean advertising a limit that was never applied.
 */
import { normalizePagination } from '@infrastructure/persistence/search';

describe('normalizePagination', () => {
    const originalPageSize = process.env.NODE_SETTINGS_PAGINATION_PAGE_SIZE;

    afterEach(() => {
        if (originalPageSize === undefined) delete process.env.NODE_SETTINGS_PAGINATION_PAGE_SIZE;
        else process.env.NODE_SETTINGS_PAGINATION_PAGE_SIZE = originalPageSize;
    });

    it('coerces string parameters to numbers and derives skip', () => {
        expect(normalizePagination({ page: '3', pageSize: '25' })).toEqual({
            page: 3,
            pageSize: 25,
            skip: 50
        });
    });

    it('defaults to page 1 with ten per page when nothing was asked for', () => {
        delete process.env.NODE_SETTINGS_PAGINATION_PAGE_SIZE;

        expect(normalizePagination()).toEqual({ page: 1, pageSize: 10, skip: 0 });
    });

    it('treats empty and zero values as absent rather than as 0', () => {
        delete process.env.NODE_SETTINGS_PAGINATION_PAGE_SIZE;

        expect(normalizePagination({ page: '', pageSize: 0 })).toEqual({
            page: 1,
            pageSize: 10,
            skip: 0
        });
    });

    // A structural guard, not a policy: a negative page would produce a negative `skip`, which
    // is not a query Mongo can run. The 422 for `?page=0` is issued at the edge.
    it('floors a page below 1 at the first page', () => {
        expect(normalizePagination({ page: -5 }).page).toBe(1);
    });

    // The contract's 1-100 range is enforced by @infrastructure/http/schemas, which answers 422. Silently
    // rewriting an out-of-range request here would make that 422 unreachable and the declared
    // maximum a fiction.
    it('does not cap a page size the caller asked for', () => {
        expect(normalizePagination({ pageSize: 5000 }).pageSize).toBe(5000);
    });

    // The env value is the one number that never passes through a request schema, so it keeps
    // its bound: a typo in deployment config must not hand every search the whole collection.
    it('still bounds the env page size, which no schema validates', () => {
        process.env.NODE_SETTINGS_PAGINATION_PAGE_SIZE = '5000';

        expect(normalizePagination().pageSize).toBe(100);
    });

    it('falls back to the env page size when the caller gives none', () => {
        process.env.NODE_SETTINGS_PAGINATION_PAGE_SIZE = '15';

        expect(normalizePagination({ page: 1 }).pageSize).toBe(15);
    });

    it('prefers an explicit page size over the env fallback', () => {
        process.env.NODE_SETTINGS_PAGINATION_PAGE_SIZE = '15';

        expect(normalizePagination({ pageSize: 50 }).pageSize).toBe(50);
    });

    // A typo in deployment config must not silently disable paging.
    it('ignores a non-numeric env page size', () => {
        process.env.NODE_SETTINGS_PAGINATION_PAGE_SIZE = 'not-a-number';

        expect(normalizePagination().pageSize).toBe(10);
    });
});

