/**
 * The audit vocabulary this module emits — `src/modules/account/audit.ts`.
 *
 * Pinned string by string, because an action is a WIRE CONTRACT and not an identifier. The
 * constant's NAME is this codebase's business and renaming it is a refactor; the STRING is read by
 * log queries, dashboards and alert rules that live outside this repo and are not refactored with
 * it. Change one and everything here type-checks, every other test passes, and someone's alert
 * quietly stops firing.
 *
 * `tests/cross-cutting/audit-actions.test.ts` proves the SHAPE of every module's vocabulary —
 * present, unique across modules, spelled as dotted lower snake_case. It cannot assert the values
 * without naming every domain, which is the coupling the module layout removes. So the values are
 * asserted by their owner, and deleting this folder takes them with it.
 *
 * Whole-object equality rather than one assertion per key: it fails on a changed value AND on an
 * action added or removed without the decision being written down here.
 */

import type { AuditAction } from '@infrastructure/observability/audit';
import { accountAuditActions } from '../../audit';

describe('the account audit vocabulary', () => {
    it('spells every action exactly as the log tooling expects', () => {
        expect(accountAuditActions).toEqual({
            AUTH_LOGIN_SUCCEEDED: 'auth.login.succeeded',
            AUTH_LOGIN_FAILED: 'auth.login.failed',
            AUTH_SIGNED_UP: 'auth.signup',
            AUTH_PROFILE_UPDATED: 'auth.profile.updated',
            AUTH_PASSWORD_RESET_REQUESTED: 'auth.password_reset.requested',
            AUTH_PASSWORD_RESET_COMPLETED: 'auth.password_reset.completed',
            AUTH_PASSWORD_CHANGED: 'auth.password.changed',
            AUTH_ACCOUNT_DELETE_REQUESTED: 'auth.account_delete.requested',
            AUTH_ACCOUNT_DELETE_COMPLETED: 'auth.account_delete.completed',
            AUTH_EMAIL_VERIFY_REQUESTED: 'auth.email_verify.requested',
            AUTH_EMAIL_VERIFY_COMPLETED: 'auth.email_verify.completed',
            AUTH_TOKEN_REFRESHED: 'auth.token.refreshed',
            AUTH_LOGGED_OUT: 'auth.logout',
            AUTH_LOGGED_OUT_EVERYWHERE: 'auth.logout_all',
            AUTH_SESSION_REVOKED: 'auth.session.revoked',
            AUTH_TOKEN_EXPIRED_CLEANUP: 'auth.token.expired_cleanup'
        });
    });

    /*
     * The one module whose wire prefix and folder name deliberately disagree, which is why the
     * rule gets an assertion of its own rather than living only in the table above. A new action
     * added here as `account.*` would satisfy every other guard in the suite: the cross-cutting
     * sweep only asks that it be unique and lower snake_case.
     */
    it('keeps the `auth.` prefix the folder name does not control', () => {
        for (const action of Object.values(accountAuditActions))
            expect(action.startsWith('auth.')).toBe(true);
    });

    /*
     * The `declare module` augmentation in `audit.ts` is what puts these into `AuditAction`.
     * Drop it and the module still compiles on its own — but `emitAuditEvent` then rejects every
     * action this module owns, at the call sites rather than here. Checked at type-check time:
     * `tsconfig.json` includes the whole `src` tree, so this line is compiled even though jest
     * does not type-check it.
     */
    it('registers its actions in the app-wide union', () => {
        const action: AuditAction = accountAuditActions.AUTH_LOGIN_SUCCEEDED;

        expect(action).toBe('auth.login.succeeded');
    });
});

tests/unit/kernel/events.test.ts.source:
import { emitDomainEvent, onDomainEvent, resetDomainEvents } from '@kernel/events';
import { logger } from '@infrastructure/adapters/logger';

/**
 * The event bus exists to break one specific cycle: products has to empty a deleted item out of
 * every cart, and the cart has to read the catalogue to price a line. Two properties make that
 * substitution safe rather than merely decoupled, and both are asserted here — handlers are
 * awaited before the emitter continues, and one failing handler does not take down the operation
 * that emitted the event.
 */

jest.mock('@infrastructure/adapters/logger', () => ({ logger: { error: jest.fn() } }));

declare module '@kernel/events' {
    interface DomainEventMap {
        'test.thing-happened': { id: string };
    }
}

afterEach(() => {
    resetDomainEvents();
    jest.clearAllMocks();
});

describe('emitDomainEvent', () => {
    it('delivers the payload to a subscriber', async () => {
        const handler = jest.fn();
        onDomainEvent('test.thing-happened', handler);

        await emitDomainEvent('test.thing-happened', { id: 'abc' });

        expect(handler).toHaveBeenCalledWith({ id: 'abc' });
    });

    it('resolves only after an async handler has finished', async () => {
        // The ordering guarantee the product delete path depends on: the cart is emptied BEFORE
        // the row disappears. A fire-and-forget bus would pass every other test in this file.
        const order: string[] = [];
        onDomainEvent('test.thing-happened', async () => {
            // A task hop rather than a timer: a fire-and-forget bus would push 'emitter' first
            // either way, and this cannot be slow enough to matter or fast enough to race.
            await new Promise((resolve) => setImmediate(resolve));
            order.push('handler');
        });

        await emitDomainEvent('test.thing-happened', { id: 'abc' });
        order.push('emitter');

        expect(order).toEqual(['handler', 'emitter']);
    });

    it('runs every subscriber, and keeps going when one throws', async () => {
        const second = jest.fn();
        onDomainEvent('test.thing-happened', () => {
            throw new Error('listener exploded');
        });
        onDomainEvent('test.thing-happened', second);

        await expect(
            emitDomainEvent('test.thing-happened', { id: 'abc' })
        ).resolves.toBeUndefined();
        expect(second).toHaveBeenCalledTimes(1);
        expect(logger.error).toHaveBeenCalledWith(
            expect.stringContaining('test.thing-happened'),
            expect.any(Error)
        );
    });

    it('does not reject when an async handler rejects', async () => {
        onDomainEvent('test.thing-happened', () => Promise.reject(new Error('async boom')));

        await expect(
            emitDomainEvent('test.thing-happened', { id: 'abc' })
        ).resolves.toBeUndefined();
        expect(logger.error).toHaveBeenCalled();
    });

    it('is a no-op when nothing subscribes', async () => {
        await expect(
            emitDomainEvent('test.thing-happened', { id: 'abc' })
        ).resolves.toBeUndefined();
    });
});

describe('resetDomainEvents', () => {
    it('drops subscriptions so they do not leak between tests', async () => {
        const handler = jest.fn();
        onDomainEvent('test.thing-happened', handler);

        resetDomainEvents();
        await emitDomainEvent('test.thing-happened', { id: 'abc' });

        expect(handler).not.toHaveBeenCalled();
    });
});

src/modules/users/tests/unit/validation-.source:
/**
 * This module's validation copy resolves against the ACTIVE locale, not the boot one.
 *
 * The failure this defends against is PROBLEM 01: `t()` called at module scope, before
 * `i18next.init()`, returning `undefined` so Zod fell back to its own English defaults. The only
 * guard that existed asserted a message was not shaped like a dotted key — which a Zod default
 * ("Too small: expected string…") satisfies perfectly. These assert the exact shipped strings, so
 * a fallback to a Zod default fails them.
 *
 * `loadBeforeI18n` is what makes the ordering real; see `tests/support/i18n-boot.ts`.
 */

import { loadBeforeI18n, mergedResources } from '@tests/i18n-boot';

const copy = (locale: 'en' | 'it') =>
    (mergedResources()[locale].translation as { users: Record<string, string> }).users;

const invalidUser = { email: 'not-an-email', username: 'ab', password: 'x' };

const messagesFor = async (locale: 'en' | 'it') => {
    const { zodUserSchema } = await loadBeforeI18n(
        locale,
        () => import('@modules/users'),
        'users.field-email-invalid'
    );

    const result = zodUserSchema.safeParse(invalidUser);
    expect(result.success).toBe(false);
    return result.error?.issues.map(({ message }) => message) ?? [];
};

describe('user validation messages', () => {
    it('uses the English copy verbatim, not a Zod default', async () => {
        const messages = await messagesFor('en');
        const en = copy('en');

        expect(messages).toContain(en['field-email-invalid']);
        expect(messages).toContain(en['field-username-min']);
        expect(messages).toContain(en['field-password-min']);
    });

    it('uses the Italian copy when the active locale is it', async () => {
        const messages = await messagesFor('it');
        const it = copy('it');

        expect(messages).toContain(it['field-email-invalid']);
        expect(messages).toContain(it['field-username-min']);
        expect(messages).toContain(it['field-password-min']);
    });

    it('is actually translated, rather than English twice', () => {
        expect(copy('it')['field-email-invalid']).not.toBe(copy('en')['field-email-invalid']);
    });

    /**
     * The same schema object, parsed twice, in two languages, with no rebuild in between.
     * This is the property a thunk gives and an eagerly-resolved message cannot.
     */
    it('follows a locale change without the schema being rebuilt', async () => {
        let english: string[] = [];
        let italian: string[] = [];

        await jest.isolateModulesAsync(async () => {
            const i18nextModule = await import('i18next');
            const i18next = i18nextModule.default;
            const { zodUserSchema } = await import('@modules/users');

            await i18next.init({ lng: 'en', fallbackLng: 'en', resources: mergedResources() });

            const parse = () =>
                zodUserSchema.safeParse(invalidUser).error?.issues.map(({ message }) => message) ??
                [];

            english = parse();
            await i18next.changeLanguage('it');
            italian = parse();
        });

        expect(english).toContain(copy('en')['field-email-invalid']);
        expect(italian).toContain(copy('it')['field-email-invalid']);
        expect(italian).not.toEqual(english);
    });
});

src/modules/payments/tests/unit/provider.source:
/**
 * The payment provider port and its `fake` implementation — `src/modules/payments/providers/`.
 *
 * No mocks, no database. `service.test.ts` moved to `tests/integration/` because it persists a
 * payment document; the provider selection and the fake PSP's own outcome logic do not touch
 * Mongo and belong here.
 */

import { cardLastFour } from '../../providers/card';
import { FAKE_DECLINE_CARD, fakePaymentProvider } from '../../providers/fake';

describe('cardLastFour', () => {
    it('keeps only the last four digits', () => {
        expect(cardLastFour('4242424242424242')).toBe('4242');
    });

    it('strips spaces before slicing', () => {
        expect(cardLastFour('4242 4242 4242 4242')).toBe('4242');
    });
});

describe('fakePaymentProvider.charge', () => {
    it('declines the documented magic number', async () => {
        const outcome = await fakePaymentProvider.charge(
            { amount: 1000, currency: 'eur' },
            { cardNumber: FAKE_DECLINE_CARD }
        );

        expect(outcome).toBe('declined');
    });

    it('declines the decline card even with spaces, matching how a form would send it', async () => {
        const outcome = await fakePaymentProvider.charge(
            { amount: 1000, currency: 'eur' },
            { cardNumber: '4000 0000 0000 0002' }
        );

        expect(outcome).toBe('declined');
    });

    it('succeeds on any other card number', async () => {
        const outcome = await fakePaymentProvider.charge(
            { amount: 1000, currency: 'eur' },
            { cardNumber: '4242424242424242' }
        );

        expect(outcome).toBe('succeeded');
    });
});

describe('fakePaymentProvider.refund', () => {
    it('always succeeds — there is no outside ledger to disagree', async () => {
        await expect(
            fakePaymentProvider.refund({ amount: 1000, currency: 'eur' })
        ).resolves.toBeUndefined();
    });
});

/** Re-imports the provider registry with a fresh module scope, so its memoisation resets. */
const loadResolver = async () => {
    jest.resetModules();
    const module_ = await import('../../providers/index');
    return module_.resolvePaymentProvider;
};

describe('resolvePaymentProvider', () => {
    const originalProvider = process.env.NODE_PAYMENT_PROVIDER;

    afterEach(() => {
        if (originalProvider === undefined) delete process.env.NODE_PAYMENT_PROVIDER;
        else process.env.NODE_PAYMENT_PROVIDER = originalProvider;
        jest.resetModules();
    });

    it('defaults to the fake provider when unset', async () => {
        delete process.env.NODE_PAYMENT_PROVIDER;
        const resolvePaymentProvider = await loadResolver();

        expect(resolvePaymentProvider().name).toBe('fake');
    });

    it('honours an explicit known provider', async () => {
        process.env.NODE_PAYMENT_PROVIDER = 'fake';
        const resolvePaymentProvider = await loadResolver();

        expect(resolvePaymentProvider().name).toBe('fake');
    });

    it('throws on a provider this build does not carry, rather than falling back silently', async () => {
        process.env.NODE_PAYMENT_PROVIDER = 'stripe';
        const resolvePaymentProvider = await loadResolver();

        expect(() => resolvePaymentProvider()).toThrow(/Unknown payment provider "stripe"/);
    });
});

tests/unit/infrastructure/http/schemas.t.source:
/**
 * The contract scalars more than one endpoint accepts.
 *
 * Each of these exists so the same question cannot get two answers across endpoints: `hardDelete`
 * read as presence makes `?hardDelete=false` permanently delete the record, and a `pageSize` bound
 * declared per-controller makes the same out-of-range request answer 422 on one endpoint and a
 * clamped 200 on the next.
 */
import {
    hardDeleteSchema,
    pageSchema,
    pageSizeSchema,
    paginationSchema
} from '@infrastructure/http/schemas';

describe('hardDeleteSchema', () => {
    // `readInput` has already decoded the string spellings a URL can carry by the time this runs,
    // so what arrives here is a real boolean or something that was never one.
    it.each([true, false])('accepts the boolean %p', (value) => {
        expect(hardDeleteSchema.parse(value)).toBe(value);
    });

    // The whole point of the schema: read as presence, this would be `true` and delete the record.
    it('does not treat a decoded false as a request to hard-delete', () => {
        expect(hardDeleteSchema.parse(false)).toBe(false);
    });

    it.each([undefined, '', null])('reads the absent value %p as soft delete', (value) => {
        expect(hardDeleteSchema.parse(value)).toBe(false);
    });

    // Rejected rather than guessed at: a value nobody can interpret must not silently become
    // the destructive option.
    it.each(['maybe', 'not-a-boolean', 1, {}])('rejects %p', (value) => {
        expect(hardDeleteSchema.safeParse(value).success).toBe(false);
    });
});

describe('pageSchema / pageSizeSchema', () => {
    it('coerces the text a query string carries', () => {
        expect(pageSchema.parse('3')).toBe(3);
        expect(pageSizeSchema.parse('25')).toBe(25);
    });

    // Absent stays absent — `normalizePagination` is the single authority on the defaults, and a
    // second set here could only be overwritten by it.
    it.each([undefined, '', null])('leaves the absent value %p undefined', (value) => {
        expect(pageSchema.parse(value)).toBeUndefined();
        expect(pageSizeSchema.parse(value)).toBeUndefined();
    });

    it.each([0, -1, 'abc'])('rejects the page %p', (value) => {
        expect(pageSchema.safeParse(value).success).toBe(false);
    });

    // openapi.yaml declares `maximum: 100`; an endpoint that ignored it was advertising a limit
    // it never applied.
    it('rejects a page size beyond the declared maximum', () => {
        expect(pageSizeSchema.safeParse(101).success).toBe(false);
        expect(pageSizeSchema.parse(100)).toBe(100);
    });

    // A fractional page produced a fractional `skip`, which is not a page.
    it('rejects a fractional page', () => {
        expect(pageSchema.safeParse(1.5).success).toBe(false);
    });
});

describe('paginationSchema', () => {
    it('parses the pair together', () => {
        expect(paginationSchema.parse({ page: '2', pageSize: '5' })).toEqual({
            page: 2,
            pageSize: 5
        });
    });

    it('reports which of the two was wrong', () => {
        const result = paginationSchema.safeParse({ page: '1', pageSize: '500' });

        expect(result.success).toBe(false);
        expect(result.error?.issues[0].path).toEqual(['pageSize']);
    });
});

tests/unit/infrastructure/i18n/context.t.source:
/**
 * The request-scoped `t`, and the AsyncLocalStorage behind it.
 *
 * Tested for both directions that matter: inside a scope the ambient `t` must be the scope's, and
 * outside one it must silently be the global instance's. The second is what keeps jobs, workers
 * and migrations working, so a regression there is invisible until something out-of-band starts
 * answering in a raw key.
 *
 * The interleaving cases are the reason this code is its own file: the bug it exists to prevent —
 * one request answered in another's language — only appears under concurrency, so never in a test
 * that does not deliberately provoke it.
 */
import {
    createLocaleContext,
    getCurrentLocale,
    getLocaleContext,
    runWithLocale,
    t
} from '@infrastructure/i18n';
import enUsers from '@modules/users/locales/en.json';
import itUsers from '@modules/users/locales/it.json';

describe('the ambient t', () => {
    it('resolves against the scope’s locale inside a scope', () => {
        runWithLocale('it', () => {
            expect(t('users.field-email-invalid')).toBe(itUsers.users['field-email-invalid']);
            expect(getCurrentLocale()).toBe('it');
            expect(getLocaleContext()?.locale).toBe('it');
        });
    });

    it('falls back to the global instance outside any scope', () => {
        expect(getLocaleContext()).toBeUndefined();
        expect(t('users.field-email-invalid')).toBe(enUsers.users['field-email-invalid']);
    });

    it('survives awaits, so a thunk deep in a promise chain still sees the scope', async () => {
        const resolved = await runWithLocale('it', async () => {
            await Promise.resolve();
            // A real task hop, not a wall-clock wait: `setImmediate` crosses the same async
            // boundary a timer would — which is what the store has to survive — without asking
            // the test to guess how long a loaded machine needs.
            await new Promise((resolve) => setImmediate(resolve));
            return t('users.field-email-invalid');
        });

        expect(resolved).toBe(itUsers.users['field-email-invalid']);
    });

    it('keeps two overlapping scopes apart', async () => {
        const [italian, english] = await Promise.all([
            runWithLocale('it', async () => {
                // Two task hops against one, so the scopes genuinely interleave — see the note
                // on the previous test for why these are not timers.
                await new Promise((resolve) => setImmediate(resolve));
                await new Promise((resolve) => setImmediate(resolve));
                return t('users.field-email-invalid');
            }),
            runWithLocale('en', async () => {
                await new Promise((resolve) => setImmediate(resolve));
                return t('users.field-email-invalid');
            })
        ]);

        expect(italian).toBe(itUsers.users['field-email-invalid']);
        expect(english).toBe(enUsers.users['field-email-invalid']);
    });

    it('binds a context without mutating the global language', () => {
        const before = getCurrentLocale();
        createLocaleContext('it');
        expect(getCurrentLocale()).toBe(before);
    });
});

tests/cross-cutting/contract-scalars.tes.source:
/**
 * `infrastructure`'s shared scalars still match every operation in the contract.
 *
 * `PageSize` and `hardDelete` are single shared components in `openapi.yaml`, but orval flattens a
 * shared component into one constant PER OPERATION — forty identical numbers, each named after the
 * endpoint it was emitted for. `infrastructure/http/schemas.ts` cannot import "the" constant because there
 * isn't one; importing any single operation's constant puts a domain's name in `infrastructure` and makes
 * that domain undeletable once the contract is split per module.
 *
 * So `infrastructure` declares the bounds and this test carries the guarantee the import used to: raise
 * `maximum` in `openapi.yaml`, regenerate, and every constant moves while `infrastructure` does not — which
 * fails here rather than silently answering 422 for a page size the contract calls legal.
 *
 * It sweeps the GENERATED module rather than a list, so a new endpoint is covered by existing.
 */

import * as generated from '@api/schemas.zod';
import { pageSizeSchema, hardDeleteSchema } from '@infrastructure/http/schemas';

/** Every generated constant whose name ends in the given suffix. */
const constantsEndingIn = (suffix: string): [name: string, value: unknown][] =>
    Object.entries(generated as Record<string, unknown>).filter(([name]) => name.endsWith(suffix));

describe('contract scalars', () => {
    it('finds the generated constants it means to compare against', () => {
        // A canary: if orval's naming changes, an empty sweep would pass over nothing.
        expect(constantsEndingIn('PageSizeMax').length).toBeGreaterThan(5);
        expect(constantsEndingIn('HardDeleteDefault').length).toBeGreaterThan(2);
    });

    it('agrees with every operation on the maximum page size', () => {
        const disagreeing = constantsEndingIn('PageSizeMax')
            // The largest value core accepts is the bound it was built with.
            .filter(([, value]) => !pageSizeSchema.safeParse(value).success)
            .map(([name, value]) => `${name} = ${String(value)}`);

        expect(disagreeing).toEqual([]);
    });

    it('rejects one above every operation’s maximum', () => {
        // The other half: core must not accept MORE than the contract allows either, or a
        // lowered `maximum` would pass unnoticed.
        const tooPermissive = constantsEndingIn('PageSizeMax')
            .filter(([, value]) => pageSizeSchema.safeParse((value as number) + 1).success)
            .map(([name]) => name);

        expect(tooPermissive).toEqual([]);
    });

    it('agrees with every operation on the hard-delete default', () => {
        const parsed = hardDeleteSchema.parse(undefined);
        const disagreeing = constantsEndingIn('HardDeleteDefault')
            .filter(([, value]) => value !== parsed)
            .map(([name, value]) => `${name} = ${String(value)}`);

        expect(disagreeing).toEqual([]);
    });
});

