/**
 * The audit vocabulary this module emits — `src/modules/locales/audit.ts`.
 *
 * Pinned string by string, because an action is a WIRE CONTRACT and not an identifier. The
 * constant's NAME is this codebase's business and renaming it is a refactor; the STRING is read by
 * log queries, dashboards and alert rules that live outside this repo and are not refactored with
 * it. Change one and everything here type-checks, every other test passes, and someone's alert
 * quietly stops firing.
 *
 * `tests/cross-cutting/audit-actions.test.ts` proves the SHAPE of every module's vocabulary —
 * present, unique across modules, spelled as dotted lower snake_case. It cannot assert the values
 * without naming every domain, which is the coupling the module layout removes. So the values are
 * asserted by their owner, and deleting this folder takes them with it.
 */

import type { AuditAction } from '@infrastructure/observability/audit';
import { localeAuditActions } from '../../audit';

describe('the locales audit vocabulary', () => {
    it('spells every action exactly as the log tooling expects', () => {
        expect(localeAuditActions).toEqual({
            ADMIN_LOCALE_CREATED: 'admin.locale.created',
            ADMIN_LOCALE_UPDATED: 'admin.locale.updated',
            ADMIN_LOCALE_DELETED: 'admin.locale.deleted',
            ADMIN_LOCALE_ENTRY_CREATED: 'admin.locale_entry.created',
            ADMIN_LOCALE_ENTRY_UPDATED: 'admin.locale_entry.updated',
            ADMIN_LOCALE_ENTRY_DELETED: 'admin.locale_entry.deleted',
            ADMIN_LOCALE_ENTRY_IMPORTED: 'admin.locale_entry.imported'
        });
    });

    /*
     * Not cosmetic. The cross-cutting sweep requires `noun.noun.verb` in lower snake_case, so
     * `locale-entry` — which is how the noun reads everywhere else in this module — would fail it.
     * Asserted here too, at the point where someone renaming the noun would be looking.
     */
    it('spells its two-word noun with an underscore, as the sweep requires', () => {
        for (const action of Object.values(localeAuditActions)) expect(action).not.toContain('-');
    });

    /*
     * The `declare module` augmentation in `audit.ts` is what puts these into `AuditAction`.
     * Drop it and the module still compiles on its own — but `emitAuditEvent` then rejects every
     * action this module owns, at the call sites rather than here.
     */
    it('registers its actions in the app-wide union', () => {
        const action: AuditAction = localeAuditActions.ADMIN_LOCALE_ENTRY_IMPORTED;

        expect(action).toBe('admin.locale_entry.imported');
    });
});

tests/cross-cutting/subdomain-discipline.source:
/**
 * Subdomain discipline: spend modelling effort where the business is, and nowhere else.
 *
 * DDD's own advice is the part most often skipped — tactical patterns belong in the **core**
 * domain, and supporting and generic subdomains should use the simplest thing that works. Every
 * module now says which of the three it is, and this file is what stops that from being a label
 * nobody acts on:
 *
 *   - a `generic` module may not carry a `domain/` folder. Auth, i18n, audit trails and health
 *     endpoints are solved problems; a pure-rules layer inside one is effort spent on the part of
 *     the system that should be replaceable by something bought.
 *
 * That rule, and the requirement that every module classify itself at all, is the whole of what
 * this file checks. Whether the classification stays HONEST is not checked. If every module drifts to `core` the
 * field stops being able to say no to anything, and nothing here will report it — that is a review
 * question now, not a failing test.
 *
 * There is deliberately no rule that a `core` module MUST have a `domain/` folder. `products` is
 * core and has none, because its rules are currently thin enough to live in the service. That is a
 * legitimate state and a fair thing to notice; it is not a violation, and a test that forced the
 * folder would only produce empty ones.
 *
 * In a boilerplate these values are a worked example rather than a finding — a starter kit has no
 * core domain, and the first thing a real project does is re-decide them. The mechanism is the
 * deliverable, not the answers. See `docs/theory/domain-layer.md` §5.
 */

import { existsSync } from 'node:fs';
import path from 'node:path';
import { enabledModules } from '../../src/modules';
import type { Subdomain } from '@kernel/registry';

const MODULES_ROOT = path.join(__dirname, '../../src/modules');

const withSubdomain = (subdomain: Subdomain): string[] =>
    enabledModules.filter((appModule) => appModule.subdomain === subdomain).map(({ name }) => name);

describe('subdomain classification', () => {
    it('classifies every enabled module', () => {
        const unclassified = enabledModules
            .filter((appModule) => !['core', 'supporting', 'generic'].includes(appModule.subdomain))
            .map(({ name }) => name);

        expect(unclassified).toEqual([]);
    });

    it('keeps a domain layer out of generic subdomains', () => {
        const misplaced = withSubdomain('generic').filter((name) =>
            existsSync(path.join(MODULES_ROOT, name, 'domain'))
        );

        expect(misplaced).toEqual([]);
    });
});

