/**
 * `src/infrastructure/adapters/demo-outbox.ts` — the demo profile's email sink.
 *
 * The paired frontend's password-reset and verification specs are only as good as this
 * recording: `token` in particular is lifted out of the templates' link URL, and a regression
 * there fails suites in ANOTHER repo with a message about an empty inbox.
 */
import {
    clearDemoOutbox,
    isDemoMode,
    readDemoOutbox,
    recordDemoEmail
} from '@infrastructure/adapters/demo-outbox';

afterEach(() => {
    clearDemoOutbox();
    delete process.env.NODE_DEMO;
});

it('is demo mode exactly when NODE_DEMO is the string true', () => {
    delete process.env.NODE_DEMO;
    expect(isDemoMode()).toBe(false);
    process.env.NODE_DEMO = 'true';
    expect(isDemoMode()).toBe(true);
});

it('records newest first, with primitive template variables as readable lines', () => {
    recordDemoEmail({ to: 'a@b.it', subject: 'First' }, 'one', { greeting: 'Hello', count: 2 });
    recordDemoEmail({ to: 'c@d.it', subject: 'Second' }, 'two', {});

    const [newest, oldest] = readDemoOutbox();
    expect(newest).toMatchObject({ to: 'c@d.it', template: 'two' });
    expect(oldest.lines).toEqual(expect.arrayContaining(['greeting: Hello', 'count: 2']));
});

it('lifts the token out of a link URL when no bare token variable exists', () => {
    recordDemoEmail({ to: 'a@b.it', subject: 'Reset' }, 'reset', {
        linkUrl: 'http://localhost:3000/account/reset/d2740058f8b671c6ae12fc8618b09129'
    });
    expect(readDemoOutbox()[0].token).toBe('d2740058f8b671c6ae12fc8618b09129');
});

it('prefers a bare token variable over the link', () => {
    recordDemoEmail({ to: 'a@b.it', subject: 'Verify' }, 'verify', {
        token: 'bare-token',
        linkUrl: 'http://localhost:3000/account/verify/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa'
    });
    expect(readDemoOutbox()[0].token).toBe('bare-token');
});

it('serializes a structured recipient rather than losing it', () => {
    recordDemoEmail({ to: { name: 'G', address: 'g@p.it' }, subject: 'S' }, 't', {});
    expect(readDemoOutbox()[0].to).toContain('g@p.it');
});

it('clears to an empty inbox — the per-spec reset the demo router performs', () => {
    recordDemoEmail({ to: 'a@b.it', subject: 'S' }, 't', {});
    clearDemoOutbox();
    expect(readDemoOutbox()).toEqual([]);
});

tests/unit/infrastructure/i18n/negotiate.source:
/**
 * Header negotiation.
 *
 * `negotiateLocale` is a pure function over a client-supplied header, so it is tested directly
 * rather than only through the integration suite — malformed headers are the interesting cases
 * and they are tedious to provoke over HTTP.
 */
import { negotiateLocale } from '@infrastructure/i18n';

const SUPPORTED = ['en', 'it'];

describe('negotiateLocale', () => {
    it.each([
        ['it', 'it'],
        ['en', 'en'],
        ['IT', 'it'],
        ['it-CH', 'it'],
        ['en-GB', 'en']
    ])('resolves %s to %s', (header, expected) => {
        expect(negotiateLocale(header, SUPPORTED)).toBe(expected);
    });

    it('prefers the highest q-weight over header order', () => {
        expect(negotiateLocale('en;q=0.8,it;q=0.9', SUPPORTED)).toBe('it');
    });

    it('keeps header order when weights tie', () => {
        expect(negotiateLocale('it;q=0.9,en;q=0.9', SUPPORTED)).toBe('it');
    });

    it('skips unsupported languages and takes the next acceptable one', () => {
        expect(negotiateLocale('de,fr;q=0.9,it;q=0.8', SUPPORTED)).toBe('it');
    });

    it('ignores an entry the client explicitly refused with q=0', () => {
        expect(negotiateLocale('it;q=0,en;q=0.5', SUPPORTED)).toBe('en');
    });

    it.each([
        ['no header at all', undefined],
        ['an empty header', ''],
        ['a wildcard', '*'],
        ['only unsupported languages', 'de,fr'],
        ['punctuation soup', ';;;,,,']
    ])('falls back to the fallback locale given %s', (_label, header) => {
        expect(negotiateLocale(header, SUPPORTED)).toBe('en');
    });

    it('honours a language whose weight is unparseable, rather than discarding it', () => {
        expect(negotiateLocale('it;q=banana', SUPPORTED)).toBe('it');
    });

    it('falls back to the first supported locale when the fallback is not supported', () => {
        expect(negotiateLocale('de', ['it', 'es'])).toBe('it');
    });

    // The default argument is the catalogue, so a caller that names no list negotiates against
    // exactly the languages `i18next.init()` registered.
    it('negotiates against the supported list when given no list', () => {
        expect(negotiateLocale('it')).toBe('it');
    });
});

