/**
 * Order rules — `src/modules/orders/domain/rules.ts`.
 *
 * No mocks, no database, no fake timers — the rules take arguments and return verdicts.
 */

import { checkOrderLines, type OrderLineCandidate } from '../../domain/rules';

/** A line whose product resolved. */
const line = (quantity = 1): OrderLineCandidate => ({ quantity, product: { price: 10 } });

describe('checkOrderLines', () => {
    it('refuses an empty set, naming the reason', () => {
        expect(checkOrderLines([])).toEqual({ ok: false, reason: 'no-lines' });
    });

    it('accepts lines whose products all resolved', () => {
        expect(checkOrderLines([line(), line(3)])).toEqual({ ok: true });
    });

    // The two reasons map to different status codes, so they must stay distinct.
    it.each([
        ['undefined', undefined],
        ['null', null]
    ])('refuses the whole set when a product is %s', (_label, product) => {
        expect(checkOrderLines([line(), { quantity: 1, product }])).toEqual({
            ok: false,
            reason: 'product-missing'
        });
    });

    it('refuses on an unresolved product even when other lines are fine', () => {
        // An order embeds a snapshot: a missing product cannot be dropped and the rest kept.
        expect(checkOrderLines([line(), line(), { quantity: 9, product: null }]).ok).toBe(false);
    });
});

// The soft-delete toggle and the read scope used to live here as `nextDeletionState` and
// `readScope`. Both were one-line expressions with one caller each, so they moved back into
// `service.ts`; `service-crud.test.ts` covers the toggle and `service-scope.test.ts` the scope,
// including the fail-closed cases.

src/modules/audit-logs/tests/unit/retent.source:
/**
 * The TTL retention this module's collection is configured with.
 *
 * Read from the environment at import time, which is unusual enough to be worth a case: a TTL
 * index is created once, at startup, from whatever the value is then. The default branch is what
 * every deployment that has not set the variable actually runs.
 */

/** Re-imports the audit model with a fresh module registry, so the import-time read runs again. */
const loadSchema = async () => {
    jest.resetModules();
    const module_ = await import('@modules/audit-logs/model');
    return module_.auditLogSchema;
};

/** The `expireAfterSeconds` the TTL index was declared with. */
const ttlSeconds = (schema: Awaited<ReturnType<typeof loadSchema>>): number | undefined =>
    schema
        .indexes()
        .map(([, options]) => (options as { expireAfterSeconds?: number }).expireAfterSeconds)
        .find((value) => value !== undefined);

describe('audit log retention', () => {
    const originalRetention = process.env.NODE_AUDIT_RETENTION_DAYS;

    afterEach(() => {
        if (originalRetention === undefined) delete process.env.NODE_AUDIT_RETENTION_DAYS;
        else process.env.NODE_AUDIT_RETENTION_DAYS = originalRetention;
        jest.resetModules();
    });

    it('defaults to 90 days when the variable is unset', async () => {
        delete process.env.NODE_AUDIT_RETENTION_DAYS;

        expect(ttlSeconds(await loadSchema())).toBe(90 * 24 * 60 * 60);
    });

    it('honours a configured retention', async () => {
        process.env.NODE_AUDIT_RETENTION_DAYS = '30';

        expect(ttlSeconds(await loadSchema())).toBe(30 * 24 * 60 * 60);
    });
});

tests/unit/infrastructure/persistence/se.source:
/**
 * `src/infrastructure/persistence/seed.ts` — the upsert policy every module seeder goes through.
 *
 * Two arms and both matter: `skipped` is what makes `db:seed` idempotent on every container
 * boot, `created` is what makes it a seeder at all. The skip arm went unexercised by any unit —
 * the db suites always seed into a dropped database — which left the branch invisible to
 * coverage the day the persistence directory fell out of the threshold globs.
 */
import { Types } from 'mongoose';
import { upsertById } from '@infrastructure/persistence/seed';

const FIXTURE = { _id: new Types.ObjectId('65de646a44f861fd83c13f13'), name: 'row' };

it('creates when no document carries the pinned id', async () => {
    const create = jest.fn().mockResolvedValue(FIXTURE);
    const repository = { findById: jest.fn().mockResolvedValue(null), create };

    await expect(upsertById(repository, FIXTURE)).resolves.toBe('created');
    expect(create).toHaveBeenCalledWith(FIXTURE, expect.anything());
});

it('skips when the id already exists — a second boot is a no-op, not a rewrite', async () => {
    const create = jest.fn();
    const repository = { findById: jest.fn().mockResolvedValue(FIXTURE), create };

    await expect(upsertById(repository, FIXTURE)).resolves.toBe('skipped');
    expect(create).not.toHaveBeenCalled();
});

